export const KNOWLEDGE_BASE: KnowledgeEntry[] = [
{"id": "chunk_0001", "question": "Chi sono gli intermediari finanziari?", "answer": "Gli Intermediari Finanziari collegano i soggetti con surplus finanziario - i cosiddetti centri di formazione del risparmio, tipicamente individui e famiglie - e unità in deficit finanziario (che intendono realizzare investimenti), tipicamente le imprese, favorendo la trasformazione del risparmio in investimenti produttivi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0002", "question": "Qual è la funzione più conosciuta dell'intermediazione finanziaria?", "answer": "L'attività bancaria di concessione del credito alle imprese e alle famiglie è forse la funzione d'intermediazione finanziaria oggi più conosciuta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0003", "question": "Su quali informazioni si basa l'attività bancaria di concessione del credito?", "answer": "Alla base di questa attività c'è l'importante lavoro di raccolta e gestione delle informazioni relative allo stato dell'economia nel suo complesso (informazioni pubbliche) e alla solidità patrimoniale e alla redditività attesa futura dei soggetti che richiedono credito (informazioni private).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0004", "question": "Perché il rapporto tra banca creditrice e impresa debitrice è di natura fiduciaria?", "answer": "Il rapporto tra la banca creditrice e l'impresa debitrice è di natura fiduciaria in quanto il creditore deve fare assegnamento sulla veridicità e completezza delle informazioni (private) acquisite e sul comportamento del debitore in termini di correttezza, diligenza professionale e rispetto delle leggi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0005", "question": "Da cosa dipende la qualità dell'attività di intermediazione finanziaria?", "answer": "Tutte le attività d'intermediazione finanziaria sono fondate sull'acquisizione continua e l'elaborazione di informazioni di natura economica. La qualità di queste informazioni (per esempio, la loro autenticità) incide sulla capacità di compiere scelte ragionate e assumere rischi misurabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0006", "question": "Qual è il ruolo generale degli intermediari finanziari nell'economia?", "answer": "In senso generale, gli intermediari finanziari mettono in collegamento tutti gli agenti economici (famiglie, imprese, Stato). Tanto più elevata è la loro capacità di indirizzare risorse verso gli investimenti più produttivi, tanto maggiore sarà il grado di crescita dell'economia nel suo complesso. Ovviamente vale anche l'inverso, come dimostrato ampiamente (e duramente) dalla crisi finanziaria originatasi nel biennio 2007-2008 ed estesasi su scala mondiale negli anni successivi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0007", "question": "Cosa differenzia la banca dagli altri intermediari finanziari?", "answer": "Il tratto più caratteristico che differenzia la banca dagli altri intermediari finanziari è rinvenibile dal lato della raccolta, costituita essenzialmente da depositi e conti correnti, che sono passività finanziarie a breve rimborsabili al valore nominale e sono parte dell'offerta di moneta (moneta bancaria) in quanto costituiscono mezzi di pagamento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0008", "question": "Come utilizzano le banche i fondi raccolti?", "answer": "I fondi così raccolti sono poi utilizzati per finanziare le imprese e la pubblica amministrazione (al pari di altri intermediari finanziari), accettando di tenere in portafoglio le attività finanziarie emesse da quest'ultime (obbligazioni, buoni del Tesoro, scoperti di conto corrente, cambiali ecc.).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0009", "question": "Cosa significa che la banca svolge una funzione di trasformazione delle scadenze?", "answer": "In questo modo, le banche attuano una funzione di trasformazione delle scadenze (e dei rischi) perché esse, grazie alla gestione della propria struttura finanziaria, consentono di soddisfare la preferenza per la liquidità e/o la tolleranza al rischio di perdita del capitale propria delle unità in surplus (i risparmiatori individuali che hanno un diritto al rimborso dei fondi) con le esigenze delle unità in deficit di avere risorse stabili sotto la veste di finanziamenti con scadenze non a breve termine (sulla base di contratti che attribuiscono comunque alla banca il diritto alla restituzione delle somme prestate).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0010", "question": "Che rischio sopporta la banca nell'attività di concessione del credito?", "answer": "La banca sopporterà anche il rischio di insolvenza (ossia il rischio che il debitore non paghi gli interessi periodici e/o non restituisca il capitale) e per questo è incentivata a condurre una continua e approfondita analisi delle condizioni di solvibilità dell'impresa finanziata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0011", "question": "Chi sono i principali destinatari del credito bancario?", "answer": "Le banche commerciali, specializzate nell'attività di prestare credito, sono tipicamente fornitrici di risorse finanziarie a famiglie e, soprattutto, a imprese piccole e medio-piccole che hanno limitate possibilità di utilizzare i mercati finanziari per soddisfare i propri fabbisogni di liquidità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0012", "question": "Quali attività e servizi svolgono gli intermediari finanziari nel loro complesso?", "answer": "Gli intermediari finanziari nel loro complesso svolgono una pluralità di attività e servizi finanziari che possono essere così riassunti secondo una logica funzionale: operazioni di pagamento/incasso di denaro (in connessione a trasferimenti di fondi, scambi commerciali tra imprese domestiche e internazionali, spese per consumo individuali, stipendi e salari, regolamento di investimenti/disinvestimenti finanziari, altre spese o incassi); gestione di carte di credito/debito; prestiti monetari (nelle diverse forme possibili); rilascio di garanzie e di impegni di firma; intermediazione non discrezionale (senza delega) di strumenti finanziari per l'investimento del risparmio privato (raccolta e trasmissione, negoziazione c/terzi di ordini di compravendita di strumenti finanziari in mercati organizzati e distribuzione di prodotti finanziari); consulenza in materia di investimenti in prodotti finanziari; intermediazione discrezionale (su delega-mandato) del risparmio finanziario privato con diversificazione dei rischi di portafoglio (attività di gestione di patrimoni collettivi e individuali); organizzazione di (o partecipazione a) sindacati di collocamento - al pubblico e/o riservato (cosiddetto private placement) - di strumenti finanziari (azioni, obbligazioni o ibridi) per conto di società-emittenti, con o senza assunzione di garanzia o preventiva sottoscrizione a fermo; investimenti diretti di risorse finanziarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-intermediari-finanziari"}},
{"id": "chunk_0013", "question": "Cosa sono i mercati finanziari?", "answer": "I mercati finanziari sono luoghi operativi, organizzati sulla base di regole pubbliche o di prassi, dove è possibile acquistare o vendere strumenti finanziari (azioni, obbligazioni, derivati, quote di fondi comuni ecc.), favorendo l'incontro tra domanda e offerta di attività finanziarie grazie alla concentrazione, in uno stesso 'spazio' e nello stesso tempo, delle negoziazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0014", "question": "I mercati finanziari sono luoghi fisici?", "answer": "Quando si parla di mercati non bisogna pensare a 'luoghi fisici' (come le vecchie Borse Valori, dove gli operatori si incontravano personalmente), quanto piuttosto a piattaforme informatiche di negoziazione (cosiddette sedi di negoziazione) o a circuiti informativi elettronici, specializzati per tipologie di strumenti finanziari e/o di soggetti-emittenti, a cui hanno accesso intermediari finanziari e altri soggetti autorizzati ad operarvi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0015", "question": "Qual è l'effetto della tecnologia telematica sui mercati finanziari?", "answer": "La moderna tecnologia di comunicazione telematica ha di fatto annullato le distanze geografiche tra operatori e luogo di scambio e, per molti versi, ha spersonalizzato le negoziazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0016", "question": "Quali sono le funzioni tradizionali dei mercati finanziari?", "answer": "Ai mercati finanziari sono tradizionalmente assegnate le seguenti funzioni: Finanziamento: facilitare il trasferimento del risparmio dalle unità in surplus (famiglie) alle unità in deficit (imprese e Stato) tramite le emissioni di nuovi titoli (mercato primario). Negoziaibilità dei titoli: favorire la formazione dei prezzi (cosiddetto pricing) di equilibrio dei titoli, incrementare la liquidità dei titoli negoziati, tendere alla riduzione dei costi di transazione. Controllo societario: consentire il trasferimento del controllo delle imprese. Gestione del rischio: ridurre il rischio di portafoglio tramite la diversificazione degli investimenti e consentire la copertura dei rischi tramite la negoziazione dei titoli derivati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0017", "question": "Cosa consentono i mercati finanziari in sintesi?", "answer": "In sintesi, i mercati finanziari consentono di ripartire e/o trasferire le risorse e il rischio finanziario tra gli agenti economici, nonché - se azionari - il controllo delle società, attraverso la compravendita di strumenti finanziari, la negoziazione di contratti finanziari (tipicamente derivati) e l'utilizzo di tecniche di gestione complesse (prestito titoli, collateralizzazione, operazioni di pronti-contro-termine), assicurandone la liquidabilità e la valorizzazione basata su un processo dinamico di formazione del prezzo tramite le proposte (ordini di compravendita) che via via affluiscono nel mercato stesso (processo cosiddetto di price discovery).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0018", "question": "Chi sono gli attori tipici dei mercati finanziari?", "answer": "Attori tipici dei mercati finanziari sono: i soggetti disposti ad investire denaro in strumenti finanziari (investitori individuali o istituzionali ossia fondi pensione, gestori di portafoglio, assicurazioni, tesorerie di imprese multinazionali ecc.); coloro che necessitano di denaro e in cambio emettono strumenti finanziari (tipicamente le imprese di medio-grandi dimensioni, ma anche le banche e gli Stati); altri investitori che intendono disinvestire (liquidare) gli strumenti finanziari già acquistati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0019", "question": "Quando un mercato finanziario è efficiente?", "answer": "Possiamo affermare che un mercato finanziario è efficiente se - secondo la tradizionale teoria risalente al professor Eugene Fama - i prezzi degli strumenti che vi si negoziano riflettono pienamente le informazioni disponibili (cosiddetta efficienza forte).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0020", "question": "Cosa devono assicurare i mercati regolamentati?", "answer": "I mercati regolamentati - assoggettati a regole pubbliche - devono assicurare condizioni di trasparenza, e cioè che le intenzioni (proposte di acquisto e di vendita) di ciascun operatore siano note a tutti gli altri e i prezzi delle transazioni concluse siano resi pubblici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0021", "question": "A cosa serve la trasparenza informativa sui prezzi di negoziazione?", "answer": "La trasparenza informativa sui prezzi di negoziazione e sugli aspetti rilevanti delle società-emittenti titoli serve a garantire l'ordinato funzionamento dei meccanismi di determinazione dei prezzi dei titoli tramite l'incrocio di domanda e offerta, riducendo il rischio di alterazioni artificiose.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0022", "question": "Chi assicura la trasparenza informativa dei mercati finanziari regolamentati?", "answer": "La trasparenza informativa dei mercati finanziari regolamentati è assicurata dal controllo di autorità di vigilanza (come la CONSOB). Fra i loro compiti vi è anche quello di reprimere abusi di mercato, quali l'uso di tecniche di manipolazione operativa dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0023", "question": "Da cosa dipende la liquidità di un mercato finanziario?", "answer": "Un mercato finanziario si può ritenere tanto più liquido quanto: più ridotto è il tempo di esecuzione di un'operazione di vendita (che dipende dai volumi di proposte in acquisto e vendita esistenti ossia dalla cosiddetta ampiezza del mercato); minore è il costo delle operazioni di compravendita (efficienza operativa); minore è la variazione di prezzo (anche temporanea) indotta dalla dimensione del controvalore scambiato (cosiddetto spessore ed elasticità del mercato).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0024", "question": "La liquidità è una caratteristica strutturale di un mercato?", "answer": "La liquidità non è una caratteristica strutturale di un mercato, pur dipendendo, in condizioni di normalità, anche dalle regole che il mercato si è dato. Essa può essere influenzata da fattori diversi dalle caratteristiche e dai meccanismi di funzionamento dei singoli mercati, quali, ad esempio, le decisioni di investimento degli operatori e degli investitori, soprattutto in presenza di cambiamenti di scenario macro-economico, che possono ridurre notevolmente le possibilità di trovare una controparte con cui concludere un'operazione di compravendita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0025", "question": "Qual è la funzione del mercato del controllo societario?", "answer": "Altra importante funzione dei mercati, e in particolare di quelli azionari, è quella di consentire lo scambio dei diritti proprietari della società emittente, facilitando così il passaggio del controllo sulle imprese societarie. Si parla infatti di mercato del controllo societario che rappresenta uno dei elementi più importanti del sistema finanziario a struttura capitalistica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0026", "question": "Come possono essere classificati i mercati finanziari?", "answer": "I mercati finanziari possono essere classificati sulla base di una serie di parametri (es. natura degli strumenti trattati, dimensione degli scambi, tipologia di operatori, ecc.).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0027", "question": "Chi regola e vigila i mercati finanziari?", "answer": "Insieme agli intermediari finanziari, i mercati costituiscono la componente principale dei sistemi finanziari e, per questo, sono regolamentati e vigilati da apposite Autorità che hanno il compito di garantirne l'integrità, la trasparenza e l'efficienza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0028", "question": "Cosa ha favorito la sovrapposizione tra mercati e intermediari finanziari?", "answer": "Negli ultimi anni si è assistito a diverse forme di 'sovrapposizione' tra i due ambiti, soprattutto grazie allo sviluppo del cosiddetto 'sistema bancario ombra'.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-degli-strumenti-finanziari"}},
{"id": "chunk_0029", "question": "Che cosa possono fare gli agenti economici secondo la teoria dei mercati finanziari?", "answer": "Secondo la consolidata teoria dei mercati finanziari, gli agenti economici (individui, imprese ecc.) possono distribuire nel tempo - in base alle proprie necessità - le decisioni di produzione e consumo di beni e servizi attraverso l'utilizzo della moneta, il credito e il mercato degli strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0030", "question": "Che cosa rappresenta il risparmio nel contesto economico-finanziario?", "answer": "Il risparmio viene trasferito nel tempo, come potere d'acquisto futuro, attraverso l'investimento in attività finanziarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0031", "question": "Che cosa guida le scelte intertemporali di consumo e risparmio?", "answer": "Il tasso d'interesse (ossia il premio percentuale pagato ad una data sul controvalore della somma investita) è la grandezza che guida le scelte intertemporali individuali o di un'impresa sull'uso delle risorse finanziarie: se consumare o risparmiare (investire in attività finanziarie) e in quali attività investire.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0032", "question": "Come si definisce un'attività finanziaria?", "answer": "Per semplicità, definiamo \"attività finanziaria\" qualsiasi rapporto contrattuale nel quale le prestazioni delle parti sono di norma definite in moneta e si possono realizzare tipicamente in tempi diversi (obbligazioni, mutuo bancario ecc.), ma possono anche realizzarsi in tempi coincidenti (contratti di swap su tassi d'interesse ecc.), ovvero al verificarsi di certe condizioni/eventi o all'esercizio di una facoltà.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0033", "question": "Perché esistono i titoli di credito e cosa sono gli strumenti finanziari?", "answer": "L'economia si è sviluppata riformando prassi finanziarie mercantili esistenti o reinventandone di nuove e adeguando via via la disciplina giuridica volta a regolare i rapporti tra le parti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0034", "question": "Che cosa si intende per mobilizzazione del credito?", "answer": "La \"mobilizzazione\" del credito e dei diritti di partecipazione agli \"affari\" economici fu una delle principali esigenze degli operatori economici dal 1400 in avanti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0035", "question": "Che cos'è la cessione di un credito?", "answer": "La semplice \"cessione di un credito\" è un'operazione ammessa dal nostro Codice Civile: è un accordo fra il creditore (cedente) e un terzo soggetto (cessionario) che trasferisce in capo a quest'ultimo il credito monetario vantato nei confronti del debitore (ceduto).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0036", "question": "Qual è il rischio legale nella cessione del credito?", "answer": "Il debitore può sempre opporre in questo caso al terzo acquirente del credito le eccezioni personali che avrebbe potuto opporre al primo creditore. Questo \"rischio legale\", insieme al costo della ricerca di un terzo soggetto (il cessionario) disposto ad acquistare il credito, costituisce un rilevante limite operativo all'utilizzo diffuso dei contratti di cessione del credito nel sistema finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0037", "question": "Che cosa sono i titoli di credito?", "answer": "Per rendere agevole la circolazione dei crediti monetari, sono stati utilizzati i cosiddetti \"titoli di credito\", rappresentati tradizionalmente da un documento contenente una promessa unilaterale di pagamento o un ordine di pagamento di una certa somma di denaro ad una data scadenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0038", "question": "Quali sono le caratteristiche principali dei titoli di credito?", "answer": "I titoli di credito si caratterizzano per: - l'autonomia del diritto di credito - in essi incorporato - dal rapporto economico che è all'origine dell'emissione dei titoli medesimi; - la letteralità: è ciò che è scritto nel documento (o nel regolamento dell'emissione nel caso di titoli di massa) che determina la quantità, qualità e modalità del diritto attribuito al possessore legittimo del titolo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0039", "question": "Che cosa significa incorporazione del diritto nel titolo di credito?", "answer": "La incorporazione del diritto nel titolo consente di applicare ai diritti di credito le regole del trasferimento della proprietà dei beni mobili, prima fra tutte il possesso del titolo. Chi acquista la proprietà del titolo acquista anche il diritto di credito in esso incorporato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0040", "question": "Quali sono i principali titoli di credito?", "answer": "Tra i titoli di credito si possono classificare: - i titoli del debito pubblico; - le obbligazioni emesse da società di capitale; - le cambiali e gli assegni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0041", "question": "Qual è la differenza tra obbligazioni e azioni?", "answer": "È netta la distinzione tra i titoli di credito rappresentati da obbligazioni (frazioni di egual valore e di uguali diritti di un'unica operazione di mutuo) e titoli di partecipazione rappresentati da azioni (unità minima di partecipazione al capitale di una società per azioni).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0042", "question": "Che diritti ha il possessore di un'obbligazione?", "answer": "Il possessore di un'obbligazione vanta un credito che genera un reddito periodico (cedole) e il diritto al rimborso dello stesso ad una scadenza data.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0043", "question": "Che diritti ha il possessore di un'azione?", "answer": "Il possessore di un'azione (socio-azionista) vanta diritti patrimoniali e amministrativi (il diritto a riscuotere i dividendi, di prendere parte alle assemblee sociali, di sottoscrivere aumenti di capitale ed emissioni di obbligazioni, ecc.), ma non anche il diritto al rimborso del suo investimento, perché partecipa - nei limiti dell'investimento stesso - al rischio d'impresa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0044", "question": "Qual è la funzione dei contratti finanziari derivati?", "answer": "Diversamente dalle azioni e dalle obbligazioni, i contratti finanziari cosiddetti derivati hanno normalmente la funzione di assicurazione o di copertura e trasferimento del rischio finanziario tra due parti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0045", "question": "Che cosa sono i prodotti finanziari?", "answer": "Prodotti finanziari: tutte le forme d'investimento di natura finanziaria (esclusi i depositi bancari a vista e a tempo e i depositi postali) ossia d'impiego di risparmio effettuate in vista di un ritorno economico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0046", "question": "Che cosa sono gli strumenti finanziari?", "answer": "Strumenti finanziari: rientrano nella categoria dei prodotti finanziari e sono costituiti da azioni, obbligazioni, altri titoli di debito, titoli di Stato, altri strumenti finanziari negoziabili sul mercato dei capitali, quote di fondi comuni d'investimento, altri titoli negoziati sul mercato dei capitali e sul mercato monetario, strumenti finanziari derivati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0047", "question": "Che cosa sono i valori mobiliari?", "answer": "Valori mobiliari: categoria di strumenti finanziari che possono essere negoziati sul mercato dei capitali, in quanto trasferibili e liquidabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0048", "question": "Qual è la funzione dei titoli di credito nelle economie moderne?", "answer": "I titoli di credito (soprattutto nella loro forma di strumenti finanziari) giocano una funzione importantissima nella circolazione della ricchezza e, quindi, per la crescita delle moderne economie industrializzate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0049", "question": "Che cosa significa che la libera trasferibilità è un carattere naturale dei titoli di credito?", "answer": "La libera trasferibilità è un carattere naturale dei titoli di credito. L'evoluzione delle pratiche finanziarie nell'utilizzo dei titoli di credito ha condotto all'emissione di titoli di credito in serie (cosiddetti titoli di massa) il cui trasferimento è stato facilitato non prevedendo più la consegna fisica dei documenti e l'appostazione di firme e annotazioni, quanto piuttosto semplici operazioni di registrazioni contabili per via telematica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0050", "question": "Quali sono i presupposti per la registrazione contabile telematica dei titoli di massa?", "answer": "I presupposti per la registrazione contabile telematica dei trasferimenti dei titoli di credito di massa sono dati dalla loro fungibilità, dalla loro dematerializzazione e dall'esistenza di soggetti abilitati alla gestione accentrata delle registrazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0051", "question": "Che cosa comporta la dematerializzazione integrale dei titoli?", "answer": "La dematerializzazione integrale è stata resa obbligatoria per tutti i titoli negoziati o destinati alla negoziazione sui mercati regolamentati e sugli altri mercati disciplinati dalla normativa dell'Unione Europea (cosiddetti MTF e OTF).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0052", "question": "Che cosa si intende per negoziabilità o liquidità dei titoli di credito?", "answer": "Altro elemento importante è la negoziabilità/liquidità dei titoli di credito/strumenti finanziari: la loro attitudine, cioè, ad essere trasformati in moneta a prezzi che ne rispecchino il valore intrinseco e in tempi ragionevoli mediante cessione sul mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0053", "question": "Che vantaggio offre la negoziabilità di un titolo obbligazionario?", "answer": "La negoziabilità rende indipendente la durata di un debito per l'emittente del titolo obbligazionario e la durata dell'investimento per il sottoscrittore del titolo stesso, il quale se per qualsiasi ragione non vuole aspettare la scadenza dell'obbligazione può vendere il titolo sul mercato e rientrare in possesso del suo capitale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-titoli-di-credito"}},
{"id": "chunk_0054", "question": "Che cos'è il baratto?", "answer": "Lo scambio di un prodotto con altro prodotto viene chiamato baratto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0055", "question": "In quali tipi di organizzazioni sociali si sviluppa il baratto?", "answer": "Nelle organizzazioni sociali meno evolute - costituite da comunità domestiche con regole elementari di convivenza - la produzione e lo scambio di prodotti naturali o di animali cacciati o loro derivati (per esempio pellame) avvengono per il sostentamento e la sicurezza degli individui che compongono la famiglia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0056", "question": "Qual è lo scopo della produzione e dello scambio nelle comunità che praticano il baratto?", "answer": "Si dice quindi che sono volti al soddisfacimento dei cosiddetti bisogni primari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0057", "question": "Che cosa si intende per economia di sussistenza?", "answer": "Si parla in questi casi di economia di sussistenza, in quanto parte di ciò che si produce (caccia, raccolta di frutti spontanei e agricoltura rudimentale) si consuma o si utilizza direttamente e la parte eccedente si scambia con altri prodotti, sempre da utilizzare o consumare direttamente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0058", "question": "Quali sono i principali limiti del baratto?", "answer": "Il baratto comporta molti limiti. Se i beni da barattare sono deperibili, ad esempio, l'operazione di scambio dovrà avvenire appena dopo la produzione e i beni così acquisiti dovranno essere consumati in breve tempo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0059", "question": "Perché il baratto è problematico per chi produce beni deperibili?", "answer": "Si pensi a chi produce uva e quindi si trova in possesso di una gran quantità di questa frutta da poter scambiare in ottobre; il problema è che per sopravvivere ha bisogno di poter acquistare altri beni in altri mesi dell'anno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0060", "question": "Che cosa accade se due persone non hanno beni di reciproco interesse da scambiare?", "answer": "Supponiamo che un uomo abbia di una certa merce più di quanto gli serva mentre un altro ne abbia meno. Di conseguenza, il primo sarebbe lieto di collocare quel superfluo e il secondo di comprarlo. Ma se per caso il secondo non avesse nulla di cui il primo ha bisogno, tra loro non si potrebbe fare alcuno scambio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0061", "question": "Perché nel baratto può essere difficile scambiare beni indivisibili come il bestiame?", "answer": "Chi, ad esempio, avesse voluto comprare del sale e non avesse avuto da dare in cambio altro che bestiame, sarebbe stato costretto a comprare sale per il valore di un bue intero o di un'intera pecora in una sola volta. Difficilmente avrebbe potuto comprarne di meno, giacché ciò che poteva dare in cambio non si sarebbe potuto dividere senza perdite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0062", "question": "Qual è la relazione tra produzione e consumo nel baratto?", "answer": "Nel baratto le fasi della produzione e del consumo finiscono per essere quasi contestuali. Difatti, la decisione di posticipare il consumo dei beni scambiati si scontra con la difficoltà di conservazione dei beni stessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0063", "question": "Perché il baratto richiede compatibilità tra preferenze e necessità di scambio?", "answer": "Il baratto richiede in ogni momento che preferenze e necessità di scambio siano simili tra gli individui e siano al tempo stesso compatibili con i beni disponibili per lo scambio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0064", "question": "Come si supera il limite del baratto?", "answer": "Per superare i limiti del baratto dovrà essere individuato un unico bene da utilizzare per acquistare altri beni e che per sua natura sia generalmente accettato da tutti: tipicamente la moneta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0065", "question": "In quali epoche storiche fu utilizzato il baratto?", "answer": "Il baratto fu utilizzato diffusamente, oltre che nelle fasi primordiali della nostra civiltà, nella prima fase dell'Alto Medioevo a causa di economie chiuse ad assetto agrario-feudale, con pochi scambi mercantili di tipo monetario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0066", "question": "Come veniva usata la moneta durante il periodo in cui prevaleva il baratto?", "answer": "La moneta a circolazione locale veniva usata a quell'epoca ad integrazione del valore delle merci oggetto di baratto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-baratto"}},
{"id": "chunk_0067", "question": "Che problemi comporterebbe se la moneta fisica fosse l'unico mezzo di pagamento?", "answer": "Se la moneta fisica fosse l'unico mezzo di pagamento, si avrebbero enormi problemi di trasferimento delle ingenti quantità di moneta necessarie per le operazioni commerciali di grande valore e a lunga distanza, come si sperimentò, soprattutto nel XVI° secolo, nel commercio con le Americhe e con le \"Indie orientali\" (i paesi asiatici).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0068", "question": "Per quali tipi di transazioni aveva senso utilizzare la moneta fisica?", "answer": "La moneta fisica, infatti, aveva un senso per transazioni di ridotto importo e a brevi distanza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0069", "question": "Perché nacquero i primi banchi di credito in Italia?", "answer": "Anche per superare questi vincoli, già in epoca medievale, nascono in Italia i primi banchi di credito e, con essi, le prime forme di scritture contabili dei saldi monetari (depositi e prelievi) e, soprattutto, le prime forme di cartolarizzazione del credito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0070", "question": "Che cosa rappresentavano le \"lettere di cambio\"?", "answer": "Si trattava delle cosiddette \"lettere di cambio\", che rappresentavano il credito in oro vantato dai depositanti, i quali potevano scambiarle, come mezzi di pagamento di operazioni commerciali, evitando così le spese e i rischi connessi al trasporto della moneta fisica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0071", "question": "Come si sono sviluppate le moderne banche?", "answer": "Da quelle prime tecniche di gestione dei depositi monetari (cui poi si agganciarono, in naturale proseguimento, quelle relative alle richieste di finanziamento dietro garanzia di beni personali) si sono sviluppate le moderne banche, a tutt'oggi perno fondamentale del sistema finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0072", "question": "Che cosa si intende per moneta legale?", "answer": "Moneta legale (circolante): L'insieme di banconote e monete metalliche in circolazione in un determinato momento nel sistema economico che devono, per legge, essere accettate in pagamento, grazie all'esistenza di un'Autorità (tipicamente una banca centrale) che le emette (come sue passività per l'acquisto di attività finanziarie) e che agisce per garantirne il valore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0073", "question": "Che cos'è la moneta bancaria?", "answer": "Moneta bancaria: L'insieme dei mezzi di pagamento messi in circolazione dalle banche, a fronte di depositi bancari disponibili (quindi trasformabili in circolante in tempo breve), sotto forma ad es. di assegni circolari, bancari, carte di credito, bonifici e giroconti, ecc.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0074", "question": "Che cosa si intende per base monetaria?", "answer": "Base monetaria: Moneta legale e altre attività finanziarie che sono trasformabili in contante immediatamente e senza costo (o a costo prefissato) e che, in quanto tali, possono essere depositate come riserva obbligatoria presso la banca centrale dalle banche a fronte dei propri depositi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0075", "question": "Che cos'è l'offerta di moneta?", "answer": "Offerta di moneta: La quantità di moneta esistente in un determinato momento nel sistema economico, pari al circolante più i depositi della clientela presso le banche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0076", "question": "Che cosa si intende per moltiplicatore monetario?", "answer": "Il rapporto tra offerta di moneta e base monetaria prende il nome di moltiplicatore monetario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0077", "question": "Come la banca centrale crea moneta?", "answer": "La banca centrale crea moneta sia attraverso l'erogazione di finanziamenti alle banche commerciali, sia tramite operazioni di acquisto di strumenti finanziari sul mercato finanziario secondario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0078", "question": "Come crea moneta il sistema bancario?", "answer": "Il sistema bancario crea moneta tramite la concessione di finanziamenti da parte delle singole banche alle imprese e alle persone: i finanziamenti bancari significano risorse finanziarie disponibili e spendibili da parte di chi li riceve.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0079", "question": "Che cosa si intende per moltiplicazione dei depositi bancari?", "answer": "Queste risorse, sia che siano spese o semplicemente trasferite presso altre banche, danno origine ad un sistema di moltiplicazione dei depositi bancari utilizzabili come mezzi di pagamento (moneta bancaria).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0080", "question": "Il singolo istituto bancario può creare moneta?", "answer": "In questo modo non è la banca singola a creare moneta, ma è il sistema bancario nella sua totalità in virtù del meccanismo del cosiddetto moltiplicatore monetario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0081", "question": "Come il settore estero può influire sulla creazione di moneta?", "answer": "Esiste un altro canale di creazione (distruzione) di moneta (ossia base monetaria) ed è quello costituito dal settore \"Estero\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0082", "question": "Cosa succede in caso di saldo attivo della bilancia dei pagamenti?", "answer": "Nel caso di un saldo attivo della bilancia dei pagamenti si verifica un afflusso di valuta straniera all'interno del paese. Quando questa valuta viene ceduta alla Banca centrale in cambio di valuta nazionale si ha automaticamente creazione di base monetaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0083", "question": "Cosa avviene in caso di bilancia dei pagamenti negativa?", "answer": "Nel caso di bilancia dei pagamenti negativa, si ha vendita di valuta estera da parte della Banca centrale in cambio di valuta nazionale, con corrispondente distruzione, cioè sottrazione dal mercato, di base monetaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0084", "question": "Come si definisce l'offerta di moneta M?", "answer": "La quantità complessiva di moneta in circolazione (offerta di moneta, M) è costituita dalla moneta bancaria (depositi, D) più la base monetaria non trattenuta in riserva dalle banche e posseduta quindi dal pubblico (Bp). Si ha perciò la definizione: M = D + Bp.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0085", "question": "Come viene utilizzata la base monetaria immessa nel sistema?", "answer": "La consistenza complessiva di base monetaria, che è stata immessa nel sistema attraverso i canali di cui si detto, è in ogni momento utilizzata, cioè trattenuta, dal pubblico (famiglie e imprese) e dalle banche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0086", "question": "Perché il pubblico trattiene parte della base monetaria?", "answer": "Il pubblico la trattiene sotto forma di circolante per far fronte alle spese correnti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0087", "question": "Come utilizzano le banche la parte di base monetaria non trattenuta dal pubblico?", "answer": "La parte non trattenuta dal pubblico affluisce alle banche che la utilizzano per soddisfare l'obbligo di riserva obbligatoria e, in parte decisamente minore, per tenere a disposizione una riserva di liquidità per le necessità di tesoreria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0088", "question": "Qual è il limite alla capacità delle banche di creare moneta?", "answer": "Le banche trovano un limite nella propria capacità di \"creare\" moneta attraverso operazioni di credito nell'obbligo di mantenere riserve finanziarie liquide presso la banca centrale, a cui possono aggiungersi riserve liquide liberamente disponibili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0089", "question": "Perché le banche devono mantenere riserve liquide presso la banca centrale?", "answer": "Le riserve liquide delle banche presso la banca centrale (nei paesi dell'Euro-zona, presso la Banca Centrale Europea) sono proporzionate ai depositi bancari e servono a far fronte alle possibilità di inattesa richiesta di contante del pubblico (ossia richieste di conversione in moneta legale dei depositi stessi).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dalla-moneta-fisica"}},
{"id": "chunk_0090", "question": "Che cos'è la moneta fisica?", "answer": "Man mano che l'economia si articola su più attività produttive - grazie anche allo sviluppo delle tecniche lavorative, di una più diffusa presenza sul territorio di comunità organizzate stabili e di un sistema di vie di comunicazione in grado di consentire lo scambio a maggiori distanze - ogni singolo organismo economico (individuo, famiglia, piccola comunità) è maggiormente invogliato a produrre non solo ciò che serve al soddisfacimento dei propri bisogni, ma anche beni destinati alla vendita. Si crea così un mercato di scambio delle merci prodotte proprio per la rivendita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0091", "question": "Perché la moneta metallica si affermò come mezzo di scambio?", "answer": "La moneta metallica (e, più tardi, quella bancaria) si afferma come unico \"mezzo\" convenzionalmente accettato per l'acquisto e la vendita delle diverse merci presenti nel mercato, perché costituisce il modo più semplice per dare un valore e, quindi, poter scambiare tra una pluralità di soggetti la moltitudine di beni negoziabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0092", "question": "Quali caratteristiche deve avere la moneta per soddisfare le sue funzioni?", "answer": "Per soddisfare tutte queste funzioni in modo ottimale, la moneta deve essere disponibile, accessibile, durevole, fungibile, portatile e affidabile, ossia mantenere una capacità di acquisto di beni e servizi stabile nel tempo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0093", "question": "Quali sono le tre proprietà fondamentali della moneta?", "answer": "Le proprietà della moneta sono le tre seguenti: misura del valore dei beni e dei servizi; mezzo di pagamento comunemente accettato; deposito di valore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0094", "question": "In cosa consisteva il valore delle monete metalliche rispetto alle banconote?", "answer": "Per oltre due millenni le monete metalliche furono coniate in metalli preziosi (argento e oro). Le banconote - introdotte in Cina nel Seicento d.C. - furono utilizzate in Europa solo nel XVIII° secolo. Mentre le monete avevano un valore intrinseco determinato dal valore dei metalli, le banconote avevano un valore intrinseco nullo: rappresentavano solo una semplice \"promessa di pagamento\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0095", "question": "Che cos'era il regime aureo della moneta?", "answer": "Proprio per attribuire un valore (reale) alla moneta cartacea (più facile da gestire rispetto a quella metallica), nel XVIII° molti Stati introdussero un regime aureo della moneta: l'emissione di banconote era realizzata dalla banca centrale (avente il monopolio d'emissione delle monete) per un valore nominale pari al valore delle proprie riserve auree.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0096", "question": "Quando è terminato formalmente il regime aureo della moneta?", "answer": "Questo regime è cessato formalmente il 15 agosto 1971, quando il presidente degli Stati Uniti d'America, Richard Nixon, cancellò la possibilità di conversione in oro del dollaro USA.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0097", "question": "Da cosa dipende oggi il valore della moneta nelle economie moderne?", "answer": "Nelle economie moderne, il valore della moneta (cartacea, metallica o elettronica che sia) è esclusivamente costituito dal grado di fiducia che hanno i detentori di mantenere attraverso di essa il potere d'acquisto di beni e servizi nel tempo; tale valore è quindi fondato sulla credibilità/affidabilità dell'istituzione che emette moneta di \"governare\" l'economia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0098", "question": "Che cosa si intende per moneta a disposizione del pubblico?", "answer": "Quando si parla di moneta a disposizione del pubblico, occorre fare riferimento sia alla moneta legale emessa dalla banca centrale (il cosiddetto circolante), sia alla cosiddetta moneta bancaria, ossia ai mezzi di pagamento che si possono usare a fronte di depositi bancari (assegni, carte di credito, bonifici, ecc.).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-moneta-fisica"}},
{"id": "chunk_0099", "question": "Cosa si intende per sistema bancario ombra o intermediazione finanziaria non bancaria?", "answer": "Come sappiamo la crisi finanziaria del 2007-2008 ha determinato, in primo luogo, una presa di coscienza a livello mondiale dei cambiamenti intervenuti negli anni nella struttura dei sistemi finanziari e, in secondo luogo, un ripensamento sia dell'assetto regolamentare generale del sistema finanziario, sia della stessa politica macroprudenziale. In questo contesto un ruolo importante lo ha svolto il cosiddetto Sistema bancario ombra (Shadow Banking System), ossia quel complesso di mercati, istituzioni e intermediari che erogano servizi bancari senza essere soggetti alla relativa regolamentazione in quanto posti al di fuori del perimetro di applicazione delle relative norme (ad esempio: fuori dal perimetro di consolidamento dei conti bancari stabilito a livello normativo).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0100", "question": "Perché si è espanso il sistema bancario ombra prima della crisi del 2007-2008?", "answer": "L'espansione di questo sistema fu dovuto in larga parte alla decisione, assunta da diverse banche negli anni precedenti alla crisi (anche grazie all'utilizzo di nuove tecnologie informatiche e alla scoperta di nuovi strumenti di matematica finanziaria), di \"esternalizzare\" e portare fuori dal perimetro di consolidamento alcune attività caratterizzate, oltre che da elevati margini di interesse, da un forte profilo di rischio da una rilevante trasformazione delle scadenze e della liquidità e da una elevata leva finanziaria (anche tramite l'utilizzo di strumenti derivati).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0101", "question": "In che modo le banche hanno realizzato l'esternalizzazione delle attività nel sistema bancario ombra?", "answer": "Tali operazioni di 'esternalizzazione', ad esempio, furono realizzate tramite l'utilizzo di società veicolo (Structured investment vehicle- SIV e Conduit) che esibivano all'attivo gli impieghi a medio e lungo termine ceduti dalle banche e al passivo titoli a breve termine (le cosiddette Asset backed commercial paper - ABCP), garantiti dalle attività bancarie cedute e assistiti da linee di liquidità messe a disposizione dalle banche stesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0102", "question": "Quali intermediari operavano nel sistema bancario ombra secondo il Financial Stability Board nel 2011?", "answer": "Secondo quanto originariamente rilevato da questa task force nel 2011 nel sistema descritto operavano diverse tipologie di intermediari: fondi comuni monetari, società di private equity, hedge funds, società finanziarie specializzate, imprese di assicurazione e di riassicurazione, succursali e società controllate da istituzioni finanziarie e bancarie come gli SPV (special purpose vehicle) e i SIV (structured investment vehicle).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0103", "question": "Quanto era cresciuto il sistema bancario ombra tra il 2002 e il 2011 secondo il FSB?", "answer": "Si trattava di un \"mondo\" che - sempre secondo il FSB - ha conosciuto una crescita sostenuta passando da un valore delle transazioni complessivamente realizzate di 26 mila mld. di $ nel 2002 a quasi 67 mila mld. di $ nel 2011, pari al 111% del PIL mondiale e a circa la metà degli asset dell'intero sistema bancario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0104", "question": "Quali aree geografiche contribuivano maggiormente al sistema bancario ombra nel 2011?", "answer": "Di questo ammontare, il 35% viene generato negli Stati Uniti (ma era il 44% fino al 2007), il 33% nell'Unione Europea e il 13% nel Regno Unito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0105", "question": "Quando e perché il termine \"shadow banking\" è stato modificato in \"intermediazione finanziaria non bancaria\"?", "answer": "Nell'ottobre del 2018 il FSB ha annunciato che il termine \"shadow banking\" sarebbe stato modificato in \"intermediazione finanziaria non bancaria\" nelle comunicazioni future.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0106", "question": "Qual è l'ammontare stimato dell'intermediazione finanziaria non bancaria secondo il Report FSB del 2020?", "answer": "Dai dati raccolti nel Report dell'FSB del febbraio 2020 risulta che tale intermediazione ammonta a circa 51,6 mila mld. di $, La consistenza dello stesso è però molto variabile nei diversi Paesi, con percentuali (sugli asset finanziari totali nazionali) che oscillano tra il 4,7% e il 67%, registrate rispettivamente in Olanda e nelle Isole Cayman.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0107", "question": "Quali percentuali dello shadow banking system si registrano nei principali Paesi?", "answer": "Negli Stati Uniti, lo shadow banking system è risultato ancora in diminuzione e pari al 15,4%, mentre in Cina e Australia si registrano percentuali pari al 14,5% e 12,2%, rispettivamente. In Europa, invece, i tassi più elevati vengono riscontrati in Irlanda (45,3%), Lussemburgo (19,9%) e Germania (11,3%). In Italia, il sistema bancario ombra è meno sviluppato e si attesta al 7,9%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0108", "question": "Quali rischi sistemici comporta lo Shadow Banking System?", "answer": "I rilevanti rischi sistemici determinati dallo Shadow Banking System (tra cui la sua interdipendenza con il sistema bancario, il forte contagio tra intermediari, il disallineamento rispetto al regime prudenziale proprio delle banche, ecc.) hanno accresciuto la consapevolezza circa la probabilità di sviluppo di crisi sistemiche con gravi effetti negativi sull'economia reale, indipendentemente dal paese o dall'area geografica nei quali si origina il fenomeno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0109", "question": "Perché le attività di shadow banking hanno attirato l'attenzione dei regolatori internazionali?", "answer": "Per questa ragione le attività di shadow banking hanno attirato l'attenzione dei regolatori, che hanno approntato diverse misure a livello mondiale (in primis negli Stati Uniti e in Europa) per porre dei freni alla crescita incontrollata e non regolamentata del settore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0110", "question": "Quali potenzialità positive individua la Commissione Europea nello shadow banking regolamentato?", "answer": "Al di là degli aspetti critici legati al sistema di shadow banking, quest'ultimo, come evidenziato dallla Commissione Europea, se ed in quanto opportunamente regolamentato, potrebbe rappresentare uno degli strumenti più efficaci (alternativi rispetto al \"tradizionale\" sistema di finanziamento bancario delle imprese) per promuovere la crescita in Europa. Con esso, infatti, si potrebbero sviluppare per le imprese forme alternative di finanziamento all'indebitamento bancario, così come il ricorso diretto al mercato dei capitali e ciò all'interno di quel più ampio percorso strategico che potrebbe portare a breve alla creazione in Europa di un mercato unico dei capitali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/intermediazione-finanziaria"}},
{"id": "chunk_0111", "question": "Che cos'è il sistema finanziario?", "answer": "Il sistema finanziario è un insieme complesso di rapporti di credito e debito di tipo dinamico e multi-relazionale, costruito su una fitta rete di legami contrattuali che mette in collegamento - attraverso il canale diretto dei mercati finanziari e quello indiretto degli intermediari finanziari - tutti gli attori del sistema economico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0112", "question": "Qual è l'importanza del sistema finanziario per l'economia?", "answer": "Il sistema finanziario è importante per il funzionamento dell'economia nel suo complesso, poiché si alimenta di informazioni e produce informazioni necessarie agli operatori economici per definire i propri piani d'investimento e le proprie strategie e, in una parola, per far funzionare l'economia in generale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0113", "question": "Perché gli operatori economici cercano informazioni non pubbliche?", "answer": "È proprio la distribuzione non uniforme e asimmetrica delle informazioni che si verifica nella realtà a spingere gli operatori a ricercare informazioni non pubblicamente disponibili e a pagarne il costo, al fine di ottenere extra-profitti dallo sfruttamento delle stesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0114", "question": "Qual è la connotazione internazionale del sistema finanziario?", "answer": "Il sistema finanziario ha una rilevante connotazione internazionale per la forte interdipendenza dei sistemi finanziari nazionali, in virtù delle interconnessioni tra i diversi mercati dei capitali di tutti i Paesi sviluppati e delle diffuse relazioni contrattuali tra intermediari internazionali e altri soggetti appartenenti a tutti i Paesi che consentono il libero movimento dei capitali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0115", "question": "Che cos'è la globalizzazione della finanza?", "answer": "La facilità tecnica e legale di movimento dei capitali finanziari è alla base della cosiddetta globalizzazione della finanza, fenomeno che inevitabilmente comporta rilevanti implicazioni socio-economiche nei singoli Paesi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0116", "question": "Quali sono le principali funzioni del sistema finanziario?", "answer": "Le funzioni principali del sistema finanziario sono quelle di: fornire al sistema economico i mezzi di pagamento necessari per assicurare il funzionamento del circuito di produzione e distribuzione del reddito (funzione monetaria); favorire la distribuzione delle risorse finanziarie nei diversi settori economici per finalità d'impiego produttivo (funzione allocativa); gestione dei rischi finanziari connessi agli investimenti effettuati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0117", "question": "Che cos'è la funzione monetaria del sistema finanziario?", "answer": "Se si guarda alla funzione monetaria, il sistema finanziario è da intendersi quale rete di pagamenti che interconnette soggetti (banche, in primo luogo, ma anche nuovi intermediari-gestori di piattaforme telematiche) appartenenti a diversi Paesi: esso è funzionale a regolare in moneta gli scambi commerciali a livello internazionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0118", "question": "Che cos'è la funzione allocativa del sistema finanziario?", "answer": "Se si guarda alla funzione di allocazione delle risorse finanziarie, il sistema finanziario deve essere inteso come un'articolazione complessa di operazioni su attività/passività finanziarie che coinvolge intermediari, imprese, investitori, gestori di mercati di negoziazione, gestori di infrastrutture operative, \"regole del gioco\" e sistema dei controlli pubblici e privati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0119", "question": "Che cosa significa finanziamento esterno diretto?", "answer": "Si ha finanziamento esterno diretto quando il soggetto che risparmia (ad esempio famiglie) cede - attraverso i mercati finanziari che sono mercati «aperti» - le proprie disponibilità monetarie direttamente al soggetto (imprese o pubblica amministrazione) che si trova in disavanzo finanziario, accettando in cambio attività finanziarie (azioni, obbligazioni, Buoni del Tesoro, ecc.) emesse da quest'ultimo e costituenti sue passività. Il rischio dell'investimento è direttamente sostenuto dal risparmiatore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0120", "question": "Che cosa si intende per investimento intermediato?", "answer": "Si ha un investimento intermediato quando chi risparmia trasferisce le sue disponibilità ad un intermediario finanziario che, a sua volta, effettua a proprio nome, ma per conto del risparmiatore, investimenti finanziari in passività di soggetti in deficit tramite operazioni sul mercato degli strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0121", "question": "Qual è il beneficio di un efficiente sistema finanziario?", "answer": "Il beneficio di un efficiente sistema finanziario risiede nella capacità di far circolare risorse finanziarie tra soggetti in surplus e soggetti in deficit, rendendo disponibili nuove risorse finanziarie a quei soggetti (gli imprenditori) che introducono - mediante gli investimenti finanziati - innovazioni nei beni e servizi destinati al mercato e/o nei processi produttivi, così sostenendo il processo di crescita dell'economia nel suo complesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0122", "question": "Da cosa dipendono le caratteristiche del sistema finanziario di un Paese?", "answer": "Le caratteristiche del sistema finanziario di ciascun Paese (o di Paesi istituzionalmente uniti, come nell'Unione Europea) sono il frutto dell'evoluzione storica e del contesto istituzionale ed economico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0123", "question": "Quali sono le differenze tra la struttura finanziaria dell'Eurozona e quella degli Stati Uniti?", "answer": "Con riguardo all'area dell'Eurozona, la struttura finanziaria è caratterizzata da un ruolo predominante del sistema bancario mentre, al contrario, la struttura finanziaria degli Stati Uniti è caratterizzata da una maggiore incidenza dei mercati mobiliari (cioè dei mercati degli strumenti finanziari).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0124", "question": "Che cos'è il modello di banca universale?", "answer": "La stessa articolazione delle attività svolte da una banca nel contesto europeo, con l'estensione delle tradizionali attività creditizie alla prestazione dei servizi d'investimento e alla distribuzione di prodotti assicurativi (secondo un modello cosiddetto di \"banca universale\"), mette in crisi una lettura puramente formale del sistema finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0125", "question": "Chi può raccogliere risparmio e fornire risorse finanziarie alle imprese oltre alle banche?", "answer": "La raccolta del risparmio tra il pubblico e l'erogazione del credito non è più una prerogativa delle banche: la nascita di nuovi intermediari finanziari (per esempio, i gestori di fondi comuni d'investimento alternativi) - che possono raccogliere risparmio anche tra il pubblico degli investitori al dettaglio per fornire risorse finanziarie alle imprese o tramite prestiti diretti (cosiddetti loan origination), ovvero tramite investimenti in strumenti finanziari di debito o rappresentativi di capitali di rischio ovvero di credito cartolarizzato - tende a moltiplicare i canali di finanziamento dell'economia reale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0126", "question": "Che cos'è il sistema bancario ombra?", "answer": "Lo sviluppo dei fondi comuni d'investimento in strumenti di mercato monetario, che hanno la caratteristica di rendere liquidi e a valori stabili gli investimenti nelle quote dei fondi medesimi da parte delle direzioni finanza delle grandi imprese (soprattutto multinazionali), ha incrinato il convincimento che siano solo le banche ad emettere passività aventi funzioni monetarie (\"Il sistema bancario ombra\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0127", "question": "Perché il sistema finanziario attuale è più complesso rispetto al passato?", "answer": "Il sistema finanziario attuale è quindi profondamente diverso e più complesso rispetto al passato. L'innovazione finanziaria genera continuamente nuovi prodotti che possono generare nuovi rischi: l'interconnessione dei mercati ha aumentato la capacità di propagazione a tutto il sistema delle crisi sorte in un punto qualsiasi dello stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0128", "question": "Quali rischi derivano dall'illusione di poter controllare totalmente i rischi finanziari?", "answer": "Negli ultimi tempi si è immotivamente affermata la presunzione di poter controllare i rischi, fino all'illusione del loro annullamento. Questo ha portato a creare enormi posizioni di rischio degli operatori su scala globale, non debitamente valutate, mettendo a repentaglio la capacità dell'economia di funzionare secondo principi di libero mercato sulla base della reciproca fiducia delle controparti private ad adempiere alle proprie obbligazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0129", "question": "Quali sono i principali temi di discussione nelle sedi istituzionali internazionali riguardo la finanza?", "answer": "Il monitoraggio dell'innovazione finanziaria, il dosaggio delle regole da applicare e le modalità di attuazione delle forme di cooperazione tra Stati per la vigilanza a livello sovra-nazionale costituiscono i principali temi di discussione nelle sedi istituzionali pubbliche internazionali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0130", "question": "Quali sono i punti critici da considerare nella regolamentazione del sistema finanziario?", "answer": "Molti sono i punti critici che - con riferimento al sistema finanziario - vanno attentamente ponderati: fiducia dei partecipanti nel funzionamento del sistema: regole efficaci e certezza di applicazione; stabilità del sistema: posizioni di rischio finanziario compatibili con le prospettive dell'economia – circoscrivere le crisi per evitare gli effetti-contagio; efficienza allocativa: diffusione di informazioni macro-economiche e micro-economiche tempestive e affidabili; regole prudenziali, di correttezza e trasparenza comportamentali omogenee per paesi e diversi settori dell'intermediazione finanziaria; funzionalità ed integrità dei mercati finanziari a tutela di tutti i partecipanti; assetto dei controlli pubblici coerenti con la natura globale della finanza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-sistema-finanziario-attuale-una-stilizzazione"}},
{"id": "chunk_0131", "question": "Che cos'è il sistema finanziario?", "answer": "Il sistema finanziario costituisce l'«impianto cardio-vascolare» dell'«organismo economia». Esso rende \"produttivo\" il risparmio privato trasformandolo, attraverso i mercati finanziari, in investimento in attività produttive e favorendo così la crescita dell'economia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/sistema-finanziario"}},
{"id": "chunk_0132", "question": "Qual è il ruolo del sistema finanziario nell'economia?", "answer": "Il sistema finanziario rende \"produttivo\" il risparmio privato trasformandolo, attraverso i mercati finanziari, in investimento in attività produttive e favorendo così la crescita dell'economia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/sistema-finanziario"}},
{"id": "chunk_0133", "question": "Perché il sistema finanziario è considerato fragile?", "answer": "Il sistema economico-finanziario è fragile perché fondato sul senso di fiducia reciproca di tutti gli attori in gioco.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/sistema-finanziario"}},
{"id": "chunk_0134", "question": "Perché il sistema finanziario è considerato incompleto?", "answer": "Il sistema economico-finanziario è incompleto perché non tutti i beni sono negoziabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/sistema-finanziario"}},
{"id": "chunk_0135", "question": "Quali sono le caratteristiche principali del sistema economico-finanziario basato sui mercati?", "answer": "Il sistema economico-finanziario basato sui mercati, per molti versi insostituibile, costituisce un \"marchingegno\" da un lato fragile, perché fondato sul senso di fiducia reciproca di tutti gli attori in gioco, e, dall'altro, incompleto, perché non tutti i beni sono negoziabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/sistema-finanziario"}},
{"id": "chunk_0136", "question": "Cosa sono i contratti finanziari derivati?", "answer": "Come già accennato, i contratti finanziari cosiddetti derivati hanno normalmente la funzione di assicurazione o di copertura e trasferimento del rischio finanziario tra due parti. Oltre a questo utilizzo \"classico\", la negoziazione di derivati può essere effettuata per motivi di arbitraggio oppure per mera speculazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0137", "question": "Cosa si intende per \"sottostante\" in un contratto derivato?", "answer": "Sotto tale categoria può essere fatto rientrare ogni strumento il cui prezzo sia basato sul valore di un'altra attività, definito \"sottostante\" (come, ad esempio, azioni, indici finanziari, valute, tassi d'interesse, materie prime, fino ad arrivare perfino agli eventi climatici).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0138", "question": "Quali sono le origini storiche dei contratti derivati?", "answer": "Alcuni strumenti derivati hanno origini antiche; infatti, i contratti a termine erano usati già ai tempi dei greci e dei romani. Aristotele racconta che nel 580 a.c. Talete di Mileto si arricchì stipulando in inverno (quando la domanda era bassa) un'opzione sull'utilizzo in autunno di alcuni frantoi (momento della massima domanda).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0139", "question": "Quando nacquero i primi contratti futures?", "answer": "L'origine dei futures risale all'età romana; in quel periodo esistevano dei mercati, chiamati fora vendalia, specializzati nella vendita di particolari produzioni agricole, che vi giungevano da ogni parte dell'Impero. Solo nel Medioevo, però, si è assisto alla nascita di moderni mercati futures, che si tenevano presso fiere stagionali, in particolare nella regione dello Champagne in Francia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0140", "question": "Qual era lo scopo dei mercati futures medievali?", "answer": "Tali mercati si svilupparono per venire incontro alle necessità degli agricoltori e dei mercanti; gli accordi che si stringevano in queste occasioni avevano per oggetto un raccolto futuro ed il principale obbiettivo era quello di giungere ad un prezzo giusto e a consentire alle parti di eliminare il rischio relativo all'incertezza sul prezzo futuro del grano.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0141", "question": "Qual è il primo esempio di contratto derivato stipulato da un ente locale?", "answer": "Nel 1164 a Genova nacque il primo contratto derivato stipulato da un ente locale con la vendita ad un istituto finanziario (Monte) delle entrate fiscali future del Comune in cambio di un anticipo immediato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0142", "question": "Quando nacquero i mercati organizzati per lo scambio di derivati?", "answer": "I primi mercati organizzati per lo scambio di derivati risalgono al sedicesimo e diciassettesimo secolo. Nel 1600 ci fu l'ammissione alla negoziazione al Royal Exchange di Londra di contratti forward (cui seguiva nel 1637 la prima bolla speculativa sui tulipani).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0143", "question": "Quando si è avvertita l'esigenza di standardizzare i contratti derivati?", "answer": "Solo a seguito della rivoluzione industriale, alla fine del diciottesimo secolo, si avvertì l'esigenza di standardizzare questo tipo di contratti, quando i mercanti europei, che si occupavano di importazioni dagli Stati Uniti, iniziarono a stipulare contratti sul cotone e sui grani detti \"to-arrive contract\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0144", "question": "Quali fattori hanno favorito la diffusione dei derivati nella seconda metà del XX secolo?", "answer": "A partire dalla seconda metà del ventesimo secolo questi strumenti hanno conosciuto una notevole diffusione legata a vari fattori: la fine, nel 1971, del sistema internazionale di cambi fissi per la caduta degli accordi di Bretton Woods, con il conseguente emergere del rischio di cambio; gli shock petroliferi del 1973 e del 1979; la globalizzazione dei mercati e la contestuale introduzione dei computer; la modellizzazione teorica per il calcolo del prezzo dei derivati, attraverso il lavoro di Black, Scholes e Merton.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0145", "question": "Qual è stata la diffusione quantitativa dei derivati tra il 1989 e il 1992?", "answer": "Tra il 1989-1992 i derivati si diffusero in modo rilevante arrivando ad una consistenza complessiva pari a 20.000 mld. di $.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0146", "question": "Quali eventi frenarono temporaneamente l'espansione dei derivati negli anni '90?", "answer": "Dopo le ingenti perdite accusate da grandi aziende, quali la Metallgesellschaft nel 1993 e la Procter & Gamble nel 1994, e il fallimento della Barings Bank nel 1995, questa espansione rallentò per qualche anno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0147", "question": "Qual era il valore complessivo delle attività sottostanti ai derivati nel 2010?", "answer": "Già nel dicembre 2010, però, il valore complessivo delle attività sottostanti i derivati ammontava a circa 670.000 mld. di $, di cui 601.048 per derivati Over The Counter (OTC), con prevalenza tra questi degli Interest Rate Swaps (IRS) per un ammontare pari a 364.378 mld. di $.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0148", "question": "Cosa indica il confronto tra PIL mondiale e valore dei derivati nel 2010?", "answer": "Considerato che il PIL mondiale, intorno al 2010, era stato stimato in circa 70.000 mld. di $, risulta di semplice percezione il livello di leva finanziaria utilizzato dai mercati finanziari attraverso l'utilizzo dei prodotti derivati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0149", "question": "Perché i derivati sono considerati prodotti di difficile comprensione?", "answer": "I prodotti derivati sono comunemente considerati come opachi, di difficile comprensione e, pertanto, i piccoli risparmiatori scelgono di tenersene lontani. A molti investitori, però, non risulta chiaro come alcuni prodotti di generale diffusione - come ad esempio mutui ipotecari, ovvero \"semplici\" obbligazioni - possano contenere al loro interno dei derivati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0150", "question": "Come può un mutuo a tasso variabile contenere un derivato?", "answer": "Quando si stipula un mutuo a tasso variabile, ad esempio, la banca ci offre spesso di abbinare al contratto una clausola per la copertura da possibili rialzi dei tassi di interesse (i famosi mutui con Cap). La stipula di un mutuo con queste caratteristiche comporta l'acquisto da parte nostra di un derivato, la banca, infatti, non si trasforma in un ente benefico che ci protegge in caso di rialzo dei tassi ma semplicemente acquista un'opzione di tipo Cap per la copertura del rischio di aumento del tasso d'interesse, che con il Cap graverebbe sulla banca, al di sopra di una certa soglia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0151", "question": "Perché un mutuo con Cap costa di più di un mutuo variabile puro?", "answer": "Questa copertura ha un costo che viene caricato sul mutuo con un aumento del tasso, per questo motivo esiste una differenza, a parità di altre condizioni, tra il tasso di un mutuo variabile puro e di un variabile con Cap.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0152", "question": "Come l’innovazione finanziaria ha modificato i mercati finanziari?", "answer": "Il processo di innovazione finanziaria che ha caratterizzato i mercati finanziari nel corso degli ultimi anni ha anche tratto impulso dalla convergenza nel settore di imprese di matrice bancaria ed assicurativa, rendendo di fatto incerti i confini tra prodotti/strumenti finanziari offerti da operatori soggetti a diversa regolamentazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0153", "question": "Cosa sono le obbligazioni strutturate e quali rischi comportano?", "answer": "Si pensi al fenomeno delle obbligazioni bancarie cosiddette strutturate, ovvero a titoli di debito emessi da intermediari bancari che possono essere scomponibili in una componente obbligazionaria (comunemente considerata come prodotto sicuro e caratterizzata da un basso grado di rischio) ed in una o più componenti derivative e il cui rendimento è regolato sulla base di parametri collegati al verificarsi o meno di certi eventi imputabili all'andamento ad es. di un titolo azionario (equity-linked), di un indice azionario (index-linked) o al merito creditizio di un emittente (credit-linked). Aspetti che, soprattutto in ottica di vigilanza, devono essere attentamente valutati nell'ambito della tutela dei profili di trasparenza e di correttezza del comportamento degli intermediari coinvolti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-uso-dei-derivati-finanziari"}},
{"id": "chunk_0154", "question": "Cosa è la leva finanziaria?", "answer": "Attraverso l'utilizzo della leva finanziaria (o \"leverage\") un soggetto ha la possibilità di acquistare o vendere attività finanziarie per un ammontare superiore al capitale posseduto e, conseguentemente, di beneficiare di un rendimento potenziale maggiore rispetto a quello derivante da un investimento diretto nel sottostante e, di converso, di esporsi al rischio di perdite molto significative.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0155", "question": "Come funziona la leva finanziaria?", "answer": "Vediamo come funziona il concetto di leva partendo da un caso semplice. Ipotizziamo di avere 100 € a disposizione da investire in un titolo. Poniamo che le aspettative di guadagno o perdita siano pari al 30%: se le cose vanno bene, avremo 130 €, in caso contrario, avremo 70 €. Questa è una semplice speculazione in cui scommettiamo su un determinato evento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0156", "question": "Cosa succede se utilizziamo una leva finanziaria di 10 a 1?", "answer": "Nel caso in cui decidessimo di rischiare di più investendo, oltre ai nostri 100 €, anche altri 900 € presi in prestito, allora l'investimento assumerebbe un'articolazione diversa poiché utilizziamo una leva finanziaria di 10 a 1 (investiamo 1000 € avendo un capitale iniziale unicamente di 100). Se le cose andranno bene e il titolo sale del 30%, riceveremo 1300 €, restituiamo i 900 presi in prestito con un guadagno di 300 € su un capitale iniziale di 100. Otteniamo, quindi, un profitto del 300% con un titolo che in sé dava un 30% di rendimento. Ovviamente sui 900 € presi in prestito dovremo pagare un interesse, ma il principio generale rimane valido: la leva finanziaria permette di aumentare i possibili guadagni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0157", "question": "Come si applica la leva finanziaria negli investimenti in derivati?", "answer": "Ipotizziamo di comprare un derivato che, tra un mese, dà il diritto di comprare 100 grammi di oro a un prezzo fissato oggi di 5.000 €. Potremmo comprare fisicamente l'oro con un esborso di 5000 € e tenerlo aspettando che il prezzo salga per poi rivendermelo. Se decidessimo invece di usare i derivati, non dovremmo avere 5000 €, ma unicamente il capitale necessario per comprare il derivato. Mettiamo che una banca vende per 100 € il derivato che ci consente di comprare tra un mese gli stessi 100 grammi di oro a 5.000 €. Se tra un mese l'oro vale 5.500, lo possiamo comprare e rivendere immediatamente, realizzando un guadagno di 500 €. Tolti i 100 € del prezzo del derivato realizziamo con 100 € un profitto di 400 €, ovvero del 400%. Senza usare i derivati e la leva finanziaria, gli stessi 500 € li avrei potuti guadagnare solo a fronte di un investimento di 5.000 €, realizzando un profitto del 10%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0158", "question": "Quali sono le potenzialità dell'utilizzo della leva finanziaria?", "answer": "Le potenzialità dell'utilizzo della leva finanziaria sono chiare. Attenzione però: l'effetto moltiplicatore della leva finanziaria, descritto con gli esempi precedenti, funziona anche nel caso in cui l'investimento dovesse andare male. Ad esempio, nel caso in cui decidessimo di investire 100 € in nostro possesso più un'ulteriore somma di 900 € presi in prestito, se il titolo si deprezzasse del 30%, rimarremmo con soli 700 € in mano; dovendo restituire i 900 € presi in prestito più gli interessi e considerando i 100 € del nostro investimento iniziale avremmo una perdita di oltre 300 € su un capitale iniziale di 100 €. In percentuale la perdita sarebbe quindi del 300% a fronte di una diminuzione del valore del titolo del 30%. Altro elemento da tenere ben presente è che le diverse leve finanziarie si possono cumulare: in questo modo si realizzano operazioni di speculazione utilizzando una \"leva finanziaria al quadrato\" con evidenti riflessi sulle possibili potenziali perdite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0159", "question": "Quali sono i rischi della leva finanziaria?", "answer": "Quello che può sembrare uno strumento interessante con potenzialità positive per l'investitore presenta, invece, dei rischi che devono quindi essere tenuti nella dovuta considerazione. Infatti, se il sistema finanziario nel suo complesso lavora con una leva molto elevata e gli istituti finanziari si prestano soldi a vicenda per moltiplicare i possibili profitti, la perdita di un singolo investitore può innescare un effetto domino contagiando l'intero mercato finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0160", "question": "Come operano le banche con la leva finanziaria?", "answer": "Le banche sono tipicamente dei soggetti che operano con un grado più o meno elevato di leva finanziaria: a fronte di un determinato capitale netto, il totale delle attività in cui le risorse sono investite è generalmente molto più elevato. Ad esempio, una banca con capitale proprio pari a 100 € e leverage pari a 20 gestisce attività per 2.000 €. Una perdita dell'1% delle attività comporta la perdita del 20% del capitale proprio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0161", "question": "Quale effetto ha avuto lo sviluppo del mercato per il trasferimento del rischio di credito sulla leva finanziaria?", "answer": "Lo sviluppo del mercato per il trasferimento del rischio di credito (dagli intermediari finanziari al mercato) ha fatto sì che il modello di banca tradizionale, denominato \"originate-and-hold\" («crea e detieni»: la banca che ha erogato il prestito lo mantiene in bilancio fino alla scadenza), sia stato sostituito per molti operatori da quello \"originate-to-distribute\" («crea e distribuisci»: l'intermediario seleziona i debitori, ma poi trasferisce ad altri il prestito, recuperando la liquidità e il capitale regolamentare prima impegnati (cartolarizzazione) o il puro rischio di credito (derivati creditizi), con benefici solo sui requisiti patrimoniali), con l'effetto di un ulteriore incremento della leva finanziaria. La diffusione di questo secondo modello di banca è uno dei fattori che spiegano la crisi innescatasi sul mercato dei mutui subprime.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0162", "question": "Che relazione c'è tra leva finanziaria e crisi dei mutui subprime?", "answer": "L'inflazione dei prezzi immobiliari ha sostenuto l'emissione dei prestiti cartolarizzati e lo sviluppo esponenziale del relativo mercato, consentendo alle banche di realizzare enormi profitti e, allo stesso tempo, incrementare la leva finanziaria. Ma \"la macchina da soldi\" non poteva durare a lungo e alla fine molte banche si sono ritrovate senza capitale sufficiente per assorbire le perdite derivanti dall'inversione di tendenza del mercato immobiliare, risultando di fatto come aziende fallite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0163", "question": "Come si è diffuso l'uso della leva finanziaria nel sistema finanziario?", "answer": "Nel frattempo l'esempio delle banche si è diffuso all'interno del sistema finanziario propagandosi a tutte le altre istituzioni finanziarie: la leva finanziaria aveva preso il sopravvento, soprattutto negli Stati Uniti, generando un enorme volume di investimenti a rischio che poggiava su una frazione infinitesima di capitale azionario. Pensiamo all'emissione dei cosiddetti \"credit default swaps\" (strumenti derivati utilizzati per coprirsi dal rischio di default del soggetto debitore): alcune compagnie di assicurazione erano fortemente esposte sul mercato immobiliare e quando quest'ultimo è crollato e il valore dei mutui è sceso, hanno cominciato a perdere senza aver capitale sufficiente per assorbire le perdite derivanti dall'emissione di quegli strumenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0164", "question": "Come possono le banche ridurre la leva finanziaria per evitare il fallimento?", "answer": "Per non rischiare di fallire e ritornare a livelli di capitale bancario sufficiente si può ricorrere ad aumenti di capitale (operazione non semplice in tempi di crisi), alla riduzione dell'importo dei prestiti alle imprese (concessione di un numero inferiore di nuovi prestiti e non rinnovo di quelli già emessi) e alla dismissione di altre attività liquide (per lo più azioni). Il risultato di tutto ciò, nel periodo di scoppio della crisi dei subprime, è stato un congelamento del credito e un crollo del mercato azionario. Questi sono i principali canali attraverso cui la crisi finanziaria ha colpito l'economia reale. Il razionamento del credito ha colpito gli investimenti e il calo del mercato azionario (che si aggiunge al calo dei prezzi delle abitazioni) ha ridotto il valore della ricchezza delle famiglie e quindi dei consumi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0165", "question": "Qual è il ruolo della leva finanziaria nella crescita economica?", "answer": "Sappiamo che un determinato livello di leverage è fisiologico per sostenere la crescita economica, anche se non abbiamo indicazioni di quale ne sia il livello ottimale. La storia però ci insegna come in un sistema economico-finanziario sempre più globalizzato e interdipendente la leva finanziaria possa rappresentare un fattore scatenante delle bolle speculative. Ed è in questi periodi che si genera lo scollamento più forte tra finanza ed economia reale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-leva-finanziaria"}},
{"id": "chunk_0166", "question": "Cosa è la securitisation?", "answer": "La \"securitisation\" è una tecnica finanziaria usata per attingere risorse finanziarie aggiuntive sempre più diffusa nel panorama economico finanziario. La sua diffusione come strumento per la raccolta di finanziamenti e come fonte alternativa di reddito è cresciuta notevolmente negli ultimi anni, tanto nel settore privato quanto in quello pubblico, divenendo una delle componenti principali del cosiddetto \"sistema bancario ombra\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0167", "question": "Quale ruolo ha avuto la securitisation nella crisi finanziaria del 2007-2009?", "answer": "Con riferimento alla crisi succitata, la cartolarizzazione ha consentito alle banche di alimentare il meccanismo di concessione dei mutui subprime «senza preoccupazioni». Nel pieno della crisi finanziaria del 2007-2009 la securitisation è stata individuata come uno dei maggiori responsabili della stessa e, conseguentemente, l'attenzione degli investitori, dei legislatori e dei regolatori non è sicuramente stata più benevola nei confronti dello strumento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0168", "question": "Come funziona tecnicamente la cartolarizzazione del debito?", "answer": "Tecnicamente, la cartolarizzazione del debito è un processo attraverso il quale una o più attività finanziarie indivise ed illiquide, in grado di generare dei flussi di cassa, quali ad esempio i crediti di una banca, vengono \"trasformate\" in attività divise e vendibili, ossia in titoli obbligazionari denominati Asset Backed Securities (ABS).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0169", "question": "Quali tipi di titoli possono derivare dalla cartolarizzazione?", "answer": "A seconda del sottostante che viene cartolarizzato, si può parlare ad es. di titoli MBS (mortgage backed securities, il cui sottostante sono mutui), CDO (collateralized debt obligation, il cui sottostante sono titoli obbligazionari pubblici o privati), ABCP (asset backed commercial paper, il cui sottostante è rappresentato da crediti a brevissimo/breve termine).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0170", "question": "Puoi fare un esempio pratico di cartolarizzazione?", "answer": "Classico esempio di cartolarizzazione è rappresentato da una banca che abbia fra le sue attività un certo numero di prestiti immobiliari; se la banca decide di cartolarizzare tali attività allora emetterà dei titoli, che hanno come garanzia quei mutui, che poi verranno venduti a investitori privati o istituzionali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0171", "question": "Qual è il ruolo della Società Veicolo (SPV) nella cartolarizzazione?", "answer": "La banca cede l'insieme dei suoi mutui ad una Società Veicolo (la Special Purpose Vehicle, brevemente SPV), istituita ad hoc, la quale emette delle obbligazioni (nel caso specifico dei mutui le Mortgage Backed Securities) che colloca presso gli investitori, e successivamente utilizza il ricavato della vendita delle obbligazioni per acquistare i mutui stessi. In tal modo il rischio viene trasferito ai sottoscrittori finali delle obbligazioni, in quanto il rimborso degli interessi che maturano e del capitale a scadenza collegato alle obbligazioni è strettamente dipendente dalla effettiva riscossione delle rate dei mutui stessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0172", "question": "Da cosa dipendono i pagamenti destinati agli investitori in titoli cartolarizzati?", "answer": "I pagamenti destinati agli investitori in titoli cartolarizzati dipendono esclusivamente dai flussi di cassa prodotti dai crediti ceduti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0173", "question": "Come si è evoluto il mercato delle cartolarizzazioni prima e dopo la crisi del 2008?", "answer": "Negli anni antecedenti la crisi dei mutui subprime vi è stata una crescita molto sostenuta delle cartolarizzazioni a livello globale, raggiungendo un picco (nell'ammontare in circolazione) pari rispettivamente a circa 11 mila mld. di $ negli Stati Uniti e a 2 mila mld. di € in Europa. Mentre negli Stati Uniti, dopo il tracollo del 2008, tali consistenze si sono riprese, in Europa la ripartenza è stata più lenta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0174", "question": "Cosa sono le CDO-squared?", "answer": "Le CDO-squared possono essere considerate delle vere e proprie CDO \"al quadrato\" o CDO sintetiche. Al posto di avere come sottostante un portafoglio di obbligazioni, prestiti e altri titoli di credito, le CDO-squared sono quindi supportate da emissioni di CDO.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0175", "question": "Qual è lo scopo delle CDO-squared per le banche?", "answer": "In pratica, le CDO-squared consentono alle banche di \"impacchettare\" il rischio di credito di cui si sono fatte carico detenendo delle CDO. Le SPV con le CDO-squared \"impacchettano\" delle CDO che poi verranno divise in tranches e vendute agli investitori sui mercati finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0176", "question": "Cosa sono i CDO-cubed?", "answer": "I CDO-cubed sono prodotti finanziari il cui sottostante è rappresentato da titoli di CDO-squared.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0177", "question": "Quali rischi ha comportato la proliferazione di strumenti come le CDO-squared e i CDO-cubed?", "answer": "La proliferazione di questi strumenti sempre più complessi ha consentito una moltiplicazione delle emissioni e un trasferimento dei rischi delle attività originarie sottostanti senza più controllo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0178", "question": "Come viene vista oggi la securitisation dopo la crisi finanziaria?", "answer": "Una volta messa in sicurezza la stabilità finanziaria, anche per via dei numerosi provvedimenti legislativi e regolamentari che hanno riguardato il settore finanziario, la securitisation è oggi nuovamente vista come un meccanismo potenziale per favorire il trasferimento dei rischi e per incrementare la capacità delle banche di liberare risorse ulteriori da destinare al finanziamento dell'economia, divenendo, di fatto, un 'ponte' naturale tra il credito di origine bancaria e la finanza basata sul mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-securitisation-"}},
{"id": "chunk_0179", "question": "Che cosa si intende per quadro regolamentare europeo nel settore finanziario?", "answer": "Il quadro regolamentare per il settore finanziario risulta ad oggi fortemente composito. La disciplina nazionale è infatti affiancata da norme prodotte a livello europeo secondo gli obiettivi di libera circolazione e integrazione dei mercati previsti dal Trattato sul Funzionamento dell'Unione Europea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0180", "question": "Quale evento ha segnato un rilevante sviluppo della produzione regolamentare europea in materia finanziaria?", "answer": "La produzione regolamentare europea in materia finanziaria ha registrato un rilevante sviluppo a seguito dell'emanazione da parte della Commissione Europea del Financial Services Action Plan, in data 11 maggio 1999.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0181", "question": "Quali erano gli obiettivi strategici del Financial Services Action Plan?", "answer": "Il Financial Services Action Plan individuava quali obiettivi strategici per lo sviluppo del settore finanziario europeo: (i) l'integrazione dei mercati finanziari all'ingrosso, (ii) l'apertura e la sicurezza dei mercati e dei servizi finanziari al dettaglio e (iii) l'armonizzazione e il rafforzamento delle regole di vigilanza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0182", "question": "Quanti e quali provvedimenti prevedeva il Piano di Azione per il settore finanziario europeo?", "answer": "Il Piano di Azione prevedeva l'adozione di 42 provvedimenti tra direttive, regolamenti e raccomandazioni, relativi ai vari settori del mercato finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0183", "question": "Quale termine ultimo per l'implementazione del Financial Services Action Plan è stato stabilito dal Consiglio Europeo di Lisbona?", "answer": "Il termine ultimo del 2005 per l'implementazione del suddetto Piano è stato successivamente stabilito dal Consiglio Europeo di Lisbona di marzo 2000.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0184", "question": "Che cos'era il comitato dei saggi sulla regolamentazione dei mercati europei dei valori mobiliari?", "answer": "Il comitato dei saggi sulla regolamentazione dei mercati europei dei valori mobiliari era un organismo con l'incarico di condurre un'indagine sullo stato di sviluppo e di integrazione dei mercati finanziari europei e di avanzare proposte per facilitare tale integrazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0185", "question": "Chi era la Commissione Lamfalussy e quale raccomandazione ha formulato?", "answer": "Nella sua relazione finale, la cosiddetta \"Commissione Lamfalussy\" ha raccomandato un approccio innovativo alla regolamentazione dei mercati finanziari attraverso la creazione di un quadro normativo articolato su quattro livelli volto ad accrescere la flessibilità, l'efficienza e la trasparenza del processo di regolamentazione a livello europeo nel settore dei valori mobiliari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0186", "question": "Quali istituzioni europee hanno accolto l'approccio proposto dalla Commissione Lamfalussy?", "answer": "L'approccio innovativo di regolamentazione finanziaria proposto nel Rapporto Lamfalussy è stato successivamente accolto sia dal Consiglio Europeo di Stoccolma del 23 e 24 marzo 2001, sia dal Parlamento Europeo in data 5 febbraio 2002.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0187", "question": "Su cosa si fonda l'approccio innovativo di regolamentazione finanziaria proposto nel Rapporto Lamfalussy?", "answer": "L'approccio innovativo di regolamentazione finanziaria proposto nel Rapporto Lamfalussy è fondato su quattro livelli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0188", "question": "Cosa prevede il Livello 1 del modello Lamfalussy?", "answer": "Livello 1: Elaborazione, da parte delle Istituzioni europee sulla base del processo legislativo individuato nel Trattato sul Funzionamento dell'Unione Europea, di atti normativi che prevedano principi quadro e ne definiscano le relative modalità di attuazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0189", "question": "Cosa prevede il Livello 2 del modello Lamfalussy?", "answer": "Livello 2: Adozione di misure di attuazione da parte della Commissione, in conformità alle valutazioni rese dall'European Securities Regulators Committee e a seguito di una procedura di consultazione sulle misure proposte.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0190", "question": "Qual è il ruolo del Livello 3 nel modello Lamfalussy?", "answer": "Livello 3: Intervento dell'European Securities Regulators Committee (oggi European Securities and Markets Authority) per assicurare l'uniforme applicazione della normativa tra i Paesi membri, mediante raccomandazioni, interpretazioni, standards e guidelines.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0191", "question": "Che funzione ha il Livello 4 nel modello Lamfalussy?", "answer": "Livello 4: Supervisione della Commissione sull'attività di attuazione da parte degli Stati membri, in via legislativa e amministrativa, delle norme e degli orientamenti adottati ai tre livelli precedenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0192", "question": "Quali sono alcuni esempi di atti legislativi adottati seguendo il modello Lamfalussy?", "answer": "Sono stati adottati - seguendo il modello \"Lamfalussy\" - significativi atti legislativi, come, in via esemplificativa, la direttiva 2003/6/CE sugli abusi di mercato, la direttiva 2003/71/CE relativa al prospetto da pubblicare per l'offerta pubblica o l'ammissione alla negoziazione di strumenti finanziari, la direttiva 2004/39/CE sui mercati degli strumenti finanziari, la direttiva 2004/109/CE sull'armonizzazione degli obblighi di trasparenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0193", "question": "Quale gruppo di lavoro è stato istituito nel 2008 in seguito alla crisi finanziaria?", "answer": "Nel 2008, nel pieno della crisi finanziaria, è stato poi istituito un nuovo gruppo di lavoro, composto da esperti e guidato da Jacques de Larosière, al fine di individuare alcune raccomandazioni per rafforzare la sorveglianza sul sistema finanziario europeo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0194", "question": "Cosa prevedevano le raccomandazioni del gruppo de Larosière?", "answer": "In linea con le raccomandazioni del gruppo de Larosière del 25 febbraio 2009, la vigilanza europea ha quindi subito una trasformazione che, a sua volta, rappresenta un'evoluzione del precedente modello Lamfalussy.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-quadro-regolamentare-europeo"}},
{"id": "chunk_0195", "question": "Che cosa ha stabilito il Consiglio Europeo del 28 e 29 giugno 2012 riguardo alle riforme nell'Unione Europea?", "answer": "Il Consiglio Europeo del 28 e 29 giugno 2012 aveva stabilito la necessità di realizzare una serie di riforme strutturali nell'Unione Europea al fine di risolvere l'attuale crisi. Tali riforme sono state tutte rivolte ad una maggiore integrazione economica tra gli Stati membri della UE e prevedevano, tra le altre cose, la costituzione di un'Unione Bancaria nell'Euro-zona (la cosiddetta Banking Union) e l'introduzione di un quadro regolamentare comune (il cosiddetto single rulebook) per tutti gli intermediari bancari nei 28 Paesi membri dell'Unione Europea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-unione-bancaria"}},
{"id": "chunk_0196", "question": "Qual è l'obiettivo principale della cosiddetta Banking Union?", "answer": "La cosiddetta Banking Union offre la possibilità di meglio proteggere l'economia reale e la stabilità finanziaria nell'intera area dell'Euro, grazie alla supervisione bancaria unificata (il cosiddetto Single Supervision Mechanism - SSM) - operativa dal novembre 2014, relativamente a tutti i paesi appartenenti alla euro-zona e a quelli non appartenenti all'eurozona che decidono di aderirvi tramite un meccanismo di stretta cooperazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-unione-bancaria"}},
{"id": "chunk_0197", "question": "Quali esigenze ha soddisfatto l'innovazione dell'Unione Bancaria?", "answer": "L'innovazione in oggetto ha risposto principalmente all'esigenza di: interrompere il circolo vizioso che ha portato nel 2011 e 2012 la crisi del debito sovrano e quella del settore bancario ad alimentarsi a vicenda, con profonde ripercussioni sull'economia reale e con un progressivo aggravamento della crisi in Europa; favorire la creazione di un \"campo di gioco\" livellato per le banche europee: la crisi del debito sovrano ha, infatti, penalizzato le banche di paesi con maggiori squilibri nei conti pubblici nei confronti di banche appartenenti a paesi con finanza pubblica più solida; salvaguardare la stabilità finanziaria in Europa alla luce della profonda integrazione dei mercati, in particolare all'interno dell'Area euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-unione-bancaria"}},
{"id": "chunk_0198", "question": "Quali sono stati i principali elementi dell'innovazione istituzionale dell'Unione Bancaria?", "answer": "L'innovazione istituzionale dell'Unione Bancaria ha comportato: 1) l'assegnazione alla Banca Centrale Europea [BCE] della vigilanza diretta sulle banche rilevanti dei paesi dell'Area euro (ed eventualmente di altre economie europee che intendano aderire); 2) la creazione di uno strumento operativo di gestione delle crisi delle banche soggette alla supervisione della BCE [il cosiddetto Single Resolution Mechanism]; 3) la definizione (ancora non completata) di un sistema europeo di garanzia dei depositi bancari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-unione-bancaria"}},
{"id": "chunk_0199", "question": "Quali compiti di vigilanza sono stati assegnati alla BCE con l'Unione Bancaria?", "answer": "Questo ha significato il passaggio di tutti i compiti di vigilanza di stabilità sulla sana e prudente gestione delle singole banche in capo alla BCE (e tutte le attività connesse di vigilanza ispettiva, informativa e sanzionatoria). La BCE assume quindi la responsabilità di compiti come il rilascio dell'autorizzazione all'esercizio dell'attività bancaria, l'acquisizione di partecipazioni rilevanti nel capitale delle banche, la conformità ai requisiti patrimoniali e di leva finanziaria e liquidità, nonché la vigilanza sui conglomerati finanziari. La BCE può intervenire tempestivamente nel caso in cui una banca violi o rischi di violare i requisiti patrimoniali chiedendo alla stessa di adottare misure correttive, agendo in coordinamento con le autorità nazionali di risoluzione delle crisi. La BCE avrà inoltre competenza esclusiva sulla vigilanza sui meccanismi di governance e assetti organizzativi che assicurino la sana e prudente gestione della banca e potrà sottoporre gli istituti a prove di stress prudenziali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-unione-bancaria"}},
{"id": "chunk_0200", "question": "Quali criteri determinano la rilevanza di una banca nell'ambito del SSM?", "answer": "La rilevanza di una banca è valutata in base a diversi requisiti dimensionali e di operatività transfrontaliera. In particolare, sono sottoposte al SSM: le banche di maggiori dimensioni, ossia quelle con attivi superiori ai 30 mld. di €; oppure, le banche con attivi almeno pari al 20% del Pil del paese di origine (a meno che tali attivi siano inferiori ai 5 mld. di €); oppure, le banche minori in seguito a notifica dell'autorità nazionale competente per la vigilanza prudenziale circa la rilevanza di un determinata istituzione creditizia in modo da assoggettarla al SSM; in tal caso la BCE è chiamata a valutare la rilevanza della banca prima di includerla nel perimetro dei soggetti vigilati dal SSM; le banche considerate rilevanti dalla BCE tra quelle che abbiano stabilito succursali in più di uno Stato membro dell'Area euro oltre al paese di origine e qualora le attività all'estero (o le passività verso l'estero) siano una quota rilevante delle attività (o passività) totali; le banche che abbiano richiesto aiuti finanziari ai fondi europei ESFS ed ESM; in ogni caso le tre principali banche di ognuno degli Stati membri dell'Area euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-unione-bancaria"}},
{"id": "chunk_0201", "question": "Quante banche sono sottoposte alla vigilanza diretta della BCE nel quadro del SSM?", "answer": "Le funzioni di vigilanza prudenziale su tutte le altre banche resteranno di competenza delle autorità nazionali. Pertanto gli istituti di credito che saranno sottoposti al SSM sarebbero meno di 200 delle circa 6.000 banche dell'Area euro. La Bce potrà comunque intervenire in caso di crisi che coinvolga banche di dimensioni minori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-unione-bancaria"}},
{"id": "chunk_0202", "question": "Chi ha dichiarato l'importanza della creazione di un Mercato Unico dei Capitali in Europa?", "answer": "Il Presidente della Commissione Europea Juncker ha dichiarato, all'avvio del proprio mandato nel novembre 2014, che la creazione in Europa di un Mercato Unico dei Capitali (cosiddetto Capital Markets Union) rappresenta uno dei punti principali della propria agenda.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0203", "question": "A chi è stato affidato lo specifico incarico per la creazione del Mercato Unico dei Capitali?", "answer": "Tale intento è stato ulteriormente esplicitato attraverso l'affidamento di uno specifico incarico al Commissario per la Stabilità Finanziaria, i Servizi Finanziari e l'Unione dei Mercati Finanziari, con scadenza nel 2019.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0204", "question": "Quali sono gli ambiti di riferimento degli interventi per la creazione di un Mercato Unico dei Capitali?", "answer": "Ambiti di riferimento degli interventi per la creazione di un Mercato Unico dei Capitali sono: 1) la raccolta di capitale; 2) la stabilità del sistema; 3) la tutela dei consumatori; 4) la riforma della regolamentazione dei servizi finanziari; 5) la revisione del sistema europeo di vigilanza finanziaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0205", "question": "Quando è stata avviata la consultazione sul progetto della Capital Markets Union e quale era il suo obiettivo?", "answer": "Il 18 febbraio 2015 la Commissione Europea ha avviato una consultazione su un progetto finalizzato alla creazione di una Capital Markets Union (Libro Verde \"Costruire un'Unione dei Mercati dei Capitali\"), con l'obiettivo di raccogliere, attraverso una discussione pubblica, indicazioni sulle possibili misure da intraprendere per realizzare un effettivo mercato unico dei capitali nel contesto europeo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0206", "question": "Quali documenti accompagnavano il Libro Verde sulla Capital Markets Union?", "answer": "Il Libro Verde è affiancato da due ulteriori documenti di consultazione in materia di cartolarizzazione dei crediti e revisione della disciplina sul prospetto informativo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0207", "question": "Quali sono le cinque aree di intervento prioritario individuate dal Libro Verde?", "answer": "Il Libro Verde identifica cinque aree di intervento prioritario: - revisione della disciplina sul prospetto informativo, al fine di agevolare le imprese, specialmente quelle di più piccole dimensioni (\"PMI\"), nel reperire finanziamenti e attrarre investitori internazionali; - ampliamento della base degli investitori per le PMI, in particolare favorendo una maggiore disponibilità delle informazioni sulla situazione creditizia delle PMI; - elaborazione di proposte per favorire un mercato sostenibile delle cartolarizzazioni, anche al fine di ‘liberare' i bilanci delle banche; - promozione di investimenti a lungo termine, in particolare di tipo infrastrutturale, sviluppando ulteriormente il quadro europeo sui nuovi fondi di investimento europeo a lungo termine (cosiddetto ELTIF); - sviluppo di un mercato europeo del private placement, secondo un approccio condiviso con l'industria e orientato a incoraggiare gli investimenti diretti nelle imprese di minori dimensioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0208", "question": "Quali sono i principi fondamentali ai quali il Libro Verde ispira la Capital Markets Union?", "answer": "Nell'ottica di migliorare l'accesso delle PMI ai finanziamenti e ai progetti di investimento, incrementare e diversificare le fonti di finanziamento e promuovere una maggiore efficienza dei mercati che favorisca il contatto diretto tra investitori e imprese, il Libro Verde individua alcuni principi fondamentali ai quali ispirare la Capital Markets Union: - massimizzazione dei vantaggi che i mercati dei capitali possono portare all'economia, alla crescita e all'occupazione; - creazione di un mercato unico dei capitali per tutti e 28 gli Stati membri, eliminando gli ostacoli agli investimenti transfrontalieri all'interno dell'UE e promuovendo relazioni più strette con i mercati dei capitali mondiali; - creazione di solide basi di stabilità finanziaria, con un unico sistema di regole sui servizi finanziari applicato in modo effettivo e coerente; - garanzia di una effettiva protezione per consumatori e investitori; - contributo all'attrazione di investimenti provenienti da tutto il mondo e al rafforzamento della competitività internazionale dell'UE.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0209", "question": "Qual è l'obiettivo finale della Commissione Europea in relazione alla Capital Markets Union?", "answer": "Sulla base delle informazioni ottenute nel corso della consultazione, la Commissione Europea si propone di elaborare un piano d'azione volto a porre le basi per un'Unione dei mercati dei capitali pienamente funzionante entro il 2019, così da consentire il finanziamento di progetti capaci di produrre ricchezza e reddito, senza discriminazione sulla base dell'ordinamento di appartenenza dell'impresa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/verso-il-mercato-unico-dei-capitali"}},
{"id": "chunk_0210", "question": "Quali fragilità strutturali ha messo in luce la crisi finanziaria del 2007-2009?", "answer": "La crisi finanziaria del 2007-2009 ha messo in luce le fragilità strutturali e le carenze del sistema finanziario internazionale. Accumulazione di eccessivo rischio finanziario in connessione con un elevato uso del debito, scarsa trasparenza ed elevata complessità delle operazioni d'investimento, presenza di intermediari non sottoposti a forme di regolamentazione e controllo (cosiddetto shadow banking) sono tra i fattori di maggiore rilievo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0211", "question": "A cosa erano finalizzati gli interventi di contrasto alla crisi in Europa a partire dal 2009?", "answer": "Il disegno degli interventi di contrasto alla crisi in Europa è stato fin dal 2009 primariamente finalizzato a definire gli strumenti di salvaguardia e di stabilizzazione del sistema finanziario europeo, in conformità agli indirizzi individuati dal G-20 e promossi dal Financial Stability Board.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0212", "question": "Quali effetti sull'economia reale sono stati trascurati negli interventi post-crisi?", "answer": "Minore attenzione è stata posta, invece, agli effetti sull'economia reale in termini di riduzione dell'offerta di credito e di possibile impatto su investimenti, produzione, occupazione e consumi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0213", "question": "Qual è stato l'effetto della politica monetaria della BCE durante la crisi?", "answer": "La politica monetaria posta in essere dalla Banca Centrale Europea (BCE) nel periodo in parola ha avuto l'effetto benefico di comprimere lo stato d'incertezza economica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0214", "question": "Perché il sostegno della BCE non è stato sufficiente dopo il 2010?", "answer": "Il sostegno della BCE alla liquidità degli intermediari non è stato sufficiente, negli anni successivi al 2010, per generare un miglioramento delle condizioni di accesso al finanziamento delle banche nei paesi più esposti alla crisi e, di conseguenza, per favorire una riduzione del costo dei prestiti bancari a famiglie e imprese. La contrazione dell'offerta di finanziamento ha interessato anche le forme alternative d'intermediazione creditizia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0215", "question": "Come ha influito l'incertezza macroeconomica sugli investimenti delle imprese?", "answer": "Il radicarsi dell'incertezza macroeconomica non aveva fino a pochi mesi fa creato sufficienti incentivi per le imprese a pianificare nuovi investimenti e richiedere nuovi finanziamenti per la crescita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0216", "question": "Quali imprese sono state maggiormente colpite dal razionamento del credito bancario?", "answer": "Il razionamento del credito bancario e delle altre forme di finanziamento all'economia ha colpito in modo più marcato le imprese di piccole e medie dimensioni a motivo del più elevato tasso di indebitamento che contraddistingue tali imprese, nonché della minore redditività rispetto a imprese di maggiori dimensioni che possono sfruttare economie di scala e di scopo, rafforzando gli impulsi recessivi per l'economia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0217", "question": "Perché le PMI di alcuni Paesi europei sono state penalizzate più di altre?", "answer": "Le PMI basate in alcuni Paesi europei sono state penalizzate anche dalla mancanza di un mercato integrato del credito nell'Eurozona.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0218", "question": "Quale impatto ha avuto la crisi sulla fiducia degli investitori istituzionali?", "answer": "La crisi finanziaria ha avuto un impatto negativo sulla fiducia e sulla propensione al rischio degli investitori istituzionali, in particolare negli Stati Membri in difficoltà finanziarie, riducendo anche la capacità del settore finanziario europeo di incanalare risparmi anche verso gli investimenti innovativi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0219", "question": "Su cosa si è concentrata la Commissione Europea a partire dal 2011 per reagire alla crisi?", "answer": "A partire dal 2011 l'attenzione della Commissione Europea si è concentrata sull'ampliamento dei canali di finanziamento disponibili per le imprese, soprattutto le PMI, al fine di salvaguardare il potenziale di crescita del sistema produttivo europeo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0220", "question": "Quali misure sono state adottate per favorire lo sviluppo di investitori specializzati?", "answer": "Sono state adottate misure per favorire lo sviluppo di investitori specializzati nell'investimento in capitale di debito e di rischio delle piccole e medie imprese (private equity e venture capital) e in progetti infrastrutturali di lungo periodo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0221", "question": "Cosa si intende per 'messa in sicurezza della stabilità finanziaria'?", "answer": "Una volta \"messa in sicurezza la stabilità finanziaria\", le Istituzioni europee si sono mosse, per favorire lo sviluppo di canali di finanziamento all'economia reale, incoraggiando l'aumento di capitali non bancari a disposizione delle imprese come complementari rispetto al credito bancario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0222", "question": "Qual è il contenuto del Libro verde della Commissione Europea del 2013?", "answer": "Il contesto più ampio nel quale si inquadra questo lavoro è stato definito nel Libro verde della Commissione Europea intitolato \"Il Finanziamento a Lungo Termine dell'Economia Europea\" (Marzo 2013), che delinea le questioni inerenti all'offerta e alla domanda per tutte le strutture di finanziamento, e confermato nel documento finale del marzo 2014.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0223", "question": "Qual è stato l'obiettivo della Direttiva sui gestori di fondi di investimento alternativi?", "answer": "Con la Direttiva sui gestori di fondi di investimento alternativi (cosiddetta AIFM Directive), l'Unione Europea ha inteso porre un tassello fondamentale del Piano per un sistema finanziario sicuro e capace di supportare l'economia reale attraverso la raccolta e l'impiego di capitale di rischio e di debito su base europea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0224", "question": "Perché la Commissione Europea ha introdotto i regolamenti EUVECA ed EuSEF?", "answer": "La necessità di facilitare l'accesso ai finanziamenti alternativi a quello bancario da parte delle PMI - non solo per migliorarne la competitività e il potenziale di crescita, ma per salvaguardarne l'esistenza in una fase caratterizzata da un calo dei prestiti all'economia reale - ha condotto la Commissione Europea a introdurre regolamenti immediatamente esecutivi, dedicati ai fondi di venture capital (Regolamento cosiddetto EUVECA) e ai fondi per le imprese sociali (Regolamento cosiddetto EuSEF).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0225", "question": "Qual è lo scopo del Regolamento sui fondi di investimento a lungo termine (ELTIF)?", "answer": "È stata emanata una disciplina sui fondi di investimento a lungo termine (Regolamento cosiddetto ELTIF) volta ad accrescere nell'immediato futuro la massa di capitale disponibile per gli investimenti a lungo termine in grandi progetti infrastrutturali o di ingegneria industriale, che per loro natura richiedono un impegno a lungo termine da parte dell'investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0226", "question": "Qual è l'obiettivo del progetto per la realizzazione di un mercato unico dei capitali in Europa?", "answer": "Poiché il problema della frammentazione dei mercati dei capitali resta uno dei principali ostacoli alla ripresa del finanziamento delle imprese, ancora fortemente dipendente dal credito bancario, la Commissione ha avviato un progetto per la realizzazione di un mercato unico dei capitali a livello europeo (cosiddetto Capital Markets Union), volto a porre le basi per un'Unione dei mercati dei capitali pienamente funzionante entro il 2019, così da consentire il finanziamento di progetti capaci di produrre ricchezza e reddito, senza discriminazione sulla base dell'ordinamento di appartenenza dell'impresa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-finanza-per-la-crescita"}},
{"id": "chunk_0227", "question": "Che cosa rappresenta la pianificazione finanziaria?", "answer": "Un'attenta pianificazione finanziaria e il monitoraggio del bilancio familiare costituiscono un passaggio necessario per la formulazione di obiettivi di spesa, risparmio e investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0228", "question": "Su cosa si fonda una buona pianificazione finanziaria?", "answer": "Una buona pianificazione si fonda sull'analisi della situazione finanziaria e patrimoniale della famiglia. Sulla base delle entrate disponibili e delle uscite nell'arco di un certo periodo puoi calcolare quanto destinare all'ammortamento di un prestito, quanto investire o quanto accantonare per sostenere spese future.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0229", "question": "Qual è la definizione di economia secondo Lionel Robbins?", "answer": "L'economia è la scienza che studia la condotta umana nel momento in cui, data una graduatoria di obiettivi, si devono operare delle scelte su mezzi scarsi applicabili ad usi alternativi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0230", "question": "Cosa implica la definizione di economia di Lionel Robbins?", "answer": "Ogni qualvolta un individuo sceglie come utilizzare le proprie risorse (necessariamente) scarse per soddisfare al meglio i propri bisogni compie una decisione economica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0231", "question": "Cosa fa un buon pianificatore secondo il testo?", "answer": "Un buon pianificatore non risparmia quello che rimane dopo aver speso, ma spende quello che rimane dopo aver risparmiato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0232", "question": "Da dove parte una buona pianificazione finanziaria?", "answer": "Una buona pianificazione finanziaria parte dall'analisi della situazione finanziaria della famiglia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0233", "question": "Perché è importante valutare la situazione passata e attuale del bilancio familiare?", "answer": "Per valutare di cosa sei capace è indispensabile partire dalla situazione passata e attuale: devi quantificare quanto entra e quanto esce abitualmente dalla 'cassa' di famiglia, tenendo conto delle caratteristiche delle tue fonti e dei tuoi consumi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0234", "question": "Qual è lo scopo della registrazione di entrate e uscite mensili e del monitoraggio del bilancio familiare?", "answer": "La registrazione di entrate e uscite mensili, il monitoraggio periodico del bilancio familiare e la pianificazione ti permetteranno di identificare e ridurre eventuali sprechi, gestire più efficacemente le tue risorse e realizzare i tuoi obiettivi di consumo e risparmio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0235", "question": "Perché è utile suddividere le entrate e le uscite per categoria?", "answer": "È buona norma suddividere in un registro entrate e uscite per categoria: tale accorgimento aiuta a non tralasciare voci di spesa che, magari, si ripetono con cadenza annuale o bi-annuale, ma incidono sul bilancio in maniera considerevole.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0236", "question": "Perché è utile aggiornare costantemente il registro delle uscite?", "answer": "Aggiornare costantemente il registro delle tue uscite, raccogliendo ricevute e scontrini e annotando quotidianamente le singole spese, può essere molto utile. Per coloro che non hanno mai gestito un budget familiare, che pianificano per la prima volta o che riconoscono di non essere particolarmente bravi a evitare spese superflue, potrebbe essere addirittura indispensabile, almeno per i primi tempi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0237", "question": "Perché è consigliabile individuare un giorno fisso per il monitoraggio del bilancio?", "answer": "Per TUTTI, in ogni caso, è assolutamente consigliabile individuare un giorno fisso in cui dedicare del tempo all'aggiornamento degli elenchi e al monitoraggio del bilancio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0238", "question": "Perché le spese di piccolo importo non vanno sottovalutate?", "answer": "Le spese voluttuarie frequenti ma di piccolo importo su base giornaliera tendono a essere sottovalutate: un fumatore di solito considera solo il costo quotidiano di acquisto delle sigarette e perde di vista le risorse complessivamente spese nel corso di un anno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0239", "question": "Cosa suggerisce George Kinder riguardo agli obiettivi finanziari?", "answer": "George Kinder sostiene che le persone non hanno obiettivi finanziari, hanno obiettivi di vita che necessitano di risorse finanziarie per essere realizzati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0240", "question": "Cosa significa pianificare e risparmiare secondo il testo?", "answer": "Pianificare e risparmiare vuol dire decidere di trasferire risorse nel tempo per fronteggiare uscite di cassa prevedibili e non prevedibili, ossia per realizzare i nostri obiettivi di consumo e di riserva.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0241", "question": "Quali sono alcuni esempi di obiettivi di consumo?", "answer": "Alcuni esempi di obiettivi di consumo possono essere: l'acquisto di una casa, l'acquisto di un'auto, l'istruzione dei figli, il pagamento delle tasse, il risparmio per le vacanze, etc.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0242", "question": "Perché è importante riflettere sulle proprie esigenze future?", "answer": "Non è sempre facile proiettarsi in avanti nel tempo per visualizzare le nostre esigenze future e renderci conto di quali esiti potrebbero avere domani le scelte che compiamo oggi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0243", "question": "Quali domande dovremmo porci per assumere un atteggiamento più lungimirante?", "answer": "Rivolgi a te stesso qualche domanda scomoda: avrai di che vivere quando sarai anziano? A cosa dovrai rinunciare quando andrai in pensione e le tue entrate mensili si ridurranno?", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0244", "question": "Quali caratteristiche devono avere gli obiettivi secondo il testo?", "answer": "I tuoi obiettivi devono essere SPECIFICI (nel cosa e nel quanto) e MISURABILI (deve essere possibile quantificare l'ammontare di denaro necessario a realizzare ciascun obiettivo).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0245", "question": "Come si calcola l'accantonamento mensile per un obiettivo?", "answer": "Per ogni obiettivo della lista, dividi l'ammontare necessario a raggiungere l'obiettivo stesso per il numero di mesi che intercorrono tra il momento attuale e il momento in cui hai immaginato di realizzarlo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0246", "question": "Cos'è un fondo-emergenze e a cosa serve?", "answer": "Costituisci anche un fondo-emergenze (equivalente a circa 6 volte le tue spese mensili) che diventerà la fonte a cui attingere per eventuali spese impreviste.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0247", "question": "Come si verifica se gli obiettivi finanziari sono realizzabili?", "answer": "Verifica che la somma degli accantonamenti sia pari o inferiore alla tua capacità di risparmio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0248", "question": "Perché può essere utile condividere i propri obiettivi con qualcuno?", "answer": "Coinvolgi un amico, un parente, una persona al cui giudizio tieni particolarmente e comunicale il tuo obiettivo di risparmio mensile. Questa persona ti chiamerà ogni mese e ti chiederà se hai raggiunto l'obiettivo prefissato. Questa \"gentile pressione\" suscitata dal giudizio di una persona per te importante aiuterà a motivarti e a impegnarti ancora di più.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0249", "question": "Cosa bisogna fare durante la fase di accumulazione e monitoraggio?", "answer": "Aggiorna costantemente il registro delle entrate e delle uscite, monitora periodicamente il raggiungimento dei tuoi obiettivi di risparmio mensile e, se serve, riaggiusta di volta in volta le tue abitudini di consumo o rivedi i tuoi obiettivi finali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0250", "question": "Quali sono i passi principali della pianificazione finanziaria secondo il recap finale?", "answer": "Tieni un registro di entrate e uscite, calcola la tua capacità di risparmio, individua i tuoi obiettivi specifici e misurabili, ordina gli obiettivi per priorità, calcola l'accantonamento mensile, costituisci un fondo per ciascun obiettivo, calcola il tuo obiettivo di risparmio mensile e controlla se gli obiettivi sono realizzabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-pianificazione-finanziaria"}},
{"id": "chunk_0251", "question": "Cosa si intende per percezione del rischio e propensione al rischio?", "answer": "Percezione del rischio e propensione al rischio sono molto soggettivi e sono influenzate da molteplici fattori: tra questi rilevano le caratteristiche socio-demografiche (genere, età, livello di istruzione, stato di famiglia, etc.) e alcuni tratti personali dell'investitore (ottimismo, la fiducia nelle proprie capacità di compiere buone scelte di investimento, etc.).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0252", "question": "Come possono le esperienze pregresse influenzare la propensione al rischio?", "answer": "L'evidenza empirica e sperimentale mostra che in genere la propensione al rischio può aumentare dopo aver realizzato un guadagno, e stimolare, viceversa, un atteggiamento più conservativo dopo aver subito una perdita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0253", "question": "Cosa consiglia la CONSOB per evitare errori legati alla percezione del rischio?", "answer": "Nel valutare un prodotto finanziario, non affidarti ai consigli di amici e parenti e non lasciarti guidare solo dai rendimenti passati: la percezione altrui del rischio finanziario potrebbe non coincidere con la tua e i risultati passati non necessariamente si ripeteranno in futuro!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0254", "question": "Cosa sono le euristiche e come influenzano le decisioni finanziarie?", "answer": "Le cosiddette euristiche sono \"scorciatoie\" mentali che semplificano un problema agevolando la decisione. In questo modo, stimare la probabilità che un evento accada può sembrare molto facile! In realtà, le scorciatoie conducono spesso a commettere errori!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0255", "question": "Quali suggerimenti vengono dati per evitare decisioni basate su istinto e scorciatoie di pensiero?", "answer": "Non fermarti ad una valutazione dei rischi rapida e istintiva, soffermati sul significato dei dati disponibili e concediti del tempo per riflettere sulle opzioni di scelta a tua disposizione! Non ragionare per stereotipi: ogni investimento va valutato per le sue caratteristiche in termini di rischio e rendimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0256", "question": "Cosa si intende per ottimismo e overconfidence?", "answer": "Alcuni individui tendono a formulare previsioni sistematicamente distorte verso scenari positivi. Fare previsioni troppo ottimistiche o fidarsi troppo delle proprie capacità di valutazione possono indurre a sottoscrivere investimenti ad alto rischio anche quando si è fortemente avversi alle perdite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0257", "question": "Come evitare gli effetti negativi dell'ottimismo e dell'eccessiva fiducia?", "answer": "Quando consideri le performance storiche o le caratteristiche di un prodotto, cerca di resistere alla naturale tendenza di soffermarti unicamente sugli aspetti positivi. Periodicamente formula e annota le tue previsioni sullo scenario economico-finanziario o sull'andamento futuro di un titolo e, successivamente, verifica l'eventuale scostamento tra le tue previsioni e le performance effettive. Vai alla ricerca dei dati e delle notizie che potrebbero contraddire il tuo punto di vista e confrontale con quelle che lo supportano: per documentare quanto è difficile prevedere i fatti economici, basta tenere una raccolta di articoli di giornale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0258", "question": "Cosa significa framing effect?", "answer": "Il cosiddetto \"inquadramento\", ossia il modo in cui l'informazione viene rappresentata, può deviare l'attenzione del lettore sulle informazioni ritenute rilevanti e distorcere il suo atteggiamento verso il rischio (framing effect).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0259", "question": "Come valutare criticamente le informazioni per evitare il framing effect?", "answer": "Valuta \"criticamente\" le informazioni esposte nei documenti informativi. Prova ad esprimere con parole tue l'informazione che ti è stata trasmessa e chiedi al consulente/promotore se la tua lettura è corretta. Chiediti se l'uso del colore o l'impostazione grafica utilizzata stanno convogliando la tua attenzione su una informazione in particolare, distraendoti da altre informazioni parimenti importanti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0260", "question": "Cosa significa avversione alle perdite?", "answer": "Gli individui sono tipicamente avversi alle perdite, ossia sono molto più sensibili alla possibilità di perdere rispetto alla possibilità di guadagnare un determinato importo. In altre parole, la reazione emotiva alle perdite è sistematicamente più forte della reazione di guadagni di pari importo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0261", "question": "Che cos'è l'avversione miope alle perdite?", "answer": "Molti individui soffrono, inoltre, della cosiddetta avversione miope alle perdite (myopic loss aversion), che corrisponde all'attitudine a trascurare le prospettive di lungo termine per concentrarsi su quelle di breve periodo, rispetto alle quali può essere dominante la paura di dover subire perdite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0262", "question": "Quali suggerimenti si possono seguire per gestire l'avversione alle perdite?", "answer": "Non sottoscrivere investimenti ad alto rischio se sei fortemente avverso alle perdite: forse stai sottostimando il rischio per eccessivo ottimismo! Se hai un obiettivo di medio/lungo termine, evita di focalizzarti solo sulle performance di breve termine e richiedi o cerca informazioni sui rendimenti riferibili al tuo orizzonte temporale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0263", "question": "Cosa si intende per paura del rimpianto e comportamento di imitazione (herding behaviour)?", "answer": "Nell'anticipare il rimpianto per eventuali decisioni sbagliate, gli individui possono scegliere di non modificare il proprio portafoglio anche quando sarebbe ottimale (immobilismo) ovvero possono imitare (herding behaviour) i comportamenti maggiormente diffusi, al fine di condividere con altri la responsabilità di una scelta eventualmente sbagliata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0264", "question": "Cos'è l'attribution bias?", "answer": "Dopo aver preso una decisione rivelatasi sbagliata, gli individui tendono ad attribuire ad altri la responsabilità delle proprie scelte per ridurre il \"rimpianto\" (cosiddetto attribution bias).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0265", "question": "Come evitare la paura del rimpianto e il comportamento imitativo?", "answer": "Tieni e aggiorna due liste, una contenente esempi in cui le scelte o gli investimenti hanno avuto un esito favorevole e un'altra in cui l'esito è stato sfavorevole. Annota a fianco di ogni scelta a chi/che cosa può essere attribuito il merito/la colpa. Discuti le attribuzioni con uno o più interlocutori allo scopo di verificare se le attribuzioni assegnate sono condivisibili o meno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0266", "question": "Che cos'è il disposition effect?", "answer": "Spesso gli individui non sanno decidersi a liquidare un investimento in perdita e senza prospettive di miglioramento, anche se non sarebbero disposti a investire il valore corrente dell'investimento nel titolo stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0267", "question": "Qual è il suggerimento per superare il disposition effect?", "answer": "Usare il prezzo di acquisto come punto di riferimento può influenzare negativamente lo stato d'animo con il quale si effettuano gli investimenti. In finanza contano solamente le prospettive future, non le performance passate. Nel caso in cui non sappia deciderti a liquidare un investimento in perdita, chiediti se saresti disposto a investire il valore corrente dell'investimento nel titolo stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0268", "question": "Cosa significa mental accounting?", "answer": "Nella gestione del denaro, gli individui tendono a ragionare per conti mentali, definiti in base alla fonte del reddito e alla tipologia e frequenza di consumo. Ad esempio, risorse derivanti dai redditi da lavoro sono spesso destinate a investimenti poco rischiosi, mentre i redditi derivanti da vincite o voci stipendiali una tantum (gratifiche e premi) sono più facilmente investiti in prodotti più rischiosi. Per la parte di investimento destinata a soddisfare il bisogno di rendimenti più ambiziosi, di solito vengono deliberatamente evitate strategie di diversificazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0269", "question": "Qual è il suggerimento per evitare errori legati al mental accounting?", "answer": "I redditi derivanti da lavoro hanno lo stesso valore delle somme vinte al gioco. Ciò che conta è il risultato congiunto degli investimenti; la diversificazione di portafoglio può aiutarti a ridurre il rischio complessivamente assunto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0270", "question": "Cosa si intende per miopia e procrastinazione negli investimenti?", "answer": "Troppo spesso scelte che appaiono ottimali oggi diventano meno attraenti con il passare del tempo (cosiddetta incoerenza dinamica), generando insoddisfazione e ripensamenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0271", "question": "Qual è il suggerimento per evitare la miopia e la procrastinazione?", "answer": "Se hai un obiettivo di medio/lungo termine, monitora il tuo investimento evitando di focalizzarti solo sulle prospettive di breve termine e richiedendo informazioni sui rendimenti riferibili al tuo orizzonte temporale. In ragione di un ripensamento momentaneo, rischiamo di prendere decisioni non ottimali: si tratta di un problema di auto-controllo che conduce a scelte miopi, come nel caso della persona pigra che vuole iniziare un'attività sportiva (o della persona in sovrappeso che intende ridurre le calorie assunte), ma poi rinuncia facilmente ai buoni propositi!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/errori-e-trappole-comportamentali"}},
{"id": "chunk_0272", "question": "Quali sono gli elementi che definiscono il profilo finanziario di un investitore?", "answer": "Nella definizione dei tuoi obiettivi dovrai valutare quanto puoi investire, quando avrai bisogno del denaro investito (l'orizzonte temporale dell'investimento), i rendimenti a cui aspiri e il rischio che sei disposto ad assumerti. Questi sono gli elementi che definiscono il tuo profilo finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0273", "question": "Cosa devi assolutamente sapere prima di investire?", "answer": "RISCHIO E RENDIMENTO ATTESO CRESCONO ASSIEME! Non esistono investimenti che rendono tanto e sono poco rischiosi. Diffida delle proposte di guadagni facili e sicuri. Chiedi sempre quanto rendono investimenti alternativi potenzialmente meno rischiosi, quali ad esempio i titoli di Stato italiani e tedeschi di pari scadenza. DIVERSIFICA: NON METTERE TUTTE LE UOVA NELLO STESSO PANIERE! Non investire tutto in un solo titolo o in titoli emessi dalla stessa società! L'ideale è scegliere investimenti diversi tra loro (per emittente, settore e scadenza). La diversificazione ti permette di ridurre il rischio complessivo del tuo portafoglio di investimenti. NON FIDARTI SOLO DEL TUO INTUITO E DELLE TUE PERCEZIONI! Sii consapevole che agire di intuito permette di compiere scelte immediate ma non sempre corrette e che il modo in cui vengono presentate le informazioni può orientare la percezione del rischio e le decisioni. Prima di investire, quindi, rifletti e sciogli tutti i tuoi dubbi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0274", "question": "A chi bisogna rivolgersi per i servizi di investimento?", "answer": "Verifica sempre che chi ti propone un servizio o un'attività di investimento sia un soggetto autorizzato! Gli intermediari autorizzati a prestare servizi d'investimento devono: agire in modo onesto, equo e professionale, per servire al meglio i tuoi interessi; fornirti informazioni corrette, chiare e non fuorvianti; classificarti come cliente al dettaglio o cliente professionale; offrirti dei servizi che tengano conto della tua situazione individuale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0275", "question": "Quali tipi di servizi d'investimento possono offrire le imprese autorizzate?", "answer": "Le imprese autorizzate possono offrirti uno o più dei seguenti tipi di servizi d'investimento: raccomandazioni riguardo agli investimenti, i prodotti e le linee d'azione (consulenza in materia di investimenti); gestione per tuo conto dei tuoi investimenti; acquisti e vendite di prodotti finanziari, senza ricevere consigli d'investimento. ATTENTO! In questo caso, il livello di tutela è minore rispetto a quello previsto per i due servizi precedenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0276", "question": "Quali cautele bisogna adottare quando si investe online?", "answer": "Se decidi di fruire delle opportunità offerte dalla rete internet, dovrai adottare particolari cautele che ti consentono di ridurre i rischi connessi all'investimento on-line.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0277", "question": "Come scegliere in cosa investire?", "answer": "Sul mercato esiste una vasta gamma di prodotti! Una volta accertato di esserti rivolto o di essere stato contattato da un soggetto autorizzato, devi scegliere, tra la vasta gamma di strumenti finanziari esistente sul mercato, i prodotti che per le loro caratteristiche di rischio e rendimento risultano adatti alle tue caratteristiche e ai tuoi obiettivi. Se non sei esperto, puoi avvalerti di una persona professionalmente preparata, in grado di consigliare prodotti appropriati o adeguati al tuo profilo di investitore e alle tue esigenze.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0278", "question": "Quali rischi sono associati agli strumenti finanziari complessi?", "answer": "Valuta con molta attenzione i rischi connessi con l'acquisto di strumenti finanziari complessi, come strumenti derivati (future, swap, contratti a termine, opzioni), obbligazioni subordinate, obbligazioni strutturate e covered warrant. La Consob ha raccomandato agli intermediari di adottare particolari cautele con riferimento ai prodotti complessi, fino a sconsigliarne in alcuni casi la distribuzione alla clientela retail.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0279", "question": "Cosa significa il concetto di 'information overload' negli investimenti?", "answer": "Può accadere, tuttavia, che una maggiore quantità di informazioni non migliori le capacità di analisi e di scelta. L'eccesso di informazione (cosiddetto \"information overload\") può addirittura rivelarsi controproducente e generare confusione. Inoltre, espressioni troppo tecniche possono risultare incomprensibili e generare equivoci.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0280", "question": "Che cos'è la valutazione di adeguatezza?", "answer": "La valutazione d'adeguatezza serve a verificare se il prodotto che ci propone l'intermediario fa al caso nostro. Il nostro profilo viene definito rispetto alle nostre conoscenze ed esperienze in materia di investimenti e al tipo specifico di prodotto o servizio, alla nostra situazione finanziaria e ai nostri obiettivi d'investimento. Lo strumento tipicamente utilizzato è il cosiddetto \"questionario MiFID\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0281", "question": "Che cos'è la valutazione di appropriatezza?", "answer": "Nei servizi di sottoscrizione e collocamento, l'intermediario deve valutare che lo strumento o il servizio di investimento offerto o richiesto sia appropriato. L'intermediario ti chiederà informazioni riguardanti, esclusivamente, la conoscenza ed esperienza circa il tipo di strumento o servizio proposto o richiesto. Lo strumento o il servizio risulterà appropriato per te se hai conoscenze ed esperienza sufficienti a comprenderne i rischi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0282", "question": "Quali precauzioni bisogna prendere nella firma dei contratti di investimento?", "answer": "Non firmare moduli in bianco e utilizza mezzi di pagamento previsti e sicuri! Spesso capita di firmare contratti e moduli senza averli prima letti o, addirittura, senza che siano stati compilati delegando poi l'intermediario a riempirli. È una prassi pericolosissima, che apre la possibilità ad operatori disonesti di commettere abusi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0283", "question": "Cosa bisogna fare dopo aver investito?", "answer": "Segui i tuoi investimenti e leggi attentamente la documentazione di rendicontazione che l'intermediario invia periodicamente. Fai attenzione a non reagire in modo automatico ai risultati di breve periodo dei tuoi investimenti: prima di movimentare il portafoglio ricorda quali sono i tuoi obiettivi e il tuo orizzonte temporale. Rifletti, quindi, e risolvi i tuoi dubbi con l'aiuto di un esperto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0284", "question": "Cosa si può fare in caso di comportamenti scorretti dell'intermediario?", "answer": "Se ritieni che l'intermediario abbia violato gli impegni contrattuali, o abbia comunque posto in essere comportamenti non corretti, inoltra un reclamo scritto, indicandone dettagliatamente i motivi. L'intermediario deve rispondere per iscritto e con sollecitudine. Successivamente potrai inoltrare un esposto alla Consob, allegando il reclamo già inviato all'intermediario e la risposta ricevuta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/il-percorso-per-l-investimento"}},
{"id": "chunk_0285", "question": "Come definire i propri obiettivi?", "answer": "L'investitore dovrebbe definire i propri obiettivi d'investimento in modo da massimizzare la ricchezza attesa e in un'ottica di portafoglio e non solo in funzione di punti di riferimento quali la ricchezza iniziale, lo stile di vita, il contesto sociale (benchmark di ricchezza) o i rendimenti storici (benchmark di rendimento). Un'attenta definizione degli obiettivi terrà conto di quando si avrà bisogno del denaro investito, del livello dei rendimenti attesi e del rischio che si è disposti ad assumere, ossia dell'orizzonte temporale, delle aspettative di rendimento e della propria propensione al rischio. Questi elementi definiscono il profilo finanziario dell'investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/obiettivi"}},
{"id": "chunk_0286", "question": "Come definire l'orizzonte temporale?", "answer": "L'investitore dovrebbe definire i propri obiettivi d'investimento in modo da massimizzare la ricchezza attesa e in un'ottica di portafoglio e non solo in funzione di punti di riferimento quali la ricchezza iniziale, lo stile di vita, il contesto sociale (benchmark di ricchezza) o i rendimenti storici (benchmark di rendimento). Un'attenta definizione degli obiettivi terrà conto di quando si avrà bisogno del denaro investito, del livello dei rendimenti attesi e del rischio che si è disposti ad assumere, ossia dell'orizzonte temporale, delle aspettative di rendimento e della propria propensione al rischio. Questi elementi definiscono il profilo finanziario dell'investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/orizzonte-temporale"}},
{"id": "chunk_0287", "question": "Cosa influenza la percezione del rischio negli investimenti finanziari?", "answer": "La percezione del rischio viene influenzata da giudizi immediati ossia non mediati dal ragionamento, ma da scorciatoie di pensiero, quali le cosiddette euristiche della disponibilità e della familiarità: ad esempio, i titoli che godono di una maggiore copertura mediatica possono essere considerati più sicuri di altri, o addirittura descrivibili attraverso una relazione rischio/rendimento negativa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0288", "question": "Cosa sono le euristiche della disponibilità e della familiarità?", "answer": "Le euristiche della disponibilità e della familiarità sono scorciatoie di pensiero che influenzano la percezione del rischio: ad esempio, i titoli che godono di una maggiore copertura mediatica possono essere considerati più sicuri di altri, o addirittura descrivibili attraverso una relazione rischio/rendimento negativa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0289", "question": "In che modo l'uso delle euristiche influisce sulla percezione del rischio?", "answer": "Il ricorso alle euristiche, semplificando il processo di elaborazione delle informazioni, può rafforzare alcuni tratti psicologici, che a loro volta incidono sulla percezione del rischio, quali l'ottimismo e l'eccesso di fiducia nelle proprie abilità (cosiddetta \"overconfidence\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0290", "question": "Come possono influenzare le associazioni mentali la percezione del rischio?", "answer": "La percezione del rischio può essere sensibile anche alla valenza positiva o negativa attribuita a un determinato titolo sulla base di associazioni mentali che prescindono da valutazioni di tipo economico-finanziario (rappresentatività).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0291", "question": "Che ruolo gioca la stima della probabilità negli errori di percezione del rischio?", "answer": "La percezione del rischio può essere influenzata da una stima non corretta della probabilità con cui l'evento rischioso può verificarsi o, ancora, dalla percezione soggettiva di una probabilità nota.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0292", "question": "Le preferenze verso il rischio sono stabili rispetto al framing effect?", "answer": "Le preferenze verso il rischio non sono stabili rispetto alle modalità di rappresentazione di un problema (cosiddetto \"framing effect\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0293", "question": "Qual è il ruolo della componente emotiva nelle decisioni in condizioni di incertezza?", "answer": "Un ruolo fondamentale viene svolto altresì dalla componente emotiva: i processi decisionali in condizioni di incertezza si fondano non solo sulla valutazione \"razionale\" del rischio ma anche su reazioni emotive. L'incidenza di tale fattore cambierebbe a seconda delle conoscenze finanziarie degli individui.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0294", "question": "Come differiscono i comportamenti degli individui in base alle loro conoscenze finanziarie?", "answer": "Secondo alcuni studi, le persone che si dichiarano avversi al rischio pur essendone attratti emotivamente decidono sulla base dei suggerimenti di amici, colleghi e parenti e si caratterizzano per bassi livelli di conoscenza finanziaria; i soggetti che scelgono in autonomia tenderebbero a rischiare di più, mentre gli investitori che si avvalgono dei servizi di consulenza sembrerebbero più equilibrati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0295", "question": "Cosa significa che gli individui sono avversi alle perdite?", "answer": "Gli individui sono avversi alle perdite, ossia sono molto più sensibili alla possibilità di perdere rispetto alla possibilità di guadagnare un determinato importo e sono spesso influenzati dal risultato di decisioni pregresse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0296", "question": "Come cambia la propensione al rischio dopo guadagni o perdite precedenti?", "answer": "L'evidenza empirica e sperimentale mostra che in genere la propensione al rischio può aumentare dopo aver realizzato un guadagno, e stimolare, viceversa, un atteggiamento più conservativo dopo aver subito una perdita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0297", "question": "In che modo il genere influenza la percezione e l'assunzione del rischio?", "answer": "La percezione e l'assunzione di rischio sembrano essere molto diverse a seconda del genere. Le donne adotterebbero un atteggiamento più prudente in occasione delle decisioni di investimento e, di conseguenza, rispetto agli uomini sono più frequentemente destinatarie di proposte di investimento relative a prodotti poco rischiosi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0298", "question": "Le differenze di genere nella propensione al rischio sono sempre uguali?", "answer": "Le differenze di genere sembrano più accentuate nel caso di individui single. I soggetti sposati, per contro, si influenzano a vicenda secondo dinamiche che, come evidenziato da alcuni recenti contributi, dipendono anche dalla distribuzione della ricchezza finanziaria all'interno della famiglia e dalla professione e dal livello di istruzione dei coniugi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/percezione-e-propensione-al-rischio"}},
{"id": "chunk_0299", "question": "Come viene classificata la clientela secondo la normativa MiFID?", "answer": "La classificazione della clientela\nCome cliente al dettaglio (retail) riceverai il livello massimo di tutela degli investitori. La normativa europea in materia (Direttiva MiFID) prevede, infatti, una protezione maggiore per gli investitori con minore conoscenza ed esperienza negli investimenti (clienti retail), mentre gli investitori con maggiore conoscenza ed esperienza in materia (clienti professionali) ricevono una protezione minore. Fra i clienti professionali rientrano le banche, i governi, i fondi pensionistici, le grandi società e, in via eccezionale, alcune persone fisiche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0300", "question": "In quali circostanze puoi essere trattato come cliente professionale?", "answer": "In determinate circostanze puoi essere trattato come cliente professionale. Potresti averne bisogno per avere accesso a prodotti che non sono a disposizione dei clienti al dettaglio, o se vuoi diventare cliente di un'impresa che non opera con i clienti retail. Se vuoi diventare un cliente professionale è necessario che tu sia in grado di prendere le tue decisioni sull'investimento, di valutare i rischi in cui incorri e di non aver bisogno di un livello elevato di tutela.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0301", "question": "Cosa comporta la scelta di diventare cliente professionale?", "answer": "Se scegli di diventare un cliente professionale perderai parte della protezione regolamentare applicata ai clienti al dettaglio. L'impresa ti illustrerà questo punto. Ad esempio, in linea generale, riceverai meno informazioni e meno comunicazioni e avvertenze su vari argomenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0302", "question": "Cosa deve fare l'impresa prima di classificare un cliente come professionale?", "answer": "Prima di classificarti come cliente professionale, l'impresa deve innanzitutto valutare se questa categoria è adatta a te. Lo scopo della valutazione da parte dell'impresa è quello di stabilire se sei in grado di prendere le tue decisioni d'investimento e se riesci a capire i rischi connessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0303", "question": "Quali criteri deve soddisfare un cliente per essere classificato come professionale?", "answer": "La tua impresa d'investimento potrà classificarti come Cliente Professionale soltanto se soddisfi almeno due dei seguenti criteri: - hai svolto frequentemente delle operazioni finanziarie; - hai un ampio portafoglio titoli; - hai lavorato nel settore dei servizi d'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0304", "question": "Cosa si intende per esercizio di auto-profilatura?", "answer": "A prescindere dalle informazioni rilevate dall'intermediario attraverso il questionario, ci sono alcuni piccoli test che potremmo svolgere in autonomia. Prima ancora di valutare se e quanto conosciamo un determinato strumento finanziario (azione, obbligazione, covered warrant, fondo comune di investimento, etc.) potremmo chiederci se conosciamo e comprendiamo la relazione esistente tra rischio e rendimento di un investimento e il principio di diversificazione del rischio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0305", "question": "Come può influenzare l'esperienza passata le scelte di investimento?", "answer": "In merito all'esperienza maturata in tema di investimenti, è importante ricordare che l'esito delle scelte pregresse può influenzare il nostro atteggiamento verso un determinato strumento finanziario. Un'esperienza di investimento positiva, ad esempio, può renderci più ottimisti e indurci a sopravvalutare le nostre conoscenze e la nostra capacità (economica ed emotiva) di assumere rischi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0306", "question": "Da cosa dipende la capacità economica di assumere rischi?", "answer": "La nostra capacità economica di assumere rischi è influenzata, ovviamente, dal nostro reddito e dalla nostra ricchezza. È importante, però, tenere presenti anche il reddito e la ricchezza complessivi della nostra famiglia, poiché il livello e la distribuzione del reddito e della ricchezza tra i membri di una famiglia possono incidere anche sulle scelte di consumo e investimento dei singoli. Al fine di definire più correttamente la nostra capacità di risparmio (e quindi d'investimento), bisognerebbe inoltre tener conto delle più significative voci di spesa del nostro nucleo familiare (legate ad esempio all'affitto, al mutuo e al numero di figli), nonché dei fattori che possono incidere sulla regolarità e sull'utilizzo delle entrate (l'età di pensionamento programmata, le aspettative di variazioni del reddito, etc.).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0307", "question": "Quali fattori incidono sulla definizione del periodo di investimento e delle sue finalità?", "answer": "I fattori appena citati sono importanti anche ai fini della definizione del periodo di tempo per il quale desideriamo conservare l'investimento e le finalità dell'investimento stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0308", "question": "Da cosa dipende la capacità emotiva di assumere rischi?", "answer": "La nostra capacità emotiva di assumere rischi, corrispondente al cosiddetto \"profilo di rischio\" dell'investitore, dipende da molteplici fattori, quali la nostra personalità e le inclinazioni individuali, il genere, il livello di cultura finanziaria, lo stato emotivo legato all'andamento dell'economia o dei mercati di borsa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0309", "question": "Quali informazioni deve ottenere l'intermediario per valutare l'adeguatezza secondo la Direttiva MiFID?", "answer": "La Direttiva 2004/39/CE (MiFID livello 1) prevede che, ai fini della valutazione dell'adeguatezza, l'intermediario debba ottenere dal cliente informazioni in merito a: conoscenze ed esperienze in materia di investimenti e al tipo specifico di prodotto o servizio, alla situazione finanziaria e agli obiettivi d'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0310", "question": "Quali dettagli specifici suggerisce di richiedere la Direttiva di attuazione 2006/73/CE?", "answer": "La Direttiva di attuazione 2006/73/CE (livello 2) suggerisce all'intermediario di richiedere al cliente informazioni in merito a: 1a) servizi/operazioni/strumenti finanziari con i quali il cliente ha dimestichezza; 1b) natura/volume/holding-period/frequenza delle operazioni realizzate; 1c) livello di istruzione e professione o, se rilevante, precedente professione. 2a) fonte e consistenza del reddito regolare; 2b) attività, comprese le attività liquide; 2c) investimenti e beni immobili; 2d) impegni finanziari regolari. 3a) periodo di tempo per il quale il cliente desidera conservare l'investimento; 3b) preferenze in materia di rischio; 3c) profilo di rischio; 3d) finalità dell'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/profilatura-e-valutazione-di-adeguatezza"}},
{"id": "chunk_0311", "question": "Cosa si intende per rischio e rendimento?", "answer": "Il rendimento è una grandezza facilmente misurabile; il rischio, invece, risulta difficilmente misurabile in quanto è una grandezza soggettiva la cui percezione è influenzata da molteplici fattori. Talvolta è difficile comprendere il giusto equilibrio tra rendimento e rischio. Ricordati che rischio e rendimento crescono insieme! Solo se abbiamo chiaro questo, possiamo valutare correttamente l'attività che promette un rendimento elevato, comunque non in linea con quello del mercato, come un'attività più rischiosa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0312", "question": "Perché è importante comprendere il rapporto tra rischio e rendimento?", "answer": "Ricordati che rischio e rendimento crescono insieme! Solo se abbiamo chiaro questo, possiamo valutare correttamente l'attività che promette un rendimento elevato, comunque non in linea con quello del mercato, come un'attività più rischiosa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0313", "question": "Cosa rappresenta il rischio negli investimenti?", "answer": "Il rischio altro non è che il prezzo da pagare per la possibilità di un maggior guadagno rispetto ad investimenti alternativi che promettono un minor guadagno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0314", "question": "Quali devono essere le aspettative di rendimento di un investitore?", "answer": "Le aspettative di rendimento devono essere realistiche: non si può \"pretendere la luna\" e soprattutto, si deve essere consapevoli che a maggiori rendimenti corrispondono maggiori rischi. Pertanto, se desideriamo un investimento che accresca il valore del nostro capitale, e non ne protegga semplicemente il potere d'acquisto dall'inflazione, dovremo essere pronti ad assumerci più rischi!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0315", "question": "Che cos'è la propensione al rischio?", "answer": "La propensione al rischio rappresenta la disponibilità a sopportare perdite patrimoniali dovute all'andamento negativo del mercato, al fallimento dell'emittente dello strumento finanziario in cui abbiamo investito o al fatto che non esiste un mercato liquido. Quanto più siamo propensi al rischio, tanto più siamo disposti ad accettare che l'investimento non consegua i risultati che ci attendevamo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0316", "question": "Cosa deve fare un investitore prima di decidere di investire?", "answer": "Nel momento in cui decidi di investire, devi: - quantificare la percentuale del patrimonio investito che sei disposto a perdere in un determinato periodo di tempo se le condizioni di mercato non si rivelassero favorevoli (\"capacità di rischio\" o \"rischio oggettivo\"); tale percentuale dipende dalla tua situazione economica corrente e dalle tue prospettive reddituali - valutare il rischio dell'investimento proposto cercando di evitare che la tua percezione del rischio sia falsata da variabili quali la modalità di rappresentazione dell'informazione di prodotto, giudizi affrettati o gli esiti delle scelte pregresse, etc.. - definire il tuo grado di \"tolleranza al rischio\", ossia la tua capacità emotiva di assumere rischio e affrontare situazioni di incertezza (rischio soggettivo); il livello di tolleranza al rischio di ciascun individuo dipende tipicamente da molteplici fattori, quali la personalità e le inclinazioni individuali, lo specifico stato emotivo, il genere, il livello di cultura finanziaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0317", "question": "Cosa si intende per capacità di rischio o rischio oggettivo?", "answer": "La capacità di rischio o rischio oggettivo è la percentuale del patrimonio investito che sei disposto a perdere in un determinato periodo di tempo se le condizioni di mercato non si rivelassero favorevoli; tale percentuale dipende dalla tua situazione economica corrente e dalle tue prospettive reddituali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0318", "question": "Cosa si intende per tolleranza al rischio?", "answer": "La tolleranza al rischio è la tua capacità emotiva di assumere rischio e affrontare situazioni di incertezza (rischio soggettivo); il livello di tolleranza al rischio di ciascun individuo dipende tipicamente da molteplici fattori, quali la personalità e le inclinazioni individuali, lo specifico stato emotivo, il genere, il livello di cultura finanziaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0319", "question": "Da cosa può dipendere la percezione del rischio di un investitore?", "answer": "La percezione del rischio può essere falsata da variabili quali la modalità di rappresentazione dell'informazione di prodotto, giudizi affrettati o gli esiti delle scelte pregresse, etc..", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischio-e-rendimento"}},
{"id": "chunk_0320", "question": "Cosa accade ai mercati finanziari durante una crisi?", "answer": "È importante sapere cosa accade ai mercati finanziari durante una crisi e quali sono i fattori psicologici e comportamentali che possono influenzare in negativo le decisioni in materia di investimenti in modo da poter compiere scelte ponderate anche in tempi difficili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0321", "question": "Quali effetti ha avuto la pandemia di Covid-19 sui mercati finanziari?", "answer": "La pandemia Covid-19 ha scatenato una crisi il cui impatto sui mercati finanziari ripropone, anche se in misura amplificata, quanto avvenuto nel caso di epidemie precedenti - la SARS nel 2003, l'influenza suina nel 2009, la MERS nel 2012 - nonché in altri periodi di crisi succedutisi nella storia. La diffusione del virus a livello globale e le misure di contenimento del contagio hanno provocato un incremento della volatilità dei mercati finanziari e la diminuzione del valore di numerose attività finanziarie, sulla scia di un forte peggioramento delle prospettive economiche a livello mondiale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0322", "question": "Perché gli investimenti dei risparmiatori subiscono perdite in tempi di crisi?", "answer": "In queste circostanze, gli investimenti dei risparmiatori possono subire diversi contraccolpi, registrando perdite di valore anche molto significative. Ciò è tanto più probabile quanto minore è la diversificazione del portafoglio, ossia quanto più gli investimenti sono concentrati su poche tipologie di strumenti e in titoli emessi da società che operano nello stesso settore o nella stessa area geografica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0323", "question": "Cosa si intende per volatilità dei mercati azionari durante una crisi?", "answer": "I mercati azionari di solito reagiscono, nel breve termine, con forti oscillazioni dei prezzi al rialzo e al ribasso, causate da variazioni significative nel volume degli scambi, più o meno ampie a seconda dell'esposizione delle società agli effetti della crisi. Nel lungo periodo, tuttavia, queste oscillazioni sono destinate a ridursi se le prospettive economiche delle società emittenti sono solide.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0324", "question": "Cosa si intende per illiquidità dei mercati durante le crisi?", "answer": "Nelle fasi di turbolenza dei mercati i numerosi investitori che vogliono vendere i propri titoli non sempre riescono a incontrare immediatamente investitori disposti ad acquistare al prezzo desiderato. In alcuni momenti, quindi, può diventare difficile disinvestire i propri investimenti, se non al costo di accettare perdite significative o di dover aspettare molto tempo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0325", "question": "Qual è la differenza tra settori ciclici e difensivi?", "answer": "Nel mercato azionario, i prezzi dei titoli possono reagire in modo diverso alla crisi a seconda del settore di attività. Taluni settori, definiti difensivi o anti-ciclici, non necessariamente seguono l'andamento complessivo dell'economia: nell'ambito della crisi da Covid-19, è il caso, ad esempio, del settore farmaceutico o di quello del commercio elettronico. Altri settori, che si definiscono ciclici, sono più esposti all'andamento complessivo dell'economia: nella crisi dovuta alla pandemia di Covid-19, ad esempio, i settori aeronautico, della ristorazione e quello petrolifero hanno subito in maniera più marcata l'impatto negativo connesso alle misure di contenimento del contagio attuate dai vari Paesi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0326", "question": "Cosa afferma la finanza comportamentale sul comportamento degli investitori?", "answer": "La finanza comportamentale ha da tempo evidenziato che nelle scelte economico-finanziarie gli individui non agiscono in modo razionale, poiché non hanno la capacità cognitiva di elaborare le innumerevoli informazioni a propria disposizione, individuare tutti i possibili scenari futuri, scegliere l'opzione migliore tra quelle disponibili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0327", "question": "Quali sono i due Sistemi descritti da Daniel Kahneman?", "answer": "Il Premio Nobel Daniel Kahneman ha descritto il processo decisionale come la risultante dell'interazione tra due Sistemi: il Sistema 1, rapido e impulsivo, perché basato sulle cosiddette scorciatoie mentali (euristiche) che permettono di scegliere velocemente semplificando (in modo errato) situazioni complesse; e il Sistema 2, lento e riflessivo perché basato su valutazioni razionali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0328", "question": "Cosa significa avversione alle perdite?", "answer": "Gli individui sono in genere molto più sensibili alla possibilità di perdere rispetto alla possibilità di guadagnare un determinato importo. In termini quantitativi, come è stato mostrato da esperimenti di laboratorio, la reazione emotiva alle perdite è in media due volte più intensa della reazione di guadagni di pari importo. Durante i periodi di crisi, la sensibilità alle perdite aumenta poiché aumenta il rischio percepito e, conseguentemente, l'avversione al rischio stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0329", "question": "Cosa si intende per euristica affettiva?", "answer": "In alcune circostanze le decisioni di investimento possono essere influenzate dalla risposta emotiva a determinate informazioni (affect). L'affect cambia la percezione dei benefici e dei rischi di una decisione, accentuando i primi o i secondi se alle informazioni relative alla decisione si associano sentimenti, rispettivamente, positivi o negativi. Durante i periodi di crisi e di forte volatilità dei mercati, la paura può alimentare una sopravvalutazione del rischio di perdere il capitale investito e spingere a vendere i titoli in portafoglio in modo affrettato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0330", "question": "Cosa si intende per action bias?", "answer": "Non fare nulla mentre i mercati crollano può essere molto difficile, perché si scontra con l'istinto ad agire e con la propensione a cercare conforto nella consapevolezza di aver almeno tentato di contenere le perdite vendendo i titoli in portafoglio. È dimostrato che la perdita è meno penosa se è stato fatto qualcosa per provare ad evitarla.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0331", "question": "Cosa rappresenta il recency bias?", "answer": "In periodi di crisi proiettarsi verso scenari positivi può apparire una forzatura. L'idea che i prezzi di mercato possano tornare a salire viene sopraffatta dall'informazione relativa ai recenti cali dei valori di mercato, che diventa saliente fungendo da àncora. Gli individui, infatti, tendono a recuperare nella memoria l'informazione più recente e a basare su quella le loro aspettative per il futuro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0332", "question": "Cos'è il comportamento gregario?", "answer": "Gli investitori tendono a imitare i comportamenti più diffusi, sia perché non sono in grado di prendere decisioni in autonomia a fronte delle conoscenze e delle informazioni disponibili sia perché possono condividere con altri la responsabilità di una scelta che ex post si riveli sbagliata. Tale comportamento ricorre sia nelle bolle speculative, quando l'ottimismo irrazionale spinge gli acquisti e gonfia i valori di mercato, sia nei periodi di forte turbolenza, quando la reazione eccessiva degli investitori si traduce nel fenomeno noto come panic selling, ossia vendite massive che innescano una spirale dei prezzi al ribasso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0333", "question": "Come reagire in tempi di crisi finanziaria?", "answer": "Diversificare il portafoglio degli investimenti finanziari - in termini di strumenti, settori e mercati - può aiutare ad attutire gli effetti di una crisi. La diversificazione tuttavia non può eliminare il cosiddetto rischio sistemico, ossia il rischio che dipende da fattori che influiscono sull'andamento generale del mercato e quindi di tutti i titoli scambiati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0334", "question": "Quali regole di comportamento seguire durante una crisi?", "answer": "Evita di prendere decisioni basate sulla paura, sull'impulsività e sull'imitazione dei comportamenti altrui. Evita di controllare continuamente il valore del tuo portafoglio. Riconsidera le tue scelte di investimento purché le tue decisioni non siano guidate dal panico. Informati scegliendo accuratamente le fonti informative, consulta i siti istituzionali della CONSOB e del Comitato Nazionale per l'Educazione Finanziaria. Sii consapevole che nei periodi di crisi aumenta la diffusione di fake news e il rischio di truffe. Rivolgiti a persone esperte se hai dubbi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0335", "question": "Cosa succede ai cittadini durante una crisi economico-finanziaria?", "answer": "Ogni crisi economico-finanziaria genera ansia e disagio nei cittadini, che possono subirne gli effetti in modo più o meno accentuato anche a seconda delle condizioni personali preesistenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0336", "question": "Perché è difficile gestire le finanze personali durante le crisi?", "answer": "Gestire le finanze personali nel clima di incertezza tipico delle crisi può essere faticoso. Può essere difficile, inoltre, orientarsi tra le tante informazioni e i tanti consigli che arrivano da più fonti, non tutte affidabili (come le fake news).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0337", "question": "Quali rischi possono presentarsi durante le crisi economiche per i cittadini?", "answer": "In alcuni casi, infatti, si può diventare bersaglio di truffatori che cavalcano la crisi per realizzare iniziative illecite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0338", "question": "Quali strumenti di tutela prevede l'ordinamento per il buon funzionamento del mercato finanziario durante le crisi?", "answer": "L'ordinamento prevede numerosi presidi a tutela del buon funzionamento del mercato finanziario. La CONSOB infatti, monitora affinché le informazioni diffuse nei mercati finanziari siano corrette e vigila costantemente per individuare ipotesi di abuso di mercato (manipolazione e insider trading vedi scheda sui mercati finanziari).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0339", "question": "Quali poteri esercita la CONSOB per assicurare la trasparenza delle negoziazioni?", "answer": "L'Autorità esercita, poi, i poteri previsti dall'ordinamento volti ad assicurare che le negoziazioni si svolgano in maniera trasparente e ordinata: ad esempio, nei casi previsti dalla legge può sospendere ed escludere strumenti finanziari dalle negoziazioni qualora intervengano fatti in grado di turbare gli scambi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0340", "question": "Come si assicura la CONSOB che i gestori di mercato siano preparati a gestire le oscillazioni?", "answer": "La CONSOB si accerta, inoltre, che i gestori delle infrastrutture di negoziazione (ad esempio, le società di gestione del mercato azionario) dispongano di adeguati sistemi per gestire le oscillazioni del mercato (cosiddetti circuit breaker, ossia meccanismi per la sospensione automatica degli scambi).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0341", "question": "Quali misure può adottare la CONSOB in situazioni straordinarie come la crisi da Covid-19?", "answer": "In particolari condizioni, come durante la crisi da Covid-19, e in coordinamento con l'Autorità europea competente, l'Istituto può adottare provvedimenti restrittivi di alcuni tipi di operatività sui mercati (cosiddetto divieto di short selling).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0342", "question": "Cosa accade ai partecipanti del mercato nei periodi di crisi?", "answer": "Nonostante i numerosi presidi e sebbene le fasi ribassiste siano fisiologiche, è normale che nei periodi di crisi si creino condizioni di incertezza che disorientano i partecipanti al mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0343", "question": "Quali errori possono commettere i piccoli investitori durante le crisi finanziarie?", "answer": "I piccoli investitori, in particolare, possono compiere scelte affrettate e inadeguate rispetto alla propria situazione personale spinti dal timore di perdere tutto o parte dei risparmi investiti in strumenti e prodotti finanziari, il cui valore di mercato può oscillare di frequente e portarsi anche al di sotto del prezzo di acquisto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/investimenti-nelle-crisi"}},
{"id": "chunk_0344", "question": "Perché l'informazione è fondamentale nei mercati finanziari?", "answer": "Nei mercati finanziari l'informazione ha un valore intrinseco centrale in quanto è alla base delle decisioni di tutti i partecipanti al mercato. Sull'informazione disponibile si fondano infatti le decisioni degli investitori di acquistare o vendere i titoli scambiati nel mercato (ad esempio, azioni e obbligazioni). Gli scambi a loro volta concorrono alla formazione dei prezzi dei titoli. È dunque fondamentale che l'informazione sia chiara, corretta e non fuorviante, come evocato anche dalla legislazione dei mercati finanziari e dalle norme a tutela dei risparmiatori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0345", "question": "Qual è il ruolo della CONSOB riguardo alle informazioni di mercato?", "answer": "La CONSOB vigila sulla correttezza delle informazioni che vengono diffuse nei mercati finanziari affinché le negoziazioni si svolgano in maniera trasparente e ordinata; altrettanto importante è l'attività di controllo tesa a individuare ipotesi di prestazione abusiva dei servizi di investimento (vedi sezione Occhio alle truffe!).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0346", "question": "Come definisce Treccani le fake news?", "answer": "L'enciclopedia digitale Treccani definisce le fake news come \"un'informazione in parte o del tutto non corrispondente al vero, divulgata intenzionalmente o inintenzionalmente attraverso il Web, i media o le tecnologie digitali di comunicazione, e caratterizzata da un'apparente plausibilità, quest'ultima alimentata da un sistema distorto di aspettative dell'opinione pubblica e da un'amplificazione dei pregiudizi che ne sono alla base, ciò che ne agevola la condivisione e la diffusione pur in assenza di una verifica delle fonti\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0347", "question": "Quali aspetti importanti mette in evidenza la definizione di fake news?", "answer": "Questa definizione pone l'accento su tre aspetti importanti. Anzitutto le fake news sono informazioni che, pur essendo parzialmente o totalmente false, appaiono vere. In secondo luogo, le fake news sono diffuse attraverso i mezzi di comunicazione, rappresentati tradizionalmente dai grandi media (televisioni e testate giornalistiche) e negli ultimi anni canali digitali (internet e media sociali o social networks) che ne hanno accelerato la condivisione tra gli utenti. Infine, le fake news fanno leva su aspettative e pregiudizi che le rendono credibili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0348", "question": "In che modo lo sviluppo del web ha influenzato la diffusione delle fake news?", "answer": "Il fenomeno delle fake news si è acuito a seguito dello sviluppo del web, che ne ha accentuato la diffusione quanto a velocità e pervasività. La condivisione istintiva o involontaria di informazioni false ne amplifica la circolazione attraverso canali popolari e caratterizzati da un elevato grado di utilizzo: basti pensare all'impatto dei commenti, dei cosiddetti like, dei condividi sulla diffusione di informazioni nelle piattaforme social (quali ad esempio, Facebook e Twitter). La condivisione da parte delle persone si potenzia a causa della presenza dei cosiddetti 'bot', ossia robot in grado di rilanciare più e più volte la fake news diffondendola in maniera mirata (ad esempio, tramite pagine web o messaggi in chat).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0349", "question": "Che cos'è l'infodemia e quando si manifesta?", "answer": "La circolazione delle fake news tende a intensificarsi nei periodi dominati da grande incertezza. A fronte dell'emergenza sanitaria causata dal Covid-19, ad esempio, la diffusione di disinformazione è aumentata in misura esponenziale tanto che l'Organizzazione Mondiale della Sanità ha parlato di 'infodemia'. Alla base di questo fenomeno vi è l'attesa di notizie rassicuranti che aumenta il numero di persone disposte a ritenere veritiere notizie che in apparenza tranquillizzano e che appaiono verosimili anche per l'ampia propagazione e i canali di diffusione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0350", "question": "In che modo le fake news possono influenzare i mercati finanziari e le scelte di investimento?", "answer": "L'ordinato svolgimento delle negoziazioni potrebbe essere turbato, ad esempio, da un tentativo di manipolazione informativa, ossia dalla diffusione di una notizia falsa in grado di influenzare l'andamento dell'intero listino o il prezzo dei titoli di una singola società quotata (vedi la scheda Mercati finanziari). In tale caso le fake news possono assumere la forma di comunicati stampa volti a manipolare i prezzi delle azioni o di avvisi/notizie/ricerche/articoli che possono incidere sul valore dei titoli. La platea di soggetti in grado di influire sui prezzi dei titoli scambiati nei mercati, per trarne un vantaggio economico, tramite la diffusione di informazioni false è ampia: tra questi, vi possono essere società quotate, manager, analisti finanziari, giornalisti, grandi investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0351", "question": "Quali mezzi utilizzano soggetti non autorizzati per veicolare fake news ai risparmiatori?", "answer": "Vi sono inoltre soggetti non autorizzati alla prestazione di servizi di investimento che veicolano fake news - ad esempio sotto forma di pubblicità ingannevole, avvisi, sms, newsletter di investimento, annunci online, falsi siti, mail ingannevoli sui prodotti di investimento - ai singoli risparmiatori con l'obiettivo di ingannarli e di indurli ad aderire a proposte di investimento apparentemente molto redditizie: si tratta in realtà di casi di abusivismo che possono nascondere una truffa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0352", "question": "Chi diffonde una fake news e quali sono i loro interessi?", "answer": "- è consapevole della falsità della notizia (ossia l'obiettiva difformità dal vero, l'esagerazione, la tendenziosità) e agisce con l'intento di disinformare e di ingannare; - ha interesse a fare in modo che la fake news raggiunga il maggior numero di persone possibile, soprattutto perché nell'epoca dei social network la crescita del numero di follower (anche fittizi) può corrispondere a un guadagno, anche economico: a tal fine, spesso rimanda a fonti o dati che paiono rilevanti e attendibili; - ha interesse a costruirsi la reputazione necessaria a carpire la fiducia dei risparmiatori. Attraverso siti personali accattivanti, articoli a pagamento presentati come interviste, profili social in cui si millantano o si mescolano artificiosamente competenze, titoli di studio, relazioni internazionali e successi finanziari, è possibile costruire un guru virtuale della finanza, che può proporre abbonamenti, iscrizioni e/o piccoli investimenti e che ricorda le caratteristiche del truffatore Charles Ponzi; - ha interesse ad accedere alle informazioni personali dei malcapitati per trarne un guadagno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0353", "question": "Perché può essere difficile per un piccolo risparmiatore identificare una fake news e cosa è importante conoscere?", "answer": "Per un piccolo risparmiatore può essere molto difficile identificare una notizia falsa che irrompe sul mercato e viene rilanciata attraverso canali di informazione ritenuti affidabili. Ci sono tuttavia alcuni elementi che possono aiutare a riconoscere le fake news che possono raggiungerlo attraverso la sua rete di contatti, le mail e i social network. A tal fine è importante conoscere: - le caratteristiche tipiche delle fake news; - i meccanismi mentali sui quali le fake news fanno leva per attrarre il malcapitato; - come proteggersi dalle fake news.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0354", "question": "Quali sono le caratteristiche tipiche delle fake news?", "answer": "- Il carattere di novità e la forte connotazione emotiva della notizia falsa catturano l'attenzione, sollecitano l'interesse e spingono alla condivisione. - La salienza, ossia la rilevanza percepita, contribuisce alla diffusione dell'informazione perché quanto più una notizia viene percepita come utile o anche solo accattivante, tante più persone vorranno condividerla. - La diffusione e la ripetizione: le notizie false si auto-alimentano. Primo Levi diceva \"quante sono le menti umane capaci di resistere alla lenta, feroce, incessante, impercettibile forza di penetrazione dei luoghi comuni?\" - La mancanza di prove concrete o di riferimenti scientifici. - Le foto e le immagini eventualmente associate alle fake news possono essere false oppure riferirsi a situazioni e contesti diversi da quelli oggetto della fake news. - L'eventuale presenza di errori di battitura e grammaticali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0355", "question": "Quali meccanismi mentali sfruttano le fake news per ingannare le persone?", "answer": "Come mostrato dalla finanza comportamentale, posti di fronte a una gran mole di informazioni da raccogliere, elaborare e utilizzare, tendiamo a lasciarci guidare da ìscorciatoie mentali' o a farci trarre in inganno da errori di percezione e trappole comportamentali. - L'eccesso di informazioni (information overload): spesso avere tante informazioni a disposizione non migliora le capacità di analisi e di scelta; tanta informazione può rivelarsi controproducente e generare confusione, perché non tutti hanno l'attenzione idonea o le capacità di analizzarla e di utilizzarla in modo appropriato. - I costi della verifica: appurare la veridicità di una notizia può richiedere ricerche e accertamenti impegnativi che non tutti hanno tempo e modo di fare. - La familiarità, la notorietà, lo stereotipo falsano la percezione e la valutazione inducendo a ritenere più probabile e veritiero un evento che sembra familiare. - La disponibilità: gli individui sono influenzati dalla facilità con la quale le informazioni possono essere richiamate alla mente (ad esempio, perché se ne è parlato diffusamente in rete). - Familiarità e disponibilità alimentano il cosiddetto effetto validità (la verità illusoria, illusory truth effect), ossia la tendenza a credere che le informazioni false siano corrette dopo essere stati ripetutamente esposti alle stesse. - L'ancoraggio: un'informazione iniziale saliente agisce da àncora, impedendo la revisione e la correzione della valutazione di partenza nonostante il sopraggiungere di nuove notizie di segno contrario. - L'effetto inquadramento (framing effect): percezioni, valutazioni e preferenze degli individui sono sensibili al modo in cui l'informazione viene rappresentata. In altri termini, le decisioni possono essere influenzate dal modo in cui le opzioni di scelta e le relative conseguenze vengono presentate e non dai dati e dalle informazioni in sé. - Il confirmation bias (o ideological bias): si tende a cercare conferme delle proprie opinioni o dei fatti che le supportano, mentre non si prendono in considerazione i dati che le contraddicono. - L'ingenuità (gullibility): alcuni soggetti tendono più di altri a fidarsi eccessivamente di persone, fonti informative e notizie, per inesperienza o propensione individuale. - L'impulsività: alcune persone tendono a reagire a una notizia senza riflettere, ad esempio sull'onda dell'emotività. - Il desiderio di condivisione: il desiderio, esteso in modo significativo dai social network, di essere parte attiva di un flusso informativo condividendo tante informazioni con la propria rete di contatti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0356", "question": "Quali azioni pratiche suggerisce il testo per proteggersi dalle fake news?", "answer": "Verifica la fonte, consulta più fonti e, quando possibile, affidati a fonti ufficiali. Ricerca e controlla le informazioni sui siti dei soggetti a cui le fake news si riferiscono, sui siti delle Istituzioni e delle Autorità di vigilanza. In particolare per le notizie finanziarie occorre fare riferimento a siti istituzionali per la quotazione di titoli e indici di mercato, e ai siti ufficiali dei maggiori quotidiani economici per verificare la notizia. Verifica i documenti ufficiali: ad esempio, nel caso in cui ti raggiungano proposte di investimento ricerca e controlla la documentazione ufficiale che dovrebbe accompagnare e descrivere le caratteristiche dell'investimento proposto. Qualora tu abbia ricevuto un link per l'accesso al sito web che confermerebbe la fake news, verifica che il sito al quale sei stato indirizzato non sia un clone di siti web legittimi (spoofing): utilizza i motori di ricerca per raggiungere autonomamente i siti di interesse. Diffida di informazioni che fanno affermazioni sorprendenti ma sono descritte con messaggi che presentano evidenti errori grammaticali e di battitura. Confronta informazioni differenti provenienti da fonti diverse. Chiediti se l'informazione si riferisce a un fatto o a un'opinione e se fatti e/o opinioni sono supportati da dati verificabili presso altre fonti. Leggi criticamente: non fermarti alla prima lettura, affidati al ragionamento e non solo all'istinto. Soffermati sul significato dei dati disponibili e concediti del tempo per riflettere sulle informazioni acquisite e sulle opzioni di scelta a tua disposizione! Chiediti se il modo in cui l'informazione è offerta non stia orientando la tua attenzione su un profilo in particolare, distraendoti da altre notizie parimenti importanti. Cerca attivamente dati e fatti che ti contraddicano, fonti che smentiscano le tue opinioni, argomentazioni che possano dimostrare l'infondatezza dell'informazione già in tuo possesso a cui stai ‘ancorando' le tue valutazioni. Prendi tutto il tempo necessario: è un errore decidere immediatamente sulla spinta delle emozioni generate da notizie e andamenti dei mercati. Rifletti prima di condividere le informazioni che hai ricevuto, ossia prima di passare-parola ai tuoi contatti! Non condividere informazioni che non hai verificato o non sei in grado di verificare per non alimentare la circolazione di fake news. Fai leva sul tuo desiderio di essere considerato una persona credibile, sincera e affidabile: tutti tengono al giudizio delle persone che si hanno accanto! Rivolgiti a persone esperte. Se hai dubbi chiedi a un esperto: nel caso di informazioni relative a proposte di investimento potrebbe essere utile chiedere un supporto, ad esempio, all'intermediario di riferimento. Ricorda che in finanza non esistono \"pasti gratis\". Una notizia che si associa a un'inaspettata prospettiva di un elevato guadagno - per giunta se in tempi brevi - deve essere valutata con molto scetticismo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0357", "question": "Qual è l'importanza di verificare documenti e siti quando si riceve una notizia finanziaria?", "answer": "Verifica i documenti ufficiali: ad esempio, nel caso in cui ti raggiungano proposte di investimento ricerca e controlla la documentazione ufficiale che dovrebbe accompagnare e descrivere le caratteristiche dell'investimento proposto. Qualora tu abbia ricevuto un link per l'accesso al sito web che confermerebbe la fake news, verifica che il sito al quale sei stato indirizzato non sia un clone di siti web legittimi (spoofing): utilizza i motori di ricerca per raggiungere autonomamente i siti di interesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0358", "question": "Che avvertimento finale dà il testo riguardo alle notizie di guadagni elevati facili?", "answer": "Ricorda che in finanza non esistono \"pasti gratis\". Una notizia che si associa a un'inaspettata prospettiva di un elevato guadagno - per giunta se in tempi brevi - deve essere valutata con molto scetticismo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/fake_news-covid"}},
{"id": "chunk_0359", "question": "Cos'è un'azione?", "answer": "Investire i propri risparmi sottoscrivendo o acquistando delle azioni equivale a partecipare direttamente all'attività d'impresa svolta dalla società che emette le azioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0360", "question": "Cosa comporta l'acquisto di azioni?", "answer": "Ciò comporta che l'investitore rimane esposto al rischio d'impresa della società: dall'andamento della specifica attività d'impresa dipende il rendimento dell'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0361", "question": "Cosa può accadere in caso di fallimento della società in cui ho investito?", "answer": "In caso negativo, ad esempio, in caso di fallimento della società, l'investitore potrebbe anche perdere completamente il capitale investito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0362", "question": "Quali diritti acquisisce l'investitore quando diventa socio di una società per azioni?", "answer": "L'investitore acquisisce lo status di socio, al quale sono ricollegati specifici diritti: in particolare, l'attribuzione di diritti patrimoniali (diritto agli utili, diritto alla quota di liquidazione) consente al socio di percepire i frutti, qualora ve ne siano, del proprio investimento o di mantenere inalterato il suo valore (diritto di opzione) mentre l'attribuzione di diritti amministrativi consente all'azionista di essere adeguatamente informato sull'andamento della società, di controllare l'operato degli organi sociali nonché, nella misura e nei tempi previsti dalla legge, di poter incidere su alcune importanti decisioni sociali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0363", "question": "Come può l'azionista monitorare il proprio investimento?", "answer": "Esercitare i diritti sociali rappresenta il modo migliore per monitorare il proprio investimento, anche al fine di adottare iniziative opportune per tutelarne la redditività nel caso la gestione messa in atto dagli amministratori non sia svolta nel rispetto della legge o dell'interesse sociale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0364", "question": "Cosa rappresenta un'azione all'interno di una società?", "answer": "L'azione rappresenta la quota di partecipazione minima al capitale sociale di una società; essendo omogenea e standardizzata, attribuisce, di norma, uguali diritti ai vari possessori di azioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0365", "question": "Cosa sono i cosiddetti \"diritti a soglia\"?", "answer": "Alcuni diritti possono essere esercitati solo se si possiede una quota minima del capitale sociale della società (cosiddetti \"diritti a soglia\"), ma in tali casi più soci possono aggregare le proprie partecipazioni azionarie al fine di raggiungere la quota minima richiesta ed esercitare congiuntamente i diritti sociali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0366", "question": "Perché l'assemblea dei soci è importante per gli azionisti?", "answer": "L'assemblea dei soci rappresenta uno dei momenti di maggior rilievo nella vita della società: infatti, i soci riuniti in assemblea adottano alcune delle decisioni più importanti per la società ed è in tal modo che gli investitori possono condizionare l'andamento della stessa e il comportamento degli amministratori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0367", "question": "Quali sono le principali competenze dell'assemblea dei soci?", "answer": "L'assemblea dei soci nomina i componenti degli organi sociali, può revocare i componenti degli stessi organi, approva il bilancio e delibera sulla distribuzione degli utili, approva le modifiche dello statuto sociale e alcune operazioni straordinarie, e decide su particolari operazioni come il cosiddetto \"whitewash\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0368", "question": "Chi nomina gli amministratori e l'organo di controllo interno della società?", "answer": "L'assemblea dei soci nomina i componenti degli organi sociali: in particolare, nomina gli amministratori, ai quali spetta gestire la società nell'interesse di tutti i soci, e i componenti dell'organo di controllo interno, i quali sono tenuti a controllare che l'operato degli amministratori rispetti la legge e l'interesse sociale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0369", "question": "Cosa può fare l'assemblea se gli amministratori non gestiscono correttamente la società?", "answer": "L'assemblea può revocare, anche senza giusta causa, i componenti degli stessi organi sociali: tale decisione può rivelarsi particolarmente importante per sostituire quegli amministratori che non si siano dimostrati in grado di gestire proficuamente la società oppure per rimuovere amministratori o sindaci che non abbiano operato correttamente e nel rispetto della legge.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0370", "question": "Quando si approva il bilancio e perché è importante per i soci?", "answer": "Il bilancio di esercizio deve essere approvato ogni anno (art. 2364 c.c.), ciò significa che l'assemblea che si tiene annualmente a tale scopo costituisce un'occasione irripetibile per i soci per essere ragguagliati e informati, anche in dettaglio, sull'andamento della società e sull'operato degli organi sociali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0371", "question": "Quali modifiche può approvare l'assemblea dei soci?", "answer": "L'assemblea approva le modifiche dello statuto sociale e alcune importanti operazioni straordinarie, quali l'aumento o la riduzione del capitale sociale, le operazioni di fusione e scissione, l'emissione di azioni speciali o di altri strumenti finanziari nonché l'eventuale scioglimento o la messa in liquidazione della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0372", "question": "Cosa si intende per decisioni di tipo \"whitewash\"?", "answer": "Ai soci di minoranza, sempre riuniti in assemblea, è attribuita la competenza a decidere su particolari operazioni (cosiddetto \"whitewash\"): in tali casi, le decisioni rimesse all'assemblea sono approvate solo con il voto favorevole della maggioranza dei soci diversi da quelli che hanno un interesse specifico nell'operazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0373", "question": "Quali sono esempi di operazioni che rientrano nel cosiddetto whitewash?", "answer": "Si tratta del caso di operazioni con parti correlate significative il cui compimento sia ostacolato dal parere negativo espresso dagli amministratori indipendenti oppure delle operazioni di ristrutturazione che l'assemblea è chiamata a deliberare in situazione di crisi e dalle quali deriverebbe l'obbligo di lanciare un'offerta pubblica d'acquisto su tutti i titoli dell'emittente in circolazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0374", "question": "Perché è importante l'assemblea dei soci per un azionista?", "answer": "Considerata l'importanza dell'assemblea, può essere utile ricordare come gli azionisti possono prendervi parte ed esprimere il proprio voto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0375", "question": "Cosa deve fare un azionista prima di partecipare all'assemblea?", "answer": "È bene prendere visione e leggere con attenzione tutte le informazioni contenute nell'avviso di convocazione dell'assemblea della società (art. 125-bis TUF).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0376", "question": "Quando deve essere pubblicato l'avviso di convocazione dell'assemblea?", "answer": "L'avviso di convocazione deve essere pubblicato almeno 30 giorni prima della data fissata per l'assemblea (40 giorni prima, nel caso l'assemblea sia stata convocata per la nomina degli organi sociali) sul sito internet della società e per estratto su quotidiani a diffusione nazionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0377", "question": "Cosa deve contenere l'avviso di convocazione dell'assemblea?", "answer": "Nell'avviso sono indicati: giorno, ora e luogo dell'adunanza nonché l'elenco delle materie da trattare; le procedure da rispettare per poter partecipare e votare in assemblea, ivi comprese le informazioni riguardanti il diritto di porre domande prima dell'assemblea e il diritto di integrare l'ordine del giorno o di presentare ulteriori proposte su materie già all'ordine del giorno, nonché le eventuali ulteriori modalità per l'esercizio di tali diritti; la procedura per l'esercizio del voto per delega e le procedure di voto per corrispondenza o con mezzi elettronici, se previsto dallo statuto; la record date; le modalità e i termini di reperibilità del testo integrale delle proposte di deliberazione, unitamente alle relazioni illustrative, e dei documenti che saranno sottoposti all'assemblea; le modalità e i termini di presentazione delle liste per l'elezione dei componenti del consiglio di amministrazione e del componente di minoranza del collegio sindacale o del consiglio di sorveglianza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0378", "question": "Cosa sono le relazioni illustrative e quando devono essere pubblicate?", "answer": "Il consiglio di amministrazione è tenuto a pubblicare relazioni illustrative sulle materie all'ordine del giorno, di norma, almeno 21 giorni prima dell'assemblea (art. 125-ter TUF) al fine di poter decidere compiutamente come esercitare il proprio diritto di voto o anche se esercitare alcuni degli altri diritti attribuiti ai soci in occasione dell'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0379", "question": "Dove possono essere consultate le relazioni illustrative?", "answer": "Le relazioni illustrative devono essere messe a disposizione del pubblico presso la sede sociale e sul sito Internet della società e descrivono le materie all'ordine del giorno e le proposte di voto al riguardo presentate dall'organo di amministrazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0380", "question": "Cosa devono contenere le relazioni illustrative relative a decisioni rilevanti?", "answer": "Alcune relazioni illustrative, poiché relative a decisioni particolarmente rilevanti, devono contenere le informazioni indicate dalla Consob nei propri regolamenti (ad esempio, nel caso debbano essere deliberate modifiche del capitale sociale, operazioni di fusione/scissione, acquisto di azioni proprie, conversione e/o emissione di obbligazioni, piani di compensi degli amministratori basati sull'attribuzione di stock options).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0381", "question": "Come può un azionista accreditarsi per partecipare all'assemblea?", "answer": "Per partecipare all'assemblea, è necessario accreditarsi presso l'emittente secondo le modalità previste dalla legge e descritte nell'avviso di convocazione assembleare: a tal fine, occorre recarsi dall'intermediario presso il quale l'investitore ha il proprio conto titoli sul quale sono depositate le azioni e chiedergli di inviare all'emittente la comunicazione che attesta la titolarità delle azioni della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0382", "question": "Cosa accade se un azionista non ottiene la comunicazione dall'intermediario?", "answer": "Senza tale comunicazione, l'azionista non può essere ammesso a partecipare ai lavori assembleari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0383", "question": "Come viene determinato il diritto di voto in assemblea?", "answer": "L'azionista è legittimato a partecipare e votare in assemblea in relazione al numero di azioni che risultano registrate sul conto titoli dell'investitore il settimo giorno precedente la data dell'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0384", "question": "Quali sono le modalità di partecipazione all'assemblea per un azionista accreditato?", "answer": "Una volta che l'azionista si è accreditato presso l'emittente, occorre decidere se partecipare all'assemblea personalmente, recandosi all'ora e nel posto indicati nell'avviso di convocazione; oppure delegando qualcun altro a partecipare e a votare in assemblea, secondo le modalità indicate nell'avviso di convocazione assembleare; oppure ancora, se consentito dalla società, partecipare con i mezzi di comunicazione a distanza (videoconferenza, internet, altro…) o esercitare il voto per corrispondenza o con mezzi elettronici, secondo le modalità eventualmente indicate nell'avviso di convocazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0385", "question": "Cosa deve fare un azionista per decidere come votare in assemblea?", "answer": "È bene leggere con attenzione tutta la documentazione messa a disposizione per l'assemblea per pervenire ad una compiuta decisione sul voto da esprimere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0386", "question": "Quali diritti possono essere esercitati dagli azionisti prima dell'assemblea?", "answer": "Prima dell'assemblea, è anche possibile esercitare alcuni importanti diritti sociali, che consentono agli azionisti di ricevere informazioni ulteriori rispetto a quelle già rese note nella documentazione preassembleare pubblicata; questo può essere utile per decidere in modo compiuto come votare o, addirittura, per incidere sulla discussione dei lavori assembleari e, quindi, sulle possibili relative deliberazioni finali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0387", "question": "Cosa prevede l'articolo 127-ter del TUF riguardo alle domande degli azionisti?", "answer": "Secondo l'art. 127-ter TUF, ogni azionista a cui spetta il diritto di voto può presentare alla società domande sulle materie all'ordine del giorno prima dell'assemblea, secondo le modalità indicate nell'avviso di convocazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0388", "question": "Entro quando devono pervenire alla società le domande degli azionisti prima dell'assemblea?", "answer": "La società può prevedere un termine entro il quale le domande devono pervenire alla società: il termine non può essere anteriore a tre giorni precedenti la data dell'assemblea, ovvero a cinque giorni, ma in quest'ultimo caso la risposta deve essere fornita almeno due giorni prima dell'assemblea anche mediante pubblicazione in una apposita sezione del sito Internet della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0389", "question": "Quando deve essere fornita la risposta alle domande degli azionisti?", "answer": "In tutti gli altri casi, la società è tenuta a fornire una risposta al più tardi durante la stessa assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0390", "question": "In quali casi la società può evitare di fornire risposta alle domande degli azionisti?", "answer": "La società può evitare di fornire una risposta quando le informazioni richieste siano già disponibili in formato domanda e risposta nella sezione del sito Internet della società oppure siano già state pubblicate in risposta alle domande poste da altri soci.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0391", "question": "Chi può chiedere l'integrazione delle proposte di voto sulle materie all'ordine del giorno?", "answer": "I soci che, anche congiuntamente, rappresentino almeno un quarantesimo del capitale sociale (2,5%), entro dieci giorni dalla pubblicazione dell'avviso di convocazione dell'assemblea, possono presentare ulteriori proposte di deliberazione su materie già all'ordine del giorno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0392", "question": "Quando le proposte di deliberazione presentate dai soci devono essere messe a disposizione del pubblico?", "answer": "Le ulteriori proposte di deliberazione così presentate sono messe a disposizione del pubblico contestualmente alla pubblicazione della notizia della presentazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0393", "question": "È possibile presentare proposte di voto durante lo svolgimento dell'assemblea?", "answer": "Ulteriori proposte di voto sulle materie iscritte all'ordine del giorno possono sempre essere presentate, anche da un solo socio e senza necessità di alcuna quota minima di partecipazione, durante lo svolgimento dei lavori assembleari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0394", "question": "Chi può votare sulle proposte di voto presentate durante l'assemblea?", "answer": "Potranno votare su tali proposte solo gli azionisti presenti in assemblea o i delegati autorizzati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0395", "question": "Chi può chiedere l'integrazione delle materie all'ordine del giorno dell'assemblea?", "answer": "I soci che, anche congiuntamente, rappresentino almeno un quarantesimo del capitale sociale (2,5%) possono chiedere, entro dieci giorni dalla pubblicazione dell'avviso di convocazione dell'assemblea, l'integrazione dell'elenco delle materie da trattare, proponendo così ulteriori argomenti da sottoporre al voto dei soci.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0396", "question": "Chi valuta le richieste di integrazione dell'ordine del giorno?", "answer": "Le richieste di integrazione dell'ordine del giorno, da presentare unitamente alla certificazione attestante la titolarità della partecipazione, sono sottoposte all'approvazione dell'organo amministrativo che deve valutarle.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0397", "question": "Cosa accade se l'organo amministrativo non decide per tempo sulle richieste di integrazione?", "answer": "Nel caso in cui l'organo amministrativo non provveda a decidere per tempo sulle richieste di integrazione delle materie all'ordine del giorno presentate dai soci, l'integrazione può essere disposta dal Tribunale con decreto qualora si accerti che il rifiuto di provvedere era ingiustificato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0398", "question": "Quando devono essere pubblicate le integrazioni ammesse all'ordine del giorno?", "answer": "Le integrazioni all'ordine del giorno ammesse sono rese note al pubblico, nelle stesse forme prescritte per la pubblicazione dell'avviso di convocazione, almeno quindici giorni prima di quello fissato per l'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0399", "question": "Cosa possono fare gli azionisti con l'informazione anticipata sulle integrazioni all'ordine del giorno?", "answer": "Le integrazioni all'ordine del giorno consentono agli altri soci di essere preventivamente informati sull'oggetto della discussione assembleare ed eventualmente di votare anche sui nuovi argomenti inseriti nell'ordine del giorno nel caso in cui si decida di votare per delega o per corrispondenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0400", "question": "Che diritto hanno gli azionisti di minoranza riguardo la nomina degli organi sociali?", "answer": "La legge impone che nelle società quotate sui mercati regolamentati sia consentito alle minoranze di eleggere almeno un componente degli organi sociali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0401", "question": "Come possono le minoranze presentare una propria lista di candidati per gli organi sociali?", "answer": "I soci che raggiungano una determinata soglia del capitale sociale hanno il diritto di presentare una propria lista di candidati per gli organi sociali da nominare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0402", "question": "Come viene garantita la rappresentanza delle minoranze negli organi sociali?", "answer": "Le norme statutarie devono comunque garantire che almeno un membro, sia dell'organo amministrativo che dell'organo di controllo, deve essere estratto dalla lista di minoranza che ha ottenuto il maggior numero di voti e che non sia collegata in alcun modo ai soci che hanno presentato o votato la lista di maggioranza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0403", "question": "Entro quando devono essere presentate e pubblicate le liste di candidati per gli organi sociali?", "answer": "Le liste vanno presentate almeno 25 giorni prima della data fissata per l'assemblea e sono pubblicate sul sito internet della società, corredate dei curricula di tutti i candidati, entro il ventunesimo giorno precedente l'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0404", "question": "Che cos'è una sollecitazione di deleghe di voto e a cosa serve?", "answer": "Una sollecitazione di deleghe di voto è la possibilità per un socio di raccogliere le deleghe degli altri soggetti a cui spetta il diritto di voto, aggregando in tal modo più voti alla propria proposta di voto e aumentandone, quindi, le possibilità di successo nella successiva deliberazione assembleare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0405", "question": "Quali regole devono essere rispettate per una sollecitazione di deleghe di voto?", "answer": "La raccolta di deleghe su una specifica proposta di voto deve essere effettuata nel rispetto delle norme di correttezza e trasparenza previste dal TUF e dalla Consob nel proprio Regolamento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0406", "question": "Cosa deve pubblicare il socio promotore di una sollecitazione di deleghe di voto?", "answer": "Il socio promotore della sollecitazione dovrà pubblicare un prospetto contenente le informazioni richieste dalla Consob sul promotore e sulle motivazioni della sollecitazione - sebbene la Consob non abbia il compito di approvare il prospetto prima della pubblicazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0407", "question": "Quali possibilità ha un socio dopo lo svolgimento dell'assemblea?", "answer": "Dopo l'assemblea, ogni socio, anche chi non ha preso parte all'assemblea, ha la possibilità di conoscere lo svolgimento dei lavori assembleari e l'esito delle operazioni di voto, oltre che prendere opportune iniziative nel caso ritenga che si siano verificate scorrettezze o violazioni di legge.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0408", "question": "Cosa può fare un socio per conoscere l'esito delle votazioni assembleari?", "answer": "Il socio può prendere visione del rendiconto sintetico delle votazioni assembleari: il rendiconto deve essere pubblicato sul sito internet della società entro 5 giorni dallo svolgimento dell'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0409", "question": "Entro quanto tempo deve essere pubblicato il verbale assembleare?", "answer": "Il verbale assembleare deve essere pubblicato entro 30 giorni dallo svolgimento dell'assemblea sul sito internet della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0410", "question": "Cosa deve contenere il verbale assembleare?", "answer": "Nel verbale, redatto secondo l'art. 2375 c.c. e secondo le indicazioni previste dalla Consob con regolamento (art. 35 Regolamento Emittenti), è data compiuta rappresentazione dello svolgimento dell'assemblea nonché indicazione del voto espresso da tutti gli azionisti presenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0411", "question": "Chi può impugnare una delibera assembleare nulla o annullabile?", "answer": "I soci assenti, dissenzienti o che si sono astenuti possono impugnare le delibere che non sono state prese in conformità della legge o dello statuto (delibere annullabili) o le delibere con oggetto illecito o in caso di mancata convocazione o in mancanza del verbale (delibere nulle), al fine di renderle invalide e annullarne l'efficacia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0412", "question": "Cosa possono fare i soci per monitorare la gestione societaria oltre l'assemblea?", "answer": "Se l'assemblea dei soci rappresenta l'occasione più importante - e più agevole - per ricevere informazioni sull'andamento della gestione societaria, e quindi monitorare l'andamento del proprio investimento, i soci possono verificare che l'operato degli amministratori sia corretto e rispondente all'interesse sociale anche in altri momenti della vita sociale e con altre modalità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0413", "question": "Quali altri diritti possono esercitare i soci al di fuori dell'assemblea?", "answer": "I soci possono esercitare anche altri diritti: ogni socio ha il diritto di ispezionare i libri sociali, nonché di ottenere copia a proprie spese di tutta la documentazione depositata presso la sede sociale per l'assemblea (art. 130 TUF): i libri sociali sono il libro soci e i libri delle adunanze assembleari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0414", "question": "Chi può chiedere la convocazione dell'assemblea dei soci?", "answer": "Tanti soci che rappresentano almeno il 5% del capitale sociale hanno il diritto di chiedere e ottenere la convocazione dell'assemblea dei soci sugli argomenti indicati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0415", "question": "Cosa accade se la convocazione dell'assemblea è rifiutata ingiustificatamente?", "answer": "Se il rifiuto è ingiustificato, può provvedere il tribunale con decreto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0416", "question": "Cosa può fare un socio se ritiene che siano stati compiuti fatti censurabili?", "answer": "Ogni socio può denunciare fatti censurabili all'organo di controllo interno affinché quest'ultimo svolga indagini per verificare se sono state compiute irregolarità o violazioni di legge.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0417", "question": "Quando il collegio sindacale è obbligato ad avviare un'indagine su una denuncia dei soci?", "answer": "L'organo di controllo interno ha il dovere di indagare senza ritardo solo se la denuncia proviene da tanti soci che rappresentino almeno il 2% del capitale sociale della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0418", "question": "Cosa deve fare l'organo di controllo se emergono fatti censurabili di rilevante gravità?", "answer": "Se ad esito di tali indagini vengono rilevati fatti censurabili di rilevante gravità e vi sia urgenza di adottare opportuni provvedimenti, l'organo di controllo interno ha il dovere di convocare lui stesso l'assemblea dei soci affinché vengano adottate le deliberazioni necessarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0419", "question": "Cosa possono fare i soci se ritengono che gli amministratori abbiano causato danni alla società?", "answer": "I soci possono agire nei confronti degli amministratori qualora ritengano che questi ultimi, violando i doveri di agire con diligenza, abbiano causato dei danni alla società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0420", "question": "Chi può promuovere l'azione sociale di responsabilità contro gli amministratori?", "answer": "L'azione sociale di responsabilità nei confronti degli amministratori (e dei membri dell'organo di controllo interno, per non vigilato adeguatamente sugli amministratori) può essere promossa o dall'assemblea, che deve deliberarla con le maggioranze previste per l'assemblea ordinaria, o direttamente da tanti soci che rappresentino almeno il 2,5% del capitale sociale della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0421", "question": "Nell'interesse di chi viene esercitata l'azione di responsabilità contro gli amministratori?", "answer": "L'azione, anche quando esercitata direttamente dai soci di minoranza, è esercitata sempre nell'interesse della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0422", "question": "A chi spetta l'eventuale risarcimento del danno riconosciuto dal giudice?", "answer": "L'eventuale risarcimento del danno riconosciuto dal giudice sarà attribuito alla società e non ai singoli soci che hanno promosso l'azione civile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0423", "question": "Quando i soci possono attivare il controllo dell'autorità giudiziaria?", "answer": "I soci possono anche attivare il controllo dell'autorità giudiziaria quando vi sia il fondato sospetto che siano state compiute dagli amministratori gravi irregolarità che possono arrecare danno alla società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0424", "question": "Qual è la soglia minima di capitale per presentare una denuncia al tribunale per gravi irregolarità?", "answer": "Il tribunale è tenuto a prendere in considerazione la denuncia solo se è presentata da tanti soci che rappresentino almeno il 5% del capitale sociale della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0425", "question": "Cosa può fare il tribunale in caso di gravi irregolarità nella gestione societaria?", "answer": "Se ricorrono i presupposti previsti dalla legge, il tribunale può ordinare l'ispezione della società nonché, effettuati tutti gli accertamenti del caso, adottare i provvedimenti necessari ad eliminare le irregolarità. Nei casi più gravi, può anche ritenere necessario revocare gli organi sociali in carica e nominare un amministratore giudiziario per ripristinare la regolarità della gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-azionista-di-minoranza-in-societa-quotate"}},
{"id": "chunk_0426", "question": "Che cos'è un emittente strumenti finanziari diffusi fra il pubblico in misura rilevante?", "answer": "Il Testo Unico della Finanza prevede, accanto alle società quotate, un'altra tipologia di soggetti che emettono strumenti finanziari, gli emittenti strumenti finanziari diffusi fra il pubblico in misura rilevante. Si tratta di emittenti i cui strumenti finanziari, pur non essendo quotati su mercati regolamentati, sono comunque oggetto di investimento e di circolazione presso un pubblico sufficientemente ampio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-detentore-di-titoli-diffusi"}},
{"id": "chunk_0427", "question": "Quali sono i criteri per stabilire quando un emittente sia diffuso?", "answer": "I criteri per stabilire quando un emittente sia diffuso sono fissati dal Regolamento Emittenti e si riferiscono in particolare al numero di sottoscrittori dello strumento finanziario (azionisti diversi dai soci di controllo in numero superiore a 500 che detengano complessivamente una percentuale di capitale sociale almeno pari al 5%; più di 500 obbligazionisti), alle dimensioni dell'investimento (obbligazioni di valore nominale complessivamente non inferiore a 5 milioni di euro) e alle dimensioni dell'emittente (l'emittente azioni non deve essere nelle condizioni per redigere il bilancio in forma abbreviata, in sostanza non deve avere ridotte dimensioni d'impresa).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-detentore-di-titoli-diffusi"}},
{"id": "chunk_0428", "question": "Quando si diventa emittente diffuso?", "answer": "Un emittente si considera diffuso dall'inizio dell'esercizio sociale successivo a quello in cui si sono verificate le condizioni previste dal Regolamento Emittenti per divenire tale e fino alla chiusura dell'esercizio sociale in cui è stato accertato il venir meno di tali condizioni. Unica eccezione è rappresentata dagli emittenti che erano già quotati su mercati regolamentati, i quali diventano diffusi a partire dal giorno successivo a quello di revoca dalla quotazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-detentore-di-titoli-diffusi"}},
{"id": "chunk_0429", "question": "Come sappiamo che un emittente è diffuso?", "answer": "Gli emittenti diffusi sono tenuti a comunicare alla Consob sia il verificarsi delle condizioni per l'assunzione di tale qualifica, sia il venir meno di tali condizioni. Sul sito della Consob è caricato un elenco aggiornato di tali emittenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-detentore-di-titoli-diffusi"}},
{"id": "chunk_0430", "question": "Perché è importante sapere che un emittente è diffuso?", "answer": "L'emittente diffuso è tenuto a fornire ai sottoscrittori dei propri strumenti finanziari informazioni ulteriori rispetto a quelle cui è tenuto un emittente che non è né quotato né diffuso. Inoltre, l'emittente diffuso è preso in considerazione dal codice civile insieme all'emittente quotato nella categoria delle società che fanno ricorso al mercato dei capitali di rischio (l'art. 2325-bis del codice civile, infatti, definisce tali le società con azioni quotate in mercati regolamentati o diffuse fra il pubblico in misura rilevante). A tale categoria il codice civile applica alcune norme che non estende alle società per azioni né quotate né diffuse, per cui sapere se un emittente è diffuso significa anche sapere se alcune disposizioni del codice civile si applicano o meno a tale società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-detentore-di-titoli-diffusi"}},
{"id": "chunk_0431", "question": "Quali sono gli obblighi di un emittente diffuso?", "answer": "Devono fare comunicati stampa ogni volta che si verificano eventi e circostanze rilevanti. Devono pubblicare i documenti contabili, ossia il bilancio di esercizio, il bilancio consolidato se redatto e le relazioni della società di revisione. Devono fornire informazioni ai possessori dei loro strumenti finanziari per consentire loro l'esercizio dei diritti connessi a tali strumenti. Devono pubblicare l'avviso di convocazione dell'assemblea, ma solo se sono emittenti azioni diffuse. Devono pubblicare il documento su eventuali piani di compensi basati su strumenti finanziari ad amministratori e dirigenti. Nel caso in cui gli strumenti finanziari di un emittente diffuso formino oggetto di un'offerta pubblica di acquisto o di scambio l'offerente è tenuto a pubblicare un documento di offerta che consentirà al titolare di valutare la proposta effettuata. Devono rendere pubblici gli incarichi assunti dai componenti gli organi di controllo al fine di verificare il rispetto dei limiti in materia di cumulo degli incarichi. Devono rispettare gli obblighi di trasparenza previsti per le società che intrattengono rapporti di controllo o di collegamento con società estere aventi sedi legali in Stati che non garantiscono la trasparenza societaria. Sono assoggettati agli obblighi previsti dal Regolamento sulle operazioni con parti correlate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-detentore-di-titoli-diffusi"}},
{"id": "chunk_0432", "question": "Che responsabilità hanno gli investitori?", "answer": "I possessori di azioni od obbligazioni di una società possono verificare, consultando il database pubblicato sul sito della Consob, se l'emittente ha strumenti finanziari diffusi fra il pubblico in misura rilevante. In caso positivo, devono sapere che quella società, rispetto ad una società che non è emittente diffuso, è tenuta per legge a fornire le ulteriori informazioni sopra richiamate, e potranno quindi acquisire anche da tali informazioni gli elementi necessari per esercitare scelte di investimento consapevoli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-detentore-di-titoli-diffusi"}},
{"id": "chunk_0433", "question": "Cosa consente alle società l'emissione di obbligazioni?", "answer": "Tramite l'emissione di obbligazioni, le società possono finanziarsi presso i risparmiatori raccogliendo anche capitale di prestito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0434", "question": "Cosa sono le obbligazioni?", "answer": "Le obbligazioni sono titoli di credito standardizzati, ossia di uguale valore nominale e che attribuiscono uguali diritti, patrimoniali e partecipativi, nelle quali è frazionata un'unitaria operazione di finanziamento della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0435", "question": "Qual è la differenza principale tra obbligazionisti e titolari di azioni?", "answer": "A differenza dei titolari di azioni, gli obbligazionisti non sono soci, ma creditori della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0436", "question": "Quali diritti patrimoniali hanno gli obbligazionisti?", "answer": "Gli obbligazionisti hanno diritto alla restituzione del valore nominale del capitale investito alla scadenza indicata: il diritto alla restituzione può essere condizionato nei tempi e subordinato ad altre categorie di creditori, ma non escluso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0437", "question": "Da cosa può dipendere il pagamento degli interessi o del rendimento per gli obbligazionisti?", "answer": "Il pagamento degli interessi o del rendimento può essere condizionato dall'andamento economico della società e, dunque, essere esposto al rischio di impresa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0438", "question": "Come sono tutelati gli interessi degli obbligazionisti?", "answer": "Gli interessi degli obbligazionisti, che possono anche divergere molto da quelli degli azionisti o delle altre categorie di creditori, sono tutelati solo attraverso la costituzione, prevista ex lege, dei titolari di obbligazioni in un gruppo organizzato, al quale sono riconosciuti alcuni diritti in grado di incidere in varia misura sulla gestione societaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0439", "question": "In quali organi è articolata l'organizzazione del gruppo degli obbligazionisti?", "answer": "L'organizzazione del gruppo degli obbligazionisti è articolata in due organi: l'assemblea e il rappresentante comune.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0440", "question": "Quali sono alcune competenze dell'assemblea degli obbligazionisti?", "answer": "L'assemblea è competente a deliberare, tra l'altro, la nomina e la revoca del rappresentante comune, le modificazioni delle condizioni del prestito obbligazionario e sulla proposta di amministrazione controllata e di concordato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0441", "question": "Cosa accade se vengono proposte modifiche alle condizioni del prestito obbligazionario?", "answer": "Qualsiasi modifica delle condizioni del prestito obbligazionario originariamente sottoscritto, proposta dalla società o eventualmente conseguente alla realizzazione di altre operazioni societarie straordinarie, per essere efficace deve essere approvata dall'assemblea degli obbligazionisti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0442", "question": "Quando e come deve essere pubblicato l'avviso di convocazione dell'assemblea speciale degli obbligazionisti?", "answer": "L'avviso di convocazione dell'assemblea speciale deve essere pubblicato almeno 30 giorni prima della data fissata per l'assemblea: l'assemblea è convocata, con le stesse modalità descritte con riguardo all'assemblea dei soci, dal consiglio di amministrazione, dal rappresentante comune o, se necessario, può essere richiesta da tanti obbligazionisti che rappresentino il 5% dei titoli emessi ancora in circolazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0443", "question": "Cosa deve fare l'obbligazionista per accreditarsi presso l'emittente?", "answer": "Occorre recarsi dall'intermediario presso il quale l'investitore ha il proprio conto titoli sul quale sono depositate le obbligazioni e chiedergli di inviare all'emittente la comunicazione che attesta la titolarità delle stesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0444", "question": "Quando l'obbligazionista è legittimato a partecipare e votare in assemblea?", "answer": "L'obbligazionista è legittimato a partecipare e votare in assemblea in relazione al numero di obbligazioni che risultano registrate sul conto titoli dell'investitore il settimo giorno precedente la data dell'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0445", "question": "Quali modalità di partecipazione all'assemblea può scegliere l'obbligazionista?", "answer": "L'obbligazionista può decidere se partecipare all'assemblea personalmente, delegando qualcun altro, oppure, se consentito dalla società, partecipare con i mezzi di comunicazione (videoconferenza, internet, altro…) a distanza o esercitare il voto per corrispondenza o con mezzi elettronici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0446", "question": "Quale quorum è richiesto per l'approvazione delle modifiche alle condizioni del prestito?", "answer": "Per l'approvazione delle modifiche alle condizioni del prestito, è necessario il voto favorevole, anche in seconda convocazione, di tanti obbligazionisti che rappresentino la metà delle obbligazioni emesse e non estinte.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0447", "question": "Quali diritti possono esercitare gli obbligazionisti prima dell'assemblea?", "answer": "Gli obbligazionisti potranno altresì esercitare i medesimi diritti riconosciuti agli azionisti in tale fase, ossia porre domande sulle materie all'ordine del giorno e chiedere l'integrazione delle proposte di voto o delle materie all'ordine del giorno indicate nell'avviso di convocazione dell'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0448", "question": "Cosa possono fare i possessori di obbligazioni dopo l'assemblea?", "answer": "Dopo l'assemblea, i possessori di obbligazioni, anche se non hanno preso parte all'assemblea, hanno la possibilità di conoscere lo svolgimento dei lavori assembleari e l'esito delle operazioni di voto, oltre che prendere opportune iniziative nel caso ritenga che si siano verificate scorrettezze o violazioni di legge.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0449", "question": "Quali documenti possono consultare gli obbligazionisti dopo l'assemblea?", "answer": "Ogni obbligazionista può prendere visione del rendiconto sintetico delle votazioni assembleari, del verbale assembleare e di qualsiasi modifica nei diritti dei possessori di tali valori mobiliari pubblicata sul sito internet della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0450", "question": "Quando deve essere pubblicato il rendiconto sintetico delle votazioni assembleari?", "answer": "Il rendiconto sintetico delle votazioni assembleari deve essere pubblicato sul sito internet della società entro 5 giorni dallo svolgimento dell'assemblea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0451", "question": "Entro quanto tempo deve essere pubblicato il verbale assembleare?", "answer": "Il verbale assembleare deve essere pubblicato entro 30 giorni dallo svolgimento dell'assemblea sul sito internet della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0452", "question": "Cosa può fare un obbligazionista se ritiene che vi siano state violazioni di legge durante l'assemblea?", "answer": "Gli obbligazionisti assenti, dissenzienti o che si sono astenuti possono impugnare le delibere che non sono state prese in conformità della legge o dello statuto o le delibere con oggetto illecito o in caso di mancata convocazione o in mancanza del verbale, al fine di renderle invalide e annullarne l'efficacia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0453", "question": "Quali sono i poteri e i doveri del rappresentante comune?", "answer": "Il rappresentante comune ha il potere/dovere di provvedere all'esecuzione delle delibere assunte dall'assemblea degli obbligazionisti, tutelare gli interessi degli obbligazionisti nei rapporti con la società e assistere all'assemblea dei soci.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0454", "question": "Che tipo di rappresentanza ha il rappresentante comune nelle procedure concorsuali?", "answer": "Il rappresentante comune ha la rappresentanza processuale degli obbligazionisti in tutte le procedure concorsuali avviate nella società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-obbligazionista"}},
{"id": "chunk_0455", "question": "Cosa significa investire i propri risparmi?", "answer": "Investire i propri risparmi significa impiegare una somma di denaro (un capitale) in una determinata attività finanziaria (ad esempio, azioni od obbligazioni) con l'obiettivo di realizzare, nel tempo, un guadagno (cioè un rendimento positivo, ad esempio, i dividendi o gli interessi o l'incremento di valore dell'azione).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0456", "question": "Quali alternative ha il risparmiatore per decidere come investire le proprie risorse finanziarie?", "answer": "Il risparmiatore dispone di una serie di alternative in base alle quali può decidere di: rivolgersi ad un intermediario, facendo attenzione che sia autorizzato, e investire i propri risparmi tramite un \"servizio di investimento\"; affidare i propri risparmi ad un intermediario autorizzato allo svolgimento della \"gestione collettiva del risparmio\"; effettuare investimenti on-line, sempre attraverso piattaforme gestite da intermediari autorizzati, usando in questo caso un'opportuna cautela; non avvalersi del supporto di un intermediario per decidere come investire, potendo anche rivolgersi o essere direttamente sollecitato da un emittente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0457", "question": "Cosa deve fare il risparmiatore prima di effettuare un investimento?", "answer": "Una volta che il risparmiatore ha monitorato il bilancio familiare e concluso la propria pianificazione finanziaria, è pronto per decidere se e come investire le risorse finanziarie di cui dispone.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0458", "question": "Quali diritti e responsabilità ha l'investitore quando si rivolge a un intermediario finanziario?", "answer": "Quale controparte di un intermediario finanziario all'investitore la legge riconosce diversi diritti accanto ai quali è opportuno sempre tenere a mente alcune regole d'oro da seguire per investire responsabilmente. È importante per il risparmiatore collaborare con l'intermediario per individuare la soluzione di investimento che meglio risponde alle sue esigenze e ai suoi obiettivi anche per evitare brutte sorprese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0459", "question": "Quali diritti e regole valgono per chi affida i propri risparmi alla gestione collettiva del risparmio?", "answer": "Affidare i propri risparmi ad un intermediario autorizzato allo svolgimento della \"gestione collettiva del risparmio\" comporta che all'investitore siano riconosciuti diversi diritti accanto ai quali è opportuno sempre tenere a mente alcune regole da seguire per investire responsabilmente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0460", "question": "Quali cautele deve adottare chi effettua investimenti online?", "answer": "Chi effettua investimenti on-line, sempre attraverso piattaforme gestite da intermediari autorizzati, deve usare un'opportuna cautela.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0461", "question": "Cosa deve sapere il risparmiatore che investe senza l'aiuto di un intermediario?", "answer": "La legge riconosce ai risparmiatori una serie di diritti relativi alle informazioni che gli emittenti devono fornire e stabilisce le regole che questi ultimi devono rispettare sia nel corso dell'offerta che successivamente alla sua conclusione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0462", "question": "Cosa accade una volta che il risparmiatore ha effettuato l'investimento?", "answer": "Nei casi in cui abbia effettuato un investimento tramite un intermediario finanziario ovvero direttamente con un emittente, il risparmiatore (ora investitore) che ha acquistato i titoli (ad esempio le azioni, le obbligazioni, i titoli di Stato, etc.) diviene titolare di un altro rapporto giuridico: quello con il soggetto (la società o l'ente) che ha emesso i titoli da lui acquistati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0463", "question": "Quali sono i più comuni strumenti di investimento acquistabili dai risparmiatori?", "answer": "Fra i più comuni strumenti di investimento che possono essere acquistati dai risparmiatori vi sono le azioni e le obbligazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0464", "question": "Che ruolo assume l'investitore quando acquista azioni o obbligazioni?", "answer": "Quando acquista azioni o obbligazioni, l'investitore diventa rispettivamente azionista di minoranza di una società quotata, obbligazionista, oppure azionista o obbligazionista di un emittente diffuso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0465", "question": "Quali diritti può esercitare l'investitore nella sua qualità di azionista o obbligazionista?", "answer": "Nella sua qualità di azionista l'investitore può essere chiamato ad esprimere il suo voto partecipando alle decisioni ordinarie o straordinarie; come obbligazionista partecipa alle decisioni che lo riguardano più da vicino, attraverso la partecipazione alle assemblee di categoria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/diritti-responsabilita-investitori"}},
{"id": "chunk_0466", "question": "Che cos'è il bail-in e quando è stato introdotto?", "answer": "Dal 1° gennaio 2016, la crisi di una banca può essere risolta attraverso il bail-in (letteralmente \"salvataggio dall'interno\"), meccanismo legale introdotto dalla Direttiva n. 2014/59 dell'Unione Europea per il risanamento e risoluzione di enti creditizi e imprese di investimento (c.d. Direttiva BRRD), che impone la partecipazione degli investitori/risparmiatori - qualora possessori di determinate attività finanziarie emesse dalla banca stessa - alle perdite patrimoniali da questa subite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0467", "question": "Qual è lo scopo del meccanismo di bail-in?", "answer": "Il meccanismo del bail-in è teso ad evitare che il salvataggio di una banca sia effettuato mediante impiego di fondi pubblici (cosiddetto bail-out, ossia il \"salvataggio dall'esterno\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0468", "question": "Chi partecipa al salvataggio della banca in caso di dissesto?", "answer": "In caso di dissesto o di rischio di dissesto di una banca, i suoi azionisti e creditori contribuiscono al salvataggio secondo una precisa gerarchia di 'coinvolgimento' (che potrebbe implicare, tra le altre, la perdita parziale o totale del proprio investimento).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0469", "question": "Qual è la gerarchia di coinvolgimento nel bail-in?", "answer": "Le azioni e gli altri titoli di capitale (assimilabili alle azioni) emessi dalla banca sono le prime attività finanziarie ad essere interessate; a seguire le obbligazioni subordinate (passibili, nei casi meno gravi, di conversione in azione); successivamente, le obbligazioni ordinarie non garantite e non subordinate; per ultimo i depositi bancari, ma solo per l'importo eccedente i 100.000 euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0470", "question": "Quali sono le principali attività finanziarie soggette al bail-in?", "answer": "Principali attività finanziarie soggette al bail-in e gerarchia: 1) Azioni e strumenti di capitale 2) Obbligazioni subordinate 3) Obbligazioni ordinarie non garantite 4) Depositi per la parte oltre i 100.000 €", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0471", "question": "Quali attività finanziarie sono escluse dal bail-in?", "answer": "Rimangono invece esclusi dalla procedura (e non subiscono, pertanto, alcuna svalutazione o conversione in capitale): i depositi bancari per gli importi fino a 100.000 euro, le obbligazioni garantite (cosiddetti covered bond) e i depositi di strumenti finanziari (in un conto titoli) o beni (in una cassetta di sicurezza).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0472", "question": "Quali categorie di depositi e titoli sono esplicitamente escluse dal bail-in?", "answer": "Sono esclusi dal bail-in: - i depositi bancari fino a 100.000 euro (protetti dal sistema di garanzia dei depositi); - le obbligazioni garantite (covered bond); - i depositi di strumenti finanziari (in un conto titoli) o beni (in una cassetta di sicurezza).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0473", "question": "Chi gestisce la procedura di risoluzione delle crisi bancarie in Italia?", "answer": "Il bail-in è una delle modalità previste dalla nuova \"procedura di risoluzione\" - gestita dalla Banca d'Italia ed introdotta a seguito del recepimento in Italia della Direttiva BRRD con i decreti legislativi nn. 180 e 181 del 16 novembre 2015 - per affrontare le crisi bancarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0474", "question": "Quali sono i presupposti per l'apertura della procedura di risoluzione da parte della Banca d'Italia?", "answer": "Per aprire la procedura di risoluzione, la Banca d'Italia deve verificare la sussistenza di alcuni presupposti: - la banca è in dissesto o a rischio di dissesto; - non si ritiene che esistano misure alternative; - esiste un interesse pubblico alla risoluzione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0475", "question": "Qual è il fine della procedura di risoluzione di una banca in dissesto?", "answer": "Il fine della procedura è quello di far sì che la banca in dissesto continui ad operare: - trovandole un acquirente; - trasferendo le sue attività sane ad un altro soggetto che sarà poi venduto sul mercato; - trasferendo le passività deteriorate ad un altro soggetto che provvederà a venderle, sia pure a valore svalutato; - applicando il bail-in, ossia riducendo o annullando il valore di azioni e debiti (i debiti possono anche essere convertiti in azioni) per assorbire le perdite e ricapitalizzare la banca in difficoltà o una nuova entità che ne continui l'attività.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-dissesto-di-una-banca"}},
{"id": "chunk_0476", "question": "Che cos'è il disinvestimento?", "answer": "Il disinvestimento è quel processo, economicamente inverso al primo, in cui le attività finanziarie vengono vendute e trasformate in denaro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0477", "question": "Perché la fase di disinvestimento necessita di particolare attenzione?", "answer": "Questa fase necessita di particolare attenzione perché è in questo momento che, effettivamente, si può realizzare, o meno, un incremento in termini di valore del capitale investito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0478", "question": "Che cos'è un'offerta pubblica di acquisto?", "answer": "Una offerta pubblica di acquisto (\"Opa\" o \"Offerta\") è una sollecitazione al disinvestimento per cui un soggetto propone al pubblico di acquistare determinati prodotti finanziari a un certo prezzo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0479", "question": "Su quali prodotti può avere ad oggetto una Offerta Pubblica di Acquisto?", "answer": "Una Offerta può avere ad oggetto titoli quotati in mercati regolamentati, titoli non quotati, titoli diffusi tra il pubblico in misura rilevante.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0480", "question": "Quali sono le principali tipologie di Offerta Pubblica di Acquisto?", "answer": "Esistono varie tipologie di Offerte. Una prima distinzione può essere effettuata in ragione dei presupposti giuridici e del quantitativo dei titoli oggetto di Offerta: opa volontaria e opa obbligatoria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0481", "question": "Che cos'è l'opa volontaria?", "answer": "L'opa volontaria (artt. 102 e ss. del Tuf) è quella in cui la promozione dell'Offerta è rimessa alla mera volontà degli Offerenti, può essere promossa su titoli quotati, titoli non quotati o titoli diffusi; il corrispettivo è determinato dall'Offerente; il buon fine dell'Offerta può essere subordinato a determinate condizioni; può avere ad oggetto la totalità dei titoli della categoria emessi dell'Emittente o solo una parte di essi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0482", "question": "Che cos'è l'opa obbligatoria?", "answer": "L'opa obbligatoria (artt. 106 e ss del Tuf) è quella in cui la promozione dell'Offerta è imposta dalla legge al verificarsi di determinati presupposti; può essere promossa soltanto su titoli quotati; il corrispettivo è determinato in base a criteri individuati dalla legge; il buon fine dell'Offerta non può essere subordinato a nessuna condizione; può essere solo di tipo totalitario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0483", "question": "In base a cosa si può distinguere un'OPA, OPS o OPASc?", "answer": "Una seconda distinzione può farsi in base al prezzo (o Corrispettivo) offerto che può essere costituito da contanti (OPA) oppure da altri strumenti finanziari. In questo secondo caso si è in presenza di una offerta pubblica di scambio (OPS). Ci sono dei casi, infine, dove il corrispettivo è costituito in parte da denaro contante e in parte da strumenti finanziari: si parla allora di offerta pubblica di acquisto e scambio (OPASc).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0484", "question": "A chi è rivolta l'Offerta una volta promossa?", "answer": "L'Offerta, una volta promossa, è irrevocabile ed è rivolta a parità di condizioni a tutti coloro che detengono i titoli che l'Offerente si offre di acquistare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0485", "question": "Chi sono i soggetti coinvolti nell'OPA?", "answer": "Il soggetto che promuove l'Opa è definito \"Offerente\". Il soggetto i cui titoli sono oggetto dell'acquisto si definisce \"Emittente\" (o anche \"società target\" o \"società bersaglio\"). I destinatari dell'Offerta (detti anche \"oblati\") sono i titolari dei prodotti finanziari, oggetto dell'Opa, che verranno acquistati dell'Offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0486", "question": "Cosa si raccomanda prima di decidere se aderire o meno all'Offerta?", "answer": "Prima di decidere se aderire o meno all'Offerta, si raccomanda una attenta lettura del Documento di offerta e del Comunicato dell'Emittente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0487", "question": "Come si aderisce all'Offerta?", "answer": "Si aderisce all'Offerta secondo modalità specifiche indicate nel Documento di Offerta in un arco di tempo definito (\"Periodo di adesione\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0488", "question": "Qual è la normativa di riferimento in materia di Opa?", "answer": "La disciplina in materia di Opa si trova principalmente nel Testo unico delle disposizioni in materia di intermediazione finanziaria (Decreto legislativo 24 febbraio 1998, n. 58) detto comunemente \"Tuf\" agli artt. 101-bis e seguenti e nel Regolamento concernente la disciplina degli emittenti approvato con delibera Consob n. 11971 del 1999 (\"Regolamento Emittenti\") agli artt. 35 e ss.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0489", "question": "Cosa deve fare un investitore quando viene promossa un'Offerta?", "answer": "Se si è in possesso di titoli oggetto di una Offerta è importante prendere visione della Comunicazione con cui l'Offerente rende nota la volontà di promuovere l'Offerta, che contiene informazioni sugli elementi fondamentali dell'operazione: soggetti coinvolti, corrispettivo, indicazioni sulla probabile tempistica, motivazioni e finalità dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0490", "question": "Perché le finalità dell'Offerta sono particolarmente importanti?", "answer": "Le finalità dell'Offerta sono particolarmente importanti se l'operazione ha ad oggetto titoli quotati; in questa sede infatti l'Offerente rende nota la propria intenzione di revocare i titoli dalla quotazione ovvero di mantenere la quotazione del titolo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0491", "question": "Perché è importante conoscere i programmi futuri dell'Offerente?", "answer": "I programmi futuri dell'Offerente sono particolarmente rilevanti soprattutto nei casi in cui si reputa non conveniente aderire all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0492", "question": "Dove è disponibile la documentazione relativa all'Offerta?", "answer": "Tutta la documentazione relativa all'Offerta (il Documento, il comunicato dell'Emittente e tutti gli altri comunicati inerenti l'Offerta) è disponibile sul sito internet della Consob e sui siti internet dell'Offerente e dell'Emittente in una apposita sezione dedicata all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0493", "question": "Quando inizia il Periodo di adesione?", "answer": "Dopo la pubblicazione del Documento di Offerta e l'approvazione del Comunicato dell'Emittente da parte del Consiglio di Amministrazione della società target ha inizio il Periodo di adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0494", "question": "Cosa bisogna leggere prima di aderire all'Offerta?", "answer": "Si raccomanda la lettura dell'intero kit informativo a disposizione degli aderenti ossia: del Documento di Offerta, del Comunicato dell'Emittente e della Scheda di adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0495", "question": "Quando si può aderire all'Offerta?", "answer": "Si può aderire all'Offerta nel corso del Periodo di adesione, nell'ambito della procedura dell'Obbligo di acquisto o durante l'eventuale periodo di Riapertura dei termini dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0496", "question": "Può essere prorogato il Periodo di adesione?", "answer": "Ci possono essere dei casi in cui il Periodo di adesione viene prorogato. Tale circostanza si può verificare su iniziativa della Consob con l'adozione di un provvedimento motivato da esigenze di corretto svolgimento dell'Offerta e di tutela degli investitori o su iniziativa motivata dell'Offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0497", "question": "Come si aderisce all'Offerta tramite scheda?", "answer": "Si aderisce all'Offerta compilando una apposita Scheda di adesione e consegnandola all'intermediario incaricato della raccolta delle adesioni oppure all'intermediario presso cui sono depositati i titoli che si vogliono apportare all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0498", "question": "Cosa deve fare l'aderente per assicurarsi il buon fine dell'adesione?", "answer": "Affinché l'adesione vada a buon fine, è importante leggere attentamente la Scheda in tutte le sue parti, compilarla in modo corretto, procedere al deposito dei titoli e chiedere all'intermediario di essere informato in tempo utile sull'esistenza di eventuali problemi che possano pregiudicare il buon fine dell'adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0499", "question": "In quali casi le adesioni sono raccolte sul mercato?", "answer": "In alcuni casi le adesioni sono raccolte sul mercato (il Mercato Telematico Azionario o MTA, gestito da Borsa Italiana Spa) e pertanto non è richiesta la sottoscrizione di alcuna scheda di adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0500", "question": "Cosa si intende per irrevocabilità dell'adesione?", "answer": "L'adesione ad un'Offerta è irrevocabile ma è fatta salva la possibilità di aderire ad offerte concorrenti. La Scheda di adesione, una volta sottoscritta e presentata, non può essere né modificata né annullata dall'aderente; con l'adesione all'Offerta i titoli conferiti divengono indisponibili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0501", "question": "Quali diritti mantengono i titolari dei titoli dopo l'adesione?", "answer": "Anche dopo l'adesione i titolari potranno esercitare tutti i diritti patrimoniali e amministrativi pertinenti ai titoli conferiti all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0502", "question": "Quando è possibile revocare l'adesione?", "answer": "L'adesione può essere revocata soltanto se viene promossa una offerta concorrente sugli stessi titoli oggetto dell'Offerta a cui si è aderito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0503", "question": "Fino a quando l'Offerente può modificare l'Offerta?", "answer": "Le modifiche all'Offerta sono ammesse fino al giorno antecedente a quello previsto per la chiusura del periodo di adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0504", "question": "Cosa succede se vengono apportate modifiche all'Offerta?", "answer": "Nel caso di modifiche apportate all'Offerta, la chiusura del periodo di adesione non potrà avvenire in un termine inferiore a tre giorni di borsa aperta dalla data di pubblicazione della modifica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0505", "question": "In cosa consistono generalmente le modifiche all'Offerta?", "answer": "Generalmente le modifiche all'Offerta consistono in un aumento del corrispettivo unitario e/o nella proroga del periodo di adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0506", "question": "L'Offerente può peggiorare le condizioni dell'Offerta?", "answer": "L'Offerta può essere modificata solo in senso migliorativo: quindi non è ammessa la riduzione del corrispettivo, la riduzione del quantitativo dei titoli oggetto di Offerta o qualsiasi altra modifica che possa risultare deteriore rispetto ai termini ed alle condizioni dell'Offerta inizialmente promossa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0507", "question": "Cosa accade se emergono fatti nuovi durante il periodo di adesione?", "answer": "Se durante l'arco temporale intercorrente tra la pubblicazione del Documento di Offerta e la chiusura del periodo di adesione intervengono dei fatti nuovi, ovvero siano riscontrate delle inesattezze nel Documento, che possano influire sulla valutazione circa l'opportunità di aderire o meno all'Offerta, tali fatti nuovi devono essere resi noti, a cura dell'Offerente, in un apposito Supplemento al Documento di Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0508", "question": "Cosa contiene il Supplemento al Documento di Offerta?", "answer": "Il Supplemento viene allegato al Documento di Offerta e pubblicato con le stesse modalità utilizzate per quest'ultimo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0509", "question": "Cosa viene diffuso durante il periodo di adesione?", "answer": "Nel corso del Periodo di adesione vengono diffusi periodicamente i dati relativi all'andamento dell'Offerta concernenti le adesioni pervenute nella giornata, l'ammontare complessivo di titoli portati in adesione e la percentuale di questi ultimi rispetto al quantitativo complessivo oggetto di Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0510", "question": "Quando vengono resi noti i risultati provvisori e definitivi dell'Offerta?", "answer": "I risultati provvisori sono resi noti non appena disponibili e comunque entro l'ultimo giorno del Periodo di Adesione. I risultati definitivi dell'Offerta sono resi noti entro il giorno di borsa aperta antecedente la data di pagamento dei titoli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0511", "question": "Cosa deve comunicare l'Offerente se il buon esito dell'Offerta è subordinato a condizioni?", "answer": "Nel caso in cui il buon esito dell'Offerta è sottoposto a condizioni sospensive, l'Offerente è tenuto a dare notizia del verificarsi o del mancato avveramento di tali condizioni ovvero, in caso di mancato avveramento, dell'esercizio della facoltà di rinuncia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0512", "question": "Dove vengono pubblicati i comunicati inerenti l'Offerta?", "answer": "Tutti i comunicati inerenti l'Offerta vengono resi disponibili sul sito internet dell'Offerente e sul sito internet della Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0513", "question": "Che cos'è la Riapertura dei Termini dell'Offerta?", "answer": "In alcuni casi specifici il Periodo di adesione viene \"riaperto\" per 5 giorni di borsa aperta con inizio a partire dal giorno successivo la data di pagamento dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0514", "question": "Come viene comunicata la Riapertura dei Termini?", "answer": "L'Offerente deve comunicare se la Riapertura dei Termini avrà luogo, o meno, con un comunicato diffuso almeno 5 giorni prima della chiusura dell'Offerta e/o nel comunicato sui risultati definitivi dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0515", "question": "Cosa prevede l'art. 108, comma 2, del Tuf?", "answer": "La disciplina dell'obbligo di acquisto si applica alle sole offerte aventi ad oggetto titoli quotati in un mercato regolamentato ed è contenuta nell'art. 108, comma 2, del Tuf nonché nell'art. 50 del Regolamento Emittenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0516", "question": "Cosa deve dichiarare l'Offerente nelle Avvertenze del Documento?", "answer": "L'Offerente nelle Avvertenze del Documento deve dichiarare se qualora, a seguito dell'Offerta, ottenga una partecipazione superiore al novanta per cento del capitale intende ripristinare un flottante sufficiente ad assicurare il regolare andamento delle negoziazioni oppure adempiere all'obbligo di acquisto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0517", "question": "Che cosa riconosce l'istituto dell'obbligo di acquisto?", "answer": "L'istituto dell'obbligo di acquisto riconosce, quindi, a favore degli azionisti di minoranza il cosiddetto \"diritto di uscita\" quale forma di tutela a fronte di un flottante non idoneo ad assicurare il regolare andamento delle negoziazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0518", "question": "Qual è il corrispettivo previsto per l'obbligo di acquisto?", "answer": "Il corrispettivo al quale l'Offerente adempirà all'Obbligo di acquisto è uguale al corrispettivo dell'Offerta in relazione alla quale si sono determinati i presupposti giuridici per il sorgere dell'obbligo se tale Offerta è obbligatoria o è volontaria e l'Offerente, in tale ambito, ha acquistato titoli rappresentativi di non meno del 90% del capitale della società Emittente; negli altri casi è determinato dalla Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0519", "question": "Come e quando si presentano le richieste di vendita?", "answer": "Gli azionisti titolari dei titoli oggetto dell'Obbligo di acquisto che intendono richiedere all'Offerente di acquistarle devono presentare una richiesta di vendita utilizzando una apposita scheda debitamente compilata e sottoscritta. La scheda va consegnata entro l'ultimo giorno del Periodo di Presentazione delle Richieste di Vendita agli intermediari incaricati per la raccolta per il tramite degli intermediari presso cui sono depositati i titoli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0520", "question": "Quanto dura il Periodo di presentazione delle richieste di vendita?", "answer": "Il Periodo di presentazione delle richieste di vendita, entro il quale l'Offerente adempie all'Obbligo di acquisto, è ricompreso tra un minimo di quindici e un massimo di venticinque giorni di borsa aperta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0521", "question": "Cosa prevede il diritto di acquisto ex art. 111, comma 1, del Tuf?", "answer": "Il diritto di acquisto (o \"squeeze-out\") è disciplinato dall'art. 111, comma 1, del Tuf: la norma prevede che l'Offerente - qualora, in seguito ad una offerta pubblica totalitaria, venga a detenere almeno il 95% delle azioni con diritto di voto dell'Emittente - ha il diritto di acquistare le azioni residue (sempre che abbia dichiarato di volersi avvalere di tale diritto nel Documento di offerta).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0522", "question": "Cosa accade ad esito del diritto di acquisto?", "answer": "Ad esito del diritto di acquisto: l'Offerente giunge a detenere l'intero capitale con diritto di voto dell'Emittente e ne diventa l'unico azionista e i titoli oggetto di Offerta verranno revocati dalla quotazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0523", "question": "Cosa comporta l'obbligo di acquisto ex art. 108, comma 1, del Tuf?", "answer": "Nel caso in cui l'Offerente, in seguito ad una offerta pubblica totalitaria, venga a detenere almeno il 95% delle azioni con diritto di voto dell'Emittente, l'Offerente ha l'obbligo di acquistare le restanti azioni dagli azionisti dell'Emittente che ne facciano richiesta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0524", "question": "Che cos'è la procedura congiunta?", "answer": "Nel caso in cui si dà luogo contestualmente all'adempimento dell'obbligo di acquisto previsto ex art. 108, comma 1, Tuf ed all'esercizio del diritto di acquisto art. 111, comma 1, Tuf le due procedure vengono riunite in una unica procedura (cosiddetta \"Procedura congiunta\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0525", "question": "Cosa avviene alla data di pagamento?", "answer": "Alla data di pagamento avviene il versamento del corrispettivo a coloro che hanno portato i propri titoli in adesione all'Offerta, a fronte del contestuale trasferimento della proprietà di tali titoli all'Offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0526", "question": "Sono previsti interessi sul corrispettivo tra la data di adesione e la data di pagamento?", "answer": "Generalmente non è previsto il pagamento di interessi sul corrispettivo tra la data di adesione all'Offerta e la data di pagamento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0527", "question": "Cosa accade nel caso di Opa volontarie parziali?", "answer": "Nel caso tipico delle Opa volontarie parziali, l'Offerta ha ad oggetto solo una parte dei titoli emessi dal soggetto Emittente, viene espressamente indicata nel Documento di offerta la soglia massima di adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0528", "question": "Cosa succede se l'ammontare dei titoli conferiti supera la soglia massima di adesione?", "answer": "Ove l'ammontare complessivo dei titoli conferiti in adesione sia superiore alla soglia massima, ai titoli eccedenti viene applicato un criterio di riparto a seguito del quale viene definito il quantitativo dei titoli che devono essere restituiti agli aderenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0529", "question": "Cosa deve garantire il criterio di riparto?", "answer": "Il criterio di riparto deve essere tale da consentire la corretta applicazione del principio di parità di trattamento dei destinatari dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0530", "question": "Come vengono restituiti i titoli eccedenti?", "answer": "I titoli eccedenti vengono rimessi a disposizione degli aderenti, senza addebito di oneri o spese a loro carico, con le modalità ed i tempi indicati nel Documento di offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0531", "question": "Cosa accade se un'Offerta non va a buon fine?", "answer": "Ci sono dei casi in cui - solo limitatamente alle opa di tipo volontario - il buon fine dell'Offerta è subordinato al verificarsi o al mancato verificarsi di talune condizioni sospensive.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0532", "question": "Cosa può fare l'Offerente se le condizioni sospensive non si verificano?", "answer": "L'Offerente può riservarsi la facoltà di rinunciare a una, o più, delle condizioni a cui è sospensivamente condizionato l'esito dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0533", "question": "Cosa accade se la condizione sospensiva non si verifica e l'Offerente non si avvale della facoltà di rinuncia?", "answer": "In tal caso l'Offerente rende noto al mercato il mancato verificarsi della condizione, la propria intenzione di non avvalersi della facoltà di rinuncia ed il conseguente inefficacia dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0534", "question": "Come vengono restituiti i titoli se l'Offerta non va a buon fine?", "answer": "Nel comunicato vengono indicati termini e modalità con cui i titoli conferiti in adesione saranno restituiti ai rispettivi titolari. La restituzione dei titoli avviene sempre senza alcun addebito di oneri o spese addizionali agli aderenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0535", "question": "Cosa sono le offerte concorrenti?", "answer": "Nel caso di Offerte aventi ad oggetto titoli quotati è ammessa la promozione di offerte concorrenti (dette anche \"contro-opa\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0536", "question": "Chi può promuovere offerte concorrenti?", "answer": "Le offerte concorrenti sono promosse sui medesimi titoli oggetto di una offerta già in corso ma da soggetti offerenti diversi rispetto a coloro che hanno promosso la prima offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0537", "question": "Quando possono essere pubblicate le offerte concorrenti?", "answer": "Le offerte concorrenti possono essere pubblicate fino a cinque giorni prima della data prevista per la chiusura dell'offerta precedente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0538", "question": "Quali caratteristiche possono avere le offerte concorrenti?", "answer": "Le offerte concorrenti sono promosse generalmente ad un prezzo maggiore rispetto a quello della prima offerta o sono caratterizzate comunque da una struttura diversa quanto alle motivazioni e ai programmi futuri rispetto all'Offerta precedente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0539", "question": "Cosa possono fare coloro che hanno aderito alla prima Offerta in caso di offerta concorrente?", "answer": "Coloro che avessero aderito alla prima Offerta possono esercitare il diritto di recesso e conferire i propri titoli in adesione all'Offerta concorrente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0540", "question": "Cosa contiene il Documento di offerta in merito alla revoca dalla negoziazione del titolo?", "answer": "Nelle Offerte riguardanti titoli quotati il Documento di offerta, in un apposito paragrafo delle Avvertenze, contiene informazioni circa la volontà dell'Offerente di mantenere, o meno, la quotazione del titolo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0541", "question": "Cosa deve indicare l'Offerente riguardo alla revoca della quotazione?", "answer": "L'Offerente deve fornire indicazioni circa la propria intenzione di adempiere all'obbligo di acquisto o all'eventuale ripristino del flottante nonché in ordine all'eventuale scarsità del flottante e possibile illiquidità degli strumenti finanziari a seguito dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0542", "question": "Cosa contiene il Documento se l'Offerta è finalizzata al delisting del titolo?", "answer": "Nel caso in cui l'Offerta è finalizzata al delisting del titolo, il Documento contiene tutte le informazioni circa la tempistica e le modalità in ordine all'eventuale esclusione dalle negoziazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0543", "question": "Quando può avvenire la revoca del titolo?", "answer": "La revoca del titolo può avvenire anche successivamente alla conclusione dell'Offerta, per effetto di eventuali operazioni di carattere straordinario (in particolare fusioni e scissioni) che coinvolgano l'Emittente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0544", "question": "Cosa devono valutare coloro che decidono di non aderire all'Offerta?", "answer": "Coloro che decidono di non aderire all'Offerta è fondamentale che siano consapevoli dei vari scenari che possono prefigurarsi a conclusione dell'operazione, con particolare riferimento alla percentuale del capitale dell'Emittente che l'Offerente acquisirà ad esito dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0545", "question": "Quali sezioni del Documento devono leggere coloro che non aderiscono all'Offerta?", "answer": "Si raccomanda pertanto una attenta valutazione delle informazioni contenute, in particolare, nelle Avvertenze del Documento e nella sezione dedicata ai Programmi futuri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0546", "question": "Qual è la disciplina in materia di Opa?", "answer": "La disciplina in materia di Opa si trova principalmente nel Testo unico delle disposizioni in materia di intermediazione finanziaria (Decreto legislativo 24 febbraio 1998, n. 58) detto comunemente \"Tuf\" agli artt. 101-bis e seguenti e nel Regolamento concernente la disciplina degli emittenti approvato con delibera Consob n. 11971 del 1999 (in breve: \"Regolamento Emittenti\") agli artt. 35 e ss.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0547", "question": "Cosa deve fare l'Offerente quando decide di promuovere l'Offerta?", "answer": "Nel momento in cui l'Offerente decide di promuovere l'Offerta deve diffondere al mercato una apposita Comunicazione dell'Offerta in cui sono riportate, in sintesi, le informazioni sugli elementi fondamentali dell'operazione, ossia, in particolare: sull'Offerente, sull'Emittente, sul prezzo, sulle eventuali condizioni cui il buon esito dell'Operazione può essere subordinato, sulle motivazioni per cui l'Offerta è stata promossa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0548", "question": "Cosa indica la Comunicazione se l'Offerta ha ad oggetto titoli quotati?", "answer": "Nel caso in cui l'Offerta ha ad oggetto titoli quotati la comunicazione indica anche se è intenzione, o meno, dell'Offerente procedere alla revoca dalle negoziazioni del titolo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0549", "question": "Cosa deve contenere la Comunicazione riguardo al periodo di adesione?", "answer": "La Comunicazione contiene una indicazione di massima anche sul periodo in cui potrebbe svolgersi il Periodo di adesione ossia il periodo (almeno pari a 3 settimane di calendario) in cui sarà possibile aderire all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0550", "question": "Quando deve essere depositato il Documento di Offerta presso la Consob?", "answer": "Entro 20 giorni di calendario dalla diffusione del comunicato, l'Offerente deve depositare presso la Consob il Documento di offerta che, una volta approvato dalla Commissione, viene pubblicato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0551", "question": "Cosa contiene il Documento di Offerta?", "answer": "Tale Documento contiene tutte le informazioni utili sulla struttura e sulle caratteristiche dell'operazione e costituisce la sola fonte cui fare riferimento per addivenire ad una decisione consapevole circa la convenienza ad aderire o meno all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0552", "question": "Dove viene pubblicato il Documento di Offerta?", "answer": "Il Documento di Offerta viene pubblicato sul sito internet dell'Offerente e sul sito internet Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0553", "question": "Chi deve informare i depositanti dell'esistenza dell'Offerta?", "answer": "Gli intermediari presso i quali sono depositati i titoli oggetto dell'Offerta sono tenuti ad informare i depositanti dell'esistenza dell'Offerta in tempo utile per consentire una eventuale adesione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0554", "question": "Quando deve essere diffuso il Comunicato dell'Emittente?", "answer": "Prima dell'inizio del periodo di adesione il Consiglio di Amministrazione dell'Emittente deve riunirsi per approvare e diffondere un Comunicato in cui esprime le propria valutazioni sull'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0555", "question": "Cosa deve contenere il Comunicato dell'Emittente?", "answer": "Il Comunicato deve contenere ogni dato utile per l'apprezzamento dell'offerta e una valutazione motivata dei componenti dell'organo amministrativo sull'offerta stessa e sulla congruità del corrispettivo, con l'indicazione dell'eventuale adozione a maggioranza, del numero e, se lo richiedono, del nome dei dissenzienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0556", "question": "Da chi può essere assistito il Consiglio di Amministrazione per formulare le valutazioni sull'Offerta?", "answer": "Per formulare le proprie valutazioni il Consiglio di amministrazione può avvalersi di un consulente finanziario indipendente chiamato a redigere un parere motivato sulla congruità del prezzo (\"fairness opinion\").", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0557", "question": "Dove è reperibile il Comunicato dell'Emittente?", "answer": "Il Comunicato dell'Emittente è reperibile sul sito internet della Consob, sul sito internet dell'Emittente e su quello dell'Offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0558", "question": "Quando il Comunicato dell'Emittente è allegato al Documento di Offerta?", "answer": "Nella maggior parte dei casi, se l'Offerta è di tipo amichevole, il Comunicato dell'Emittente è allegato in Appendice al Documento di Offerta e ne costituisce parte integrante.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0559", "question": "Cosa contengono le Premesse del Documento di Offerta?", "answer": "Le Premesse riepilogano in sintesi le caratteristiche dell'Offerta e contengono una tabella in cui viene riportata la tempistica dell'operazione dall'inizio fino alla sua conclusione con evidenza di tutte le date significative relative all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0560", "question": "Cosa contengono le Avvertenze del Documento di Offerta?", "answer": "Le Avvertenze contengono gli elementi di rischio connessi all'operazione, nonché un paragrafo finale in cui vengono dettagliatamente descritti gli scenari che si profilano sia per coloro che aderiscono all'Offerta, sia per quanti non aderiscono e rimangono in possesso dei relativi titoli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0561", "question": "Cosa contiene la sezione Corrispettivo del Documento di Offerta?", "answer": "La sezione Corrispettivo contiene informazioni sul corrispettivo, sui criteri seguiti per la sua determinazione nonché specifici indicatori che agevolano nel valutare la convenienza dell'Offerta; nei casi in cui il corrispettivo è costituito da altri titoli ovvero da contanti e titoli questa parte del Documento fornisce elementi informativi anche sui titoli che si riceveranno in scambio aderendo all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0562", "question": "Cosa contiene la sezione Motivazioni dell'operazione e programmi futuri?", "answer": "La sezione Motivazioni dell'operazione e programmi futuri reca informazioni sulle motivazioni dell'operazione e sui programmi elaborati dall'Offerente relativamente all'Emittente; in caso di Offerta su titoli quotati l'Offerente deve indicare se l'Opa è finalizzata o meno alla revoca dei titoli dalla quotazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0563", "question": "Quando può iniziare il Periodo di adesione?", "answer": "Se il Documento di Offerta comprende anche il Comunicato dell'Emittente, il Periodo di adesione può iniziare anche il giorno dopo la pubblicazione del Documento; se, diversamente, il Comunicato dell'Emittente non è contenuto nel Documento, il Periodo di adesione avrà inizio dopo 5 giorni dalla pubblicazione del Documento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0564", "question": "Qual è la durata minima del periodo di adesione indicata nella Comunicazione dell'Offerta?", "answer": "La Comunicazione contiene una indicazione di massima anche sul periodo in cui potrebbe svolgersi il \"Periodo di adesione\" ossia il periodo almeno pari a 3 settimane di calendario in cui sarà possibile aderire all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0565", "question": "Quando e dove vengono pubblicati tutti i comunicati stampa e documenti relativi all'Offerta?", "answer": "Nel comunicato dell'Offerta deve essere indicato il sito internet in cui verranno pubblicati tutti i comunicati stampa ed i documenti relativi all'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0566", "question": "Cosa succede alla data di pagamento dell'Offerta?", "answer": "Alla data di pagamento avviene il versamento del corrispettivo a coloro che hanno portato i propri titoli in adesione all'Offerta, a fronte del contestuale trasferimento della proprietà di tali titoli all'Offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0567", "question": "Cosa accade per chi non aderisce all'Offerta?", "answer": "Coloro che decidono di non aderire all'Offerta è fondamentale che siano consapevoli dei vari scenari che possono prefigurarsi a conclusione dell'operazione, con particolare riferimento alla percentuale del capitale dell'Emittente che l'Offerente acquisirà ad esito dell'Offerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/in-caso-di-offerta-pubblica-di-acquisto"}},
{"id": "chunk_0568", "question": "Chi può prestare servizi di investimento e di gestione collettiva del risparmio?", "answer": "I servizi di investimento e la gestione collettiva del risparmio possono essere prestati solo da banche e da altri soggetti abilitati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0569", "question": "Come può il risparmiatore verificare che l'intermediario con cui entra in contatto sia autorizzato?", "answer": "Quando il risparmiatore decide di investire i propri risparmi può verificare che l'intermediario con cui entra in contatto sia stato autorizzato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0570", "question": "Cosa pubblica la Consob sul proprio sito riguardo ai soggetti non autorizzati?", "answer": "La Consob pubblica sul proprio sito i provvedimenti adottati nei confronti di soggetti che offrono prodotti finanziari senza le dovute autorizzazioni e i nominativi dei soggetti, segnalati anche da autorità di vigilanza estere, che sono privi dell'autorizzazione per la prestazione dei servizi di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0571", "question": "Cosa possono fare i risparmiatori se entrano in contatto con soggetti non autorizzati?", "answer": "Gli stessi risparmiatori possono segnalare alla Consob di essere entrati in contatto con un soggetto che presta servizi di investimento senza le dovute autorizzazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0572", "question": "Qual è il diritto generale degli investitori quando un intermediario presta un servizio di investimento?", "answer": "Il diritto generale è ottenere la prestazione del servizio di investimento da parte dell'intermediario in base ai principi e regole di condotta definiti dalla disciplina di riferimento: (i) agire in modo onesto, equo e professionale, (ii) fornire informazioni appropriate e complete e (iii) offrire dei servizi che tengano conto della situazione individuale del risparmiatore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0573", "question": "Qual è la regola fondamentale per investire?", "answer": "La regola fondamentale per investire è conoscere (e il suo corollario, se non si conosce, è meglio non investire).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0574", "question": "Quali diritti specifici ha l'investitore prima di investire?", "answer": "L'investitore ha diritto di ricevere dall'intermediario, prima di investire, informazioni su: (i) servizi offerti, (ii) caratteristiche e rischi dei tipi di strumenti finanziari che si possono acquistare o negoziare, (iii) modalità di esecuzione degli ordini e (iv) costi dei servizi offerti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0575", "question": "Come viene classificato l'investitore prima della prestazione del servizio di investimento?", "answer": "L'investitore viene classificato, a seconda dei requisiti, in cliente al dettaglio o cliente professionale; il cliente al dettaglio riceve il livello massimo di tutela previsto per l'investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0576", "question": "In quale forma deve essere stipulato il contratto con l'intermediario per un cliente al dettaglio?", "answer": "Il contratto con l'intermediario, nel caso di cliente al dettaglio, deve essere stipulato in forma scritta (ad eccezione del servizio di consulenza in materia di investimenti).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0577", "question": "Che tipo di assistenza deve ricevere l'investitore a seconda del servizio di investimento?", "answer": "L'investitore deve ricevere assistenza dall'intermediario, a seconda del servizio di investimento prestato, sotto diverse gradazioni via via decrescenti in termini di tutela: dalla valutazione di adeguatezza dell'investimento a quella di appropriatezza fino all'esclusione di ogni valutazione nel caso della mera esecuzione di ordini.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0578", "question": "Di quali incentivi e conflitti di interesse deve essere informato l'investitore?", "answer": "L'investitore deve essere informato dell'esistenza degli eventuali: (i) compensi, commissioni o prestazioni non monetarie (cosiddetti. \"incentivi\") pagati o ricevuti da un intermediario in connessione alla prestazione di un servizio di investimento, della loro natura e portata e (ii) conflitti di interesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0579", "question": "Cosa deve ricevere l'investitore dopo aver investito?", "answer": "Dopo aver investito, l'investitore deve ricevere dall'intermediario la rendicontazione dell'attività prestata, comprensiva dei costi applicati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0580", "question": "Quali regole deve seguire un risparmiatore prima di investire?", "answer": "Prima di investire, un risparmiatore deve: (i) verificare se l'intermediario è in possesso delle autorizzazioni richieste ad operare in Italia, (ii) acquisire le informazioni necessarie dagli intermediari e dai promotori finanziari, (iii) diffidare delle proposte \"improbabili\" e (iv) considerare con attenzione i prodotti \"rischiosi\" come titoli non quotati o strumenti finanziari derivati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0581", "question": "Cosa deve fare il risparmiatore al momento di concludere il contratto?", "answer": "Al momento di concludere il contratto, il risparmiatore deve: (i) pretendere che il contratto sia concluso nelle forme dovute, (ii) consegnare il denaro da investire solo nelle forme previste dal contratto e non consegnare mai denaro in contanti nel caso di promotori finanziari, e (iii) non firmare mai contratti e moduli senza averli letti o compilati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0582", "question": "Cosa deve fare l'investitore dopo la conclusione del contratto?", "answer": "Una volta concluso il contratto, l'investitore deve controllare la regolarità dell'attività svolta dall'intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0583", "question": "Cosa può fare l'investitore in caso di insolvenza di un intermediario?", "answer": "In caso di insolvenza di un intermediario, l'investitore può chiedere l'intervento del Fondo Nazionale di Garanzia al fine di ottenere l'indennizzo previsto e le connesse modalità operative.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0584", "question": "Quali cautele deve adottare l'investitore negli investimenti online?", "answer": "Nel caso di investimenti on line, l'investitore deve adottare particolari cautele comportamentali: è importante avere consapevolezza del carattere \"internazionale\" di internet e valutare criticamente le informazioni disponibili nei \"forum\" in rete.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0585", "question": "Cosa deve fare l'investitore se qualcosa non è in linea rispetto ai diritti e alle responsabilità?", "answer": "Se qualcosa non è in linea rispetto a quanto sopra rappresentato relativamente ai diritti e alle responsabilità: - per prima cosa è bene cercare un chiarimento informale con il soggetto con il quale normalmente si hanno i rapporti (promotore finanziario o dipendente dell'intermediario distributore); - se ciò non fosse sufficiente, occorre effettuare un reclamo formale nei confronti dell'intermediario distributore; - oltre al reclamo presso l'intermediario, se si ritiene che l'intermediario o il promotore abbiano violato regole di correttezza o di comportamento, è opportuno inviare un esposto alla CONSOB, chiarendo cosa può comportare l'attivazione di questa iniziativa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nei-servizi/attivita-di-investimento"}},
{"id": "chunk_0586", "question": "Qual è il diritto generale degli investitori nel servizio di gestione collettiva?", "answer": "Il diritto generale degli investitori nel servizio di gestione collettiva è ottenere la prestazione del servizio di gestione collettiva secondo i principi generali della diligenza, correttezza e trasparenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0587", "question": "Quali diritti specifici ha l'investitore prima di investire?", "answer": "Prima di investire, il potenziale investitore ha diritto a ricevere dal distributore tutte le informazioni concernenti la natura del fondo, con particolare riguardo alle tipologie di attività in cui sarà investito il fondo medesimo, il profilo di rischio e i costi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0588", "question": "Che documentazione informativa deve ricevere l'investitore prima di investire?", "answer": "L'investitore ha diritto a ricevere la documentazione informativa concernente il fondo, con particolare riguardo al KIID, cioè il documento contenente le informazioni chiave dell'OICR.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0589", "question": "L'investitore può essere assistito dall'intermediario distributore nella scelta del fondo?", "answer": "L'investitore può essere assistito dall'intermediario distributore nella scelta del fondo più idoneo al suo profilo. A tal fine, è necessario che l'investitore fornisca al distributore uno specifico set di informazioni. È sconsigliabile che i risparmiatori, specie quelli meno esperti, si rifiutino di fornire le informazioni richieste non potendo, quindi, usufruire dell'assistenza dell'intermediario distributore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0590", "question": "Quali sono i diritti dell'investitore al momento dell'investimento?", "answer": "Al momento dell'investimento, l'investitore ha il diritto che l'operazione di sottoscrizione sia eseguita in conformità a quanto previsto dal contratto, cioè dal regolamento di gestione del fondo, e dal prospetto informativo del fondo. In tale fase, particolare attenzione dovrà essere prestata sia alla tempistica di esecuzione dell'operazione di sottoscrizione che alle commissioni che sono prelevate dall'importo versato o che saranno percepite dal gestore per la sua attività di gestione nel corso del rapporto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0591", "question": "Quali diritti ha l'investitore durante l'investimento?", "answer": "Durante l'investimento, l'investitore ha diritto ad ottenere che il servizio di gestione collettiva sia prestato in conformità al regolamento di gestione del fondo e ha diritto a ricevere la documentazione periodica che informa sull'andamento dell'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0592", "question": "Quali diritti ha l'investitore in fase di disinvestimento?", "answer": "In fase di disinvestimento, l'investitore ha diritto ad ottenere che l'operazione di rimborso sia eseguita in conformità a quanto previsto dal contratto, cioè dal regolamento di gestione del fondo, e dal prospetto informativo. Anche in questa fase, particolare attenzione dovrà essere prestata sia alla tempistica di esecuzione dell'operazione di rimborso che alle commissioni che sono prelevate dall'importo che viene restituito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0593", "question": "Qual è la responsabilità generale dell'investitore nel servizio di gestione collettiva?", "answer": "In generale, è responsabilità dell'investitore controllare che tutti i suoi diritti siano rispettati dagli intermediari, sia quello distributore che quello gestore. Ciò implica un attento monitoraggio da parte dell'investitore sia nella fase antecedente l'investimento, che in quella dell'investimento che in fase di rimborso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0594", "question": "Cosa deve fare l'investitore prima di sottoscrivere le quote di un fondo?", "answer": "Prima di procedere a sottoscrivere le quote di un fondo o azioni di una SICAV o SICAF, l'investitore è tenuto ad acquisire una conoscenza adeguata della natura dell'investimento, avendo particolare riguardo ai rischi e ai costi ad esso connessi. Particolarmente utile a tale scopo è un'attenta lettura della documentazione d'offerta del fondo con specifico riguardo al KIID, cioè il documento che in sole due pagine riassume le caratteristiche chiave dell'investimento. Per opportuni approfondimenti è consigliabile altresì la lettura del prospetto informativo e del regolamento di gestione del fondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0595", "question": "Quali informazioni deve fornire l'investitore al distributore per ricevere assistenza nella scelta del fondo?", "answer": "Per far sì che l'assistenza fornita dal distributore sia utile ai fini dell'individuazione del fondo più adatto al proprio profilo, è necessario che l'investitore presti la sua collaborazione fornendo al distributore informazioni sulla propria situazione finanziaria. In particolare, il set informativo che l'investitore è chiamato a fornire all'intermediario distributore sarà tanto più ampio quanto più approfondita è l'assistenza fornita dal distributore medesimo: il set informativo sarà molto ampio nel caso in cui l'intermediario presti al cliente il servizio di consulenza, comprendendo informazioni su conoscenza ed esperienza, situazione finanziaria e obiettivi di investimento; più contenuto negli altri casi, dove rileva esclusivamente l'informazione sulla conoscenza ed esperienza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0596", "question": "Cosa deve fare l'investitore al momento della sottoscrizione?", "answer": "Al momento della sottoscrizione, è necessaria una lettura attenta del modulo di sottoscrizione e una verifica della corretta esecuzione, conforme cioè alle previsioni del regolamento di gestione, dell'operazione di sottoscrizione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0597", "question": "Come deve comportarsi l'investitore durante l'investimento?", "answer": "Durante l'investimento, occorre monitorare l'andamento del fondo consultando il valore della quota che, generalmente, è pubblicato con periodicità quotidiana o con la diversa cadenza prevista dal regolamento del fondo, e leggendo la documentazione periodica inviata dal gestore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0598", "question": "Cosa deve fare l'investitore in fase di disinvestimento?", "answer": "In fase di disinvestimento, l'investitore deve prestare attenzione a che l'operazione di rimborso sia eseguita in conformità alle previsioni contrattuali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0599", "question": "Cosa deve fare l'investitore se qualcosa non è in linea con i propri diritti o responsabilità?", "answer": "Se qualcosa non è in linea rispetto a quanto rappresentato relativamente ai diritti e alle responsabilità, per prima cosa è bene cercare un chiarimento informale con il soggetto con il quale normalmente si hanno i rapporti, cioè il promotore finanziario o l'intermediario distributore. Se ciò non fosse sufficiente, occorre effettuare un reclamo formale nei confronti della SGR e/o dell'intermediario distributore. Inoltre, se si ritiene che l'intermediario o il promotore abbiano violato regole di correttezza o di comportamento, è opportuno inviare un esposto alla CONSOB.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/nella-gestione-collettiva"}},
{"id": "chunk_0600", "question": "Che cosa rappresenta la sezione dedicata alle nozioni e agli strumenti di base?", "answer": "Questa sezione vuole proprio essere una cassetta degli attrezzi che ci aiuti a districarci nel mondo degli investimenti finanziari, fornendo i primi elementi di base sui mercati finanziari, sui principali prodotti che vi vengono scambiati, sui soggetti che vi operano e sui servizi d'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0601", "question": "Che cosa sono i mercati finanziari?", "answer": "I mercati finanziari sono i \"luoghi\" dove è possibile acquistare o vendere strumenti finanziari (azioni, obbligazioni, derivati, quote di fondi ecc.). I mercati finanziari hanno delle regole il cui fine è garantire la correttezza degli scambi e la disponibilità di adeguate informazioni. L'informazione, infatti, ancora una volta, è un elemento centrale per il mondo finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0602", "question": "Quali sono i principali prodotti finanziari trattati nei mercati?", "answer": "Le azioni, le obbligazioni e i fondi comuni sono i più comuni prodotti finanziari trattati nei mercati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0603", "question": "A chi sono adatte le azioni?", "answer": "Le azioni sono per chi vuole partecipare ai profitti delle imprese, sopportandone anche le possibili perdite, che possono arrivare ad annullare l'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0604", "question": "A chi sono adatte le obbligazioni?", "answer": "Le obbligazioni sono per i risparmiatori più \"tranquilli\" che si accontentano di un rendimento più limitato, ma con maggiori garanzie di riavere indietro il capitale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0605", "question": "A chi sono adatti i fondi comuni di investimento?", "answer": "I fondi sono per chi non si sente all'altezza di selezionare i singoli prodotti su cui investire e delega questo compito al gestore di un fondo comune d'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0606", "question": "Perché i derivati fanno parte della cassetta degli attrezzi del risparmiatore?", "answer": "I derivati molto spesso entrano a fare parte di altri prodotti che comunemente vengono offerti ai risparmiatori, come le obbligazioni strutturate ed i fondi comuni che frequentemente, nella loro politica di gestione, utilizzano strumenti derivati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0607", "question": "Chi sono gli operatori finanziari?", "answer": "Gli operatori finanziari (banche, sim, sgr, promotori finanziari ecc.) sono i soggetti che operano nel mondo finanziario e con cui necessariamente abbiamo a che fare nell'investire i nostri risparmi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0608", "question": "Perché i risparmiatori si rivolgono ai servizi di investimento?", "answer": "Siccome i singoli risparmiatori non possono accedere ai mercati, né comprare direttamente strumenti finanziari, una parte importante è rappresentata dai servizi di investimento, prestati da soggetti appositamente autorizzati (ad esempio banche e sim), che svolgono la funzione di intermediari tra risparmiatori e soggetti che emettono o vogliono vendere strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0609", "question": "Perché è importante leggere, studiare e approfondire in materia di investimenti?", "answer": "Leggere, studiare, approfondire è importante. Ma a volte si impara meglio con la pratica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/strumenti-e-risorse"}},
{"id": "chunk_0610", "question": "Chi sono tipicamente i soggetti autorizzati all'esercizio dell'attività bancaria?", "answer": "Le banche sono tipicamente i soggetti autorizzati all'esercizio dell'attività bancaria; possono però prestare nei confronti del pubblico anche servizi e attività di investimento, oltre ai servizi accessori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0611", "question": "In base a dove è situata la sede legale, in quali categorie possono distinguersi le banche?", "answer": "In base a dove è situata la sede legale, possono distinguersi in: - banca italiana; - banca comunitaria, con sede legale e amministrazione centrale in uno Stato comunitario diverso dall'Italia; - banca di Paese terzo, con sede legale in uno Stato extracomunitario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0612", "question": "In quali modalità le banche comunitarie e di Paesi terzi possono svolgere la loro attività in Italia?", "answer": "Le banche comunitarie e di Paesi terzi possono svolgere la loro attività in Italia: - tramite succursale, cioè una sede, sprovvista di personalità giuridica, che effettua direttamente, in tutto o in parte, l'attività della banca; - in libera prestazione di servizi, cioè senza stabilire succursali nel nostro territorio, operando direttamente (ad esempio attraverso servizi on-line) dal proprio Stato di origine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0613", "question": "Su quale base le banche italiane e di Paesi terzi possono prestare servizi e attività di investimento in Italia?", "answer": "Le banche italiane e di Paesi terzi possono prestare servizi e attività di investimento in Italia sulla base di un'autorizzazione rilasciata dalla Banca d'Italia/Banca Centrale Europea, sentita la Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0614", "question": "Come sono autorizzate le banche comunitarie e come possono prestare servizi di investimento in Italia?", "answer": "Le banche comunitarie sono autorizzate nello Stato di appartenenza e possono prestare servizi di investimento in Italia (sia tramite succursale sia in libera prestazione di servizi) a seguito di una semplice comunicazione alla Banca d'Italia da parte dell'Autorità competente dello Stato di appartenenza. La Banca d'Italia dà notizia alla Consob delle autorizzazioni ricevute.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0615", "question": "A quale vigilanza è sottoposta l'operatività in Italia in regime di libera prestazione di servizi da parte di banche comunitarie?", "answer": "In base ai principi comunitari, l'operatività in Italia in regime di libera prestazione di servizi da parte di banche comunitarie è sottoposta esclusivamente alla vigilanza dell'Autorità del Paese di origine (alle Autorità italiane non sono pertanto riconosciuti poteri/doveri di vigilanza).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0616", "question": "Chi controlla il rispetto delle regole di condotta quando una banca comunitaria opera in Italia attraverso una succursale?", "answer": "Nel caso in cui, invece, una banca comunitaria operi in Italia attraverso una succursale, il controllo sul rispetto delle regole di condotta dell'attività svolta dalla succursale italiana spetta alla Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0617", "question": "Chi sono gli unici soggetti che possono svolgere l'attività di gestione collettiva del risparmio?", "answer": "Le Societa di gestione del risparmio (sgr) sono, insieme alle sicav e alle sicaf, gli unici soggetti che possono svolgere l'attività di gestione collettiva del risparmio (ad esempio, la gestione di fondi comuni di investimento mobiliare).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0618", "question": "Quali servizi di investimento possono prestare le sgr oltre alla gestione collettiva del risparmio?", "answer": "Le sgr possono commercializzare i fondi propri e di terzi anche prestare alcuni, determinati, servizi di investimento: - la gestione di portafogli (le cosiddette gestioni patrimoniali); -la consulenza in materia di investimenti; - la ricezione e trasmissione di ordini (solamente in alcuni specifici casi).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0619", "question": "Da chi sono autorizzate le sgr e quali requisiti devono essere verificati?", "answer": "Le sgr sono autorizzate dalla Banca d'Italia (sentita la Consob) dopo aver verificato la sussistenza dei requisiti previsti per legge (art. 34, comma 1, del Testo Unico della finanza), volti ad assicurare la solidità patrimoniale della società (v. provvedimento della Banca d'Italia dell'8 maggio 2012), la professionalità e l'onorabilità degli amministratori, sindaci e direttore generale e l'onorabilità degli azionisti (v. d.m. 11 novembre 1998, n. 468 del Ministro dell'Economia e della Finanza con).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0620", "question": "Qual è l'obiettivo delle regole previste per le sgr?", "answer": "L'obiettivo di queste regole è far sì che l'attività di gestione, per la sua rilevanza economica e sociale, venga svolta da soggetti qualificati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0621", "question": "Per quale motivo sono state fissate regole di condotta per le sgr?", "answer": "Sempre la rilevanza dell'attività ha portato a fissare anche regole di condotta (art.  35-decies del Testo Unico della finanza e artt. 65 e ss. del regolamento Consob n. 16190/2010).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0622", "question": "Quali obblighi di comportamento devono rispettare le sgr?", "answer": "In particolare, le sgr devono: - operare con diligenza, correttezza e trasparenza nell'interesse dei partecipanti ai fondi; - organizzarsi in modo tale da ridurre al minimo il rischio di conflitti di interesse; - adottare misure idonee a salvaguardare i diritti dei partecipanti ai fondi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0623", "question": "In quali parti il legislatore ha distinto l'attività di gestione collettiva del risparmio?", "answer": "L'attività di gestione collettiva del risparmio è distinta dal legislatore in due parti: - istituzione del fondo, e cioè promuovere la sua costituzione e curare, da un punto di vista amministrativo, i rapporti con i partecipanti (procedere alle sottoscrizioni, rimborsi, ecc.). - gestione vera e propria, e cioè decidere la composizione del portafoglio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0624", "question": "Che cosa si intende per sgr \"promotrice\"?", "answer": "Entrambe queste attività possono essere svolte da un'unica sgr, ovvero da sgr diverse. In quest'ultimo caso, la sgr che istituisce il fondo si chiama \"promotrice\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0625", "question": "Chi svolge normalmente l'attività di gestione vera e propria all'interno della sgr e sulla base di quali direttive?", "answer": "L'attività di gestione vera e propria viene di norma svolta da un team di dipendenti della sgr, i gestori, che selezionano gli strumenti finanziari da acquistare o vendere sulla base delle direttive di carattere generale ricevute dal consiglio di amministrazione della sgr.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0626", "question": "È possibile delegare la selezione degli strumenti finanziari a un'altra società e chi mantiene il compito di controllo?", "answer": "È anche possibile, però, che la selezione degli strumenti finanziari, per l'intero portafoglio del fondo o per una parte, venga delegata ad un'altra società, che deve comunque essere autorizzata alla gestione (in Italia possono esserlo sgr, sim e banche). Anche in questo caso, comunque, al consiglio di amministrazione della sgr spetta il compito di fornire le direttive di carattere generale e di controllare l'operato del delegato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0627", "question": "Chi sono i soggetti che possono svolgere l'attività di gestione collettiva del risparmio insieme alle sgr?", "answer": "Le società di investimento a capitale variabile (sicav) e le società di investimento a capitale fisso (sicaf) sono, insieme alle sgr, gli unici soggetti che possono svolgere l'attività di gestione collettiva del risparmio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0628", "question": "Qual è l'unica attività che possono svolgere le sicav e le sicaf?", "answer": "Questa attività (e le relative attività connesse e strumentali) è l'unica che possono svolgere (sono, cioè, società ad oggetto sociale esclusivo).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0629", "question": "Da chi sono autorizzate le sicav e le sicaf e quali requisiti devono essere verificati?", "answer": "Sono autorizzate dalla Banca d'Italia (sentita la Consob) dopo aver verificato la sussistenza dei requisiti previsti per legge (art. 35 -bis comma 1, del Testo Unico della finanza), volti ad assicurare la solidità patrimoniale della società, la professionalità e l'onorabilità degli amministratori, sindaci e direttore generale e l'onorabilità degli azionisti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0630", "question": "Qual è l'obiettivo delle regole previste per sicav e sicaf?", "answer": "L'obiettivo di queste regole è far sì che l'attività di gestione, per la sua rilevanza economica e sociale, venga svolta da soggetti qualificati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0631", "question": "Quali regole di condotta devono rispettare le sicav e le sicaf?", "answer": "In particolare, le sgr devono: - operare con diligenza, correttezza e trasparenza nell'interesse dei partecipanti ai fondi; - organizzarsi in modo tale da ridurre al minimo il rischio di conflitti di interesse; - adottare misure idonee a salvaguardare i diritti dei partecipanti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0632", "question": "Che cosa ottengono i risparmiatori quando acquistano azioni di una sicav o sicaf?", "answer": "Si noti che le sicav e le sicaf sono vere e proprie società di cui i risparmiatori diventano azionisti, acquisendo tutti i diritti connessi, compreso il diritto di voto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0633", "question": "Qual è la principale limitazione al diritto di voto dei risparmiatori nelle sicav e sicaf?", "answer": "Occorre precisare, però, che i risparmiatori acquistano normalmente azioni al portatore che, per legge, consentono un solo voto qualsiasi sia il numero delle azioni sottoscritte.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0634", "question": "Per quale motivo i soci fondatori mantengono un forte controllo nelle sicav e sicaf?", "answer": "I soci che hanno promosso la costituzione della sicav o della sicaf (i soci fondatori) hanno azioni ordinarie, che attribuiscono un voto per ogni azione. Per questa ragione, la possibilità che i risparmiatori possano imporre in assemblea decisioni in contrasto con la volontà dei soci fondatori è alquanto ridotta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0635", "question": "Chi svolge normalmente la gestione vera e propria nelle sicav?", "answer": "L'attività di gestione vera e propria viene di norma svolta da un team di dipendenti della sicav. i gestori, che selezionano gli strumenti finanziari sulla base delle direttive di carattere generale ricevute dal consiglio di amministrazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0636", "question": "È possibile delegare la selezione degli strumenti finanziari nelle sicav e sicaf e chi mantiene il controllo?", "answer": "E' anche possibile, però, che l'attività di selezione degli strumenti finanziari, per l'intero portafoglio o per una parte, venga delegata ad una sgr. Anche in questo caso, comunque, al consiglio di amministrazione della sicav o della sicaf spetta il compito di fornire le direttive di carattere generale e di controllare l'operato del delegato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0637", "question": "Chi sono i soggetti autorizzati all'esercizio dell'attività assicurativa?", "answer": "Le imprese di assicurazione sono i soggetti autorizzati all'esercizio dell'attività assicurativa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0638", "question": "A quale vigilanza sono sottoposte le imprese di assicurazione?", "answer": "Esse sono, in via generale, sottoposte alla vigilanza dell'Ivass (Istituto per la vigilanza sulle assicurazioni), che è chiamata a tutelare la sana e prudente gestione e a garantire la trasparenza e la correttezza dei loro comportamenti nei confronti dei clienti nell'attività di distribuzione, anche quando posta in essere per il tramite di intermediari (agenti, broker...).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0639", "question": "Quali competenze spettano alla Consob in relazione ai prodotti di investimento assicurativi?", "answer": "Spettano invece alla Consob le competenze di vigilanza sulla trasparenza e correttezza dei comportamenti sull'offerta di prodotti di investimento assicurativi (cosiddetti IBIP, polizze vita a contenuto prettamente finanziario quali quelle riconducibili ai rami III, V e, in parte, I), quando tale attività è svolta da intermediari bancari/finanziari (banche, SIM…).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0640", "question": "Che cos'è il KID e chi vigila sulle informazioni contenute in esso?", "answer": "La Consob è inoltre deputata a vigilare sulle informazioni fornite dalle imprese di assicurazione, tramite il KID (Key Information Document), sui ridetti prodotti di investimento assicurativo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0641", "question": "Che cosa sono le SIM?", "answer": "Le Società di intermediazione mobiliare (SIM) sono le imprese di investimento, aventi sede legale e direzione generale in Italia che, a seguito dell'autorizzazione della Consob (sentita la Banca d'Italia), sono iscritte in un apposito albo tenuto sempre dalla Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0642", "question": "Quali attività possono svolgere le SIM?", "answer": "Insieme alle banche possono prestare nei confronti del pubblico i servizi e attività d'investimento, oltre a poter svolgere anche i cosiddetti servizi accessori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0643", "question": "Per quale motivo la legge ha riservato determinate attività alle SIM?", "answer": "Queste attività sono state riservate dalla legge alle SIM (o alle Banche autorizzate) con l'intento di preservare il pubblico di investitori dai danni derivanti dall'attività di figure di intermediari con scarsa professionalità e onestà, purtroppo presenti nelle cronache degli anni passati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0644", "question": "A quale vigilanza sono sottoposte le SIM?", "answer": "Le SIM sono sottoposte ad una continua attività di vigilanza da parte della Consob, per i profili di trasparenza e correttezza, e della Banca d'Italia, per i profili di solidità patrimoniale, al fine di garantire una corretta operatività ed una adeguata informativa nei confronti della propria clientela.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0645", "question": "Chi sono le imprese di investimento UE?", "answer": "Le imprese di investimento UE sono quei soggetti, diversi dalle banche, aventi sede legale in uno Stato UE, diverso dall'Italia, a cui è riservato, insieme ad altri soggetti (banche, SIM, ecc.) l'esercizio professionale nei confronti del pubblico dei servizi e attività di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0646", "question": "In quali modalità possono operare in Italia le imprese di investimento UE?", "answer": "Le imprese di investimento UE possono svolgere la loro attività in Italia: - tramite succursale, cioè una sede, sprovvista di personalità giuridica, dove viene effettuata direttamente, in tutto o in parte, l'attività dell'impresa; - in libera prestazione di servizi, cioè senza stabilire succursali nel nostro territorio, operando direttamente (ad esempio attraverso servizi on-line) dal proprio Stato di origine; - Le imprese di investimento UE sono autorizzate nello Stato di appartenenza e possono prestare servizi di investimento in Italia (sia tramite succursale sia in libera prestazione di servizi) a seguito di una comunicazione (notifica) alla Consob da parte dell'Autorità competente del Paese UE di origine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0647", "question": "A quale vigilanza è sottoposta l'operatività in libera prestazione di servizi da parte di imprese di investimento UE?", "answer": "In base ai principi UE (principio del Home Country Control), l'operatività in Italia in regime di libera prestazione di servizi è sottoposta esclusivamente alla vigilanza dell'Autorità del Paese UE di origine (alle Autorità italiane non sono pertanto riconosciuti poteri/doveri diretti di vigilanza).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0648", "question": "Chi controlla le regole di condotta quando un'impresa di investimento UE opera tramite succursale in Italia?", "answer": "Nel caso in cui, invece, una impresa di investimento UE operi in Italia attraverso una succursale, il controllo sul rispetto delle regole di condotta dell'attività svolta dalla succursale italiana sul territorio nazionale spetta alla Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0649", "question": "Chi vigila sui profili organizzativi e prudenziali delle imprese di investimento UE che operano tramite succursale in Italia?", "answer": "Al contrario, la vigilanza sui profili organizzativi (procedure, controlli interni, conflitti di interesse, misure per la salvaguardia dei beni della clientela,…) e prudenziali (contenimento dei rischi e stabilità patrimoniale) restano in capo alla sola Autorità del Paese di origine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0650", "question": "Chi sono le imprese di investimento extracomunitarie?", "answer": "Le imprese di Paesi terzi diverse dalle banche sono quei soggetti autorizzati a svolgere servizi o attività di investimento e aventi sede legale in uno Stato extraUE.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0651", "question": "Perché alle imprese di investimento extracomunitarie non si applica il principio del mutuo riconoscimento?", "answer": "A queste soggetti non si applica il principio del mutuo riconoscimento delle autorizzazioni previsto in ambito UE.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0652", "question": "Quali autorizzazioni devono ottenere le imprese di investimento extracomunitarie per operare in Italia?", "answer": "Per poter operare in Italia, sia nella modalità della libera prestazione di servizi e sia mediante stabilimento di succursale devono pertanto essere in possesso di una autorizzazione, rilasciata dalla Consob, sentita la Banca d'Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0653", "question": "Chi è il \"Consulente finanziario abilitato all'offerta fuori sede\"?", "answer": "Il \"Consulente finanziario abilitato all'offerta fuori sede\" è la persona fisica che in Italia esercita professionalmente \"l'offerta fuori sede\" (come dipendente, agente o mandatario) per conto di una Impresa di investimento, Banca, Società di gestione del risparmio, ecc.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0654", "question": "Qual è l'unico operatore autorizzato a incontrare i risparmiatori al di fuori delle sedi degli intermediari finanziari?", "answer": "Il \"Consulente abilitato\" è l'unico operatore autorizzato ad incontrare i risparmiatori al di fuori della sede e delle filiali di un intermediario finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0655", "question": "Quali requisiti deve possedere il Consulente finanziario abilitato all'offerta fuori sede?", "answer": "Il Consulente finanziario abilitato (in possesso dei requisiti di onorabilità e professionalità stabiliti dal Ministero dell'Economia e delle Finanze) deve essere iscritto in apposita Sezione dell'Albo Unico dei consulenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0656", "question": "Chi tiene l'Albo Unico dei consulenti finanziari e chi vigila sui Consulenti abilitati?", "answer": "L'Albo è tenuto dall'Organismo di Vigilanza e tenuta dell'Albo Unico dei Consulenti Finanziari-OCF. A questo Organismo compete anche lo svolgimento della funzione pubblica di vigilanza sui Consulenti abilitati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0657", "question": "Per conto di quanti intermediari può operare un Consulente finanziario abilitato all'offerta fuori sede?", "answer": "Il Consulente finanziario abilitato può svolgere l'attività per conto di un solo Intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0658", "question": "Che responsabilità hanno gli Intermediari rispetto all'attività svolta dai loro consulenti abilitati?", "answer": "Gli Intermediari devono costantemente controllare l'attività dei loro consulenti (dotandosi di procedure di controllo e di un'organizzazione interna adeguate) e sono civilmente responsabili in via solidale con i propri consulenti del loro operato nei confronti dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0659", "question": "Quali attività non può esercitare il Consulente finanziario abilitato all'offerta fuori sede?", "answer": "Il Consulente finanziario abilitato all'offerta fuori sede non può esercitare (anche in assenza di incarichi per intermediari finanziari) le attività di Consulente finanziario autonomo (anche in forma di Società) e l'iscrizione in una delle 3 sezioni dell'Albo è incompatibile con l'iscrizione in altra sezione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0660", "question": "A quali soggetti è riservato l'esercizio professionale della Consulenza in materia di investimenti?", "answer": "L'esercizio professionale nei confronti del pubblico della \"Consulenza in materia di investimenti\" è riservato, come gli altri Servizi e Attività di investimento definiti dalla legge, solamente a determinati soggetti (banche, SIM, imprese di investimento UE, SGR, ecc).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0661", "question": "Chi può prestare il servizio di Consulenza in materia di investimenti pur non rientrando tra i soggetti riservati dalla legge?", "answer": "Le norme prevedono che tale riserva di attività non pregiudica la possibilità per i \"Consulenti finanziari autonomi\" (persone fisiche) e per le \"Società di consulenza finanziaria\" (S.r.l. o S.p.a.) di prestare la (il Servizio di) \"Consulenza in materia di investimenti\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0662", "question": "A quali strumenti può riferirsi la consulenza prestata dai consulenti autonomi e dalle società di consulenza?", "answer": "I \"Consulenti autonomi\" e le \"Società\" possono prestare il Servizio di Consulenza limitatamente a consigli d'investimento aventi ad oggetto solo \"valori mobiliari\" e \"quote di organismi d'investimento collettivo\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0663", "question": "Quali divieti si applicano ai consulenti finanziari autonomi e alle società di consulenza?", "answer": "È anche vietata la possibilità di detenere somme di denaro e strumenti finanziari di pertinenza dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0664", "question": "Quali requisiti devono possedere i consulenti finanziari autonomi e le società di consulenza finanziaria?", "answer": "Anche queste categorie di consulenti devono possedere determinati requisiti di professionalità, onorabilità nonché d'indipendenza e patrimoniali stabiliti dal Ministero dell'Economia e delle Finanze.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0665", "question": "Dove devono essere iscritti i consulenti finanziari autonomi e le società di consulenza?", "answer": "Anche i Consulenti finanziari autonomi e le Società di consulenza finanziaria devono essere iscritti in apposita Sezione dell'Albo Unico dei consulenti finanziari, tenuto dall'OCF.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0666", "question": "In cosa consistono i servizi di crowdfunding?", "answer": "I servizi di crowdfunding consistono nell'abbinamento tra gli interessi a finanziare attività economiche di investitori e titolari di progetti tramite l'utilizzo di un sistema informatico accessibile via internet (piattaforma on-line) gestito da un fornitore di servizi di crowdfunding.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0667", "question": "Quali forme di crowdfunding sono sottoposte a riserva?", "answer": "Sono sottoposte a riserva due forme di crowdfunding: - il lending-based crowdfunding, che prevede la concessione di prestiti alle imprese; - l'investment-based crowdfunding, che consente alle imprese di raccogliere capitale tramite l'emissione di azioni/quote, ovvero titoli di debito/obbligazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0668", "question": "Da chi sono autorizzati i fornitori di servizi di crowdfunding?", "answer": "I fornitori di servizi di crowdfunding sono autorizzati dalla Consob e dalla Banca d'Italia secondo un riparto di competenza per tipologia di soggetti e sono vigilati dalle medesime Autorità, ciascuna per i profili di propria competenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0669", "question": "Di quali profili è competente la Consob nella vigilanza sul crowdfunding?", "answer": "In particolare, la Consob è competente per quanto riguarda la trasparenza e la correttezza dei comportamenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0670", "question": "Di quali profili è competente la Banca d'Italia nella vigilanza sul crowdfunding?", "answer": "La Banca d'Italia è competente per il contenimento del rischio, la stabilità patrimoniale e la sana e prudente gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0671", "question": "Chi tiene il registro europeo dei fornitori di servizi di crowdfunding?", "answer": "Il registro dei fornitori di servizi di crowdfunding è centralizzato a livello europeo ed è tenuto dall'ESMA.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-operatori-finanziari"}},
{"id": "chunk_0672", "question": "Cosa sono i prodotti derivati?", "answer": "I prodotti derivati si chiamano in questo modo perché il loro valore deriva dall'andamento del valore di una attività ovvero dal verificarsi nel futuro di un evento osservabile oggettivamente. L'attività, ovvero l'evento, che possono essere di qualsiasi natura o genere, costituiscono il \"sottostante\" del prodotto derivato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0673", "question": "Per quali finalità vengono utilizzati i prodotti derivati?", "answer": "Tali strumenti sono utilizzati, principalmente, per tre finalità: - ridurre il rischio finanziario di un portafoglio preesistente (finalità di copertura o, anche, hedging); - assumere esposizioni al rischio al fine di conseguire un profitto (finalità speculativa); - conseguire un profitto privo di rischio attraverso transazioni combinate sul derivato e sul sottostante tali da cogliere eventuali differenze di valorizzazione (finalità di arbitraggio).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0674", "question": "Qual è il problema più complesso dei derivati?", "answer": "Il problema più complesso dei derivati è, da sempre, quello della determinazione del loro valore o, meglio della sua stima. E' un aspetto particolarmente importante e, nello stesso tempo, critico, in quanto richiede complesse attività di analisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0675", "question": "Da cosa varia il valore di un derivato?", "answer": "A grandi linee si può dire che il loro valore varia in connessione all'andamento del sottostante, secondo una relazione, propria di ciascun derivato, rappresentata da una funzione matematica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0676", "question": "Quali sono le principali categorie di prodotti derivati?", "answer": "Le principali categorie di prodotti derivati sono: 1. Contratti a termine, 2. Gli swap, 3. Le opzioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0677", "question": "Che cos'è un contratto a termine?", "answer": "Un contratto a termine è un accordo tra due soggetti per la consegna di una determinata quantità di un certo sottostante (attività finanziarie o merci) ad un prezzo (prezzo di consegna) e ad una data (data di scadenza o maturity date) prefissati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0678", "question": "Da cosa dipende il profilo di rischio e rendimento di un contratto a termine?", "answer": "Le variazioni del valore del sottostante determinano il profilo di rischio/rendimento di un contratto a termine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0679", "question": "Qual è il rischio per l'acquirente di un contratto a termine?", "answer": "Per l'acquirente del contratto, cioè colui che deve comprare un certo bene ad una certa data e ad un prezzo già fissato nel contratto, il rischio è rappresentato dal deprezzamento del bene. In questo caso, infatti, egli sarebbe comunque costretto a pagare il prezzo già fissato nel contratto per un bene il cui valore di mercato è minore del prezzo da pagare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0680", "question": "Qual è il rischio per il venditore di un contratto a termine?", "answer": "Per il venditore del contratto, al contrario, il rischio è rappresentato dall'apprezzamento del bene.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0681", "question": "Quali sono le principali tipologie di contratti a termine?", "answer": "Le principali tipologie di contratti a termine sono i contratti: - forward, che si caratterizzano per il fatto di essere scambiati fuori dai mercati regolamentati; - futures, negoziati sui mercati regolamentati e, proprio per questo, standardizzati per oggetto, dimensione, scadenza e regole di negoziazione. Alle parti, pertanto, è rimessa solamente la possibilità di definire il prezzo a cui vogliono acquistare o vendere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0682", "question": "Che cos'è uno swap?", "answer": "Attraverso lo swap due parti si accordano per scambiarsi flussi di pagamenti (anche detti flussi di cassa) a date certe. I pagamenti possono essere espressi nella stessa valuta o in valute differenti ed il loro ammontare è determinato in relazione ad un sottostante. Gli swap sono contratti OTC (over-the-counter) e, quindi, non negoziati su mercati regolamentati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0683", "question": "Quali sono i principali tipi di swap?", "answer": "In base al sottostante si individuano vari tipi di swap. I principali osservati sui mercati finanziari sono: - Interest rate swap, - Currency swap, - Asset swap, - Credit default swap (CDS).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0684", "question": "Che cos'è un interest rate swap?", "answer": "Gli interest rate swap sono contratti in cui due controparti si scambiano pagamenti periodici di interessi, calcolati su una somma di denaro, detta capitale nozionale di riferimento (notional principal amount), per un periodo di tempo predefinito pari alla durata del contratto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0685", "question": "Cos'è un plain vanilla swap?", "answer": "La più diffusa forma di IRS è denominata plain vanilla swap e si caratterizza per il fatto che uno dei due flussi di pagamenti è basato su un tasso di interesse fisso, mentre l'altro è indicizzato a un tasso di interesse variabile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0686", "question": "Da cosa dipende il profilo di rischio e rendimento di un interest rate swap?", "answer": "Le variazioni del tasso variabile, rispetto ai livelli ipotizzati al momento della conclusione del contratto, determinano il profilo di rischio/rendimento del prodotto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0687", "question": "Quando chi paga il tasso fisso in un interest rate swap matura un profitto?", "answer": "Se il tasso variabile risulta superiore alle aspettative, chi è obbligato a pagare il tasso fisso matura un profitto, in quanto, fermo restando i pagamenti a tasso fisso cui è obbligato, riceverà pagamenti a tasso variabile di importo superiore a quanto previsto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0688", "question": "Che cos'è un currency swap?", "answer": "I currency swap, letteralmente \"scambio di valute\", sono contratti in cui due parti si scambiano il capitale e gli interessi espressi in una divisa contro capitale e interessi espressi in un'altra divisa. Caratteristica ricorrente dei currency swap è che entrambi i flussi di pagamenti sono a tasso variabile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0689", "question": "Che cos'è un asset swap?", "answer": "Gli asset swap sono contratti in cui due parti si scambiano pagamenti periodici liquidati in relazione ad un titolo obbligazionario (asset) detenuto da una di esse. Chi detiene l'obbligazione corrisponde l'interesse connesso all'obbligazione. L'altra parte riceve l'interesse dell'obbligazione e paga un tasso di natura diversa (se l'obbligazione è a tasso fisso pagherà un variabile e viceversa).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0690", "question": "Che cos'è un credit default swap (CDS)?", "answer": "I credit default swap (CDS) sono contratti in cui un soggetto (cosiddetto protection buyer), a fronte di pagamenti periodici effettuati a favore della controparte (cosiddetto protection seller), si protegge dal rischio di credito associato ad un determinato sottostante che può essere costituito da una specifica emissione, da un emittente o da un intero portafoglio di strumenti finanziari. La funzione tipica del contratto è quindi la copertura dei rischi associati ad una determinata attività.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0691", "question": "Che cos'è un'opzione?", "answer": "L'opzione è un contratto che attribuisce il diritto, ma non l'obbligo, di comprare (opzione call) o vendere (opzione put) una data quantità di un bene (sottostante) ad un prezzo prefissato (strike price o prezzo di esercizio) entro una certa data (scadenza, o maturità), nel qual caso si parla di opzione americana, o al raggiungimento della stessa, nel qual caso si parla di opzione europea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0692", "question": "Quali beni possono essere sottostanti di un'opzione?", "answer": "Il bene sottostante può essere: - un'attività finanziaria, come azioni, obbligazioni, valute, strumenti finanziari derivati, ecc.; - una merce, come petrolio, oro, grano, ecc.; - un evento di varia natura.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0693", "question": "Cosa accade quando il compratore di un'opzione esercita il diritto?", "answer": "Nel momento in cui il compratore dell'opzione esercita il diritto, cioè decide di acquistare (call) o vendere (put), il suo ricavo consisterà: - nel caso di opzione call, nella differenza tra il prezzo corrente del sottostante (cosiddetto prezzo spot) e il prezzo di esercizio; - nel caso di put, nella differenza tra prezzo di esercizio e prezzo spot.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0694", "question": "Cosa sono i covered warrant?", "answer": "Assimilabili alle opzioni sono i covered warrant i quali, a differenza delle opzioni che sono contratti, sono titoli che incorporano un'opzione, emessi da banche o imprese di investimento; sono strumenti diffusi anche fra i piccoli risparmiatori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-derivati"}},
{"id": "chunk_0695", "question": "Quali sono i documenti da leggere prima di investire in fondi comuni aperti?", "answer": "Prima di investire è indispensabile la lettura del KIID (Key Investor Information Document), cioè del documento che, in sole due pagine, riassume le caratteristiche chiave dell'OICR. Ulteriori approfondimenti possono essere rinvenuti sia nel prospetto informativo che nel regolamento di gestione del fondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0696", "question": "In quante parti si articola il KIID e quali informazioni contiene?", "answer": "Il KIID si articola in 4 parti: a) finalità e politica di investimento; b) profilo di rischio rendimento; c) costi; d) performance storiche. Viene, quindi, fornita una guida alla lettura di ogni parte del documento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0697", "question": "Come è strutturato il prospetto informativo dei fondi comuni aperti?", "answer": "Il prospetto informativo si suddivide in parte I e parte II.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0698", "question": "Qual è il regime di consegna e pubblicazione della documentazione d'offerta per i fondi comuni aperti?", "answer": "Il regime di consegna e pubblicazione della documentazione d'offerta prevede la consegna obbligatoria per il KIID e la consegna su richiesta di prospetto e regolamento di gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0699", "question": "Quali documenti devono essere letti prima di investire in fondi comuni chiusi?", "answer": "Nel caso di un'offerta al pubblico e/o ammissione alle negoziazioni su un mercato regolamentato, è necessario pubblicare un prospetto, affinché il potenziale investitore sia messo nelle condizioni di assumere consapevoli scelte di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0700", "question": "Cosa contiene il prospetto dei fondi comuni chiusi?", "answer": "Il prospetto contiene informazioni riguardanti le caratteristiche del gestore e del fondo, nonché le relative rischiosità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0701", "question": "Che cos'è la nota di sintesi del prospetto dei fondi comuni chiusi e a cosa serve?", "answer": "La nota di sintesi costituisce una parte del prospetto, nell'ambito della quale sono rappresentate con linguaggio non tecnico le informazioni chiave relative all'investimento proposto. Ciò al fine di consentire al potenziale investitore di decidere quali investimenti esaminare ulteriormente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0702", "question": "Dove si possono trovare ulteriori approfondimenti sui fondi comuni chiusi?", "answer": "Ulteriori approfondimenti possono essere rinvenuti nell'eventuale documentazione contrattuale ad hoc predisposta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0703", "question": "Come può ottenere il prospetto un potenziale investitore in fondi comuni chiusi?", "answer": "Copia del prospetto è consegnata gratuitamente al potenziale investitore, previa specifica richiesta. Il prospetto è altresì consultabile tramite sito web dell'emittente/offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0704", "question": "Quali documenti devono essere pubblicati nel caso di un'offerta di valori mobiliari come obbligazioni, certificates o covered warrants?", "answer": "Nel caso di un'offerta al pubblico e/o ammissione alle negoziazioni su un mercato regolamentato, è necessario pubblicare un prospetto, affinché il potenziale investitore sia messo nelle condizioni di assumere consapevoli scelte di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0705", "question": "Cosa contiene il prospetto relativo ai valori mobiliari?", "answer": "Il prospetto contiene informazioni riguardanti le caratteristiche dell'emittente e del prodotto, nonché le relative rischiosità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0706", "question": "Qual è la funzione della nota di sintesi nel prospetto dei valori mobiliari?", "answer": "La nota di sintesi costituisce una parte del prospetto, nell'ambito della quale sono rappresentate con linguaggio non tecnico le informazioni chiave relative all'investimento proposto. Ciò al fine di consentire al potenziale investitore di decidere quali investimenti esaminare ulteriormente. La nota di sintesi viene fra l'altro redatta secondo un formato comune, per agevolare la comparazione tra prodotti finanziari similari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0707", "question": "Dove si possono trovare ulteriori informazioni sui valori mobiliari?", "answer": "Ulteriori approfondimenti possono essere rinvenuti nell'eventuale documentazione contrattuale ad hoc predisposta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0708", "question": "Come può ottenere il prospetto un potenziale investitore in valori mobiliari?", "answer": "Copia del prospetto è consegnata gratuitamente al potenziale investitore, previa specifica richiesta. Il prospetto è altresì consultabile tramite sito web dell'emittente/offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0709", "question": "Quali documenti devono essere letti prima di investire in prodotti finanziari assicurativi?", "answer": "Prima di investire è indispensabile la lettura della Scheda sintetica e delle Condizioni di contratto, che devono essere obbligatoriamente consegnate all'investitore prima della sottoscrizione. Ulteriori approfondimenti possono essere rinvenuti nel prospetto informativo e nei regolamenti di gestione dei fondi sottostanti al prodotto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0710", "question": "Come è strutturata la Scheda sintetica dei prodotti finanziari assicurativi?", "answer": "La Scheda sintetica si articola in una parte 'Informazioni generali' e in tante parti relative alle 'Informazioni specifiche' quante sono le proposte di investimento in cui è possibile investire.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0711", "question": "Come può ottenere il prospetto un potenziale investitore in prodotti finanziari assicurativi?", "answer": "Il prospetto deve essere consegnato gratuitamente al potenziale investitore che ne faccia richiesta. Il prospetto è altresì consultabile tramite il sito web dell'emittente e del distributore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-documenti-da-leggere-prima-dell-investimento"}},
{"id": "chunk_0712", "question": "Cosa sono i fondi comuni?", "answer": "I fondi comuni sono strumenti di investimento, gestiti dalle società di gestione del risparmio (sgr) che riuniscono le somme di più risparmiatori e le investono, come un unico patrimonio, in attività finanziarie (azioni, obbligazioni, titoli di stato, ecc.) o, per alcuni di essi, in immobili, rispettando regole volte a ridurre i rischi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0713", "question": "Come sono suddivisi i fondi comuni?", "answer": "Sono suddivisi in tante parti unitarie, dette quote, che vengono sottoscritte dai risparmiatori e garantiscono uguali diritti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0714", "question": "Qual è la differenza tra fondi comuni, SICAV e SICAF?", "answer": "Il fondo comune è un patrimonio a sé stante, costituito con il denaro dei sottoscrittori e gestito dalla sgr, mentre le sicav e le sicaf sono vere e proprie società di cui i sottoscrittori divengono soci con tutti i relativi diritti, come ad esempio il diritto di voto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0715", "question": "Che tipo di attività svolgono i fondi, le SICAV e le SICAF?", "answer": "In pratica, sia i fondi che le sicav e le sicaf svolgono lo stesso tipo di attività, per cui nel prosieguo con il termine \"fondo\" ci si riferisce anche alle \"sicav\" e alle \"sicaf\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0716", "question": "Qual è la distinzione fondamentale tra i tipi di fondi?", "answer": "Una distinzione fondamentale è fra fondi aperti e fondi chiusi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0717", "question": "Cosa sono i fondi aperti?", "answer": "I fondi aperti consentono di sottoscrivere quote, o chiederne il rimborso, in qualsiasi momento. Questi fondi investono normalmente in attività finanziarie quotate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0718", "question": "Cosa sono i fondi chiusi?", "answer": "I fondi chiusi consentono di sottoscrivere quote solo nel periodo di offerta, che si svolge prima di iniziare l'operatività vera e propria, e le rimborsano di norma solo alla scadenza del fondo. Ai fondi chiusi sono riservati investimenti poco liquidi e di lungo periodo come immobili, crediti o società non quotate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0719", "question": "Cosa sono i fondi aperti armonizzati?", "answer": "I fondi armonizzati sono fondi aperti costituiti nei paesi dell'Unione europea che investono prevalentemente in titoli quotati come azioni e obbligazioni. Il termine \"armonizzati\" deriva dal fatto che seguono regole e criteri comuni volti a tutelare gli interessi dei risparmiatori, limitando e frazionando i rischi assumibili dai fondi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0720", "question": "Chi vigila sui fondi armonizzati?", "answer": "La vigilanza sui fondi armonizzati è affidata alle autorità del paese di origine. Ad esempio, un fondo lussemburghese sarà vigilato dall'autorità del Lussemburgo, anche se offerto in Italia. Alle autorità italiane spetta esclusivamente la vigilanza sulle modalità di commercializzazione del prodotto nel nostro Paese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0721", "question": "Come si suddividono i fondi armonizzati in base alla politica di investimento?", "answer": "A seconda delle loro politiche di investimento, i fondi armonizzati si suddividono in fondi azionari, fondi obbligazionari, fondi bilanciati e fondi monetari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0722", "question": "Cosa caratterizza i fondi azionari?", "answer": "I fondi azionari investono prevalentemente in azioni e, generalmente, si caratterizzano per un alto grado di rischio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0723", "question": "Cosa caratterizza i fondi obbligazionari?", "answer": "I fondi obbligazionari investono principalmente in titoli di Stato ed in obbligazioni e si caratterizzano per un grado di rischio generalmente minore dei fondi azionari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0724", "question": "Cosa caratterizza i fondi bilanciati?", "answer": "I fondi bilanciati investono sia in azioni che in obbligazioni, con livelli di rischio via via crescenti in base alla percentuale di azioni presenti in portafoglio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0725", "question": "Cosa caratterizza i fondi monetari?", "answer": "I fondi monetari investono in strumenti del mercato monetario a breve termine, non superiore a 6 mesi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0726", "question": "Cosa deve leggere l'investitore per scegliere un fondo?", "answer": "Per scegliere il fondo occorre leggere il KIID (Key Investor Information Document), che deve essere obbligatoriamente consegnato al sottoscrittore, e prestare molta attenzione alle caratteristiche chiave.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0727", "question": "Quali sono le caratteristiche chiave da valutare nel KIID?", "answer": "Le caratteristiche chiave da valutare nel KIID sono finalità e politica di investimento, profilo di rischio-rendimento, costi e rendimenti passati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0728", "question": "Cosa descrive la finalità e politica di investimento?", "answer": "La finalità e politica di investimento indica le principali tipologie di attività in cui il fondo investe, con particolare riguardo, se rilevante, all'area geografica o settoriale di riferimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0729", "question": "Cosa rappresenta il profilo di rischio-rendimento?", "answer": "Il profilo di rischio-rendimento classifica ciascun fondo con un indicatore sintetico di rischio che va da 1 (minimo rischio) a 7 (massimo rischio).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0730", "question": "Perché è importante conoscere i costi di un fondo?", "answer": "Conoscere i costi è importante perché possono abbattere in maniera significativa il rendimento del fondo e perché molti fondi offrono formule alternative di costi, come commissioni di rimborso invece che di sottoscrizione, che meglio possono soddisfare le esigenze del risparmiatore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0731", "question": "Come devono essere interpretati i rendimenti passati?", "answer": "Occorre non sopravvalutare i rendimenti passati perché non vi è alcuna certezza di conseguire analoghi rendimenti in futuro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0732", "question": "Cosa deve fare il risparmiatore una volta acquistato il fondo?", "answer": "L'investimento in fondi deve essere seguito nel tempo. Il risparmiatore è avvantaggiato dalla mole di informazioni che può ottenere, grazie alle quali può monitorare l'investimento ed eventualmente maturare altre scelte.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0733", "question": "Quali informazioni sono a disposizione del risparmiatore?", "answer": "Le informazioni a disposizione del risparmiatore sono il valore della quota, le modifiche su caratteristiche importanti del fondo, la parte 2a del prospetto informativo e i documenti contabili del fondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0734", "question": "Cosa rappresenta il valore della quota?", "answer": "Il valore della quota, pubblicato sui principali quotidiani o su internet, indica giorno per giorno l'ammontare e l'andamento dell'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0735", "question": "Quali modifiche devono essere comunicate ai partecipanti?", "answer": "Devono essere comunicate singolarmente ai partecipanti le modifiche su caratteristiche importanti del fondo, come l'identità del gestore, le variazioni della politica di investimento o un aumento superiore al 20% dei costi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0736", "question": "Cosa contiene la parte 2a del prospetto informativo?", "answer": "La parte 2a del prospetto informativo contiene tutti i dati aggiornati di rendimento del fondo e del benchmark e deve essere inviata al risparmiatore entro il mese di febbraio di ciascun anno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0737", "question": "Cosa illustrano i documenti contabili del fondo?", "answer": "I documenti contabili del fondo, come il rendiconto annuale e la relazione semestrale, illustrano la situazione patrimoniale e reddituale del fondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-fondi-comuni"}},
{"id": "chunk_0738", "question": "Cosa sono i mercati finanziari?", "answer": "I mercati sono i \"luoghi\" dove è possibile acquistare o vendere strumenti finanziari (azioni, obbligazioni, derivati, quote di fondi ecc.).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0739", "question": "Qual è la distinzione principale tra mercato primario e mercato secondario?", "answer": "Una prima distinzione è fra: - mercato primario - dove si acquistano i titoli al momento dell'emissione; - mercato secondario - rappresentato dai mercati finanziari dove si acquistano titoli da chi li ha già sottoscritti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0740", "question": "I mercati finanziari sono ancora luoghi fisici?", "answer": "I mercati finanziari non sono più luoghi fisici ma piattaforme informatiche (\"sedi di negoziazione\") dove si \"incrociano\" le proposte di acquisto e di vendita di strumenti finanziari immesse nel sistema telematicamente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0741", "question": "Come possono essere suddivisi i mercati operanti in Italia?", "answer": "I \"mercati\" operanti in Italia possono essere suddivisi in tre categorie: - mercati regolamentati; - sistemi multilaterali di negoziazione; - (\"MTF\") e Internalizzatori sistematici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0742", "question": "Cosa sono i mercati regolamentati?", "answer": "Sono sistemi dove, nel rispetto di un regolamento, vengono immesse da più intermediari, per conto proprio o dei loro clienti, proposte di vendita e di acquisto di strumenti finanziari. Le proposte trovano esecuzione l'una contro l'altra, abbinandosi con le proposte di segno contrario (ma compatibili per prezzo e quantità) immesse nel sistema da altri intermediari, senza l'interposizione del gestore del mercato (questo sistema di negoziazione è detto di tipo multilaterale).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0743", "question": "Chi gestisce i mercati regolamentati?", "answer": "Sono gestiti da società di gestione del mercato, autorizzate dalla Consob, che adottano un regolamento approvato dalla stessa Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0744", "question": "Qual è l'importante caratteristica dei mercati regolamentati?", "answer": "Importante caratteristica è l'ampiezza delle informazioni disponibili per gli investitori relativamente: all'emittente degli strumenti finanziari negoziati (situazione finanziaria, fatti rilevanti che lo riguardano, maggiori azionisti, soggetti che esercitano il controllo sulla società) e agli stessi strumenti finanziari (caratteristiche, vendite allo scoperto significative di azioni, azioni acquistate o vendute dal Top Management dell'emittente).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0745", "question": "Cosa sono i sistemi multilaterali di negoziazione?", "answer": "Per molti aspetti sono simili ai Mercati regolamentati in quanto sono sistemi di negoziazione multilaterale, autorizzati dalla Consob e disciplinati da regole sottoposte alla stessa Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0746", "question": "Chi può gestire i sistemi multilaterali di negoziazione?", "answer": "Possono però essere gestiti anche da soggetti diversi da società di gestione del mercato (ad esempio banche o sim) purchè autorizzati allo specifico servizio di investimento della gestione di sistemi multilateriali di negoziazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0747", "question": "Qual è la differenza informativa tra i mercati regolamentati e i sistemi multilaterali di negoziazione?", "answer": "Anche il set informativo a disposizione è meno ampio; non sono ad esempio previsti meccanismi di pubblicità relativamente ai maggiori azionisti, al controllo della società e alle operazioni compiute da amministrazioni, sindaci e dirigenti su titoli dell'emittente (Top managers).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0748", "question": "Cosa sono gli MTF e gli internalizzatori sistematici?", "answer": "Sono intermediari (soprattutto banche) abilitati al servizio di investimento di negoziazione per conto proprio che, in modo organizzato, frequente e sistematico, negoziano strumenti finanziari per conto proprio, eseguendo gli ordini dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0749", "question": "Che tipo di sistema di negoziazione utilizzano gli internalizzatori sistematici?", "answer": "Si tratta di un sistema di negoziazione bilaterale (e non multilaterale) perché l'unico intermediario presente è proprio l'internalizzatore sistematico che si interpone in ogni operazione, acquistando, al prezzo da esso stesso stabilito, dai clienti che vogliono vendere e vendendo a quelli che vogliono acquistare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0750", "question": "Esistono obblighi informativi particolari per gli internalizzatori sistematici?", "answer": "Non sono previste norme particolari per quanto riguarda le informazioni sugli emittenti i titoli negoziati esclusivamente su tali sistemi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0751", "question": "È possibile acquistare o vendere strumenti finanziari al di fuori dei mercati?", "answer": "É inoltre possibile acquistare o vendere strumenti finanziari anche al di fuori dei mercati (cosiddetti over-the-counter). Queste operazioni avvengono in genere in contropartita con il proprio intermediario abilitato (banca o sim).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0752", "question": "Cosa si intende per integrità dei mercati?", "answer": "L'integrità dei mercati prevede sanzioni per chi commette abusi di mercato che possono essere suddivisi in: abuso di informazioni privilegiate e manipolazione del mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0753", "question": "Cosa si intende per abuso di informazioni privilegiate?", "answer": "L'abuso di informazioni privilegiate consiste nell'utilizzo o nella comunicazione ad altri di informazioni di carattere preciso (cioè relativa a fatti esistenti o che verosimilmente si realizzeranno e non generica) concernenti emittenti di strumenti finanziari o gli stessi strumenti finanziari che, se rese pubbliche, potrebbero influire in modo sensibile sui prezzi di tali strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0754", "question": "Cosa si intende per manipolazione del mercato?", "answer": "La manipolazione del mercato consiste nella diffusione di informazioni false o nel conferimento di ordini al fine di alterare ingiustificatamente il processo di formazione dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0755", "question": "Quali sono le sanzioni previste per gli abusi di mercato?", "answer": "Le sanzioni consistono in forti multe ma, anche, nella confisca del profitto dell'illecito. Per diverse fattispecie dolose sono anche stabilite sanzioni penali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-mercati-finanziari"}},
{"id": "chunk_0756", "question": "Cosa sono i servizi di investimento?", "answer": "Attraverso i servizi di investimento gli intermediari (banche, SIM ecc.) ci consentono di impiegare, sotto varie forme, i nostri risparmi in strumenti finanziari (azioni, obbligazioni, titoli di Stato, quote di fondi, contratti e strumenti derivati ecc.).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0757", "question": "Quali sono i servizi e le attività di investimento individuati dalla legge?", "answer": "I servizi e le attività di investimento, puntualmente individuati dalla legge (Testo unico della finanza), sono: esecuzione di ordini per conto dei clienti: è l'acquisto o vendita di titoli per conto del cliente; negoziazione per conto proprio: è l'acquisto dal cliente o la vendita al cliente di titoli di proprietà dell'intermediario; gestione di sistemi multilaterali di negoziazione: si tratta di sistemi che consentono di far incontrare, sulla base di regole predeterminate, proposte di acquisto e di vendita provenienti da una pluralità di operatori; ricezione e trasmissione di ordini: l'intermediario riceve dal cliente un ordine di acquisto o vendita di titoli e lo trasmette ad altro intermediario per l'esecuzione; sottoscrizione e/o collocamento: è la distribuzione di strumenti finanziari, nell'ambito di un'offerta al pubblico standardizzata, sulla base di un accordo con l'emittente (o offerente); gestione di portafogli: è la gestione del nostro patrimonio, svolta dall'intermediario, investendolo in strumenti finanziari; consulenza in materia di investimenti: il consulente fornisce consigli o raccomandazioni personalizzati circa una o più operazioni relative ad un determinato strumento finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0758", "question": "Chi può prestare servizi di investimento?", "answer": "I servizi di investimento, in quanto coinvolgono un tema importante come il risparmio, possono essere prestati solo da intermediari dotati di una specifica autorizzazione. I principali soggetti che possono essere autorizzati sono: società di intermediazione mobiliare (SIM) italiane: possono essere autorizzate dalla Consob ad offrire tutti i servizi di investimento; banche italiane: possono essere autorizzate dalla Banca d'Italia ad offrire tutti i servizi di investimento; società di gestione del risparmio: possono essere autorizzate dalla Banca d'Italia all'esercizio dell'attività di gestione di portafogli, dell'attività di consulenza e di commercializzazione di fondi comuni o SICAV; banche di Paesi comunitari: possono offrire in Italia i servizi per i quali sono state autorizzate dall'autorità di vigilanza del Paese d'origine; imprese di investimento di Paesi comunitari: possono offrire in Italia i servizi per i quali sono state autorizzate dall'autorità di vigilanza del Paese d'origine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0759", "question": "Perché è importante verificare che l'intermediario sia autorizzato?", "answer": "Quando si entra in contatto con un intermediario è bene verificare che sia autorizzato. Intrattenere rapporti con soggetti che operano abusivamente potrebbe portare a brutte sorprese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0760", "question": "Quali principi e regole di condotta devono rispettare gli intermediari?", "answer": "Gli intermediari devono rispettare principi e regole di condotta, il cui fine è quello di favorire i propri clienti nell'effettuare scelte di investimento informate, consapevoli e rispondenti alle loro esigenze. Gli intermediari, quindi, per servire al meglio gli interessi dei propri clienti devono operare con: diligenza, ossia in maniera professionalmente adeguata; correttezza, ossia comportarsi con lealtà, senza secondi fini oltre quello dell'interesse del cliente e rispettando tutte le prescrizioni; trasparenza, ossia rendendo al cliente tutte le informazioni importanti in relazione al servizio prestato e agli strumenti finanziari offerti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0761", "question": "Cosa significa che gli intermediari devono valutare l'adeguatezza e l'appropriatezza di un investimento?", "answer": "Gli intermediari devono valutare che l'investimento proposto sia adeguato, cioè se corrisponde ai nostri obiettivi di investimento, se pone a nostro carico rischi non sopportabili o che comunque non siamo in grado di comprendere. La valutazione di adeguatezza è prevista solo per i servizi di consulenza in materia di investimenti e di gestione di portafogli. Devono inoltre valutare se l'investimento è appropriato, cioè se siamo in grado, in base alle nostre conoscenze ed esperienza, di comprenderne i rischi. La valutazione di appropriatezza deve essere fatta per tutti i servizi di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0762", "question": "Perché l'intermediario deve conoscere il cliente prima di instaurare il rapporto?", "answer": "L'intermediario può valutare se un investimento è adeguato o appropriato solo se ci conosce. E per farlo, prima di instaurare il rapporto ci sottoporrà un questionario per acquisire informazioni in merito alla nostra conoscenza ed esperienza in materia di investimenti, alla nostra situazione finanziaria e ai nostri obiettivi di investimento, cioè per quanto tempo vogliamo investire il nostro denaro, la nostra propensione al rischio e le finalità per cui investiamo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0763", "question": "Qual è il suggerimento per i clienti riguardo al questionario dell'intermediario?", "answer": "Il suggerimento è di fornire senza esitazioni e diffidenza le informazioni richieste. Solo così ci potrà essere reso un servizio efficace.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento"}},
{"id": "chunk_0764", "question": "Che cos'è l'inflazione?", "answer": "L'inflazione è un aumento generalizzato del livello dei prezzi di beni e servizi per un certo periodo di tempo. In presenza di inflazione, con la stessa quantità di denaro oggi puoi comprare meno di quanto potevi comprare ieri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0765", "question": "Come fanno le banche centrali a tenere sotto controllo l'inflazione?", "answer": "Per tenere sotto controllo l'inflazione, le banche centrali aumentano i tassi di interesse che applicano ai prestiti concessi alle banche commerciali. Queste ultime a loro volta applicano tassi più alti ai propri clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0766", "question": "Su cosa può avere conseguenze l'inflazione?", "answer": "L'inflazione può avere conseguenze su: i tuoi prestiti; i tuoi risparmi; i tuoi investimenti finanziari; i tuoi piani pensionistici; le tue assicurazioni; qualsiasi altro prodotto finanziario tu possieda.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0767", "question": "Qual è l'effetto dell'aumento dei tassi di interesse sui nuovi prestiti?", "answer": "Quando i tassi di interesse salgono, il costo del denaro che prendi in prestito aumenta: probabilmente pagherai tassi di interesse più alti sui nuovi prestiti, e probabilmente potrai permetterti di prendere in prestito somme minori rispetto a prima.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0768", "question": "Da cosa dipende l'effetto dell'inflazione sui prestiti che ho già in essere?", "answer": "L'effetto sui finanziamenti in essere può variare a seconda che il tasso di interesse sui tuoi prestiti sia fisso o variabile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0769", "question": "Che effetto può avere l'inflazione sui miei risparmi?", "answer": "I tuoi risparmi potrebbero aumentare a causa dell'interesse che la banca ti corrisponderà sui depositi a risparmio. Tuttavia, questi risparmi ti consentiranno di comprare più che in passato soltanto se il tasso di interesse reale è positivo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0770", "question": "Perché devo considerare l'inflazione nella mia strategia di investimento?", "answer": "Nella tua strategia di investimento è bene tener conto dell'inflazione. L'inflazione riduce i rendimenti reali degli investimenti finanziari ed erode il tuo potere d'acquisto. In altre parole, nel momento in cui avrai necessità di liquidare i tuoi investimenti, questi potrebbero aver perso valore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0771", "question": "L'inflazione ha lo stesso effetto su tutti gli strumenti finanziari?", "answer": "L'inflazione può avere conseguenze diverse sui diversi tipi di strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0772", "question": "Che effetto ha l'inflazione sulle assicurazioni e sui piani pensionistici?", "answer": "L'inflazione può avere conseguenze sul costo della tua assicurazione (il premio), la tua copertura e i tuoi rimborsi. Il rischio dell'inflazione permarrà quando sarai in pensione. Indipendentemente da quanti contributi avrai versato, la tua pensione potrebbe non adeguarsi al tasso di inflazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0773", "question": "Cosa dovrei fare con le mie spese in periodi di alta inflazione?", "answer": "Con l'inflazione aumenta il costo della vita, perciò è bene controllare se è il caso di rivedere le tue spese. Fallo prima di prendere qualsiasi decisione finanziaria. Questo ti aiuterà a pianificare meglio le tue finanze e a utilizzare in modo efficiente le tue entrate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0774", "question": "Quali suggerimenti posso seguire per fare un semplice budget?", "answer": "Di seguito alcuni suggerimenti per fare un semplice budget: fai un elenco delle tue entrate e uscite mensili/annuali; controlla l'estratto conto della tua banca e delle tue carte di debito e di credito. Non dimenticare di includere le spese occasionali (es. per la riparazione dell'auto) e di tenere dei soldi da parte per spese impreviste (es. per riparare un elettrodomestico rotto).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0775", "question": "Come posso ordinare le mie spese secondo la priorità?", "answer": "Quando sei consapevole di tutte le tue entrate e uscite, puoi calcolare il tuo saldo e verificare di avere abbastanza per poter pagare tutte le tue spese e mettere qualcosa da parte. A questo punto, quando predisponi il budget, per prima cosa stabilisci le tue priorità finanziarie: mutuo/affitto, gas/elettricità, cibo, bollette, ecc. In secondo luogo, verifica in che modo puoi pagare le tue spese aggiuntive (es. scegliendo alternative più convenienti) e come puoi ridurle, se necessario e possibile. Considera sempre per prime le spese prioritarie e poi pianifica se e come spendere il resto delle tue entrate. Usa la domiciliazione dei pagamenti per le spese fisse. Cerca sempre di spendere meno di quanto guadagni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0776", "question": "Perché devo fare attenzione alle commissioni dei prodotti finanziari?", "answer": "Molti prodotti finanziari come carte di credito, conti bancari e prodotti assicurativi, hanno delle spese. Alcune sono inevitabili, ma verifica se altre possono essere ridotte o evitate. Ad esempio, chiedi sempre alla tua banca le varie tariffe disponibili e quali spese si applicano al tuo conto bancario. Analogamente, se hai fatto investimenti come ad esempio nei fondi di investimento (es. gli OICVM, cioè gli Organismi d'Investimento Collettivo in Valori Mobiliari), confronta sempre i costi per vedere se esistono alternative più a buon mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0777", "question": "Perché dovrei chiedere consiglio per adeguare i miei piani finanziari?", "answer": "È possibile che tu abbia dubbi su come gestire le tue finanze in periodi di alta inflazione. Non esitare a contattare un consulente finanziario autorizzato. Può aiutarti a prendere decisioni più consapevoli, ma anche a sviluppare un approccio personalizzato alla gestione delle tue finanze. Ad esempio, per considerare l'eventuale necessità di aggiornare il tuo profilo e l'adeguatezza dei tuoi investimenti; o, se decidessi di estinguere il contratto di assicurazione sulla vita in anticipo, per evitare di pagare penali eccessive.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0778", "question": "Cosa dovrei fare se ho difficoltà a ripagare le rate di un prestito?", "answer": "Se hai difficoltà a ripagare le rate di un prestito, contatta la tua banca o il tuo istituto di credito quanto prima per trovare una soluzione e approfittare della consulenza sul debito. Questo potrebbe risparmiarti penali per ritardi nei pagamenti e aiutarti ad evitare interessi di mora/arretrati e pignoramenti. Potrebbe anche evitarti di incorrere in restrizioni al credito in caso di richiesta di nuovi prestiti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0779", "question": "Perché dovrei seguire i movimenti dei tassi di interesse delle banche centrali?", "answer": "Le banche centrali spesso alzano i tassi d'interessi per contrastare l'alta inflazione. Se hai contratto un prestito a tasso variabile, questi rialzi faranno aumentare il valore degli interessi che dovrai restituire. Tenerti aggiornato sugli annunci delle banche centrali ti preparerà ai potenziali cambiamenti alle rate che ripagherai.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0780", "question": "Cosa comportano l'alto livello di inflazione e l'aumento dei tassi di interesse per i nuovi prestiti?", "answer": "L'alta inflazione e l'aumento dei tassi di interesse possono rendere più costoso e meno accessibile prendere denaro a prestito. Nei periodi di alta inflazione c'è un aumento generalizzato dei prezzi di beni e servizi. Le banche centrali di solito aumentano i tassi di interesse per contrastare l'inflazione e questo ha conseguenze per i tassi di interesse applicati dalle banche commerciali ai tuoi prestiti. Questo significa che dovrai fare più attenzione nel gestire i tuoi soldi ed evitare di contrarre debiti al di là delle tue possibilità finanziarie. Assicurati di avere sempre denaro a sufficienza per ripagare le rate del tuo prestito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0781", "question": "Perché un acquisto importante costa di più in periodi di alta inflazione?", "answer": "Se devi sostenere una spesa importante, ad esempio acquistare un'automobile, questa ti costerà di più poiché i prezzi delle automobili saranno più alti. Se poi hai bisogno di un finanziamento per l'acquisto, dovrai contrarre un prestito per un valore maggiore e pagare più interessi. Inoltre, potresti avere più difficoltà a ottenere un prestito da una banca e a ripagarlo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0782", "question": "Che effetto hanno inflazione e aumento dei tassi sui prestiti a tasso variabile?", "answer": "L'inflazione e l'aumento dei tassi di interesse rendono più costosi i tuoi prestiti a tasso variabile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0783", "question": "Che differenza c'è tra prestiti a tasso fisso e a tasso variabile in caso di inflazione?", "answer": "L'effetto di un'alta inflazione e dell'aumento dei tassi di interesse su prestiti come mutui, finanziamenti per l'acquisto di beni o prestiti personali varia in base al tipo di tasso di interesse: tasso fisso o variabile. Se hai contratto un prestito a tasso fisso, significa che hai concordato con la banca un tasso di interesse stabile per un dato periodo di tempo. Quando i tassi di mercato salgono, il tasso di interesse sul tuo prestito rimane lo stesso e le tue rate non aumentano. Se hai contratto un prestito a tasso variabile, il tasso di interesse sul tuo prestito salirà o scenderà con i tassi di mercato. Quando l'inflazione è alta, i tassi di interesse delle banche potrebbero salire. Di conseguenza, salirà anche il tasso di interesse sul tuo prestito e l'ammontare delle rate che pagherai sarà più alto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0784", "question": "Che conseguenze hanno inflazione e aumento dei tassi di interesse per i miei risparmi?", "answer": "L'inflazione potrebbe avere un impatto positivo sui tuoi risparmi, ma fa' attenzione al tasso di interesse reale. Se hai dei risparmi in contanti, il loro valore non crescerà né diminuirà. Tuttavia, in periodi di alta inflazione, il tuo potere d'acquisto diminuirà. Ciò significa che non potrai acquistare tutto quello che avresti potuto comprare prima con la stessa somma di denaro, perché i beni sono più costosi. D'altra parte, se tieni il tuo denaro in un deposito a risparmio, in linea di principio, i tuoi risparmi dovrebbero accrescersi, dal momento che le banche pagano interessi più alti sui depositi a risparmio. Tuttavia, i benefici apportati dall'aumento dei tassi di interesse in un periodo di alta inflazione non implicano necessariamente che gli interessi che la banca paga sui tuoi risparmi saranno alti. Ricorda che il rendimento del deposito è spesso inferiore al tasso d'inflazione, per cui il tasso di interesse effettivo potrebbe non essere sempre positivo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0785", "question": "Quali strategie posso adottare per gestire l'effetto dell'alta inflazione sui miei prestiti e risparmi?", "answer": "Confronta sempre i tassi di interesse. Confronta le varie opzioni di prestito facendo attenzione al Tasso Annuo Effettivo Globale (TAEG), che indica il tasso annuale applicato a un finanziamento e comprende tutte le spese e i costi aggiuntivi. Tieni d'occhio i tassi di interesse sui tuoi risparmi e confronta varie opzioni, in modo da gestire i tuoi risparmi in modo proattivo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0786", "question": "Perché devo verificare la tutela dei depositi?", "answer": "Verifica che i tuoi risparmi siano depositati in una banca autorizzata nell'Unione Europea, il che ti dà diritto alla tutela dei depositi fino a 100.000 euro a persona nel caso in cui la tua banca fallisca.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0787", "question": "Cosa devo valutare quando contraggo un nuovo prestito in periodi di alta inflazione?", "answer": "Quando contrai un nuovo prestito, valuta i pro e i contro dei finanziamenti a tasso fisso o variabile per scegliere l'opzione migliore per te.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0788", "question": "Quali sono le caratteristiche dei finanziamenti a tasso fisso?", "answer": "Un prestito a tasso fisso sarà probabilmente più costoso al momento della stipula, e potrebbe vincolarti per un lungo periodo. Tuttavia, se i tassi di interesse salgono, la tua rata mensile rimarrà la stessa. L'aspetto positivo è che se i tassi di interesse di mercato calano nettamente, puoi scegliere di rinegoziare il finanziamento o trasferirlo a un'altra banca o istituto di credito, per ottenere condizioni di prestito e di pagamento più favorevoli. Ricorda che per rinegoziare il finanziamento serve il consenso della banca, che potrebbe addebitarti delle commissioni e altre spese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0789", "question": "Quali sono le caratteristiche dei finanziamenti a tasso variabile?", "answer": "Se contrai un prestito a tasso variabile, considera attentamente gli effetti di possibili aumenti futuri dei tassi sulle tue rate mensili. Chiedi alla tua banca o istituto di credito a quanto ammonterebbero le tue rate mensili se i tassi di interesse salissero (ad es. se il tasso di interesse passasse dal 2%'%' al 3%). Potresti ancora permetterti di pagare le rate?", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0790", "question": "Perché è importante prestare attenzione al rischio di sovraindebitamento?", "answer": "In un periodo di alta inflazione, prima di contrarre un prestito considera quanto impatteranno le rate per ripagarlo sul tuo budget mensile/annuale, e se sarà necessario ridurre altre spese (ove possibile). Verifica la tua capacità di ripagare i debiti, non prendere in prestito più di quanto puoi permetterti, e contrai solo finanziamenti che sai di poter ripagare. Se ti rendi conto di avere problemi a ripagare dei finanziamenti, contatta al più presto la tua banca o istituto di credito per cercare possibili soluzioni. Agire in questo modo può aiutarti a evitare di pagare interessi di mora per pagamenti tardivi e di avere problemi a ottenere prestiti in futuro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0791", "question": "Come deve comportarsi un investitore rispetto all'inflazione?", "answer": "Devi tenere conto dell'inflazione nella definizione della tua strategia di investimento. L'inflazione riduce i rendimenti reali degli investimenti finanziari ed erode il tuo potere d'acquisto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0792", "question": "Come si calcola il rendimento reale di un investimento in presenza di inflazione?", "answer": "Lo strumento finanziario X ha un rendimento nominale del 3%'%' al lordo dell'inflazione. Se l'inflazione è del 5%, il rendimento reale è negativo (-2%) e il potere d'acquisto del capitale investito si riduce del 2%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0793", "question": "L'inflazione ha lo stesso impatto su tutte le azioni?", "answer": "L'impatto dell'inflazione e dell'aumento dei tassi di interesse sul mercato azionario non è di immediata comprensione. L'aumento generale dei prezzi di beni e servizi può avere un impatto sugli utili delle imprese, influenzando così positivamente o negativamente il prezzo delle loro azioni sul mercato. Per gli investitori al dettaglio questo non è facilmente prevedibile, poiché l'inflazione non avrà lo stesso impatto sui prezzi delle azioni di ogni singola impresa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0794", "question": "Che impatto ha l'inflazione sugli strumenti finanziari a cedola fissa?", "answer": "È possibile che tu possieda strumenti finanziari con tassi cedolari fissi. Molte obbligazioni governative o societarie rientrano in questa categoria. In tal caso riceverai: un pagamento periodico fisso fino alla data di scadenza dello strumento (cedola); e il rimborso dell'investimento iniziale (valore nominale) alla scadenza. L'inflazione ha un impatto su questi investimenti. Alla scadenza, l'importo ricevuto sarà lo stesso durante i cicli inflazionistici, ma il potere d'acquisto di questo importo si riduce. In altre parole, in caso di inflazione, con lo stesso importo potrai comprare meno cose.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0795", "question": "Puoi fornire un esempio dell'effetto dell'inflazione su un'obbligazione a cedola fissa?", "answer": "Supponiamo che un'obbligazione a tre anni paghi 1.000 euro ogni anno. L'inflazione fa sì che, al terzo anno, 1.000 euro ti consentono di acquistare meno cose rispetto al primo e al secondo anno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0796", "question": "Che impatto ha l'inflazione sugli strumenti finanziari a cedola variabile?", "answer": "Potresti avere strumenti finanziari a cedola variabile, come le obbligazioni a tasso variabile. In tal caso riceverai: un pagamento periodico variabile fino alla data di scadenza dello strumento (cedola); e il rimborso dell'investimento iniziale (valore nominale) alla scadenza. Il valore della cedola periodica è variabile, in funzione di vari fattori (ad esempio, può essere legato all'andamento dei tassi d'interesse, dell'inflazione, ecc.). L'inflazione ha un impatto sul rimborso ricevuto a scadenza, che sarà lo stesso durante i cicli inflazionistici, ma il potere d'acquisto di questo importo si riduce. La cedola periodica varia e può essere in grado di controbilanciare (in tutto o in parte) l'effetto dell'inflazione. Tuttavia, non è sempre detto che le variazioni del tasso cedolare riflettano il livello attuale dei tassi di interesse, né che compensino il tasso di inflazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0797", "question": "Che impatto ha l'inflazione sui fondi comuni di investimento?", "answer": "L'investimento in fondi comuni dà accesso a un portafoglio composto da diversi strumenti finanziari. L'impatto dell'inflazione e dell'aumento dei tassi d'interesse sui fondi d'investimento dipende dal tipo di fondo e dalla composizione del suo portafoglio d'investimento, ossia, ad esempio, dalle tipologie di strumenti o dal settore d'attività in cui il fondo investe.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0798", "question": "Quali passi posso compiere per gestire l'impatto dell'inflazione sui miei investimenti finanziari?", "answer": "Quando confronti le opportunità di investimento o analizzi i rischi e i benefici potenziali di uno strumento finanziario: prendi sempre in considerazione il rischio di inflazione e il possibile effetto che può avere sul valore reale e sul rendimento reale dell'investimento; tieni presente che il rischio di inflazione si aggiunge ai normali costi dell'investimento in prodotti finanziari, come le commissioni di entrata e uscita, i costi di transazione, ecc. Confronta i costi dei tuoi investimenti finanziari e verifica se esistono alternative meno costose. Valuta i costi complessivi e i rendimenti reali netti (ossia al netto dei costi totali e dell'inflazione) o chiedi al tuo consulente finanziario informazioni al riguardo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0799", "question": "Perché è utile diversificare gli investimenti in periodi di inflazione?", "answer": "Tieni sempre a mente i principi fondamentali dell'investimento: mantenere un portafoglio ben diversificato; assicurarsi che gli investimenti rimangano allineati con i propri obiettivi. La diversificazione dei tipi di strumenti detenuti in un portafoglio d'investimento può generare un rendimento sufficientemente elevato da controbilanciare l'impatto dell'inflazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0800", "question": "Quali strumenti possono aiutare a coprire il rischio d'inflazione in un portafoglio bilanciato?", "answer": "Portafogli bilanciati che comprendono fondi d'investimento, azioni e obbligazioni possono aiutare a coprire il rischio d'inflazione: le azioni sono soggette a rischi e variabilità maggiori rispetto alle obbligazioni, ma in genere offrono rendimenti attesi più elevati sebbene, come spiegato in precedenza, gli effetti dell'inflazione su tali rendimenti non sono prevedibili; le obbligazioni possono essere influenzate in maniera più diretta dall'inflazione e dai conseguenti aumenti dei tassi di interesse, ma il loro prezzo è meno volatile di quello delle azioni; investire in fondi comuni di investimento, come gli Organismi di Investimento Collettivo in Valori Mobiliari (OICVM), potrebbe aiutare a diversificare il portafoglio. Questi strumenti non solo eliminano la necessità di selezionare singole azioni o obbligazioni, ma offrono anche un'esposizione a diverse classi di attività e ai principali settori economici, a seconda della composizione del loro portafoglio di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0801", "question": "Perché dovrei chiedere consiglio per riadattare i miei investimenti?", "answer": "Un consulente finanziario può aiutarti a prendere decisioni più informate. In qualità di investitore, se hai dubbi su come l'inflazione possa influire sui tuoi investimenti finanziari, discutine con un consulente finanziario autorizzato. Durante i periodi di inflazione, potresti contattare un professionista che valuterà la necessità di aggiornare il tuo profilo di investitore e l'adeguatezza dei tuoi investimenti rispetto alle tue caratteristiche e alle tue esigenze.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0802", "question": "Che cosa significa l'inflazione per me come investitore?", "answer": "Devi tenere conto dell'inflazione nella definizione della tua strategia di investimento. L'inflazione riduce i rendimenti reali degli investimenti finanziari ed erode il tuo potere d'acquisto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0803", "question": "Quali effetti possono avere inflazione e aumento dei tassi di interesse sui vari tipi di strumenti finanziari?", "answer": "L'inflazione e l'aumento dei tassi di interesse possono avere effetti diversi sui vari tipi di strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0804", "question": "Che cosa succede al potere d'acquisto dell'importo rimborsato alla scadenza di strumenti a cedola fissa o variabile?", "answer": "Alla scadenza, l'importo ricevuto sarà lo stesso durante i cicli inflazionistici, ma il potere d'acquisto di questo importo si riduce.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0805", "question": "Le variazioni della cedola variabile compensano sempre l'inflazione?", "answer": "La cedola periodica varia e può essere in grado di controbilanciare (in tutto o in parte) l'effetto dell'inflazione. Tuttavia, non è sempre detto che le variazioni del tasso cedolare riflettano il livello attuale dei tassi di interesse, né che compensino il tasso di inflazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0806", "question": "Da cosa dipende l'impatto dell'inflazione sui fondi comuni?", "answer": "L'impatto dell'inflazione e dell'aumento dei tassi d'interesse sui fondi d'investimento dipende dal tipo di fondo e dalla composizione del suo portafoglio d'investimento, ossia, ad esempio, dalle tipologie di strumenti o dal settore d'attività in cui il fondo investe.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0807", "question": "Quali sono i principi fondamentali da ricordare per gestire l'impatto dell'inflazione sugli investimenti?", "answer": "Tieni sempre a mente i principi fondamentali dell'investimento: mantenere un portafoglio ben diversificato; assicurarsi che gli investimenti rimangano allineati con i propri obiettivi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0808", "question": "In che modo la diversificazione può aiutarmi in periodi di inflazione?", "answer": "La diversificazione dei tipi di strumenti detenuti in un portafoglio d'investimento può generare un rendimento sufficientemente elevato da controbilanciare l'impatto dell'inflazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0809", "question": "Quali strumenti possono contribuire alla diversificazione del portafoglio?", "answer": "Portafogli bilanciati che comprendono fondi d'investimento, azioni e obbligazioni possono aiutare a coprire il rischio d'inflazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0810", "question": "Perché è utile consultare un consulente finanziario durante periodi di inflazione?", "answer": "Un consulente finanziario può aiutarti a prendere decisioni più informate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0811", "question": "Cosa può fare un consulente finanziario se ho dubbi sull'effetto dell'inflazione sui miei investimenti?", "answer": "In qualità di investitore, se hai dubbi su come l'inflazione possa influire sui tuoi investimenti finanziari, discutine con un consulente finanziario autorizzato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0812", "question": "Quale impatto ha l'inflazione sulla mia assicurazione e sulla mia pensione privata?", "answer": "L'inflazione può avere un impatto sulla tua situazione finanziaria e ridurre il tuo potere d'acquisto ora e nel lungo termine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0813", "question": "Perché devo considerare attentamente le decisioni sui miei prodotti assicurativi durante l'inflazione?", "answer": "Prenditi del tempo per considerare le opzioni a tua disposizione prima di prendere decisioni importanti sui tuoi prodotti assicurativi (ad es.: sospendere temporaneamente i pagamenti periodici relativi al tuo piano pensionistico o al tuo prodotto assicurativo sulla vita, non rinnovare un prodotto assicurativo scaduto o riscattare anticipatamente un prodotto di investimento assicurativo) perché queste decisioni possono anche avere un impatto sulla tua situazione finanziaria attuale e futura.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0814", "question": "Perché è importante avere una visione completa delle polizze assicurative?", "answer": "È importante avere una visione completa delle polizze assicurative sottoscritte e di cosa coprono, prima di prendere decisioni in merito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0815", "question": "Il premio è l'aspetto più importante di un prodotto assicurativo?", "answer": "Tieni presente che il premio del prodotto assicurativo non è necessariamente il fattore più importante.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0816", "question": "Perché dovrei chiedere una consulenza sui miei prodotti assicurativi?", "answer": "Prendi in considerazione la possibilità di chiedere una consulenza. In effetti, chiedere una consulenza sul tuo prodotto assicurativo può aiutarti a considerare le tue esigenze attuali e future nonché le potenziali conseguenze di una decisione (ad es. valutare le penalità in caso di riscatto anticipato, una copertura non adeguata per la tua casa/auto).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0817", "question": "In che modo l'inflazione può influire sulla mia assicurazione sulla vita o sulla pensione privata?", "answer": "L'inflazione può significare che i tuoi investimenti sono meno redditizi per te.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0818", "question": "Come può l'inflazione influenzare il mio reddito disponibile?", "answer": "L'inflazione può portarti ad avere un reddito disponibile inferiore ora o in futuro in base ai rendimenti dei tuoi investimenti o della tua pensione privata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0819", "question": "Perché la mia pensione privata potrebbe non essere adeguata in futuro?", "answer": "Quando smetti di lavorare o vai in pensione, l'importo che hai risparmiato nel tuo fondo pensione, indipendentemente da quanto tempo hai contribuito, potrebbe not essere adeguato al tasso di inflazione: il tuo potere d'acquisto potrebbe quindi ridursi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0820", "question": "Cosa succede se riscatto anticipatamente la mia assicurazione sulla vita o interrompo i pagamenti?", "answer": "Se decidi di riscattare la tua assicurazione sulla vita anticipatamente o interrompere temporaneamente il pagamento di un premio regolare o di un prodotto di risparmio, a causa delle tue esigenze finanziarie momentanee, potresti dover pagare penali e potresti avere un reddito o un capitale inferiori quando vai in pensione o ottenerli in un momento della tua vita successivo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0821", "question": "In che modo l'inflazione può influire sui prodotti assicurativi danni come l'assicurazione sulla casa?", "answer": "L'inflazione può influire sui costi (il tuo premio), sulla tua copertura e sul risarcimento che ricevi in caso di sinistro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0822", "question": "Perché il premio della mia assicurazione auto potrebbe aumentare con l'inflazione?", "answer": "Per esempio, da un anno all'altro, il tuo premio sull'assicurazione auto può significativamente aumentare a causa degli aumenti dei costi per le riparazioni delle auto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0823", "question": "In che modo l'inflazione può influire sull'assicurazione sulla casa?", "answer": "In alcuni casi, come l'assicurazione sulla casa, l'inflazione potrebbe avere un impatto diretto perché il risarcimento per eventuali perdite coperte dalla tua polizza potrebbe not essere sufficiente a coprire il costo dei materiali per le riparazioni o la ricostruzione dopo un sinistro. Il rimborso della tua polizza potrebbe not essere sufficiente per ricostruire tutta o parte della tua casa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0824", "question": "Qual è il primo passo per affrontare l'impatto dell'inflazione sui miei prodotti assicurativi e pensionistici privati?", "answer": "Per tutti i tipi di prodotti assicurativi e pensionistici privati, evita di prendere decisioni affrettate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0825", "question": "Perché non dovrei prendere decisioni affrettate sui miei prodotti assicurativi?", "answer": "Evita che un aumento contingente dei prezzi determini le tue decisioni sull'opportunità di stipulare contratti assicurativi, importanti per le tue esigenze primarie, come l'assicurazione sulla casa. A volte, non sottoscrivere la polizza può portare a conseguenze più rischiose di quanto avresti potuto prevedere. Quindi non limitarti a confrontare i prezzi. Trova la polizza adeguata alle tue esigenze. Prima di prendere una decisione importante sui tuoi prodotti assicurativi, valuta di rivolgerti al tuo consulente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0826", "question": "Perché non dovrei ridurre ora i contributi alla pensione privata?", "answer": "Le pensioni private hanno un orizzonte a lungo termine. Tieni presente che risparmiare ora per avere un reddito più alto nell'immediato, significa avere una pensione più bassa in futuro, che potrebbe not corrispondere alle tue esigenze nel periodo di ritiro dal lavoro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0827", "question": "Qual è il secondo passo per gestire i prodotti assicurativi e pensionistici privati durante l'inflazione?", "answer": "Per i prodotti assicurativi sulla vita e le pensioni private, adotta una prospettiva di lungo periodo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0828", "question": "Perché devo adottare una prospettiva di lungo periodo?", "answer": "Non dovresti guardare solo all'impatto a breve termine dell'inflazione elevata, ma considerare anche che nel lungo periodo la situazione potrebbe cambiare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0829", "question": "Perché una polizza vita richiede una prospettiva di medio-lungo periodo?", "answer": "È importante tenere presente che una polizza vita è un prodotto di investimento assicurativo che viene normalmente acquistato con una prospettiva di investimento di medio-lungo periodo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0830", "question": "Quali decisioni dovrei evitare per via dell'attuale tasso di inflazione?", "answer": "Non prendere decisioni affrettate basate solo sull'attuale tasso di inflazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0831", "question": "Perché il valore dei miei investimenti può cambiare nel tempo?", "answer": "Il valore di alcuni investimenti può variare nel tempo a causa dei frequenti cambiamenti nei mercati finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0832", "question": "Il valore attuale di una polizza vita è garantito nel tempo?", "answer": "Tieni presente che il valore di oggi potrebbe non essere il valore di domani.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0833", "question": "Cosa devo sapere se chiedo una consulenza per una polizza vita o un investimento assicurativo?", "answer": "Se ti rivolgi a un consulente per una consulenza, tieni presente quanto segue: Il consulente è tenuto per legge ad agire sempre in modo onesto, equo e professionale perseguendo il tuo migliore interesse. Il consulente dovrebbe aiutarti a fare una scelta informata quando acquisti una polizza assicurativa sulla vita o quando investi più denaro in una polizza esistente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0834", "question": "Cosa dovrei chiedere se sto pensando di acquistare una rendita vitalizia?", "answer": "Se ti stai già avvicinando alla pensione e stai pensando di acquistare una rendita vitalizia, chiedi se è disponibile una rendita legata all'inflazione, che proteggerà la tua rendita dall'inflazione. Questo prodotto inizialmente avrà un tasso molto più basso ma ti aiuterà a evitare qualsiasi rischio inflazionistico futuro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0835", "question": "Cosa devo chiedere al consulente se mi consiglia di investire in diversi tipi di attività?", "answer": "Se ti viene consigliato di investire in una gamma di diversi tipi di attività per ottenere rendimenti più elevati e battere l'inflazione elevata, chiedi al tuo consulente il tipo di commissioni che devi pagare e quali sono i rischi dell'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0836", "question": "Qual è il terzo passo per affrontare l'impatto dell'inflazione sui prodotti assicurativi?", "answer": "Adatta la copertura per i prodotti danni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0837", "question": "Come posso risparmiare senza rinunciare alla mia polizza assicurativa?", "answer": "Se hai bisogno di risparmiare, piuttosto che decidere di non rinnovare una polizza esistente, potresti considerare di: Scegliere solo la copertura più essenziale. Aumentare l'importo della franchigia della polizza (questa è la somma di denaro che resta a tuo carico per il costo complessivo di qualsiasi sinistro). Verificare se sei già coperto per lo stesso rischio da una polizza diversa (incluse le carte di credito).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0838", "question": "Cosa dovrei fare prima di scegliere una nuova polizza assicurativa?", "answer": "Guardati intorno sul mercato e confronta le quotazioni di diversi fornitori di assicurazioni, ma fai attenzione a non decidere solo in base al prezzo. Verifica le tipologie di copertura offerte.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-inflazione"}},
{"id": "chunk_0839", "question": "Cosa sono le azioni?", "answer": "Le azioni sono le singole parti unitarie in cui è diviso il capitale delle società per azioni. Il titolare di un'azione, quindi, possiede un pezzetto della società, con tutti i diritti e gli oneri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0840", "question": "Le azioni sono un titolo di credito?", "answer": "Le azioni sono anche un titolo di credito, cioè uno strumento che incorpora un diritto e ne facilita la trasmissione ad altri soggetti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0841", "question": "Qual è la differenza tra azioni quotate e non quotate?", "answer": "Le azioni possono essere quotate o non quotate. Nel primo caso è più facile acquistarle o venderle ad un prezzo di mercato. Le azioni non quotate, invece, possono presentare grossi problemi al momento della vendita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0842", "question": "Perché le società emettono azioni?", "answer": "Attraverso l'emissione e il collocamento delle azioni, le società per azioni finanziano la propria attività.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0843", "question": "L'azionista è un socio o un creditore della società?", "answer": "L'azionista è un socio, e non un creditore, della società e quindi partecipa all'attività economica della società stessa sopportandone i rischi in caso di perdite. Rischi, peraltro, che sono limitati al valore delle azioni possedute.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0844", "question": "Quali sono i diritti dell'azionista?", "answer": "I diritti dell'azionista sono: la percezione dei dividendi, se distribuiti dalla società; la possibilità di esprimere il proprio voto nelle assemblee; la possibilità di consultare determinati libri sociali; la possibilità di impugnare le delibere assembleari invalide.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0845", "question": "Le azioni hanno sempre lo stesso valore e gli stessi diritti?", "answer": "Di norma le azioni hanno uguale valore (valore nominale) e uguali diritti. Tuttavia, le società, nello statuto, possono prevedere diverse categorie di azioni, con diritti amministrativi ed economici differenziati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0846", "question": "Cosa sono le azioni di risparmio?", "answer": "Le azioni di risparmio non danno diritto di voto ma hanno dei privilegi di natura economica in genere riferiti alla distribuzione dividendi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0847", "question": "Cosa sono le azioni privilegiate?", "answer": "Le azioni privilegiate generalmente prevedono una prevalenza nella distribuzione dei dividendi a fronte della limitazione del diritto di voto alle sole assemblee straordinarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0848", "question": "Cosa sono le azioni a voto plurimo?", "answer": "Le azioni a voto plurimo prevedono la possibilità, per le società non quotate, di creare statutariamente azioni con diritto di voto plurimo. Anche le società quotate possano avere azioni a voto plurimo nel caso in cui tale categoria fosse già presente prima della quotazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0849", "question": "Cosa sono le azioni a voto maggiorato?", "answer": "Gli statuti delle società quotate possono prevedere che sia attribuito un voto maggiorato, fino a un massimo di due voti, per ciascuna azione appartenente al medesimo soggetto per un periodo continuativo non inferiore a due anni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0850", "question": "Dove si negoziano le azioni?", "answer": "Il luogo dove sono negoziati i titoli azionari è il mercato azionario. I mercati operanti in Italia possono essere suddivisi in tre categorie: Mercati regolamentati; Sistemi multilaterali di negoziazione (MTF); Internalizzatori sistematici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0851", "question": "Qual è il principale mercato regolamentato azionario in Italia?", "answer": "Il più importante mercato regolamentato azionario è gestito da Borsa Italiana s.p.a.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0852", "question": "Chi può acquistare o vendere azioni?", "answer": "Le persone fisiche o anche le società che vogliono compravendere titoli devono rivolgersi ad intermediari autorizzati, cioè essenzialmente banche e società di intermediazione mobiliare - SIM, i quali inseriranno per loro conto nei sistemi di negoziazione gli ordini di acquisto e vendita di azioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-azioni"}},
{"id": "chunk_0853", "question": "In quale contesto tecnologico ed economico nascono le criptovalute secondo il testo?", "answer": "Le nuove tecnologie, favorite dai progressi della crittografia - ovvero dell'applicazione di metodi che servono per rendere un messaggio comprensibile/intelligibile solo a persone autorizzate a leggerlo - e dalle evoluzioni della rete internet, stanno determinando un cambiamento radicale nell'economia globale, con particolare riferimento al settore finanziario, sotto il profilo delle modalità di scambio di beni, servizi e ogni attività finanziaria. Tra le più significative applicazioni della tecnologia digitale al settore finanziario spicca la nascita e la diffusione delle \"criptovalute\" (o \"valute virtuali\"), la più nota delle quali è il bitcoin.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0854", "question": "Che cosa significa il termine criptovaluta secondo il testo?", "answer": "Cos'è una criptovaluta? Il termine si compone di due parole: cripto e valuta. Si tratta quindi di valuta 'nascosta', nel senso che è visibile/utilizzabile solo conoscendo un determinato codice informatico (le cosiddette 'chiavi di accesso' pubblica e privata, in linguaggio ancora più tecnico).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0855", "question": "In quale forma esiste la criptovaluta e come viene generata e scambiata?", "answer": "La criptovaluta non esiste in forma fisica (anche per questo viene definita 'virtuale'), ma si genera e si scambia esclusivamente per via telematica. Non è pertanto possibile trovare in circolazione dei bitcoin in formato cartaceo o metallico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0856", "question": "Come viene adattato il concetto di portafoglio nel contesto delle monete virtuali?", "answer": "Alcuni concetti tradizionalmente utilizzati per le monete a corso legale, come ad esempio quello di 'portafoglio', sono stati adattati anche al contesto delle monete virtuali, dove si parla di 'portafoglio digitale/elettronico' (o wallet digitale/elettronico o semplicemente e-wallet).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0857", "question": "In che modo la criptovaluta può essere scambiata per acquistare beni e servizi?", "answer": "La criptovaluta, ove ci sia consenso tra i partecipanti alla relativa transazione, può essere scambiata in modalità peer-to-peer (ovvero tra due dispositivi direttamente, senza necessità di intermediari) per acquistare beni e servizi (come fosse moneta a corso legale a tutti gli effetti).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0858", "question": "Qual è la classificazione tra moneta virtuale chiusa, unidirezionale e bidirezionale e come viene definito il bitcoin?", "answer": "Un'altra classificazione in uso prevede la suddivisione tra moneta virtuale 'chiusa', 'unidirezionale' e 'bidirezionale'. La differenza tra le tre fattispecie risiede nella possibilità o meno di poter scambiare la criptovaluta con moneta a corso legale (o valuta 'ufficiale' o 'moneta fiat', secondo altre comuni denominazioni) e nella tipologia di beni/servizi acquistabili. Il bitcoin, ad esempio, è una moneta virtuale biridezionale in quanto può essere facilmente convertita con le principali valute ufficiali e viceversa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0859", "question": "Le monete virtuali hanno corso legale e come avviene la loro accettazione come mezzo di pagamento?", "answer": "le monete virtuali non hanno corso legale in quasi nessun angolo del pianeta e dunque l'accettazione come mezzo di pagamento è su base volontaria;", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0860", "question": "Le monete virtuali sono regolate da enti centrali governativi?", "answer": "le monete virtuali non sono regolate da enti centrali governativi, ma sono generalmente emesse e controllate dall'ente emittente secondo regole proprie, a cui i membri della comunità di riferimento accettano di aderire;", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0861", "question": "Quali esempi di Stati che sperimentano l'utilizzo di moneta virtuale vengono riportati nel testo?", "answer": "ci sono Stati che hanno deciso di sperimentare, sotto il proprio controllo, l'utilizzo di moneta virtuale nei propri Paesi (es. l'Uruguay con l'e-peso) o ne hanno annunciato il loro utilizzo senza che però si abbiano maggiori informazioni al riguardo (es. il Venezuela con il Petro) o, ancora, che abbiano in cantiere iniziative al riguardo (es. Estonia e Svezia).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0862", "question": "Quali sono gli elementi costitutivi delle criptovalute secondo il testo?", "answer": "Le criptovalute hanno caratteristiche peculiari che le contraddistinguono. Di seguito sono riportati gli elementi costitutivi: - un insieme di regole (detto \"protocollo\"), cioè un codice informatico che specifica il modo in cui i partecipanti possono effettuare le transazioni; - una sorta di \"libro mastro\" (distributed ledger o blockchain) che conserva immodificabilmente la storia della transazioni; - una rete decentralizzata di partecipanti che aggiornano, conservano e consultano la distributed ledger delle transazioni, secondo le regole del protocollo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0863", "question": "Chi può creare una valuta digitale e cosa sono le ICO?", "answer": "Chiunque può creare una valuta digitale; quindi in qualsiasi momento ci possono essere centinaia o persino migliaia di criptovalute in circolazione. Per creare/distribuire criptovalute si può ricorrere ad una cosiddetta \"initial coin offering\" (ICO). Le prime ICO furono proprio lanciate per raccogliere fondi per nuove criptovalute, mentre in seguito la finalità principale è diventata quella di finanziare direttamente delle idee imprenditoriali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0864", "question": "Come possono essere acquistate o vendute le valute virtuali e quali rischi presentano le piattaforme?", "answer": "Una volta emesse, le valute virtuali possono essere acquistate o vendute su una piattaforma di scambio (cosiddette exchange platform) utilizzando denaro a corso legale (per esempio, EUR, USD, ecc.). Le piattaforme di scambio su cui si acquistano e vendono valute digitali non sono attualmente regolamentate, quindi non è prevista una tutela legale specifica in caso di contenzioso o fallimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0865", "question": "Quali benefici evidenziano i promotori delle criptovalute?", "answer": "Le criptovalute si sottrarrebbero all'azione degli incentivi, potenzialmente controproducenti, tradizionalmente legati alle banche e ai governi sovrani. Le criptovalute offrirebbero molti potenziali vantaggi, tra cui una maggiore velocità ed efficienza nei pagamenti e nelle rimesse estere, promuovendo altresì l'inclusione finanziaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0866", "question": "Perché le valute digitali sono attraenti per i criminali secondo le autorità europee di vigilanza?", "answer": "La natura relativamente anonima delle valute digitali li ha resi molto attraenti per i criminali, che potrebbero utilizzarli per riciclaggio di denaro sporco e altre attività illegali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0867", "question": "Quali rischi per i consumatori e gli investitori vengono evidenziati dalle autorità?", "answer": "Secondo le ricostruzioni delle autorità di settore, le criptovalute possono comportare rischi notevoli anche con riguardo alle truffe. Pongono quindi numerosi interrogativi in termini di protezione dei consumatori/investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0868", "question": "Le criptovalute rappresentano un rischio per la politica monetaria?", "answer": "I rischi per la gestione della politica monetaria sembrano, invece, del tutto improbabili, considerata la loro attuale esigua diffusione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0869", "question": "Quando potrebbero insorgere rischi per la stabilità finanziaria?", "answer": "Quanto ai rischi per la stabilità finanziaria, solo una ben più ampia utilizzazione delle criptovalute potrebbe determinarne l'insorgenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0870", "question": "Quali rischi legali gravano sugli utenti in assenza di un quadro giuridico preciso?", "answer": "L'assenza di un quadro giuridico preciso determina l'impossibilità di attuare un'efficace tutela legale e/o contrattuale degli interessi degli utenti, che possono, pertanto, trovarsi esposti a dover subire ingenti perdite economiche, ad esempio in caso di condotte fraudolente, fallimento o cessazione di attività delle piattaforme on-line di scambio presso cui vengono custoditi i portafogli digitali personali (i cosiddetti e-wallets).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0871", "question": "Quali rischi operativi e di sicurezza riguardano le piattaforme di scambio?", "answer": "In un contesto di assenza di obblighi informativi e di regole di trasparenza, le piattaforme di scambio sono altresì esposte a elevati rischi operativi e di sicurezza: esse, infatti, a differenza degli intermediari autorizzati, non sono tenute ad alcuna garanzia di qualità del servizio, né devono rispettare requisiti patrimoniali o procedure di controllo interno e gestione dei rischi, con conseguente elevata probabilità di frodi ed esposizione al cybercrime.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0872", "question": "Quali ulteriori rischi vengono citati per le criptovalute?", "answer": "Sussistono, inoltre, rischi di controparte, di mercato, di liquidità e di esecuzione. Priva di ogni garanzia è d'altronde la futura possibilità di un'immediata conversione dei bitcoin e delle altre criptovalute in moneta ufficiale a prezzi di mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0873", "question": "Perché la finanza e il settore bancario guardano con diffidenza alle criptovalute?", "answer": "Non è un caso, quindi, che la finanza e il settore bancario guardino con diffidenza e riluttanza alle criptovalute, temendo che siffatte evoluzioni, determinando, in particolare, la possibilità di trasmettere valore senza l'intervento degli intermediari, possano finire per spiazzare il business normalmente svolto dall'industria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0874", "question": "Quali potenziali sviluppi tecnologici e finanziari potrebbero derivare dalla distributed ledger technology?", "answer": "Guardato, tuttavia, come fase primordiale di un più ampio processo di sperimentazione tecnologica e finanziaria, le criptovalute e, più in generale, la distributed ledger technology potrebbero utilmente porre le basi per dar vita a soluzioni capaci di rendere più efficiente o, secondo i più ottimisti, di trasformare radicalmente l'attuale sistema economico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0875", "question": "In che fase si trova lo sviluppo delle risposte regolatorie alle criptovalute?", "answer": "Lo sviluppo di risposte regolatorie efficaci in merito alle criptovalute è ancora in una fase iniziale: si tratta di un ambito difficile da disciplinare, rientrando nella competenza di differenti soggetti pubblici a livello nazionale e operando, al contempo, su scala globale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0876", "question": "Perché molti sistemi di scambio risultano difficili da monitorare?", "answer": "Molti sistemi di scambio sono del tutto opachi e operano al di fuori del sistema finanziario convenzionale, ciò che rende difficile monitorarne l'operatività.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0877", "question": "Quali approcci hanno adottato i vari Paesi nei confronti delle valute virtuali?", "answer": "I regolatori hanno iniziato ad affrontare tali sfide e le risposte fornite al fenomeno sono state molteplici, con una varietà di approcci tra i differenti Paesi. Taluni hanno valutato la possibilità di includere le valute virtuali nel novero di fattispecie già appropriatamente regolate, altri hanno diramato apposite avvertenze ai consumatori o hanno assoggettato a un regime autorizzatorio lo svolgimento di talune delle attività proprie del sistema, altri ancora hanno proibito alle istituzioni finanziarie di negoziare valute virtuali o ne hanno addirittura vietato l'uso, perseguendo penalmente i trasgressori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0878", "question": "Qual è la maturità attuale delle risposte di policy sul tema delle valute virtuali?", "answer": "Si tratta di risposte di policy ancora embrionali rispetto alle sfide poste dalle valute virtuali ed è altamente probabile che, nel prossimo futuro, interverranno ulteriori sviluppi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0879", "question": "Cosa dovrebbe fare il regolatore nelle future regolazioni sulle criptovalute?", "answer": "Sembra, al riguardo, auspicabile che le autorità calibrino i contenuti delle future regolazioni in modo da affrontare adeguatamente i rischi, senza, tuttavia, soffocare oltremodo l'innovazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0880", "question": "Qual è il ruolo degli organismi internazionali nella regolazione delle valute virtuali?", "answer": "Gli organismi internazionali stanno giocando un ruolo importante nell'identificazione e nella valutazione dei rischi posti dalle valute virtuali e potrebbero senz'altro contribuire a facilitare il processo di sviluppo e di affinamento delle politiche regolatorie a livello nazionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0881", "question": "Che cosa si prevede con la diffusione di standard internazionali e best practice?", "answer": "A mano a mano che si acquisirà una certa esperienza in ordine al loro funzionamento, la diffusione di standard internazionali e best practice potrà fornire utili indicazioni sulle misure regolatorie più appropriate da implementare nei diversi campi, promuovendo l'armonizzazione e prevenendo il rischio di strategie di arbitraggio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0882", "question": "Quali settori potrebbero beneficiare di accordi di cooperazione internazionale?", "answer": "Tali standard potrebbero comprendere accordi di cooperazione internazionale in settori quali lo scambio di informazioni e lo svolgimento di indagini nel perseguimento dei reati transfrontalieri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0883", "question": "Le monete a corso legale e le criptovalute assolvono alle stesse funzioni?", "answer": "Sappiamo che alle monete a corso legale vengono solitamente riconosciute le funzioni di unità di conto, di mezzo di pagamento comunemente accettato e di deposito di valore. Può una criptovaluta assolvere alle stesse funzioni? L'elevata volatilità delle criptovalute non consente sicuramente il corretto svolgimento della funzione 'unità di conto': i prezzi delle principali criptovalute sono soggetti a fluttuazioni molto ampie, anche all'interno delle stesse giornate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0884", "question": "Perché è inefficiente prezzare beni e servizi in unità di criptovalute?", "answer": "Quindi è altamente inefficiente, per non dire impossibile, prezzare beni e servizi in unità di criptovalute.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0885", "question": "Come incide il limite alla creazione di nuova criptovaluta sulla funzione di riserva di valore?", "answer": "Per quanto riguarda la funzione di riserva di valore bisogna considerare che, per come sono state progettate, quanto più saranno utilizzate per il pagamento di beni e servizi, tanto più aumenteranno di valore. Questo perchè il numero di unità di criptovaluta che possono essere prodotte è limitato (la creazione di nuova criptovaluta è contenuta e si riduce nel tempo); ne consegue che più transazioni vengono regolate in criptovalute, maggiore sarà il loro valore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0886", "question": "Le criptovalute sono una moneta merce?", "answer": "Infine, esse non sono una moneta merce, ovvero non hanno anche una funzione d'uso, come ad esempio l'oro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0887", "question": "A quale funzione potrebbero assolvere le criptovalute nel prossimo futuro?", "answer": "Potrebbero invece assolvere sempre di più, in un futuro prossimo, ad una funzione di scambio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0888", "question": "Che cos’è un distributed ledger o blockchain secondo il testo?", "answer": "Un distributed ledger o blockchain (quest'ultimo nome è in genere accomunato all'utilizzo del bitcoin e in italiano si traduce letteralmente in 'catena di blocchi') è un registro aperto e distribuito che può memorizzare le transazioni tra due parti in modo sicuro, verificabile e permanente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0889", "question": "Chi sono i partecipanti al sistema basato su blockchain?", "answer": "I partecipanti al sistema vengono definiti 'nodi' e sono connessi tra di loro in maniera distribuita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0890", "question": "Che cosa è un block all’interno della blockchain?", "answer": "Nella sostanza è una lista in continua crescita di record, chiamati block, che sono collegati tra loro e resi sicuri mediante l'uso della crittografia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0891", "question": "Perché i dati contenuti in un blocco sono immutabili?", "answer": "I dati in un blocco sono per loro natura immutabili (non possono essere retroattivamente alterati senza che vengano modificati tutti i blocchi successivi ad esso; per fare ciò, dati la natura del protocollo e lo schema di validazione, servirebbe il consenso della maggioranza della rete).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0892", "question": "Quali costi e tempi richiede il processo di validazione nella Blockchain di Bitcoin?", "answer": "La natura distribuita e il modello cooperativo rendono particolarmente sicuro e stabile il processo di validazione, pur dovendo ricorrere a tempi e costi non trascurabili, in gran parte riferibili al prezzo dell'energia elettrica necessaria per effettuare la validazione dei blocchi (questo nel caso della Blockchain del bitcoin) e alla capacità computazionale necessaria per risolvere complessi calcoli algoritmici (attività che viene comunemente definita come 'mining').", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0893", "question": "Come avviene l’autenticazione delle transazioni nella blockchain?", "answer": "L'autenticazione avviene tramite la collaborazione di massa ed è alimentata da interessi della comunità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0894", "question": "Che cosa rappresenta la Blockchain nel sistema Bitcoin?", "answer": "La Blockchain è un registro pubblico delle transazioni Bitcoin in ordine cronologico. È utilizzata per memorizzare in modo permanente le transazioni Bitcoin e per prevenire il fenomeno del cosiddetto \"double spending\" (per evitare che possa spendere i bitcoin più di una volta nello stesso momento).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0895", "question": "Che cosa contiene ogni blocco della Blockchain?", "answer": "Come già osservato, la Blockchain è un insieme di blocchi fra loro concatenati: ogni blocco è identificato da un codice, contiene le informazioni di una serie di transazione, e contiene il codice del blocco precedente, così che sia possibile ripercorrere la catena all'indietro, fino al blocco originale (una sorta di DNA delle transazioni Bitcoin).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0896", "question": "Chi memorizza la Blockchain nel sistema Bitcoin?", "answer": "Tutti i nodi della rete memorizzano tutti i blocchi e quindi tutta la Blockchain.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0897", "question": "Che cosa identifica una Initial Coin Offering (ICO)?", "answer": "Con tale termine si identifica un meccanismo finalizzato alla raccolta di fondi necessari a finanziare un progetto imprenditoriale, in maniera simile alle \"Initial Public Offering\" (IPO) e all'equity crowdfunding.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0898", "question": "In che cosa le ICO differiscono dalle IPO e dall’equity crowdfunding?", "answer": "A differenza di questi ultimi, l'ICO implica l'emissione di cosiddetti coin o token digitali in luogo di strumenti finanziari tradizionali (es. azioni).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0899", "question": "Come vengono acquistati i token nelle ICO?", "answer": "I token vengono offerti agli investitori che li acquistano contro cash (USD, EUR…) oppure, più spesso, criptovalute (principalmente Bitcoin e Ether).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0900", "question": "Quale tecnologia viene utilizzata per la creazione ed emissione dei token?", "answer": "La creazione, l'emissione ed il trasferimento di token avviene per mezzo della tecnologia \"distributed ledger\" (DLT).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0901", "question": "Quali sono le fasi tipiche del ciclo di vita di una ICO?", "answer": "Il \"ciclo di vita\" di una ICO - nella forma più ricorrente riscontrata sul mercato - riproduce, con alcune spiccate peculiarità, le fasi del processo di finanziamento diretto di una realtà imprenditoriale innovativa di piccole dimensioni e (usualmente) in fase di lancio alla ricerca di investitori: creazione di un progetto 'innovativo' da sviluppare e finanziare; redazione e pubblicazione (sul web) di un documento informativo non standardizzato relativo a emittente, progetto e coin/token (\"white paper\"); utilizzo della blockchain per le fasi di coinvolgimento degli investitori (su mercato primario e, ove previsto, secondario).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0902", "question": "Perché le ICO si sono diffuse rapidamente nel 2017?", "answer": "La mancanza di un quadro regolamentare specifico per tali operazioni (in particolare l'incertezza circa l'applicabilità, almeno per analogia, delle varie discipline in essere, quali ad es. quelle delle securities, dell'offerta al pubblico e dei servizi di investimento) ha favorito una proliferazione massiccia delle ICOs a livello mondiale nel 2017 (per un valore complessivo di circa 5,68 mld. di USD; fonte Coindesk), che è andata di pari passo all'incremento del valore delle principali criptovalute (Bitcoin +1.318'%' e Ether +9.162% vs. USD nel 2017).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0903", "question": "Quali sono i profili di attenzione sollevati dalle ICO per le autorità di supervisione dei mercati finanziari?", "answer": "I profili di attenzione per le autorità di supervisione dei mercati finanziari sollevati dalle ICOs sono molteplici, così come sono numerosi e differenti gli approcci finora seguiti per fornire una prima risposta 'regolamentare' al fenomeno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/criptovalute"}},
{"id": "chunk_0904", "question": "Chi acquista un'obbligazione cosa fa?", "answer": "Chi acquista un'obbligazione versa del denaro a chi l'ha emessa (detto \"emittente\") che lo utilizza per finanziarsi e si impegna a restituirlo alla scadenza ed a pagare un interesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0905", "question": "Chi è l'emittente di un'obbligazione?", "answer": "L'emittente, che beneficia dell'operazione di finanziamento, è, tipicamente, uno Stato, una società privata, una banca ecc.. Dalla sua solidità economica dipende il pagamento degli interessi e la restituzione del capitale investito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0906", "question": "Che cosa indica la scadenza di un'obbligazione?", "answer": "La scadenza individua il termine del prestito obbligazionario, il momento in cui l'emittente dovrà restituire le somme ricevute. Le obbligazioni possono essere a breve, medio e lungo termine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0907", "question": "Che cos'è l'interesse di un'obbligazione?", "answer": "L'interesse, che viene normalmente corrisposto tramite cedole, è il prezzo che l'investitore pretende per prestare il proprio denaro. La sua funzione è duplice: compensare l'acquirente per la rinuncia a una certa somma di denaro e per il rischio a cui si espone, in quanto l'emittente potrebbe non restituire il denaro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0908", "question": "Da cosa è composto il rendimento di un'obbligazione?", "answer": "Il rendimento dell'obbligazione, oltre che dall'interesse, è composto anche dal guadagno in conto capitale (capital gain), che si ha se il titolo è acquistato a un prezzo minore di quello a cui è rimborsato o venduto. Se, al contrario, il titolo viene rimborsato o venduto ad un prezzo minore di quello di acquisto, si ha una perdita in conto capitale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0909", "question": "Cosa riduce il rendimento delle obbligazioni?", "answer": "Il rendimento delle obbligazioni è ridotto, anche in maniera sensibile, dalle commissioni di negoziazione e dalla tassazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0910", "question": "Qual è la prima grande classificazione delle obbligazioni?", "answer": "Esistono moltissimi tipi di obbligazioni. Una prima, grande, classificazione distingue fra: obbligazioni ordinarie, dette anche plain vanilla; obbligazioni strutturate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0911", "question": "Quali sono le due categorie di obbligazioni ordinarie?", "answer": "Le obbligazioni ordinarie possono suddividersi, a loro volta, in due categorie: a tasso fisso, che attribuiscono all'investitore interessi in misura predeterminata; a tasso variabile, il cui interesse non è predeterminato, ma variabile in relazione ai tassi di mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0912", "question": "Perché le obbligazioni a tasso variabile sono considerate più sicure?", "answer": "Le obbligazioni a tasso variabile, a parità di altre condizioni, sono più sicure, in quanto offrono rendimenti sempre in linea con quelli di mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0913", "question": "Da cosa è composta la struttura delle obbligazioni strutturate?", "answer": "Le obbligazioni strutturate sono più complesse e meno facilmente comprensibili. In particolare, la loro \"struttura\" si basa sulla combinazione di due elementi: una componente obbligazionaria ordinaria, che può prevedere o meno il pagamento di cedole periodiche e che assicura la restituzione del valore nominale del titolo; un contratto derivato, che fa dipendere la remunerazione dell'investitore dall'andamento di uno o più parametri finanziari o reali, come ad esempio indici o combinazioni di indici di borsa, azioni, fondi comuni, tassi di cambio o materie prime.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0914", "question": "Cosa bisogna fare prima di acquistare obbligazioni strutturate?", "answer": "Si tratta di prodotti complessi. Prima di acquistarli dobbiamo essere sicuri di averne compreso il funzionamento, struttura, le possibilità di rendimento e i rischi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0915", "question": "Le obbligazioni sono strumenti privi di rischi?", "answer": "Le obbligazioni, come ogni attività finanziaria, comportano dei rischi. E' bene subito affermare che sicurezza e redditività sono di norma concetti opposti: interessi elevati sono la contropartita di rischi altrettanto elevati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0916", "question": "Che cos'è il rischio di interesse?", "answer": "Il rischio di interesse, che riguarda la possibilità che il prezzo del titolo diminuisca a seguito di variazioni dei tassi di interesse. I titoli a tasso fisso, e soprattutto quelli a lunga scadenza, sono maggiormente esposti a questo rischio rispetto ai titoli a tasso variabile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0917", "question": "Perché i titoli a tasso fisso sono esposti al rischio di interesse?", "answer": "I titoli a tasso fisso non possono modificare le cedole e, quindi, per adeguare il loro rendimento ai nuovi livelli dei tassi, si modifica il prezzo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0918", "question": "Come si comportano i titoli a tasso variabile quando cambiano i tassi di interesse?", "answer": "I titoli a tasso variabile adeguano le cedole al nuovo livello dei tassi per cui il prezzo si modifica solo limitatamente (tale modifica dipende dalla velocità e dall'ampiezza con cui avviene l'adeguamento delle cedole).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0919", "question": "Che cos'è il rischio di credito?", "answer": "Il rischio di credito (o rischio emittente), che è legato alla possibilità che l'emittente sia inadempiente, in tutto o in parte, nel pagamento degli interessi e/o del capitale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0920", "question": "Tutti gli emittenti hanno la stessa affidabilità?", "answer": "Sotto questo profilo, esistono titoli di diversa rischiosità, poiché non tutti gli Emittenti hanno la stessa affidabilità. Ad esempio, uno Stato è generalmente più affidabile di una impresa privata e, infatti, il fallimento di uno Stato, anche se possibile, è meno probabile di quello di un'impresa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0921", "question": "Tutte le obbligazioni dello stesso emittente hanno lo stesso rischio?", "answer": "E anche per lo stesso emittente, non tutte le obbligazioni hanno il medesimo rischio. Esistono infatti le obbligazioni subordinate, per le quali il pagamento delle cedole ed il rimborso del capitale, in caso di particolari difficoltà finanziarie dell'emittente, dipendono dalla soddisfazione degli altri creditori non subordinati (o subordinati di livello inferiore).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0922", "question": "Perché non tutte le obbligazioni con la stessa scadenza hanno lo stesso rendimento?", "answer": "La presenza di livelli diversi di merito creditizio spiega perché non tutte le obbligazioni offrono lo stesso rendimento, anche se uguali per scadenza e per tipologia. Il rendimento, infatti, cresce al ridursi dell'affidabilità dell'emittente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0923", "question": "Che ruolo hanno le agenzie di rating?", "answer": "Esistono delle agenzie di rating che misurano l'affidabilità di un emittente assegnando un rating che individua il relativo rischio di credito. Il rating non è altroche un giudizio sulla capacità dell'emittente di far fronte ai suoi impegni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0924", "question": "Che cos'è il rischio di liquidità?", "answer": "Il rischio di liquidità si riferisce alla difficoltà di vendere rapidamente ed economicamente (cioè senza perdite in termini di prezzo) le proprie obbligazioni prima della scadenza. A questo riguardo, i titoli non quotati sono sicuramente meno liquidi di quelli quotate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0925", "question": "Che cos'è il rischio di cambio?", "answer": "Il rischio di cambio che si corre se si investe in titoli denominati in valuta diversa da quella domestica ed è legato alla variabilità del rapporto di cambio tra le due valute.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0926", "question": "Dove possono essere acquistate le obbligazioni?", "answer": "Le obbligazioni - come del resto tutti i titoli - possono essere acquistate sul mercato primario, sottoscrivendoli al momento in cui vengono offerti per la prima volta al pubblico; mercato secondario, cioè acquistandoli \"in borsa\", in un momento successivo alla loro emissione, da chi lo ha già acquistato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0927", "question": "A cosa serve il mercato secondario delle obbligazioni?", "answer": "La presenza di un mercato secondario permette all'investitore, in caso di necessità, di vendere prima della scadenza i propri titoli. In assenza di un mercato secondario l'investitore dovrebbe, con molta probabilità, aspettare la scadenza del titolo per smobilizzare la propria posizione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0928", "question": "Che cosa sono le obbligazioni subordinate?", "answer": "Le obbligazioni subordinate sono titoli in cui il pagamento delle cedole ed il rimborso del capitale, in caso di particolari difficoltà finanziarie dell'emittente, dipendono dalla soddisfazione degli altri creditori non subordinati (o subordinati di livello inferiore). Proprio per questo motivo i titoli subordinati dovrebbero rendere più di un'obbligazione non subordinata dello stesso emittente con simili caratteristiche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0929", "question": "Esistono diversi livelli di subordinazione?", "answer": "È importante tener presente che esistono vari livelli di subordinazione che possono caratterizzare un titolo, ai quali corrispondono diversi livelli di rischio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0930", "question": "Quali sono le principali tipologie di obbligazioni subordinate emesse dalle banche?", "answer": "Di seguito vengono sinteticamente descritte le principali tipologie di obbligazioni subordinate emesse dalle banche, in ordine decrescente di grado di subordinazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0931", "question": "Cosa sono le obbligazioni Lower Tier 2?", "answer": "Si va dai livelli più bassi delle cosiddette Lower Tier 2, che differiscono da un'obbligazione ordinaria solo perché quest'ultima gode di priorità in caso di liquidazione dell'emittente; le cedole (fisse o variabili) vengono sempre pagate alla data prevista e sono bloccate solo in caso di insolvenza. Hanno scadenza compresa fra 5 e 10 anni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0932", "question": "Cosa caratterizza le obbligazioni Tier 3?", "answer": "Allo stesso livello di subordinazione si collocano anche le cosiddette Tier 3, che si caratterizzano però per una scadenza inferiore rispetto alle precedenti (inferiore ai 5 anni).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0933", "question": "Cosa distingue le obbligazioni Upper Tier 2?", "answer": "Al livello successivo troviamo le cosiddette Upper Tier 2, più rischiose rispetto alle precedenti in quanto prevedono la possibilità per l'emittente di bloccare il pagamento delle cedole in caso di profitti insufficienti o in caso di sospensione dei pagamenti di dividendi sulle azioni ordinarie. Tuttavia le cedole bloccate vengono cumulate e corrisposte quando vengono meno le condizioni che hanno determinato la sospensione del pagamento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0934", "question": "Qual è la tipologia di obbligazioni subordinate più rischiosa?", "answer": "Infine, abbiamo le cosiddette Tier 1, la tipologia più rischiosa. Sono titoli senza scadenza, anche se l'emittente ha la facoltà di rimborso anticipato dopo un certo periodo di tempo dall'emissione (10 anni). Il rischio per il sottoscrittore è elevato dato che il pagamento delle cedole può essere annullato (e non solo sospeso). Inoltre, qualora vengano realizzate perdite in grado di compromettere la solidità patrimoniale dell'emittente, il capitale da rimborsare viene decurtato, pro-quota, di queste perdite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0935", "question": "Cosa comporta la disciplina del bail-in per i possessori di obbligazioni subordinate?", "answer": "A seguito dell'introduzione della disciplina del bail-in (in vigore dal 1° gennaio 2016) e delle conseguenze che ne derivano per i possessori di obbligazioni subordinate di una banca in dissesto, l'investimento in questi strumenti deve essere valutato in modo ancora più analitico e oculato, in considerazione della propria propensione al rischio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-obbligazioni"}},
{"id": "chunk_0936", "question": "Quando si sviluppano i primi mercati di scambio delle merci nel Medioevo?", "answer": "A partire dall'ultima fase dell'Alto Medioevo (che per convenzione va dalla caduta dell'Impero romano d'Occidente, avvenuta nel 476, all'anno 1000 circa), nelle società agrarie e nei piccoli centri urbani si vengono a sviluppare via via mercati di scambio delle merci prodotte proprio per la rivendita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0937", "question": "Perché la moneta metallica si afferma come mezzo di scambio?", "answer": "La moneta metallica (e, molto più tardi, quella bancaria) si afferma come \"mezzo\" convenzionale (ossia l'equivalente universale riconosciuto) per l'acquisto e la vendita delle diverse merci presenti nel mercato, perché costituisce il modo più semplice per risolvere le relazioni di valore tra una moltitudine di beni negoziabili tra una pluralità di soggetti. L'uso della moneta si diffonde perché riduce notevolmente i costi di transazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0938", "question": "Come nasce l'economia di mercato nel Medioevo?", "answer": "Dall'interazione tra l'attività economica svolta presso le corti feudali e quella dei borghi contigui e relativamente autonomi, inizia a formarsi un'economia di mercato che si basa sulle compra-vendite di merci dietro pagamento di un prezzo monetario concordato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0939", "question": "Che cosa sono le lettere di cambio o lettere di credito?", "answer": "Le \"lettere di cambio\" (o \"lettere di credito\") erano vere e proprie forme di riconoscimento di un debito monetario chiamata anche \"moneta scritturale\" - per importi necessari al commerciante/acquirente finale ad acquistare un bene o a saldare pregressi debiti (senza dover necessariamente avere con sé o possedere il denaro contante).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0940", "question": "Come nasce l'attività bancaria?", "answer": "La sistematizzazione di questo tipo d'attività - con l'accettazione di depositi monetari, l'effettuazione di pagamenti per conto dei clienti-depositanti mediante scritturazione nei libri e il prestito di una frazione dei depositi ricevuti ad altre parti - diede luogo alla nascita dell'attività bancaria e alla moneta bancaria, dando un grosso contributo all'espansione dell'economia europea per via della facilitazione degli scambi commerciale indotta dalla ridotta necessità di trasferimento e trasporto di moneta metallica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0941", "question": "Qual è la differenza tra economia naturale e economia monetaria?", "answer": "L'attività economica si trasforma da un sistema feudale di \"produzione per l'uso\" (con scarso uso della moneta: si parla infatti di economia naturale) a un sistema pre-capitalistico di \"produzione per il mercato\" (con ampio utilizzo della moneta e del credito: si parla di economia monetaria).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0942", "question": "Come funzionava l'economia feudale nel Medioevo?", "answer": "Nella società feudale, i proprietari fondiari (i signori feudali) agiscono costantemente sui contadini e sugli altri produttori presenti nell'area del feudo per appropriarsi, attraverso la coercizione politica e la forza delle consuetudini, della maggiore quantità di beni da essi prodotta per il loro uso e consumo. Il lavoro dei contadini non è remunerato con moneta, in quanto non prestato liberamente. I prodotti ottenuti dai contadini sotto forma di rendita feudale sono destinati dal signore solo per l'eccedenza a mercati di vendita e fiere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0943", "question": "Che cosa si intende per sistema mercantile pre-capitalistico?", "answer": "Si parla di \"sistema mercantile pre-capitalistico\" (o di \"capitalismo mercantile\") con riferimento al forte sviluppo dell'economia di produzione di merci nelle città che si genera in tutta Europa nel Basso Medio-Evo a seguito dell'intenso processo di urbanizzazione di parte della popolazione delle campagne, in cerca di prospettive di vita più libera e migliore di quella servile loro concessa nel sistema agricolo feudale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0944", "question": "Come si sviluppa l'attività di prestito di denaro nel XIII secolo?", "answer": "Il \"commercio\" di denaro porta ben presto nel XIII al sorgere di un'attività specializzata, ossia all'attività di prestito di moneta (ossia di credito finanziario, la cosiddetta moneta fiduciaria) a piccoli produttori e a piccoli e grandi commercianti di merci o agli acquirenti finali, giocando un ruolo propulsivo all'intensificarsi degli scambi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0945", "question": "Che cosa caratterizza il cosiddetto \"lungo XVI secolo\"?", "answer": "Nel periodo che va dal 1450 al 1650 (il cosiddetto «lungo XVI° secolo») l'economia europea si organizza su scala mondiale, con un robusto traffico - dall'Estremo Oriente all'Europa e viceversa - di merci di vario genere. La massa monetaria è fortemente aumentata in tutta Europa, grazie all'oro e all'argento proveniente dal Nuovo Mondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0946", "question": "Quando nascono i grandi banchi cittadini?", "answer": "Verso la fine del XVI° secolo e l'inizio del XVII° nascono i grandi banchi cittadini: il Banco di Rialto a Venezia, il nuovo Banco di San Giorgio a Genova, la Banca di Amsterdam e la Banca di Amburgo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0947", "question": "Qual era il valore della moneta nel Medioevo?", "answer": "Nell'Europa medievale e rinascimentale le monete erano solo metalliche (in oro o in argento), tipicamente in lega aurea o d'argento. Il valore intrinseco della moneta era dato dal suo peso per la proporzione del metallo prezioso nella lega utilizzata, mentre il valore estrinseco era costituito dal valore nominale attribuitole dall'autorità del territorio dove veniva accettata come mezzo di scambio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0948", "question": "Perché la Chiesa proibì il prestito di denaro a interesse?", "answer": "Durante il Medio Evo la Chiesa romana proibì per lungo tempo l'attività di prestito di denaro a interesse, considerata usura. Questa concezione, di origine aristotelica e scolastica, poggiava sul postulato della \"sterilità\" del denaro: esso, cioè, non può produrre ricchezza attraverso il \"commercio del tempo\" di per sé non cedibile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0949", "question": "Come cambiò la posizione della Chiesa sull'usura tra il Duecento e il Quattrocento?", "answer": "Fra il Due e il Quattrocento, il progredire, sempre più intenso, delle attività economiche favorì l'indebolimento e il ripensamento delle tradizionali categorie di etica economica dell'alto Medio Evo. Così, la Chiesa operò una progressiva distinzione fra usura e credito: l'usura restava proibita, mentre il credito appariva moderato e lecito in quanto \"giusto prezzo\" per l'indennizzo del lucrum cessans del prestatore, ossia del mancato guadagno che il prestatore-mercante avrebbe ottenuto investendo il denaro in altro modo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0950", "question": "Che tipo di beni importava ed esportava l'Europa nel tardo Medioevo?", "answer": "L'Europa importava pepe, spezie e droghe, seta, porcellana, lacca cinese, rame, perle, pietre preziose ed esportava tessuti di lana, argento e oro, quest'ultimi provenienti dal cosiddetto Nuovo Mondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0951", "question": "Chi erano i banchieri genovesi e quale ruolo ebbero?", "answer": "Esistono grandi mercanti che diventano ben presto dediti esclusivamente al commercio del denaro e del credito, come i banchieri genovesi, finanziatori importanti di Stati come la Spagna, la cui ennesima bancarotta del 1627 ne decreterà il declino.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/dal-medioevo-all-eta-moderna"}},
{"id": "chunk_0952", "question": "Che cosa fu l'accordo di Bretton Woods?", "answer": "Nel 1944 alla conferenza di Bretton Woods, nel New Hampshire, fu approvato un accordo internazionale che portò all'istituzione del Fondo Monetario Internazionale (FMI) e della Banca Mondiale. Il medesimo accordo condusse alla definizione del sistema di regolazione dei cambi e delle relazioni commerciali tra i principali paesi industrializzati che ha funzionato a partire dal secondo dopoguerra e fino al 1971.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0953", "question": "Qual era la premessa che portò agli accordi di Bretton Woods?", "answer": "Le profonde devastazioni arrecate dalla Seconda Guerra Mondiale avevano generato l'esigenza, ampiamente condivisa, di conferire un ordine duraturo alle relazioni internazionali. La storia economica dei principali paesi avanzati era stata inoltre segnata dalla grande depressione degli anni 30, periodo durante il quale le diffuse pratiche protezionistiche, unite alle svalutazioni competitive dei tassi di cambio, avevano causato un rapido declino del commercio internazionale e dell'economia globale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0954", "question": "Qual era lo scopo principale dell'accordo di Bretton Woods?", "answer": "Gli Stati Uniti si fecero promotori di un accordo che garantisse il monitoraggio dei flussi di pagamento, degli scambi commerciali e dei movimenti di capitali internazionali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0955", "question": "Come era strutturato il sistema dei cambi stabilito a Bretton Woods?", "answer": "L'accordo condusse all'istituzione di un sistema basato su rapporti di cambio fissi tra le valute, con il dollaro come moneta di riferimento. Tutte le valute dovevano essere convertibili in dollari e le banche centrali dovevano mantenere un cambio stabile con il dollaro attraverso operazioni di mercato aperto. La svalutazione era ammessa solo in caso di gravi squilibri strutturali della bilancia dei pagamenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0956", "question": "Quali istituzioni furono create con l'accordo di Bretton Woods?", "answer": "L'accordo stabiliva la creazione del Fondo monetario internazionale (FMI) e della Banca internazionale per la ricostruzione e lo sviluppo (la Banca Mondiale). Entrambe queste istituzioni sarebbero diventate operative solo nel 1946, una volta raccolta la ratifica dell'accordo da parte di un numero considerevole di paesi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0957", "question": "Quali erano i compiti del Fondo Monetario Internazionale?", "answer": "Tra i compiti assegnati al FMI vi erano quelli di promuovere la cooperazione monetaria internazionale, facilitare l'espansione del commercio internazionale, promuovere la stabilità e l'ordine dei rapporti di cambio evitando svalutazioni competitive, offrire risorse per affrontare difficoltà derivanti dai disavanzi della bilancia dei pagamenti. Il Fondo aveva dunque il compito di vigilare sulla stabilità monetaria e contribuire a ricostituire un commercio internazionale aperto e multilaterale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0958", "question": "Quali erano gli obiettivi della Banca Mondiale dopo la seconda guerra mondiale?", "answer": "Tra gli obiettivi della Banca Mondiale vi era il sostegno alla ricostruzione di Europa e Giappone dopo la seconda guerra mondiale, sebbene negli anni sessanta l'Istituzione si occupò anche dello sviluppo economico dei paesi di Africa, Asia e America Latina in via di decolonizzazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0959", "question": "Che cosa fu il GATT?", "answer": "Nel 1947 fu firmato l'Accordo generale sulle tariffe e il commercio, il cosiddetto GATT (General Agreement on Tariffs and Trade) teso alla liberalizzazione degli scambi internazionali di beni commerciali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0960", "question": "Perché finì l'accordo di Bretton Woods?", "answer": "In seguito alla guerra del Vietnam, l'aumento della spesa pubblica statunitense e l'ingente emissione di dollari da parte del governo degli Stati Uniti spinsero ripetutamente i paesi aderenti all'accordo a richiedere la conversione delle riserve in oro, mettendo a rischio le riserve auree del Tesoro degli USA. Il 15 agosto 1971, il presidente Richard Nixon annunciò la sospensione della convertibilità del dollaro in oro, ponendo fine agli accordi di Bretton Woods.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0961", "question": "Quale fu il ruolo del FMI dopo Bretton Woods?", "answer": "Dopo Bretton Woods, il FMI si concentrò sul finanziamento degli squilibri della bilancia dei pagamenti dei paesi in via di sviluppo, a fronte del rispetto di specifiche condizioni e dell'implementazione di piani di stabilizzazione macroeconomica. Tale funzione costituisce tuttora la priorità del Fondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0962", "question": "Cosa accadde al GATT nel 1995?", "answer": "Il GATT fu sostituito nel 1995 dal WTO (World Trade Organization - Organizzazione mondiale del commercio), organizzazione tesa all'abolizione delle barriere tariffarie agli scambi internazionali di beni, servizi e proprietà intellettuali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0963", "question": "Che cos'era lo SME?", "answer": "Il Sistema Monetario Europeo (SME) era un accordo di cooperazione monetaria entrato in vigore il 13 marzo 1979, con l'obiettivo di realizzare un mercato finanziario unico, creare una zona di stabilità monetaria in Europa e favorire la libera circolazione di capitali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0964", "question": "Che cos'era l'ECU?", "answer": "L'ECU (European Currency Unit) era un'unità di conto comune calcolata come la media ponderata delle valute dei Paesi membri della CEE, relazionata all'importanza economica di ciascun Paese. Fu usata come valuta virtuale per il budget interno della Comunità europea e per la regolazione delle posizioni debitorie tra le banche centrali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0965", "question": "Qual era lo scopo della centralizzazione delle riserve presso il FECoM?", "answer": "La centralizzazione, presso il Fondo Europeo di Cooperazione Monetaria (FECoM), del 20% delle riserve auree e del 20% delle riserve in dollari detenute da ciascuna banca centrale aveva l'obiettivo di creare una banca centrale europea per il raggiungimento dell'Unione Economica Monetaria (UEM).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0966", "question": "Che cosa accadde allo SME negli anni '90?", "answer": "Nei primi anni '90 emersero le debolezze dello SME, messe a dura prova dalle diverse politiche economiche dei Paesi membri. I tassi di interesse tedeschi furono aumentati per contenere l'inflazione, inducendo gli altri paesi a fare lo stesso. La speculazione finanziaria del 1992 portò Italia e Regno Unito ad abbandonare lo SME.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0967", "question": "Che cosa fu il Compromesso di Bruxelles?", "answer": "Il Compromesso di Bruxelles del 1993 revisionava il sistema monetario europeo, stabilendo una più ampia banda di fluttuazione (dal 2,5% al 15%) per i tassi di cambio delle valute europee rispetto al tasso centrale di parità, rendendo praticamente inoperante lo SME.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0968", "question": "Quando e come terminò lo SME?", "answer": "La fine dello SME fu dichiarata ufficialmente a fine dicembre 1998. L'ECU visse fino al 1º gennaio 1999, quando venne sostituito dall'euro in un rapporto 1:1.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0969", "question": "Che cosa rappresenta la globalizzazione finanziaria?", "answer": "La globalizzazione finanziaria è un fenomeno che si è realizzato a partire dai primi anni '90 del XX secolo e consiste nella crescente interdipendenza economica e finanziaria tra le diverse aree geopolitiche mondiali, favorita dalla libertà di movimento dei capitali, dalla deregolamentazione finanziaria e dalle nuove tecnologie di comunicazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0970", "question": "Quali fattori hanno favorito la globalizzazione finanziaria?", "answer": "Tra i fattori principali vi sono il rafforzamento dell'interdipendenza economica e finanziaria tra le aree geopolitiche, la libertà di movimento dei capitali, la deregolamentazione delle transazioni finanziarie, la diffusione della tecnologia di comunicazione telematica e l'integrazione dei diversi segmenti dei mercati finanziari internazionali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0971", "question": "Quali rischi comporta la mobilità del capitale finanziario?", "answer": "La mobilità del capitale finanziario accresce i rischi di eccessiva variabilità dei prezzi delle attività finanziarie, creando condizioni di minore stabilità dei sistemi finanziari in assenza di presidi istituzionali sovranazionali in grado di regolarli e controllarli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0972", "question": "Che cosa dimostrò la crisi finanziaria recente?", "answer": "La crisi, originata negli Stati Uniti, ha dimostrato l'interdipendenza tra economia e finanza e l'instabilità dei loro rapporti per squilibri macroeconomici, reazioni emotive, cattivi incentivi e carenze nella regolamentazione dei rischi sistemici e nella vigilanza nazionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0973", "question": "Che cos'è l'eurozona?", "answer": "L'eurozona è l'insieme degli Stati membri dell'Unione Europea che hanno adottato l'euro come valuta ufficiale. L'euro, introdotto nel 1999 come moneta virtuale e dal 2002 come moneta reale, è attualmente la valuta ufficiale di 19 dei 28 paesi membri dell'UE ed è utilizzata anche in altri sei stati europei.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0974", "question": "Quali sono gli obiettivi principali della Banca Centrale Europea?", "answer": "Gli obiettivi principali della BCE sono il mantenimento della stabilità dei prezzi mediante la definizione della politica monetaria dell'Unione e la stabilità del sistema finanziario, assicurandosi che i mercati e le istituzioni siano controllati in modo appropriato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0975", "question": "Quali sono le principali funzioni monetarie della BCE?", "answer": "Tra le funzioni monetarie della BCE vi sono: il diritto esclusivo di autorizzare l'emissione di banconote e monete; fissare i tassi d'interesse di riferimento per l'area euro; gestire le riserve in valuta estera dell'area euro; e assicurarsi che i mercati finanziari e i sistemi di pagamento funzionino correttamente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0976", "question": "Che cosa stabiliva il Trattato di Roma del 1957?", "answer": "Il Trattato di Roma del 25 marzo 1957 istituì la Comunità Economica Europea (CEE), stipulato da sei paesi fondatori: Italia, Francia, Repubblica Federale di Germania, Belgio, Paesi Bassi e Lussemburgo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0977", "question": "Che cosa fu il Serpente Monetario?", "answer": "Il \"Serpente Monetario\" era l'accordo del 1972 tra i paesi della CEE che stabiliva i margini di oscillazione rispetto al marco tedesco delle monete europee all'interno di una fascia, mantenendo uno spazio di movimento nei confronti del dollaro statunitense. È considerato l'antenato dello SME.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0978", "question": "Qual era l'obiettivo del Serpente Monetario?", "answer": "L'idea di base era quella di creare un sistema simile al progetto Bretton Woods, che prevedeva un sistema di cambi fissi per tutte le monete e che aveva come punto di riferimento il valore del dollaro, al fine di raggiungere una stabilità nei cambi che favorisse gli scambi commerciali e contribuisse al loro sviluppo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0979", "question": "Perché il Serpente Monetario fallì?", "answer": "Il Serpente Monetario non durò a lungo in quanto le diverse valute che ne facevano parte non riuscivano a rispettare le regole.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0980", "question": "Che cosa accadde al Serpente Monetario durante la crisi petrolifera del 1973?", "answer": "Con la crisi petrolifera del 1973, che innescò un forte e generale aumento dei prezzi, determinando fluttuazioni nei cambi oltre i margini prestabiliti, molti Paesi membri uscirono dall'accordo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0981", "question": "Quando l'Italia uscì dal Serpente Monetario?", "answer": "Nel 1973 l'Italia uscì dal sistema e ne rimase fuori fino all'entrata in funzione del Sistema Monetario Europeo, nel 1979.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0982", "question": "Quali paesi rimasero nel Serpente Monetario fino al 1979?", "answer": "Solo il marco tedesco, il fiorino olandese, il franco belga e la corona danese restarono vincolati al Serpente Monetario fino al 1979.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-corrente"}},
{"id": "chunk_0983", "question": "Che cos'è il capitalismo nella sua forma più evoluta?", "answer": "Il Capitalismo nella sua forma più evoluta è un sistema di produzione di merci finalizzato allo scambio con profitto legittimo. Il commercio è il presupposto logico del capitalismo; il suo sviluppo abbisogna di un'economia monetaria (e finanziaria) sempre più sofisticata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0984", "question": "Quando era evidente la necessità di superare i limiti della moneta fisica?", "answer": "Era evidente alla fine del XVI° secolo che l'espansione dell'attività economica aveva bisogno di superare i \"limiti\" imposti da una quantità finita di una moneta fisica in oro o argento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0985", "question": "Quando si affermò il capitalismo industriale e quali furono le sue caratteristiche principali?", "answer": "Il \"capitalismo industriale\" si affermerà molti secoli dopo - a partire dalla fine del XVIII° secolo e soprattutto nella seconda parte del XIX° - quando, con la cosiddetta rivoluzione industriale, la borghesia riesce a emergere come forza sociale dominante in contrapposizione alla nobiltà terriera: taluni individui dotati di \"spirito capitalistico\", gli imprenditori, realizzano mediante impiego delle proprie risorse finanziarie e/o del credito ottenuto dalle banche un sistema di produzione \"seriale\" di merci fondato sul lavoro (formalmente libero) di altri individui, dietro pagamento di un salario, e nell'uso sistematico di macchine organizzati in un unico luogo fisico (la fabbrica) secondo un principio di divisione tecnologica delle operazioni produttive e di specializzazione del lavoro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0986", "question": "Qual era la finalità dell'assetto del processo produttivo nel capitalismo industriale?", "answer": "L'assetto del processo produttivo rispondeva alla finalità di massimizzare le quantità prodotte e minimizzare i costi di produzione in relazione alle possibilità di rivendita con guadagno, quasi sempre reinvestito nell'impresa stessa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0987", "question": "In quali paesi si realizzò primariamente lo sviluppo industriale capitalistico?", "answer": "Ciò si realizzerà primariamente in quei paesi, l'Inghilterra tra tutti, nei quali sia le condizioni socio-economiche e politiche sono tali da supportare lo sviluppo industriale capitalistico sia perché i fattori esterni di natura internazionale l'hanno consentito, primo fra tutti, l'estensione del commercio internazionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0988", "question": "Qual era il legame tra crescita economica e innovazione finanziaria?", "answer": "La trasformazione della finanza costituisce un ingrediente storicamente necessario per lo sviluppo del sistema economico e viceversa. In altre parole, crescita economica e innovazione finanziaria appaiono processi interdipendenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0989", "question": "Qual era il problema principale legato alla scarsità fisica di moneta?", "answer": "Il problema della scarsità fisica di moneta non era superabile fin tanto che le banche dell'epoca prestavano soldi nei limiti dei depositi di monete in metallo prezioso che ricevevano.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0990", "question": "Dove e quando ebbe origine la rivoluzione finanziaria?", "answer": "Ben prima della \"rivoluzione industriale\" ci fu, a cavallo dei secoli XVII° e XVIII°, una rivoluzione finanziaria che ebbe la sua genesi in Olanda, prima, e successivamente, in Inghilterra.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0991", "question": "Quali furono le principali innovazioni introdotte dalla rivoluzione finanziaria?", "answer": "Inizia in quel tempo e in quei paesi a delinearsi un sistema monetario e finanziario in senso moderno: le società per azioni a partecipazione diffusa, l'offerta pubblica di titoli di debito e di titoli di partecipazione al capitale di rischio (le azioni), la nascita di banche che provvedono tramite il sistema di accettazione di depositi in tutte le monete europee e l'emissione di \"note di credito\" ad aumentare la velocità di circolazione della \"moneta\", l'uso degli assegni bancari fondato sulla fiducia nel debitore, l'istituzione delle prime banche di emissione che \"stampavano\" banconote convertibili in oro o argento in nome e per conto dello Stato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0992", "question": "Quale fu la principale innovazione introdotta dalla Compagnia Olandese delle Indie Orientali nel 1602?", "answer": "L'innovazione principale era rappresentata dalla possibilità offerta alla Compagnia di raccogliere i capitali necessari mediante pubblica sottoscrizione aperta a tutti i residenti nel territorio olandese, senza un tetto prefissato. Il capitale finanziario, suddiviso in azioni, fu sottoscritto da cittadini di ogni ceto sociale, che rischiavano di perdere al massimo il proprio investimento in caso di fallimento della società, affermando così il principio della responsabilità limitata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0993", "question": "Quando e dove nacque una delle prime Borse Valori al mondo?", "answer": "Gli scambi avvenivano in un primo tempo in uno spazio aperto, ma assunsero presto un'intensità tale da indurre nel 1608 la costruzione della Beurs van Amsterdam, una delle prime \"Borse Valori\" al mondo, sicuramente la più sofisticata per le tecniche negoziali impiegate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0994", "question": "Qual era il ruolo della Banca di Amsterdam istituita nel 1609?", "answer": "Nel 1609 fu istituita la Banca di Amsterdam (Wisselbank), specializzata nella conversione delle diverse monete circolanti in Europa in proprie banconote aventi la garanzia dello Stato olandese, nella forma di ricevute bancarie negoziabili, utilizzabili anche per i pagamenti domestici con altri clienti della stessa banca.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0995", "question": "Come garantiva la Banca di Amsterdam il compimento delle operazioni commerciali?", "answer": "La possibilità, consentita ai mercanti olandesi, di aprire un deposito denominato in un'unità di conto monetaria propria della Banca di cambio introdusse un sistema efficiente di trasferimenti diretti mediante addebito-accredito contabile dei depositi interessati, garantendo il compimento di moltissime operazioni commerciali senza necessità di trasferimento materiale di moneta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0996", "question": "Perché la Banca di Amsterdam non creava moneta bancaria?", "answer": "L'innovazione nel sistema dei pagamenti commerciali non si accompagnò alla \"creazione\" di moneta bancaria perché la Banca non erogava prestiti, intendendo mantenere paritario il rapporto fra depositi ricevuti e riserve in metalli preziosi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0997", "question": "Chi introdusse in Francia una gestione moderna del debito pubblico tra il 1716 e il 1720?", "answer": "Fu uno scozzese geniale trasferitosi in Francia - John Law - ad applicare sul campo tra il 1716 e il 1720 la possibilità di superare i limiti di una circolazione monetaria fondata sull'oro attraverso l'istituzione di una banca pubblica che emetteva banconote e di introdurre una gestione \"moderna\" del debito pubblico del Regno di Francia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0998", "question": "Qual era l'intuizione principale di John Law sulla moneta?", "answer": "La grande intuizione di John Law fu che il fondamento di una stabile moneta è dato dalla fiducia pubblica che essa suscita, a sua volta generata dalla comune percezione della \"ricchezza della nazione\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_0999", "question": "Quando fu istituita la Bank of England e con quale scopo?", "answer": "Nel 1694 fu istituita a Londra la Bank of England, inizialmente concepita per mobilizzare il risparmio nazionale in soccorso alle deboli finanze pubbliche, prosciugate a seguito della guerra con la Francia. La Banca nacque quindi come banca del Governo e gestore del suo debito e godette di privilegi notevoli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_1000", "question": "Quale ruolo assunse la Bank of England nel sistema bancario britannico?", "answer": "Ben presto la Bank of England assunse una rilevanza tale nel sistema bancario britannico da essere descritta nel 1781 come lo Scacchiere dell'Erario (\"the public exchequer\") e la banca dei banchieri per il ruolo centrale giocato nelle transazioni interbancarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_1001", "question": "Quali condizioni crearono le basi per una moderna gestione finanziaria delle attività economiche?", "answer": "Lo sviluppo, registrato nel XVII° e XVIII° secolo, di nuove tecniche finanziare e di nuove modalità di gestione delle banche, unitamente all'utilizzo diffuso di nuovi strumenti finanziari (azioni e obbligazioni) e al consolidarsi di mercati di scambio di tali strumenti, aveva creato le condizioni per una più moderna gestione finanziaria delle attività economiche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_1002", "question": "Cosa osservò Joseph de la Vega nel suo libro del 1688?", "answer": "Nella Borsa di Amsterdam era possibile già allora osservare l'uso di tecniche manipolative dei prezzi, come illustrato da un cronista dell'epoca, Joseph de la Vega, nel libro \"Confusion de Confusiones\", scritto nel 1688, ma di straordinaria modernità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/l-eta-moderna"}},
{"id": "chunk_1003", "question": "Quali caratteristiche hanno avuto le crisi finanziarie degli anni novanta?", "answer": "Le crisi finanziarie degli anni novanta si sono caratterizzate per la presenza di crescenti squilibri sia di finanza pubblica sia nei rapporti con l'estero. Questa circostanza viene anche indicata con l'espressione \"deficit gemelli\": a un deficit pubblico (differenza tra entrate e uscite dello Stato) si accompagna un deficit della bilancia commerciale (differenza tra esportazioni e importazioni). Tali condizioni possono minare la fiducia nella sostenibilità del debito complessivo del Paese, determinare pressioni sul tasso di cambio e, per tale via, sui tassi di interesse e sul livello dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1004", "question": "Quali furono le cause della crisi del Messico del 1994?", "answer": "La liberalizzazione delle transazioni finanziarie dei primi anni '90 aveva indotto un ingente afflusso di capitali verso il Messico. Al fine di combattere l'elevata inflazione di quegli anni, il Messico aveva ancorato la propria valuta, il peso, al dollaro statunitense e aveva fissato i tassi di interesse a livelli elevati, per incentivare gli investitori a detenere pesos. L'ancoraggio al dollaro e la conseguente impossibilità di ricorrere allo strumento della svalutazione determinarono, tuttavia, una perdita di competitività del Paese sui mercati internazionali, un calo delle esportazioni e un progressivo aumento del deficit della bilancia commerciale. Nel 1994 il deficit di parte corrente superò l'8%' del PIL.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1005", "question": "Come si sviluppò la crisi di fiducia in Messico nel 1994?", "answer": "I mercati reputarono il deficit della bilancia commerciale eccessivo e incoerente rispetto a un tasso di cambio ancorato a una parità di poco più di 3 pesos per dollaro. I disordini politici del gennaio 1994 contribuirono ad alimentare una crisi di fiducia e indussero le autorità messicane a sostituire i titoli di debito pubblico denominati in valuta locale, via via che giungevano a scadenza, con titoli in dollari, al fine di ridurre i rendimenti richiesti dai creditori esteri per coprirsi dal rischio di svalutazione. Questa misura non riuscì, tuttavia, a scongiurare l'aumento dei rendimenti dei titoli pubblici, poiché le riserve in dollari detenute dalla banca centrale messicana non erano sufficienti a garantire il rimborso dei nuovi titoli a breve scadenza e gli investitori richiedevano un premio per il rischio di ripudio del debito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1006", "question": "Cosa accadde al peso messicano tra il 1994 e il 1995?", "answer": "Nel dicembre 1994 il livello delle riserve era ormai esiguo e sufficiente a coprire solo circa un quarto del debito pubblico denominato in dollari. Tale circostanza, unita alla difficoltà ormai conclamata di reperire capitali sui mercati internazionali, costrinse le autorità ad abbandonare la parità. Tra settembre 1994 e aprile 1995, il peso si svalutò quasi del 100 per cento (da una parità centrale di poco più di 3 pesos per dollaro a una parità di 6 nuovi pesos per 1 dollaro americano).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1007", "question": "Quali furono gli effetti economici della crisi messicana del 1994?", "answer": "Nel 1995 il PIL messicano si ridusse di quasi il 6%. L'intervento del Fondo Monetario Internazionale e del governo degli Stati Uniti, per un ammontare complessivo di 50 miliardi, ripristinò rapidamente la fiducia dei mercati e frenò la crisi. Nel 1996 i titoli in dollari furono rimborsati in anticipo rispetto alla loro scadenza e il PIL tornò a crescere a un tasso del 4%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1008", "question": "Quali furono le cause della crisi del Sud Est asiatico del 1997?", "answer": "Fra il 1965 e il 1996 i paesi dell'Asia Orientale avevano registrato un tasso medio annuo di crescita del PIL pro-capite pari a circa il 6%, valore superiore al dato relativo a qualsiasi altra economia mondiale (cosiddetto \"miracolo asiatico\" o \"miracolo delle tigri asiatiche\"). Fino ai primi anni ‘90, la sostenibilità dello sviluppo economico era garantita da politiche monetarie e inflazione moderate, equilibrio dei conti pubblici ed esportazioni in crescita. Fattori di vulnerabilità, tuttavia, emergevano con riferimento al peso degli investimenti finanziari di breve periodo, all'incremento sostenuto del livello di indebitamento delle imprese, favorito dal clima di fiducia nelle prospettive di crescita, da tassi d'interesse bassi e dalla facilità di accesso al credito bancario, e al sistema bancario privato, che operava in un regime di liberalizzazione e deregolamentazione. Un ulteriore limite strutturale era da ricondurre all'ancoraggio delle valute locali al dollaro, il cui apprezzamento verso la metà degli anni '90 contribuì alla contrazione dell'export e alla crisi valutaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1009", "question": "Come ebbe inizio la crisi valutaria in Tailandia nel 1997?", "answer": "L'epicentro della crisi fu la Tailandia, che a seguito dell'apprezzamento reale del baht si trovò a dover fronteggiare un debito estero insostenibile. La situazione risultava aggravata dalla vulnerabilità del sistema bancario domestico, che si era indebitato in dollari a breve termine e aveva erogato credito in valuta locale a lungo termine. L'inizio della crisi valutaria si fa coincidere con la svalutazione del baht, nel luglio 1997, decisa dalla Banca centrale tailandese a seguito di una serie di attacchi speculativi da parte di fondi di investimento internazionali che nel giro di due settimane ne avevano provocato un deprezzamento rispetto al dollaro pari al 15% (30%' a fine luglio).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1010", "question": "Come si diffuse la crisi del Sud Est asiatico ad altri paesi?", "answer": "Il crollo della moneta tailandese innescò fenomeni di contagio che coinvolsero rapidamente le economie limitrofe. Fra la metà di luglio e la fine di agosto il baht si era stabilizzato, ma gli attacchi speculativi avevano già colpito dapprima la valuta della Malesia, poi dell'Indonesia, e infine della Corea del Sud. Le monete dell'area si svalutarono in una misura che andava dal 20%' circa per il dollaro di Taiwan al 110%' per il won coreano.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1011", "question": "Quali furono gli effetti economici della crisi asiatica del 1997?", "answer": "La crisi valutaria si riflesse rapidamente sull'economia reale con una recessione che perdurò fino al 1998. La fuga dei capitali, indotta dal timore di ulteriori svalutazioni, mise in gravi difficoltà banche e imprese. Alla fine del secondo semestre del 1997, le Borse dell'area registrarono perdite tra il 20%' di Hong Kong e il 55%' della Tailandia; le perdite furono anche superiori nel comparto immobiliare. Nel giro di pochi mesi fallirono numerose imprese, banche e istituzioni finanziarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1012", "question": "Come intervenne il Fondo Monetario Internazionale nella crisi asiatica?", "answer": "Al fine di ripristinare la fiducia del mercato, il Fondo Monetario Internazionale si attivò fin dal luglio 1996, concedendo prestiti condizionati all'attuazione di \"riforme strutturali\". I piani di riforma prevedevano, tra le altre cose, tagli alla spesa pubblica, aumento della pressione fiscale, maggiore apertura e trasparenza del sistema finanziario, nonché una riforma della legislazione su banche e istituti di credito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1013", "question": "Quali furono le cause della crisi valutaria russa del 1998?", "answer": "La crisi valutaria russa del 1998 si sviluppò in un contesto di significative difficoltà politiche, sociali, economiche e finanziarie a fronte del crollo dell'URSS e della transizione da un'economia pianificata a un'economia di mercato. Il calo del prezzo del petrolio aveva penalizzato le esportazioni, determinando uno squilibrio della bilancia commerciale che si aggiungeva allo squilibrio dei conti pubblici. Questi fattori, unitamente al contagio della crisi asiatica, misero sotto pressione il rublo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1014", "question": "Come cercò la Russia di difendere il rublo nel 1998?", "answer": "La Russia decise di ancorare il valore della valuta domestica al dollaro statunitense, secondo un meccanismo semi-rigido che prevedeva la possibilità che il tasso di cambio si muovesse entro bande di oscillazione predeterminate. In particolare, il valore centrale del tasso di cambio venne fissato a 6,2 rubli per dollaro con una banda di oscillazione del ±15%. La Banca centrale tentò di difendere l'ancoraggio al dollaro sia con operazioni sul mercato valutario sia innalzando il tasso ufficiale di sconto, ma le riserve in valuta estera si assottigliavano sempre più.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1015", "question": "Quali misure adottò il governo russo durante la crisi del 1998?", "answer": "Il governo mise a punto un piano anticrisi che prevedeva da un lato riforme strutturali e fiscali, dall'altro la richiesta di un prestito alle istituzioni internazionali per fronteggiare gli attacchi speculativi. Il FMI varò, nel luglio 1998, un piano di sostegno finanziario per un ammontare complessivo di quasi 23 miliardi di dollari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1016", "question": "Cosa accadde nell'agosto 1998 in Russia?", "answer": "A metà agosto 1998 vennero annunciati una serie di provvedimenti, tra i quali l'allargamento della banda di oscillazione del rublo, una ristrutturazione del debito pubblico denominato in rubli che prevedeva una sospensione dei pagamenti connessi ai titoli di Stato a breve termine e una moratoria di 90 giorni sul debito estero. Il 2 settembre del 1998 venne definitivamente abbandonato l'ancoraggio del rublo al dollaro. Il tasso di cambio passò in pochi giorni da 6 rubli per dollaro a 21 rubli per dollaro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1017", "question": "Come reagì l'economia russa dopo la crisi del 1998?", "answer": "Negli anni successivi l'economia russa sperimentò una ripresa molto rapida, sostenuta anche dal rialzo del prezzo del petrolio e dal conseguente miglioramento della bilancia dei pagamenti. Già nel 1999 il tasso di crescita del PIL superava il 5%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1018", "question": "Quali furono le cause della crisi del Brasile del 1998-99?", "answer": "Nel corso degli anni '90, il Brasile sperimentò un peggioramento dei saldi di finanza pubblica e un crescente disavanzo del saldo commerciale con l'estero, a fronte di significativi afflussi di capitale. In quegli anni la valuta del Brasile, il real, era ancorata al dollaro. Il contagio della crisi asiatica a livello globale fece emergere gli squilibri macroeconomici che caratterizzavano l'economia brasiliana.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1019", "question": "Come si sviluppò la crisi valutaria in Brasile nel 1998-99?", "answer": "Sul finire del 1998 forti vendite di obbligazioni brasiliane, pubbliche e private, innescarono pressioni sul tasso di cambio, sopravvalutato rispetto ai fondamentali economici del Paese. L'ancoraggio del real al dollaro si rivelò ben presto insostenibile. Nell'ottobre del 1998 il FMI varò un programma di aiuti finanziari per un ammontare complessivo di oltre 41 miliardi di dollari. Nel gennaio 1999 il Brasile abbandonò il regime di cambi fissi con il dollaro e nei due mesi seguenti il real subì un deprezzamento del 40%' circa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1020", "question": "Come reagì il Brasile dopo la crisi valutaria del 1999?", "answer": "Nel marzo del 1999 il Brasile varò una nuova e drastica manovra fiscale correttiva per contenere la dinamica del debito pubblico. La recessione economica e l'abbandono dei meccanismi di indicizzazione dei salari concorsero a contenere le pressioni inflazionistiche, con riflessi positivi per le finanze pubbliche e il clima di fiducia. L'abbandono dell'ancoraggio del real al dollaro prima che le riserve fossero esaurite contribuì a mitigare l'impatto della crisi sull'economia reale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1021", "question": "Quali furono le cause della crisi argentina del 2001?", "answer": "Le cause della crisi sono da far risalire all'ingente debito accumulato nel corso di lunghe dittature militari e al rigido ancoraggio del peso, la valuta locale, al dollaro. Negli anni 80 l'Argentina continuò ad accumulare debito pubblico. Il tasso di cambio fisso favorì le importazioni, alimentando una deindustrializzazione del paese ed elevati tassi di disoccupazione. Il Fondo Monetario Internazionale continuava comunque a concedere prestiti e dilazioni di pagamento finalizzati al risanamento della finanza pubblica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1022", "question": "Come si manifestò la crisi economica argentina nel 2001?", "answer": "Nel 1999 il PIL argentino diminuì del 4%' e il paese entrò in recessione. Il timore di una svalutazione innescò, nel 2001, una corsa agli sportelli bancari da parte dei correntisti che ritiravano pesos da convertire in valuta pregiata. Le misure restrittive imposte dal governo per arginare i prelievi provocarono in poco tempo una vera e propria rivolta popolare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1023", "question": "Quali furono le conseguenze del default argentino del 2001?", "answer": "Nel dicembre del 2001, il Governo annunciò la sospensione della scadenza delle obbligazioni governative (moratoria). La decisione ebbe riflessi anche sugli investitori italiani, che avevano sottoscritto titoli pubblici argentini, e diede avvio a una complessa fase di negoziati internazionali finalizzati alla ristrutturazione del debito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1024", "question": "Perché i bond argentini erano così diffusi in Italia?", "answer": "I titoli obbligazionari argentini risultavano presenti nei portafogli di circa 430.000 investitori italiani, per un controvalore nominale pari a 12,8 miliardi di euro. Il 95%' circa dei titoli argentini circolanti in Italia era detenuto da investitori privati e l'85%' di tali titoli era costituito da obbligazioni governative. La percezione di affidabilità di un emittente sovrano e gli elevati rendimenti offerti dai titoli argentini possono spiegarne l'ampia diffusione presso la clientela retail italiana.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1025", "question": "Quali furono gli effetti economici della crisi argentina del 2001?", "answer": "Il deprezzamento progressivo della valuta nazionale provocò un rialzo del tasso d'inflazione. Molte imprese chiusero o fallirono; molti prodotti importati divennero inaccessibili ai consumatori locali e la qualità media della vita si ridusse drasticamente; il tasso di disoccupazione raggiunse il 25%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1026", "question": "Come avvenne la ripresa economica in Argentina dopo il 2003?", "answer": "A partire dal 2003, le misure a sostegno della produzione domestica assieme alla debolezza del peso e alla ripresa delle esportazioni consentirono all'economia argentina di tornare a crescere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-anni-90-ed-inizio-2000"}},
{"id": "chunk_1027", "question": "Che cos'è la bolla dei tulipani?", "answer": "La bolla dei tulipani nel 1637 fu la prima grande crisi finanziaria innescata dall'utilizzo di strumenti finanziari con finalità speculative.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1028", "question": "Quando iniziò la diffusione dei tulipani in Europa?", "answer": "Nella seconda metà del 1500 i bulbi di tulipano iniziarono ad essere esportati dalla Turchia in Europa e l'Olanda fu il paese che si fece promotore della loro diffusione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1029", "question": "Quando fu avviata la coltivazione del tulipano nei Paesi Bassi?", "answer": "Negli ultimi anni del 1500 la coltivazione del tulipano fu avviata nei Paesi Bassi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1030", "question": "Perché le varietà di tulipani meno comuni divennero merce di lusso?", "answer": "Le varietà meno comuni di questo fiore vennero rapidamente considerate come merce di lusso, altamente desiderate presso la borghesia e i ricchi mercanti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1031", "question": "Cosa provocò l'aumento dei prezzi dei tulipani?", "answer": "La domanda di nuovi fiori superò ben presto la loro offerta, a causa del lento ciclo riproduttivo, cosicché i prezzi delle specie più ricercate di tulipani subirono delle continue spinte al rialzo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1032", "question": "Perché i bulbi di tulipano erano considerati un solido investimento?", "answer": "All'epoca si arrivò a considerare il bulbo del tulipano come un solido investimento, in quanto rappresentava un concentrato di fiori futuri; venne quindi utilizzato come un'embrionale forma di future sul tulipano.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1033", "question": "Dove avvenivano le contrattazioni sui bulbi di tulipano?", "answer": "Le contrattazioni avvenivano in aste tenute in luoghi pubblici o in privato (in collegi di coltivatori e commercianti riuniti nelle locande) delle varie città olandesi, tra cui Haarlem, L'Aia ecc.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1034", "question": "Cosa favorì lo sviluppo della bolla dei tulipani?", "answer": "L'espansione commerciale dell'Olanda, con l'ampliamento dell'economia e l'accrescimento della ricchezza finanziaria privata, favorì lo sviluppo di questa bolla.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1035", "question": "Chi partecipava al commercio dei tulipani durante la bolla?", "answer": "Non solo gli intenditori e appassionati di fiori appartenenti alle classi più agiate, ma anche fioristi-commercianti delle classi meno abbienti iniziarono a partecipare, a partire dal 1635, alle transazioni su bulbi di tulipano anche di specie più comuni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1036", "question": "Come funzionavano i contratti di prenotazione dei bulbi di tulipano?", "answer": "Si radicò la consuetudine di prenotare in anticipo presso i contadini-coltivatori i bulbi ancora in terra attraverso l'utilizzo di contratti con prezzi fissati ex-ante da onorare a scadenza; ciò consentiva l'estensione del periodo di compravendite da pochi mesi estivi a tutto l'anno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1037", "question": "Che cosa si intende per 'commercio al vento'?", "answer": "Si negoziavano i diritti sul bulbo, cioè i futures di tulipani, pagando subito solo un acconto del prezzo finale e corrispondendo il saldo alla consegna del bulbo fiorito, dando luogo a quel fenomeno che venne chiamato il commercio al vento perché lo scambio reale era di fatto differito ad una data futura identificata nel contratto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1038", "question": "Perché si creava una catena di impegni nel commercio dei tulipani?", "answer": "Dato che la consegna materiale avveniva a distanza di mesi, furono oggetto di negoziazione tra i fioristi-commercianti gli stessi contratti a termine già stipulati. Si creava così una lunga catena d'impegni che legava insieme tutti i partecipanti, con il rischio che l'inadempimento dell'ultimo acquirente avrebbe creato un effetto-domino sui precedenti acquirenti-debitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1039", "question": "Qual era il rischio principale del commercio dei bulbi di tulipano?", "answer": "I collegi di commercianti non controllavano né che gli acquirenti disponessero di denaro sufficiente a saldare i debiti contratti né che i venditori possedessero i bulbi di tulipano che s'impegnavano a cedere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1040", "question": "Quale era lo scopo principale degli acquisti con consegna futura dei bulbi?", "answer": "Gli acquisti con consegna futura del bulbo erano effettuati solo allo scopo di partecipare al gioco al rialzo dei prezzi, così da potere lucrare, attraverso la vendita, sull'incremento indotto dei prezzi medesimi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1041", "question": "Cosa alimentò la crescita dei prezzi dei tulipani?", "answer": "Le aspettative di facile guadagno nonché l'avidità e la cecità collettiva che ne costituivano le fondamenta alimentarono di continuo la crescita dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1042", "question": "Perché si parla di 'bolla' dei tulipani?", "answer": "I prezzi ben presto ebbero un andamento del tutto slegato dalla realtà dando luogo ad una vera e propria bolla, termine che ben riflette la psicosi diffusa tra i commercianti di tulipani.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1043", "question": "Quanto poteva valere un singolo fiore di tulipano nel 1637?", "answer": "Un fiore di tulipano del valore di 3000 fiorini avrebbe potuto essere scambiato nel gennaio 1637 con un'enorme quantità di merci come 8 maiali grassi, 4 buoi grassi, 12 pecore grasse, 24 tonnellate di grano, 48 tonnellate di segale, 2 botti di vino e altro ancora.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1044", "question": "Cosa accadde durante l'asta di Alkmaar del 5 febbraio 1637?", "answer": "La bolla dei tulipani culminò nella famosa asta di Alkmaar del 5 febbraio 1637, in cui centinaia di lotti di bulbi furono venduti per un ammontare monetario di 90.000 fiorini, ossia ciascun bulbo venduto al prezzo medio pari al reddito di oltre un anno e mezzo di un muratore dell'epoca.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1045", "question": "Cosa provocò il crollo dei prezzi dei tulipani?", "answer": "Fu sufficiente che ad Haarlem un'asta di bulbi andasse deserta per provocare il panic selling incontrollato e far precipitare i prezzi di mercato in tutto il paese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1046", "question": "Quali furono le conseguenze per i fioristi dopo il crollo?", "answer": "Chi aveva acquistato attraverso i contratti i bulbi si ritrovò vincolato contrattualmente a pagarli una cifra notevolmente più elevata rispetto ai prezzi reali del momento, a vantaggio dei contadini che avevano il diritto di percepire prezzi elevatissimi per dei bulbi che ormai non valevano quasi più nulla.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1047", "question": "Cosa decretarono le Provincie Unite dopo la crisi?", "answer": "La giustizia delle Provincie Unite olandesi decretò la trasformazione dei contratti a termine in contratti di opzione. Il detentore del contratto fu autorizzato a non onorare l'impegno pagando solo una penalità pari al 3,5% del prezzo pattuito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1048", "question": "Perché la bolla dei tulipani è importante nella storia finanziaria?", "answer": "Questa bolla può essere assolutamente considerata il primo grande crack finanziario della storia originato da un comportamento di massa guidato dalla diffusa credenza del facile arricchimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-dei-tulipani1"}},
{"id": "chunk_1049", "question": "Quali sono stati gli effetti economici e sociali della crisi sanitaria da Covid-19?", "answer": "Dopo la prima fase emergenziale, si è accesso il dibattito sulle ripercussioni economiche e sociali della crisi e sulle misure più adeguate per mitigarne l'impatto. Sebbene permetta di contenere il contagio, il distanziamento sociale determina infatti pesanti ripercussioni sull'attività economica e finanziaria del Paese che se ne avvale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1050", "question": "Quali parametri sono cruciali per stimare la durata e la gravità degli effetti economici della pandemia?", "answer": "I parametri cruciali per la stima della durata e della gravità degli effetti economici sono: il tasso di morbilità; il tasso di mortalità; il numero di giornate lavorative perse per malattia e in seguito all'applicazione delle misure di distanziamento sociale adottate per rallentare l'epidemia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1051", "question": "Perché è stato complicato stimare l'impatto economico della pandemia?", "answer": "L'incertezza sul valore dei parametri di morbilità, mortalità e giornate lavorative perse ha reso complicato stimare l'impatto economico della pandemia, pur essendo chiari sin da subito i canali di trasmissione della crisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1052", "question": "Da cosa dipendono le ricadute economiche di un'emergenza sanitaria che richieda misure di distanziamento sociale?", "answer": "In generale, le ricadute economiche di un'emergenza sanitaria che richieda misure di distanziamento sociale dipendono dagli effetti, diretti e indiretti, che ne discendono sia sull'offerta sia sulla domanda.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1053", "question": "Cosa si intende per shock negativo dell'offerta durante la pandemia?", "answer": "La contrazione imprevista dell'offerta (shock negativo dell'offerta) è un effetto diretto del lockdown, ossia dell'interruzione delle filiere produttive ritenute non essenziali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1054", "question": "Che ruolo ha avuto il lavoro da remoto durante la crisi?", "answer": "Ove possibile, si può ovviare al fermo delle attività 'in presenza fisica' attraverso il lavoro da remoto (cosiddetto smart working). Tale soluzione organizzativa non è tuttavia applicabile in modo generalizzato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1055", "question": "Quali settori non hanno potuto adottare il lavoro da remoto?", "answer": "Ne sono esclusi, ad esempio, alcuni comparti a stretto contatto con il pubblico del settore dei servizi (come turismo e ristorazione) e del settore industriale, dove il lockdown determina la chiusura di impianti e stabilimenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1056", "question": "In che modo le interdipendenze produttive e geografiche hanno amplificato lo shock iniziale?", "answer": "Le conseguenze dell'interruzione della produzione in un comparto e in una determinata area geografica possono estendersi ad altri comparti e ad altre aree geografiche, a seconda del livello di integrazione verticale delle attività e delle connessioni geografiche, amplificando così lo shock iniziale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1057", "question": "Quali sono stati gli effetti della pandemia sul lato della domanda?", "answer": "Allo shock dal lato dell'offerta si aggiunge inoltre uno shock dal lato della domanda, innescato da molteplici fattori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1058", "question": "Come hanno influito le misure restrittive alla mobilità individuale sui consumi?", "answer": "Le misure restrittive alla mobilità individuale provocano, nell'immediato, il calo dei consumi (come nel caso, ad esempio, di turismo, commercio al dettaglio, trasporti, intrattenimento di massa).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1059", "question": "Cos'è l'effetto reddito e come si manifesta durante la pandemia?", "answer": "Il cosiddetto effetto reddito si manifesta quando il rallentamento o la chiusura temporanea di alcune attività determina un calo del reddito disponibile alle famiglie poiché molti lavoratori subiscono una riduzione della retribuzione oppure perdono il lavoro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1060", "question": "Cosa si intende per effetto ricchezza?", "answer": "La crisi innesca inoltre un effetto ricchezza, poiché le attività finanziarie possedute dagli individui possono perdere di valore per effetto dell'andamento negativo dei mercati finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1061", "question": "Qual è l'impatto psicologico dell'incertezza durante la pandemia?", "answer": "Sul piano psicologico, l'incertezza comporta una paralisi della domanda, poiché gli individui tendono a limitare i consumi al minimo indispensabile, a rimandare le spese e a rafforzare il risparmio precauzionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1062", "question": "Quali effetti della crisi potrebbero essere temporanei e quali più persistenti?", "answer": "Il calo della domanda derivante dall'incertezza e dal crollo della fiducia dovrebbe essere transitorio. Anche l'effetto ricchezza potrebbe risultare transitorio, almeno in parte. Più persistente potrebbe risultare l'effetto reddito nel caso in cui numerose imprese fallissero e il tasso di disoccupazione aumentasse in modo significativo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1063", "question": "Quali settori produttivi sono stati colpiti in modo eterogeneo dalla pandemia?", "answer": "La contrazione della domanda amplifica lo shock sull'offerta, generando ripercussioni eterogenee sui settori produttivi. Per alcuni settori (come quello farmaceutico, delle telecomunicazioni o dell'high tech) la pandemia non dovrebbe comportare sviluppi avversi. Comparti come quello del turismo, della ristorazione e dell'intrattenimento sono invece destinati a subire ripercussioni significative.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1064", "question": "In che modo la pandemia ha inciso sul sistema finanziario?", "answer": "Lo sviluppo della pandemia e delle sue conseguenze economiche si ripercuote sull'andamento dei mercati finanziari determinando una diminuzione del valore dei titoli che riduce la ricchezza finanziaria delle famiglie e la loro propensione al consumo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1065", "question": "Come la crisi ha influenzato la capacità di raccolta di fondi da parte di Stato e imprese?", "answer": "L'andamento negativo dei mercati riduce la capacità di raccogliere risorse sul mercato da parte dei soggetti prenditori di fondi (ossia lo Stato e le imprese) perché si riduce la propensione dei potenziali investitori ad assumere rischio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1066", "question": "Quali sono stati gli effetti della crisi sulle banche?", "answer": "La crisi potrebbe avere effetti negativi anche sulle banche, che a loro volta potrebbero ridurre l'erogazione di credito a famiglie e imprese a fronte delle possibili difficoltà a recuperare i prestiti già concessi e nel timore che i nuovi prestiti non vengano rimborsati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1067", "question": "Quali impatti ha avuto la pandemia sulle finanze pubbliche?", "answer": "Una pandemia può determinare un forte shock esogeno sulle finanze pubbliche, derivante dalle poderose misure poste in essere per adeguare il sistema sanitario all'emergenza e per sostenere i redditi di famiglie e imprese, il flusso di credito e il buon funzionamento dei mercati. Lo squilibrio nei conti pubblici risulta accentuato dalla riduzione delle entrate fiscali e dalla contrazione del prodotto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1068", "question": "In che modo il deterioramento delle condizioni economiche ha influenzato gli attivi delle banche?", "answer": "Il deterioramento delle condizioni economiche generali determinato dalle misure di distanziamento sociale si ripercuote sulla qualità degli attivi delle banche a causa dell'aumento del tasso di insolvenza atteso dei crediti concessi a famiglie e imprese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1069", "question": "Perché il valore dei titoli di Stato può influenzare gli attivi delle banche?", "answer": "Gli attivi delle banche risentono dell'andamento negativo dei mercati dei titoli di Stato se questi ultimi costituiscono una quota significativa delle attività possedute dagli istituti creditizi. Durante una crisi, il peggioramento delle prospettive economiche di un paese può determinare un incremento dei rendimenti dei titoli pubblici con una conseguente riduzione del loro valore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1070", "question": "Come il peggioramento della qualità degli attivi influisce sulla solidità patrimoniale delle banche?", "answer": "Il peggioramento della qualità degli attivi riduce la solidità patrimoniale delle banche. Questo effetto, unitamente agli andamenti negativi dei corsi azionari e obbligazionari, rende più costosa e più difficile la raccolta di nuovi fondi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1071", "question": "Come si differenzia la crisi da Covid-19 dalle crisi del 2008 e del 2011?", "answer": "Rispetto al 2008, le condizioni complessive del sistema bancario appaiono notevolmente migliorate, anche per effetto di nuove norme prudenziali più stringenti e più efficaci nel mitigare almeno in parte la pro-ciclicità insita nell'attività di intermediazione creditizia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1072", "question": "Perché è difficile stimare l'impatto complessivo della pandemia sulla crescita economica?", "answer": "Nel caso della pandemia di Covid-19, il riferimento alle esperienze passate può risultare poco utile poiché le epidemie precedenti avevano caratteristiche diverse. Anche la modellistica sviluppata in passato si basa sull'ipotesi che il contagio si esaurisca in tempi brevi, ipotesi non valida nel caso del Covid-19.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1073", "question": "Cosa prevedevano gli studi precedenti sulla durata e sull'impatto di una pandemia?", "answer": "Alcuni lavori scientifici basati su pandemie ipotetiche stimavano un calo del Pil elevato nel trimestre di emergenza, destinato però a essere riassorbito successivamente, ipotizzando una ripresa economica rapida a forma di V (V-shaped recovery).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1074", "question": "Perché le ipotesi di una rapida ripresa economica non sono valide per la crisi da Covid-19?", "answer": "Le ipotesi di una rapida ripresa non valgono nel caso della crisi da Covid-19 perché è difficile stimare la durata della pandemia e i tassi di morbilità e mortalità. Inoltre, si trascura l'impatto psicologico e il calo di fiducia che la pandemia ha innescato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1075", "question": "Quali scenari economici ipotizzano alcuni studi recenti sul Covid-19?", "answer": "Alcuni studi, come quello di Fornaro e Wolf (2020), arrivano alla conclusione che l'evoluzione della crisi potrebbe seguire un percorso a L (cosiddetto L-shaped), ossia sfociare in una stagnazione caratterizzata da bassa crescita e alta disoccupazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1076", "question": "Qual è il grado di incertezza sulle prospettive economiche globali nel 2020?", "answer": "Le evidenze raccolte nei primi mesi del 2020 non permettono di stimare la durata della pandemia. Rimane elevata l'incertezza sulle prospettive economiche globali e sull'ampiezza della crisi che il mondo dovrà fronteggiare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1077", "question": "Quali sono le previsioni del Fondo Monetario Internazionale sulla crescita del 2020?", "answer": "Il Fondo Monetario Internazionale (FMI) prevede per il 2020 un calo del Pil mondiale pari al 3%, che nelle economie avanzate si attesterebbe in media attorno al 6% e in quelle emergenti attorno all'1%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1078", "question": "Come si colloca l'Italia nelle previsioni economiche del 2020?", "answer": "Per l'Italia, che ha adottato misure di contenimento molto stringenti, il FMI stima un calo del Pil nel 2020 pari al 9,1% a fronte di una media dell'area euro del 7,5%; un dato simile e pari al 9,5% è stato pubblicato dalla Commissione europea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1079", "question": "Cosa indicano gli indici di fiducia di imprese e consumatori dopo l'inizio della pandemia?", "answer": "A partire dal mese di marzo 2020 gli indici di fiducia di imprese e consumatori segnalano l'aspettativa di un netto calo dell'attività economica in tutti i maggiori Paesi europei.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1080", "question": "Cosa sono i PMI e cosa indicano?", "answer": "I PMI (Purchasing Manager Indexes) sono indici dei responsabili degli acquisti che rilevano il clima di fiducia in vari settori produttivi. Un valore dell'indice inferiore a 50 indica un peggioramento della fiducia mentre un valore superiore a 50 indica un miglioramento della fiducia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1081", "question": "Come si sono mossi gli indicatori di fiducia elaborati dalla Commissione europea nel primo trimestre 2020?", "answer": "Gli indicatori di fiducia elaborati dalla Commissione europea per il primo trimestre del 2020 mostrano una drastica riduzione sia per l'Area euro, dove l'economic sentiment si è portato sui livelli del 2008, sia per l'Italia, che ha registrato un calo più significativo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-sanitaria-economica"}},
{"id": "chunk_1082", "question": "Qual è stato l'impatto del Covid-19 sui mercati azionari a livello mondiale?", "answer": "La forte incertezza sulle prospettive economiche globali ha innescato forti turbolenze sui mercati azionari che, a livello mondiale, si sono riflesse in ampi cali dei corsi e in un incremento della volatilità. L'impatto è stato differente a seconda delle aree geografiche e dei settori, in funzione dell'esposizione alla pandemia e agli effetti delle misure di lockdown.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1083", "question": "Quali indici azionari sono stati considerati per confrontare l'andamento dei mercati durante la crisi da Covid-19?", "answer": "La figura che segue confronta l'andamento dei prezzi delle azioni delle maggiori società statunitensi, britanniche e dell'eurozona, ossia rispettivamente degli indici S&P500 per gli USA, FTSE100 per il Regno Unito e EuroStoxx50 per l'area euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1084", "question": "A quale livello si è portato l'indice EuroStoxx50 durante il periodo di massimo calo?", "answer": "L'indice EuroStoxx50, nel periodo di massimo calo, si è portato al di sotto del livello registrato all'inizio del 2007.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1085", "question": "Come è variata la volatilità dei prezzi durante la crisi da Covid-19 rispetto ad altre crisi precedenti?", "answer": "Anche la volatilità dei prezzi è aumentata in maniera significativa, portandosi a livelli di gran lunga superiori a quelli registrati in occasione di altre crisi, come quella finanziaria o subprime nel 2008 e del debito sovrano nel 2011.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1086", "question": "Qual è stata la flessione dell'indice FtseMib italiano durante la prima settimana di lockdown?", "answer": "Il 12 marzo, ossia durante la prima settimana di lockdown, il principale indice azionario italiano (FtseMib) registrava una flessione da inizio anno pari al 36,6%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1087", "question": "Qual è stata la contrazione dei principali mercati europei nel marzo 2020?", "answer": "La contrazione superava il 30% anche negli altri principali Paesi europei, nonostante a quella data essi non avessero ancora adottato misure di distanziamento sociale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1088", "question": "Cosa è accaduto ai mercati azionari europei dopo il brusco calo delle prime settimane della pandemia?", "answer": "Dopo il brusco calo delle prime settimane, i mercati azionari europei hanno registrato un lento recupero.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1089", "question": "Come si sono comportati i mercati dei titoli di Stato e delle obbligazioni private durante la crisi?", "answer": "Anche i mercati dei titoli di Stato e delle obbligazioni emesse da società private hanno sperimentato un calo dei prezzi, che in alcuni casi è risultato più ampio per l'Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1090", "question": "Quali effetti può avere la crisi pandemica sulle banche italiane?", "answer": "La crisi scatenata dalla pandemia può avere effetti anche sulle banche italiane, anche se esse sono più robuste rispetto al passato grazie a molteplici operazioni di rafforzamento patrimoniale e di miglioramento della qualità degli attivi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1091", "question": "In che modo la pandemia di Covid-19 ha influito sui mercati obbligazionari?", "answer": "Al pari dei mercati azionari, anche i mercati obbligazionari hanno risentito delle incertezze innescate dalla pandemia di Covid-19.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1092", "question": "Da cosa sono scaturite le tensioni sui mercati dei titoli di Stato durante la pandemia?", "answer": "Con riferimento ai mercati dei titoli di Stato, le tensioni sono scaturite principalmente dalle aspettative di un rapido peggioramento dei parametri di finanza pubblica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1093", "question": "Perché i programmi di intervento dei governi hanno generato tensioni sui mercati?", "answer": "I programmi di intervento posti in essere dai diversi governi per sostenere i sistemi sanitari nell'emergenza epidemiologica e mitigare l'impatto del lockdown sull'economia reale sono risultati di ammontare straordinariamente elevato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1094", "question": "Cosa è accaduto ai rendimenti dei titoli di Stato nei primi giorni di marzo 2020?", "answer": "Sin dai primi giorni di marzo i mercati secondari dei titoli di Stato hanno visto un incremento dei rendimenti in tutte le economie avanzate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1095", "question": "Cosa hanno mostrato i credit default swap (CDS) sul debito sovrano durante la crisi da Covid-19?", "answer": "Analoghe dinamiche sono state osservate con riferimento ai credit default swap (CDS) sul debito sovrano.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1096", "question": "Come si sono modificati i rendimenti dei titoli di Stato italiani a 10 anni nel primo trimestre del 2020?", "answer": "Nel primo trimestre dell'anno, ad esempio, i rendimenti delle obbligazioni con scadenza a 10 anni hanno raggiunto valori prossimi al 2,5% dall'1,3% registrato all'inizio dell'anno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1097", "question": "A quanto è salito lo spread tra BTP e Bund a 10 anni a metà marzo 2020?", "answer": "Lo spread tra i rendimenti dei titoli di Stato italiani con scadenza a 10 anni (BTP) e il benchmark tedesco è salito velocemente a metà marzo, raggiungendo il picco di 320 punti base da una media di circa 145 punti base registrata nei due mesi precedenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1098", "question": "Quale intervento ha annunciato la BCE per contrastare le tensioni sui mercati dei titoli pubblici?", "answer": "La Banca centrale europea (BCE) è intervenuta in breve tempo, annunciando un programma straordinario di acquisto di titoli pubblici e privati per l'emergenza pandemica (Pandemic Emergency Purchase Programme, PEPP) finalizzato a ripristinare il corretto funzionamento dei mercati dei titoli pubblici europei e assicurare l'efficace trasmissione degli impulsi di politica monetaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1099", "question": "Qual è stato l'effetto dell'annuncio del PEPP sui rendimenti dei titoli di Stato?", "answer": "L'annuncio di tale misura ha notevolmente attenuato le tensioni sui mercati secondari dei titoli di Stato, che hanno registrato una rapida riduzione dei rendimenti, rimasti comunque su livelli superiori ai valori medi di febbraio 2020.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1100", "question": "A quanto si è attestato in media lo spread tra BTP e Bund a marzo 2020?", "answer": "Lo spread tra BTP e Bund a 10 anni si è attestato in media a 205 punti base a marzo, rispetto ai 140 punti a febbraio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1101", "question": "Come si sono comportati i rendimenti delle obbligazioni private durante la crisi?", "answer": "Sul mercato secondario i rendimenti degli indici obbligazionari hanno registrato un incremento pari a oltre due punti percentuali per il settore bancario e a un punto percentuale e mezzo per quello non finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1102", "question": "Quali banche hanno registrato l'aumento più elevato nei rendimenti obbligazionari?", "answer": "Le banche italiane hanno registrato l'aumento più elevato rispetto ai competitors stranieri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1103", "question": "Quali miglioramenti hanno registrato le banche italiane nell'ultimo decennio?", "answer": "Le banche italiane, dopo le pesanti conseguenze della crisi subprime e della crisi del debito sovrano, hanno registrato miglioramenti significativi dei propri attivi grazie a molteplici operazioni tese all'innalzamento del patrimonio e al miglioramento della qualità del patrimonio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1104", "question": "Cosa ha contribuito al miglioramento della qualità del patrimonio delle banche italiane?", "answer": "La qualità del patrimonio ha beneficiato della riduzione del peso dei titoli di Stato italiani presenti in portafoglio e del miglioramento della qualità del credito, dovuto a politiche di gestione del rischio più stringenti e a numerose operazioni di cessione di parte delle consistenze di crediti problematici accumulate nel tempo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1105", "question": "Come è cambiata la composizione della raccolta fondi delle banche italiane negli ultimi anni?", "answer": "Negli ultimi anni, gli istituti di credito italiani hanno cambiato la composizione della raccolta di fondi, riducendo il peso delle emissioni obbligazionarie e privilegiando la fonte più stabile rappresentata dai depositi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1106", "question": "Perché le banche italiane non hanno mostrato significativi miglioramenti reddituali?", "answer": "Le banche italiane non hanno mostrato significativi miglioramenti reddituali principalmente a causa della debolezza dei ricavi derivanti dalla tradizionale attività di intermediazione creditizia, il cosiddetto margine di interesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1107", "question": "Da cosa dipendono i ricavi derivanti dal margine di interesse delle banche?", "answer": "Tali ricavi dipendono essenzialmente dall'andamento dei tassi di interesse, che nell'ultimo decennio sono rimasti a livelli estremamente bassi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-mercati-finanziari"}},
{"id": "chunk_1108", "question": "Quali misure di distanziamento sociale sono state introdotte in Italia a seguito della pandemia di Covid-19?", "answer": "Le misure di distanziamento sociale introdotte nel nostro Paese a seguito della pandemia sono state severe e hanno riguardato dapprima la chiusura delle scuole e la sospensione di eventi pubblici (5 marzo 2020), poi a partire dal 9 marzo l'introduzione di varie limitazioni alla libera circolazione di persone anche all'interno dei confini nazionali, per culminare, il 28 marzo, nel fermo all'attività di diversi settori produttivi ritenuti non essenziali e nel ricorso, ove possibile, al lavoro da remoto (smart working).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1109", "question": "Quando sono state gradualmente rimosse le restrizioni in Italia?", "answer": "Le restrizioni sono state gradualmente rimosse a partire dal 4 maggio; dal 3 giugno, infine, sono stati rimossi i limiti alla libera circolazione nel territorio nazionale (cosiddetta fase due).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1110", "question": "Quali sono stati gli effetti economici immediati del lockdown in Italia?", "answer": "Gli effetti economici del lockdown sono apparsi sin da subito severi. Le previsioni sulle prospettive economiche pubblicate da diverse istituzioni internazionali mostrano un impatto della crisi molto più marcato in Italia rispetto a quello stimato per altre economie avanzate e, in particolare, per quelle dell'area euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1111", "question": "Perché l'impatto economico della crisi da Covid-19 è stato più marcato in Italia rispetto ad altre economie avanzate?", "answer": "Ciò dipende da vari fattori. In primo luogo in Italia l'epidemia si è diffusa con alcune settimane di anticipo rispetto alle altre economie avanzate. Tale circostanza ha determinato il mantenimento di misure di distanziamento sociale per un periodo più prolungato con impatti diretti legati alla sospensione delle attività dei settori sottoposti a fermo produttivo e impatti indiretti legati al deterioramento delle relazioni intersettoriali, al calo del reddito disponibile e quindi dei consumi dei lavoratori, al calo della fiducia e all'aumento dell'incertezza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1112", "question": "Quali dati ISTAT mostrano l'impatto economico della crisi nel primo trimestre del 2020?", "answer": "I dati ISTAT per il primo trimestre del 2020 mostrano che il Pil ha registrato un calo pari al 5,3% rispetto al trimestre precedente e al 5,4% nei confronti del primo trimestre del 2019.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1113", "question": "Quale settore economico italiano è stato tra i più colpiti dalla crisi?", "answer": "L'attività economica in Italia si caratterizza per il contributo significativo di uno dei settori più duramente colpiti dalla crisi, ossia il settore terziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1114", "question": "Qual è stato il contributo dell'industria turistica italiana al Pil nel 2017?", "answer": "Secondo il World Travel and Tourism Council (WTTC), nel 2017 l'industria turistica in Italia ha contribuito al 5,5% del Pil; se si considerano anche gli effetti indiretti, quali ad esempio quelli derivanti dai consumi dei lavoratori nel settore (che impiega circa il 6,5% degli occupati), il dato supera il 13%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1115", "question": "In quali settori si faranno sentire più a lungo gli effetti economici della pandemia?", "answer": "L'epidemia farà sentire i suoi effetti economici più intensamente e più a lungo nel settore dei servizi (a cui si riferiscono attività come il turismo, la ristorazione e l'intrattenimento) rispetto ad altri settori, quali ad esempio quello manifatturiero.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1116", "question": "Perché la dipendenza dalle esportazioni ha aggravato la crisi economica in Italia?", "answer": "L'economia italiana è fortemente dipendente dalle esportazioni. Questa circostanza determina un'ampia contrazione del prodotto nei periodi, come quello attuale, in cui il calo del commercio internazionale risulta particolarmente rilevante.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1117", "question": "Quali stime indicano la riduzione del commercio globale nel 2020?", "answer": "Stime recenti della Banca d'Italia e del FMI indicano una riduzione del commercio globale nel 2020 dell'ordine del 10% circa, valore analogo a quello registrato nel 2009.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1118", "question": "Quali conseguenze sociali ha avuto la crisi in Italia rispetto agli altri Paesi europei?", "answer": "In Italia anche le conseguenze sociali della crisi sembrerebbero potenzialmente più rilevanti rispetto agli altri Paesi europei.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1119", "question": "Cosa ha rivelato l'indagine dell'Osservatorio Giovani dell'Istituto Toniolo nel 2020?", "answer": "Un'indagine pubblicata ad aprile 2020, promossa dall'Osservatorio Giovani dell'Istituto Toniolo e dal Ministero per le Pari Opportunità e la Famiglia, evidenzia che il 60% dei giovani italiani ritiene che l'emergenza sanitaria avrà conseguenze negative sui propri piani futuri, seguiti a distanza dai giovani francesi e tedeschi (rispettivamente il 46% e il 42%).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1120", "question": "Cosa mostrano gli indicatori congiunturali sull'impatto del lockdown in Italia?", "answer": "L'intensità degli effetti delle misure di distanziamento sociale adottate in Italia si coglie attraverso alcuni indicatori congiunturali, disponibili quasi in tempo reale, relativi al traffico autostradale e alla domanda di energia elettrica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1121", "question": "Cosa indica l'incremento del traffico dati e voce comunicato dagli operatori di telefonia?", "answer": "L'incremento del traffico dati e voce comunicati dagli operatori di telefonia fissa e mobile fornisce un quadro dell'ampio ricorso al lavoro da remoto in molte attività in comparti pubblici e privati in Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1122", "question": "Qual è stata la riduzione delle importazioni e delle esportazioni italiane nel marzo 2020?", "answer": "La riduzione delle importazioni nel mese di marzo 2020 è stata pari al 16,8% su base congiunturale e del 19,7% su base tendenziale. Il calo delle esportazioni è stato rispettivamente del 16,8% e del 14,5%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1123", "question": "Quali Paesi rappresentano i principali mercati di approvvigionamento per l'Italia?", "answer": "L'importazione per mercato di approvvigionamento si attesta attorno al 20% per i primi due Paesi, ossia Germania e Francia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1124", "question": "Quale contrazione delle importazioni è stata registrata con riferimento alla Cina?", "answer": "La contrazione più rilevante si registra con riferimento alle importazioni dalla Cina (-27,4%), che da sole rappresentano il 7,5% dei beni complessivamente importati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1125", "question": "Quali Paesi hanno registrato il calo maggiore nelle esportazioni italiane?", "answer": "Il calo maggiore è stato registrato verso il Regno Unito (-24%), la Spagna (-20%) e la Svizzera (-19%), che assieme rappresentano circa il 16% delle esportazioni italiane. Significativo risulta anche il dato riferito alla Francia (-18%), che costituisce il secondo mercato di sbocco delle merci italiane con una quota di oltre il 10% sul totale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-in-italia"}},
{"id": "chunk_1126", "question": "Quali misure hanno adottato governi, banche centrali e autorità di regolazione dei mercati finanziari per far fronte alla crisi da Covid-19?", "answer": "Governi, banche centrali e Autorità di regolazione dei mercati finanziari hanno adottato molteplici misure per far fronte agli impatti della crisi sull'attività economica e sul sistema finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1127", "question": "Quali misure sono state adottate a livello europeo per sostenere l'economia durante la crisi da Covid-19?", "answer": "A livello europeo, è stata resa disponibile una parte dei fondi di coesione già stanziati nel bilancio dell'Unione attraverso un'iniziativa denominata CRII (Coronavirus Response Investment Initiative). Per attenuare le ripercussioni occupazionali della crisi è stato inoltre attivato il programma SURE (Support to mitigate Unemployment Risks in an Emergency) con una disponibilità di 100 miliardi di euro che saranno utilizzati a completamento delle misure di cassa integrazione adottate da vari paesi europei.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1128", "question": "Quale ruolo ha avuto la Banca europea degli investimenti durante la crisi da Covid-19?", "answer": "La Banca europea degli investimenti (BEI) ha proposto l'istituzione di un fondo paneuropeo di garanzia per le piccole e medie imprese di ammontare pari a 25 miliardi di euro che punterebbe a mobilitare risorse fino a 200 miliardi di euro in forma di finanziamenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1129", "question": "Quale accordo è stato raggiunto in ambito europeo tra aprile e maggio 2020?", "answer": "Tra aprile e maggio è stato raggiunto un accordo in ambito europeo finalizzato a dotare il Meccanismo europeo di stabilità (European Stability Mechanism, ESM) di un'ulteriore linea di credito precauzionale rinforzata per un ammontare complessivo di 240 miliardi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1130", "question": "Cosa ha proposto la Commissione europea il 27 maggio 2020?", "answer": "Il 27 maggio la Commissione europea ha proposto un nuovo fondo europeo temporaneo per la ricostruzione denominato Next Generation EU per un ammontare di 750 miliardi di euro, oltre al rafforzamento dei fondi di bilancio dell'Unione Europea per il periodo 2021-2027 per un ammontare complessivo di 1.100 miliardi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1131", "question": "Quali misure hanno adottato la BCE e l'EBA per sostenere il sistema bancario durante la crisi da Covid-19?", "answer": "La Banca Centrale Europea (BCE) e l'Autorità europea di vigilanza delle banche (EBA) hanno varato misure fortemente espansive per sostenere la liquidità del sistema bancario e consentire agli istituti di credito di continuare a finanziare adeguatamente le attività produttive e le famiglie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1132", "question": "Quali sono state le principali misure della BCE per sostenere la liquidità durante la crisi da Covid-19?", "answer": "Tra le tante misure adottate, le più rilevanti sono: la riduzione dei tassi di interesse di riferimento; l'avvio di nuove operazioni di rifinanziamento che consentiranno alle banche di ottenere una maggiore liquidità dalla BCE a condizioni più vantaggiose; la mitigazione di alcuni criteri di vigilanza che potrebbero indurre le banche a ridurre i prestiti ai privati in momenti di recessione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1133", "question": "Cosa prevede il Pandemic Emergency Purchase Programme (PEPP)?", "answer": "Sono stati ampliati i programmi di acquisto di attività finanziarie pubbliche e private, inclusa la carta commerciale e le obbligazioni emesse da società non finanziarie (Pandemic Emergency Purchase Programme, PEPP).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1134", "question": "Quali interventi sono stati adottati a livello nazionale in Italia per sostenere imprese e famiglie?", "answer": "A livello nazionale sono stati varati interventi volti a sostenere la liquidità delle imprese e i redditi delle famiglie e ad assicurare l'accesso al credito, quali ad esempio il rilascio di garanzie pubbliche sui prestiti alle imprese e l'assegnazione di sussidi alle famiglie in difficoltà. Sono stati inoltre differiti gli adempimenti fiscali a favore di diverse categorie di soggetti privati ed erogate moratorie creditizie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1135", "question": "Quali effetti hanno avuto le misure sanitarie e di sostegno economico sulla finanza pubblica?", "answer": "Le misure poste in essere dai Governi nazionali per adeguare il sistema sanitario all'emergenza in atto e sostenere famiglie e imprese hanno generato un significativo aumento della spesa pubblica, in concomitanza con una riduzione delle entrate dovute al differimento di alcuni adempimenti fiscali e alla riduzione della base imponibile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1136", "question": "In che modo le misure europee possono mitigare le conseguenze sui conti pubblici?", "answer": "Le misure adottate a livello europeo potranno almeno parzialmente mitigare le ripercussioni negative che un tale aumento della spesa avrà sull'equilibrio dei conti pubblici, specie nei paesi maggiormente indebitati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1137", "question": "Cosa è accaduto ai mercati finanziari durante la crisi da Covid-19?", "answer": "L'andamento dei mercati finanziari in occasione della crisi innescata dalla pandemia di Covid-19 è in gran parte collegato alle aspettative negative sulle prospettive future dell'attività economica. Il crollo delle quotazioni osservato nel mese di marzo 2020 è stato solo un sintomo, e non la causa, della crisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1138", "question": "Come hanno reagito le Autorità di vigilanza dei mercati finanziari europei durante la crisi?", "answer": "Le Autorità di vigilanza dei mercati finanziati sono intervenute al fine di salvaguardare l'integrità e il buon funzionamento dei mercati e di garantire la tutela degli investitori, mettendo in campo diverse restrizioni all'operatività.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1139", "question": "Quali provvedimenti ha preso l'ESMA nel contesto della pandemia?", "answer": "L'ESMA (la European Securities and Markets Authority) ha pubblicato raccomandazioni e chiarimenti volti a garantire il rispetto della disciplina comunitaria nel difficile contesto generato dalla pandemia, coinvolgendo nel processo decisionale le Autorità nazionali competenti (inclusa la CONSOB).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1140", "question": "Quali misure ha adottato la CONSOB per limitare la volatilità e proteggere il mercato durante la crisi da Covid-19?", "answer": "La CONSOB ha assunto misure in materia di vendite allo scoperto e posizioni nette corte volti a contenere la volatilità dei mercati finanziari e a evitare attacchi speculativi ai titoli delle imprese italiane.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1141", "question": "Quali altre misure ha adottato la CONSOB a beneficio dei soggetti vigilati durante la pandemia?", "answer": "A beneficio dell'operatività dei soggetti vigilati, l'Istituto ha adottato misure di differimento dei termini per l'adempimento di diversi obblighi a carico dei soggetti vigilati e dei termini dei procedimenti in corso presso l'Arbitro per le controversie finanziarie (ACF) e dei procedimenti sanzionatori in corso, con l'obiettivo di assicurare a chi è destinatario di un procedimento sanzionatorio piena facoltà di partecipazione al procedimento stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1142", "question": "Cosa ha fatto la CONSOB per proteggere gli investitori da truffe online durante la crisi da Covid-19?", "answer": "Con riferimento ai tentativi di abusi e truffe online, nel mese di aprile 2020 la CONSOB ha messo in guardia i risparmiatori segnalando attraverso un'apposita Avvertenza (warning) che le drammatiche notizie sui focolai virali possono rappresentare un'opportunità per i malintenzionati di diffondere informazioni false o fuorvianti finalizzate a trarre indebito vantaggio dai timori della pandemia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1143", "question": "Cosa sono le vendite allo scoperto e perché possono essere restritte in momenti di crisi?", "answer": "Le vendite allo scoperto sono operazioni in cui il venditore non possiede ancora il titolo che si è impegnato a vendere e che acquisterà in seguito. In alcuni casi le vendite allo scoperto possono determinare una riduzione significativa e repentina dei corsi dei titoli, creando disordine nei mercati e incrementando la volatilità, per questo possono essere soggette a restrizioni in periodi di crisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1144", "question": "Qual è la differenza tra vendite allo scoperto covered e naked?", "answer": "Le vendite allo scoperto covered sono quelle assistite dal prestito dei titoli mentre quelle naked, invece, non lo sono, per cui il venditore dovrà ricercare sul mercato le azioni da consegnare al compratore al fine di regolare la propria posizione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1145", "question": "Cosa sono le posizioni nette corte e come vengono regolate?", "answer": "L'insieme delle posizioni corte che un operatore ha assunto su un titolo definisce la posizione corta lorda sul titolo. La posizione corta netta invece si ottiene sottraendo dalla posizione corta lorda la somma delle posizioni lunghe sullo stesso titolo. Le posizioni nette corte in azioni e titoli di Stato sono soggette a obblighi di segnalazione all'Autorità di vigilanza al superamento di determinate soglie e possono essere temporaneamente vietate al ricorrere di alcune condizioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1146", "question": "Come si sono espresse le istituzioni sovranazionali riguardo alla chiusura dei mercati finanziari durante la crisi Covid-19?", "answer": "In occasione della crisi Covid-19 le istituzioni sovranazionali quali G20, IOSCO ed ESMA si sono pronunciate contro la chiusura dei mercati. Solo la Borsa di Manila è stata chiusa, per due giorni, contestualmente allo scoppio dell'emergenza sanitaria, per motivi tecnici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1147", "question": "Quali provvedimenti ha adottato la CONSOB nel marzo 2020 in materia di vendite allo scoperto?", "answer": "Nel mese di marzo 2020 la CONSOB è intervenuta a più riprese con provvedimenti restrittivi di alcuni tipi di operatività sui mercati. Il 12 marzo 2020, la CONSOB ha vietato temporaneamente le vendite allo scoperto su 85 titoli azionari italiani quotati sull'MTA per l'intera giornata di negoziazione di venerdì 13 marzo 2020.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1148", "question": "Cosa ha deciso la CONSOB il 18 marzo 2020 riguardo le posizioni nette corte?", "answer": "A partire dalla seduta del 18 marzo la CONSOB ha introdotto un divieto alle posizioni nette corte relativo a tutte le azioni negoziate sul mercato regolamentato italiano per un periodo di tre mesi. Il provvedimento è stato finalizzato a vietare ogni forma di operazione speculativa ribassista, anche effettuata tramite derivati o altri strumenti finanziari nonché le operazioni ribassiste infragiornaliere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1149", "question": "Perché la CONSOB ha sospeso il provvedimento di divieto alle posizioni nette corte il 18 maggio 2020?", "answer": "Il 18 maggio 2020 alla luce della progressiva normalizzazione delle condizioni generali di mercato, la CONSOB ha deciso di sospendere tale provvedimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1150", "question": "Qual è stato l'obiettivo dell'abbassamento temporaneo della soglia di comunicazione delle posizioni nette corte deciso dall'ESMA?", "answer": "La misura è stata assunta con l'obiettivo di fornire alle autorità di vigilanza informazioni più dettagliate sull'operatività in un momento di forti tensioni sui mercati finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-misure-sostegno"}},
{"id": "chunk_1151", "question": "Quando e dove è scoppiata l'infezione di Covid-19?", "answer": "Tra la fine del 2019 e l'inizio del 2020 un'infezione generata da un virus della famiglia SARS-Covid, il cosiddetto Covid-19, scoppiata a Wuhan, in Cina, si è rapidamente diffusa in tante nazioni di tutti i continenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1152", "question": "Quali sono gli effetti dell'infezione di Covid-19 sulle persone?", "answer": "Nella maggior parte dei casi, le persone che hanno contratto l'infezione possono guarire grazie a protocolli e terapie già in uso, senza bisogno di trattamenti particolari; nei casi più gravi, tuttavia, la malattia può degenerare secondo dinamiche ancora non completamente comprese, anche attraverso l'aggravamento di patologie pregresse (prevalentemente di natura polmonare) fino al decesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1153", "question": "Perché la crisi da Covid-19 è considerata un evento epocale?", "answer": "La crisi connessa alla diffusione della pandemia di Covid-19 rappresenta un evento epocale destinato a generare forti ripercussioni economiche e sociali, allo stato attuale difficilmente stimabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1154", "question": "Quanti Paesi erano coinvolti nella pandemia di Covid-19 all'11 maggio 2020?", "answer": "Alla data dell'11 maggio 2020 la pandemia coinvolge 215 Paesi, conta quasi 5 milioni di casi accertati in tutto il mondo e ha provocato circa 318 mila morti (corrispondente a un tasso di letalità complessivo del 7'%' circa, a cui corrispondono differenze tra Paesi in alcuni casi significative).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1155", "question": "Quali altre gravi patologie respiratorie sono comparse in anni recenti?", "answer": "La pandemia di Covid-19 si inserisce nel novero delle gravi patologie respiratorie comparse in anni recenti: la SARS (Sindrome respiratoria acuta e severa), rilevata in Cina a fine 2002; il virus H1N1 (cosiddetta influenza suina), rilevato in Messico nel 2009; il MERS-CoV (Sindrome respiratoria del Medio Oriente), diffusosi nel 2012 dapprima in Arabia Saudita e poi in altri Paesi del Medio Oriente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1156", "question": "In cosa differivano i virus SARS, H1N1 e MERS-CoV rispetto al Covid-19?", "answer": "Questi virus erano caratterizzati da un inferiore tasso di morbilità (ossia erano meno contagiosi) del Covid-19, pur facendo registrare un tasso di mortalità più elevato (come nel caso di SARS e MERS-CoV).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1157", "question": "Quali fragilità hanno mostrato i sistemi sanitari durante la pandemia?", "answer": "Al propagarsi dell'infezione di Covid-19 a livello globale, sono emerse le fragilità di molti sistemi sanitari nazionali. Per allentare la pressione sulle strutture esistenti, sono stati approntati ospedali dedicati ai malati di Covid-19; in parallelo, sono state avviate innumerevoli ricerche volte a individuare cure efficaci e vaccini sicuri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1158", "question": "Perché i Governi hanno adottato misure di distanziamento sociale?", "answer": "Poiché il virus è apparso sin da subito molto contagioso e la trasmissione da uomo a uomo risulta possibile anche da individui asintomatici, i Governi dei Paesi colpiti sono ricorsi all'unica misura allo stato in grado di rallentare il ritmo del contagio, ossia il distanziamento sociale, secondo tempistiche e intensità variabili da caso a caso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1159", "question": "Quali sono state le principali misure adottate in Europa per contenere la pandemia?", "answer": "In Europa, le prime misure adottate in tal senso sono state la sospensione dei voli da e per la Cina, cui hanno fatto seguito la chiusura di scuole, le limitazioni alla libera circolazione di persone anche all'interno dei confini nazionali, la sospensione di eventi pubblici, la chiusura di diverse attività produttive non essenziali (cosiddetto lockdown).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-covid-19"}},
{"id": "chunk_1160", "question": "Che cosa fu la crisi del 1929?", "answer": "La grave crisi economico-finanziaria del 1929, iniziata negli Stati Uniti d'America, sconvolse l'economia mondiale dalla fine degli anni venti fino a buona parte del decennio successivo, con devastanti ripercussioni sociali e politiche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1161", "question": "Quali furono le cause remote della crisi del 1929?", "answer": "Il boom economico che gli USA avevano sperimentato quasi ininterrottamente dall'inizio della prima guerra mondiale, rappresentato da una forte espansione del Prodotto Interno Lordo grazie alle numerose innovazioni tecnologiche (radio, telefono, energia elettrica), allo sviluppo dell'industria automobilistica, alla rapida crescita di settori come quello del petrolio e alla conseguente espansione del settore delle costruzioni di uffici, fabbriche e case, aveva costituito il motore del rialzo dell'indice azionario Dow Jones relativo al settore industriale a partire da metà 1922, riflettendo l'acquisita supremazia economica nel mondo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1162", "question": "Quali erano i livelli dell'indice azionario Dow Jones prima del crollo?", "answer": "Nel periodo che va dal 1922 al settembre 1929, l'indice azionario era passato da 63,0 a 381,17 ossia aveva registrato un incremento di circa il 500%, numero che esprime bene il senso di entusiasmo diffuso dei cosiddetti \"ruggenti anni-venti\" degli americani.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1163", "question": "Quando avvenne il crollo di Wall Street del 1929?", "answer": "Il crollo dell'indice di Wall Street avvenne il 24 ottobre del 1929 (noto come il giovedì nero di Wall Street), in cui 13 milioni di azioni furono vendute senza limite di prezzo, e fu seguito da un secondo il 28 ottobre e un terzo il 29 ottobre (martedì nero) con circa 16 milioni di azioni vendute in un solo giorno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1164", "question": "Quali furono gli effetti immediati del crollo di Wall Street?", "answer": "Il Dow Jones Industrial Average subì una flessione del 40% in un mese e il panico si diffuse a macchia d'olio: fu l'inizio di un ciclo economico altamente recessivo su scala mondiale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1165", "question": "Che ruolo ebbe la politica monetaria della Riserva Federale nella crisi?", "answer": "La crisi affonda le sue radici in una politica monetaria fortemente espansiva della Riserva Federale, a partire dalla primavera del 1927, che rese disponibili a banche e individui una massa rilevante di liquidità, impiegata in larga parte in acquisto di azioni quotate a Wall Street da parte di privati anche per il tramite di investment trust.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1166", "question": "Cosa alimentò la speculazione azionaria prima del 1929?", "answer": "Dall'inizio del 1928 la speculazione sui titoli azionari alimentò un boom senza precedenti nei volumi di azioni giornalmente compravendute e rese possibile l'innescarsi di una spirale di rialzi dei prezzi, sospinta dalla immaginifica rappresentazione di prospettive floride di crescita economica e da conseguenti aspettative irrealistiche di profitti futuri delle società industriali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1167", "question": "Che clima psicologico dominava negli anni precedenti la crisi?", "answer": "Un senso di forte fiducia circa lo stato dell'economia era largamente diffuso tra la gente comune e questo costituiva il propellente del comportamento degli investitori-speculatori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1168", "question": "Come descrisse John K. Galbraith il clima economico dell'epoca?", "answer": "John K. Galbraith descrive questo \"clima psicologico\" di ostentato (e artificioso) ottimismo economico affermando: \"Affermando solennemente che la prosperità continuerà, si può contribuire, così si crede, ad assicurare che la prosperità effettivamente continui. Specialmente fra gli uomini d'affari è grande la fede nell'efficacia di tale formula magica\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1169", "question": "Che cos'è il contratto di \"riporto\" nel contesto della crisi del 1929?", "answer": "Il contratto di \"riporto\" era una tecnica di acquisto delle azioni tramite contratti conclusi dagli investitori privati con gli operatori di borsa in forza dei quali quest'ultimi fornivano ai propri clienti a prestito la liquidità necessaria agli acquisti di titoli ricevendo a garanzia i titoli medesimi, con l'obbligo di restituzione del prestito stesso a scadenza ravvicinata (tipicamente, un mese).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1170", "question": "Come funzionava il circuito finanziario che alimentava la bolla?", "answer": "Questo circuito finanziario \"perfetto\" costituito da Riserva Federale-banche-operatori di borsa-investitori privati si reggeva sul presupposto che gli incrementi di prezzo dei titoli registrati sul mercato di Wall Street fossero superiori ai tassi d'interesse sui prestiti concessi nel periodo di riferimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1171", "question": "Cosa accade in generale nelle situazioni di bolla finanziaria?", "answer": "Come si verifica in tutte le situazioni di \"bolla finanziaria\", basate su speculazione ed euforia, il mercato prima o poi torna in equilibrio e questo accade con una spinta emotiva alle vendite incontrollate pari d'intensità, ma di segno opposto, a quella che ne sorregge gli acquisti in precedenza; l'euforia che origina la bolla viene seguita da fenomeni di panico che ne decretano lo scoppio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1172", "question": "Quali furono i segnali premonitori del crollo del 1929?", "answer": "Nel marzo del 1929, i segnali di un possibile crollo del mercato borsistico erano stati avvertiti dalla Riserva Federale che pur decise di non agire. Nel settembre dello stesso anno, l'indice di borsa iniziò a muoversi in modo irregolare con una tendenza al ribasso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1173", "question": "Cosa successe durante il panico di ottobre 1929?", "answer": "Quando nell'ottobre del 1929 si assistette ad una brusca correzione dei prezzi azionari registrati a Wall Street, gli investitori furono presi dalla paura di un inizio della corsa al ribasso dei prezzi e affluirono freneticamente sul mercato per vendere azioni fino a generarne il tracollo in preda al panico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1174", "question": "Come reagirono gli operatori di borsa e le banche?", "answer": "Gli operatori di borsa iniziarono a richiedere maggiori garanzie per i prestiti concessi ai propri clienti. La forte esposizione delle banche sul mercato azionario indusse i risparmiatori, intimoriti dalle ripercussioni sui propri depositi, a richiederne il ritiro, dando luogo ad una vera e propria \"corsa agli sportelli\" (bank run).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1175", "question": "Quale banca fu tra le prime a fallire?", "answer": "La Bank of the United States, ritenuta un colosso del tempo contando sui depositi di oltre 400.000 risparmiatori, fu una delle prime banche a dichiarare bancarotta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1176", "question": "Come si estese la crisi al settore produttivo?", "answer": "La crisi si estese alla borsa merci: i prezzi di prodotti agricoli, del cotone e delle materie prime non agricole crollarono. L'indice generale della produzione industriale registrò una flessione: ciò significava che la produzione di acciaio e ghisa, di carbone, di automobili e di altri manufatti scendeva.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1177", "question": "Quali erano le cause reali profonde della crisi?", "answer": "La contrazione dell'economia statunitense a partire dagli inizi del 1929 ha origini nella seconda parte degli anni Venti quando si registra una diffusa riduzione dei prezzi dei beni agricoli e, in parte, dei manufatti, dovuta al notevole incremento della produzione connessa all'uso intensivo delle moderne tecniche e dell'energia a basso costo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1178", "question": "Perché la sovrapproduzione contribuì alla crisi?", "answer": "La sovra-produzione agricola, prima, e industriale, poi, era anche frutto di una più ridotta capacità degli Stati europei d'importare beni e prodotti da oltre Atlantico per effetto delle conseguenze della Guerra.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1179", "question": "Quale fu la risposta del governo statunitense alla crisi agricola?", "answer": "La risposta governativa negli Stati Uniti alla riduzione di domanda e prezzi dei beni agricoli fu primariamente tesa a difendere il settore agricolo con una politica protezionistica di dazi, estesa nel giugno del 1930 anche agli altri settori che via via entrarono in crisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1180", "question": "Quali furono gli effetti del protezionismo dopo il 1929?", "answer": "L'approccio protezionistico si rafforzò a seguito del crollo di Wall Street dell'ottobre del '29 e la sua estensione a livello di tutti i paesi esportatori portò a un collasso del commercio internazionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1181", "question": "Quali furono le conseguenze globali della Grande Depressione?", "answer": "La Grande Depressione ebbe effetti recessivi devastanti ad ampio spettro geografico sotto diversi profili: anche i prezzi dei prodotti industriali subirono una drastica pressione al ribasso dalla contrazione della domanda, determinando gravi difficoltà per le imprese nel far fronte ai loro debiti e alimentando la contrazione del commercio internazionale e di conseguenza dei redditi dei lavoratori, del reddito fiscale, dei prezzi e dei profitti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1182", "question": "Quali furono gli effetti economici e sociali negli Stati Uniti?", "answer": "Il tracollo economico e finanziario mise in ginocchio centinaia di migliaia di americani, con il fallimento di numerose aziende, l'incremento vertiginoso della disoccupazione (oltre il 25% della popolazione attiva) e una severa contrazione del reddito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1183", "question": "Come gli Stati Uniti contribuirono all'espansione della crisi nel mondo?", "answer": "Le esigenze nazionali spinsero gli istituti finanziari degli Stati Uniti a richiamare i prestiti erogati all'estero (30 miliardi di dollari) estendendo gli effetti recessivi della crisi su scala mondiale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1184", "question": "Che cosa si intende per \"bolla azionaria\"?", "answer": "Il fenomeno di acquisti incontrollati che spingono in alto i prezzi delle azioni prende il nome di \"bolla azionaria\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-crisi-del-29"}},
{"id": "chunk_1185", "question": "Quando il governo greco ha aggiornato le proiezioni di finanza pubblica e quali effetti ha avuto sul rating?", "answer": "Nel ottobre 2009 il governo greco aggiorna le proiezioni di finanza pubblica portando il rapporto deficit/Pil dal 3,7% al 12,7%. L'agenzia di Rating Fitch porta da A ad A- il rating sul debito pubblico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1186", "question": "Cosa ha fatto il Portogallo nel novembre 2009 riguardo al deficit pubblico?", "answer": "Nel novembre 2009 anche il Portogallo rivede al rialzo la stima del deficit pubblico in rapporto al PIL portandole dal 5,9% all'8%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1187", "question": "Quali downgrade ha subito la Grecia nel dicembre 2009?", "answer": "Nel dicembre 2009 Fitch declassa il rating sovrano della Grecia da A- a BBB+, seguita dopo pochi giorni da Standard & Poors che porta da A a BBB+ il rating sul debito pubblico greco. A fine mese anche Moody's declassa la Grecia portando il rating sul merito di credito del paese da A1 ad A2.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1188", "question": "Quali misure erano previste dal piano di stabilità approvato dal governo greco nel gennaio 2010?", "answer": "Nel gennaio 2010 il governo greco approva il piano di stabilità che prevede un calo del rapporto deficit/Pil al 3% entro il 2012.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1189", "question": "Cosa prevedeva il piano triennale approvato dall'Unione Europea nel febbraio 2010 per la Grecia?", "answer": "Nel febbraio 2010 l'Unione Europea approva il piano triennale di risanamento dei conti pubblici della Grecia che prevede, tra le varie misure, il congelamento dei salari ed il blocco delle assunzioni pubbliche per il 2010, la riduzione del 10% delle spese di tutti i ministeri, l'aumento dell'età pensionabile, l'introduzione di nuove imposte sui carburanti e sui dividendi azionari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1190", "question": "Quando è stato varato il piano di assistenza finanziaria per la Grecia e a quanto ammontava?", "answer": "Nel aprile 2010 l'Eurogruppo vara il piano di assistenza finanziaria (emergency loan facility) per un ammontare di 45 miliardi di euro (di cui 15 messi a disposizione dal FMI).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1191", "question": "Qual è stato il primo grande intervento di salvataggio per la Grecia nel maggio 2010?", "answer": "Nel maggio 2010 i paesi dell'Eurozona e il FMI approvano un prestito di salvataggio per la Grecia di 110 miliardi di euro (30 da parte del FMI), subordinato alla realizzazione di severissime misure di austerità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1192", "question": "Cos'è lo European Financial Stability Facility (EFSF) e quando è stato creato?", "answer": "Nel giugno 2010 l'Eurogruppo approva la creazione dello European Financial Stability Facility (EFSF), fondo intergovernativo di durata triennale, dotato di garanzie fornite dagli Stati partecipanti per un ammontare complessivo di 440 miliardi di euro. L'istituzione di tale fondo ha lo scopo di potenziare i meccanismi di stabilità dell'area dell'euro e di fornire sostegno finanziario agli Stati membri in difficoltà.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1193", "question": "Cosa prevedeva la riforma Basilea III annunciata nel settembre 2010?", "answer": "Nel settembre 2010 il Comitato di Basilea per la vigilanza bancaria annuncia una riforma del regime patrimoniale degli istituti di credito che prevede un innalzamento di tutti i presidi a salvaguardia dei rischi fronteggiati dalle banche in modo da garantirne una maggiore solidità. La riforma prende il nome di Basilea III.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1194", "question": "Quale fondo ha sostituito l'EFSF e quando è stato istituito?", "answer": "Nel dicembre 2010 l'Eurogruppo istituisce lo European Stability Mechanism (ESM), meccanismo di gestione permanente delle crisi che sostituirà l'EFSF a partire dal primo luglio 2013.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1195", "question": "Quando l'Irlanda ha ricevuto il piano di sostegno e a quanto ammontava?", "answer": "Nel novembre 2010 le istituzioni europee con la partecipazione del FMI approvano un piano di sostegno per l'Irlanda. Il prestito ammonta a 85 miliardi di euro e prevede l'intervento dell'EFSF.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1196", "question": "Cosa è accaduto nel marzo 2011 riguardo la Grecia e l'EFSF?", "answer": "Nel marzo 2011 viene aumentata la capacità di finanziamento dell'EFSF (da 440 a 780 miliardi di euro) e dell'ESM (fissata a 550 miliardi di euro). Viene accolta la richiesta di una rinegoziazione del prestito concesso alla Grecia con riduzione del tasso e allungamento della scadenza in cambio di un nuovo piano di austerità e di privatizzazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1197", "question": "Quando il Portogallo ha richiesto ufficialmente aiuti all'UE e per quale cifra?", "answer": "Nel aprile 2011 il forte squilibrio nei conti pubblici aggravato dalla recessione porta il Portogallo a ufficializzare la richiesta di aiuti all'UE per una cifra tra i 60 e gli 80 miliardi di euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1198", "question": "Qual è stato l'accordo raggiunto a maggio 2011 tra il governo portoghese e la Troika?", "answer": "Nel maggio 2011 si raggiunge un accordo fra il Governo portoghese e UE, BCE e FMI per la concessione di un prestito di 78 miliardi di euro in tre anni. Il piano di aggiustamento dei conti pubblici prevede un taglio del deficit dall'8,6% del PIL nel 2010 al 3% nel 2013 e privatizzazioni per 5,5 miliardi di euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1199", "question": "Cosa ha fatto la BCE nel dicembre 2011 per contrastare la riduzione dell'offerta di credito?", "answer": "Nel dicembre 2011 la BCE vara due operazioni di rifinanziamento (Long Term Refinancing Operations – LTROs) a tre anni, per un ammontare complessivo di oltre 1.000 miliardi di euro al tasso agevolato dell'1%. Nella prima asta vengono assegnati fondi a più di 500 banche europee per un ammontare di 490 miliardi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1200", "question": "Quando è stato approvato il Fiscal Compact e cosa stabilisce?", "answer": "Nel marzo 2012 viene approvato il Fiscal Compact, un accordo tra 26 Stati membri dell'Unione europea che stabilisce che il deficit strutturale non possa eccedere lo 0,5% del PIL e che il debito pubblico in rapporto al PIL debba diminuire ogni anno di 1/20 della distanza tra il suo livello effettivo e la soglia del 60%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1201", "question": "Quale programma di acquisti ha annunciato la BCE nel gennaio 2015?", "answer": "Nel gennaio 2015 la BCE annuncia l'estensione del programma di acquisti di ABS e covered bonds anche ai titoli pubblici dell'Area euro (Expanded Asset Purchase Programme, EAPP o cosiddetto 'quantitative easing'). Il programma prevede acquisti di titoli fino a 60 miliardi di euro mensili per un ammontare complessivo di circa 1.140 miliardi di euro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1202", "question": "Quale fu la dichiarazione di Mario Draghi nell'agosto 2012 e quale effetto ebbe?", "answer": "Nel agosto 2012 le dichiarazioni del governatore BCE Mario Draghi (\"l'euro è irreversibile\" e \"la BCE è pronta a fare tutto il necessario\") favoriscono un progressivo calo delle tensioni sui mercati finanziari alimentando aspettative positive degli investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1203", "question": "Cosa annunciò la BCE nel settembre 2012 per contrastare le tensioni sui mercati?", "answer": "Nel settembre 2012 la BCE annuncia l'Outright Monetary Transactions (OMT), ovvero si dichiara disponibile ad acquistare titoli governativi in quantità illimitata nel caso in cui lo spread mostri dinamiche incompatibili con la corretta trasmissione dei segnali di politica monetaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano"}},
{"id": "chunk_1204", "question": "Da cosa trae origine la crisi del debito sovrano nell'Area euro?", "answer": "La crisi del debito sovrano nell'Area euro trova le sue radici nella crisi del settore dei mutui residenziali statunitensi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1205", "question": "Quali effetti ebbe la crisi subprime sugli istituti di credito europei?", "answer": "In seguito alla crisi subprime, numerosi istituti di credito europei hanno sperimentato gravi difficoltà e sono stati salvati da interventi pubblici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1206", "question": "Come gli interventi pubblici di salvataggio hanno inciso sulla finanza pubblica dei Paesi europei?", "answer": "Questi interventi hanno esacerbato gli squilibri di finanza pubblica dei Paesi più vulnerabili, concorrendo a provocare una contrazione del Pil a livello globale dell'uno per cento circa nel 2009.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1207", "question": "Quali furono gli effetti della crisi sul Pil dei paesi industrializzati e dell'Italia?", "answer": "I paesi industrializzati hanno registrato una variazione del prodotto interno lordo negativa. Per l'Italia la contrazione del prodotto nel 2009 è risultata prossima al 5 per cento, configurando una delle più gravi recessioni dal dopoguerra.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1208", "question": "Quali differenze presentavano i paesi dell'eurozona prima della crisi del debito sovrano?", "answer": "I paesi dell'eurozona presentavano differenze significative nelle condizioni di finanza pubblica e nel tasso di crescita. I Paesi core si connotavano per livelli contenuti del debito pubblico e per un'attività economica più solida, mentre i Paesi PIIGS si caratterizzavano per una maggiore vulnerabilità legata a dinamiche non sostenibili del debito pubblico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1209", "question": "Quali furono le principali cause della vulnerabilità dei Paesi PIIGS?", "answer": "La vulnerabilità dei Paesi PIIGS era dovuta all'indebitamento accumulato negli anni, all'incremento incontrollato del deficit, ai bassi tassi di crescita del PIL e agli oneri delle operazioni di salvataggio degli istituti bancari in crisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1210", "question": "Cosa accadde nell'ottobre 2009 che segnò l'inizio della crisi del debito sovrano?", "answer": "Il dissesto dei conti pubblici della Grecia, reso noto nell'ottobre 2009, ha segnato il passaggio alla fase della crisi del debito sovrano, interrompendo la ripresa già incerta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1211", "question": "Quali paesi furono inizialmente colpiti dalla crisi del debito sovrano e come si diffuse successivamente?", "answer": "La crisi ha avuto epicentro nei paesi periferici dell'eurozona (Portogallo, Irlanda e Grecia) per poi estendersi nel corso del 2011 a Spagna e Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1212", "question": "Quali furono i primi interventi di salvataggio nel 2010?", "answer": "Nel corso del 2010, a maggio in particolare, i paesi dell'Eurozona e il FMI hanno approvato un prestito di salvataggio per la Grecia di 110 miliardi di euro (30 da parte del FMI).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1213", "question": "Cosa accadde al sistema bancario irlandese nel novembre 2010?", "answer": "Nel mese di novembre 2010 è emersa la crisi del sistema bancario irlandese: il Governatore della banca centrale irlandese ha rivelato che le perdite delle banche domestiche ammontavano a 85 miliardi di euro (pari al 55% del PIL).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1214", "question": "Quale aiuto ricevette il Portogallo nel 2011?", "answer": "A maggio 2011, UE, BCE e FMI (la cosiddetta Troika) hanno concesso un prestito di 78 miliardi di euro al Governo portoghese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1215", "question": "Come reagirono i mercati finanziari alle tensioni dei paesi in crisi?", "answer": "Le tensioni di questi paesi si sono riflesse immediatamente su tutti i principali mercati finanziari, ove si sono registrati cali di ampie dimensioni, in alcuni casi comparabili a quelli verificatisi nel corso della crisi del 1929.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1216", "question": "Come influenzarono le agenzie di rating la crisi?", "answer": "Le maggiori agenzie di rating hanno abbassato il merito di credito di diversi paesi europei e di diverse banche, amplificando in molti casi le turbolenze sui mercati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1217", "question": "Quale settore fu più esposto al contagio della crisi?", "answer": "Il comparto dei titoli bancari, in ragione dei profondi legami con il settore pubblico, è risultato quello maggiormente esposto al contagio, tanto da far registrare, nel 2011, un ribasso superiore a quello degli altri comparti in tutte le economie avanzate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1218", "question": "In che modo la crisi si trasmise all'economia reale?", "answer": "Gli effetti della crisi hanno trovato nelle dinamiche connesse alle concessioni di credito bancario un veloce canale di trasmissione verso l'economia reale, con forti segnali di irrigidimento degli standard di concessione del credito da parte del sistema bancario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1219", "question": "Quali tipi di razionamento del credito si osservarono?", "answer": "Si osservarono il razionamento in senso forte, consistente in un vero e proprio rifiuto di accordare nuovi finanziamenti, e il razionamento in senso debole, consistente nella concessione di finanziamenti a condizioni tanto onerose da indurre il debitore a rifiutare l'offerta di credito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1220", "question": "Quali sono i principali canali di trasmissione della crisi del debito sovrano alle banche domestiche?", "answer": "Le banche detengono quote consistenti di titoli pubblici in portafoglio. Tensioni sul mercato dei titoli di Stato comportano un deterioramento della qualità degli attivi bancari e un aumento del costo della raccolta. Inoltre, il merito di credito delle banche risente dello standing creditizio dello Stato di appartenenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1221", "question": "Quali furono gli effetti delle manovre di austerità?", "answer": "Le manovre di contenimento della spesa (cosiddetta austerity) attuate dai Governi hanno rallentato la crescita inducendo, in alcuni casi, una vera e propria recessione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1222", "question": "Quando la crisi colpì l'Italia e con quali effetti sul debito?", "answer": "La crisi si è manifestata in tutta la sua gravità a partire dai primi giorni di luglio 2011, quando ha investito anche l'Italia. Il rendimento dei Btp decennali ha raggiunto livelli prossimi al 7 per cento, con il conseguente innalzamento del costo complessivo di rifinanziamento del debito pubblico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1223", "question": "Cosa accadde allo spread italiano rispetto al Bund tedesco nel 2011?", "answer": "Il differenziale di rendimento rispetto al Bund tedesco è passato in pochi mesi da valori inferiori ai 200 punti base a valori superiori ai 500 punti base (570 punti nel mese di novembre).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1224", "question": "Cosa si intende per effetto contagio nello spread?", "answer": "L'effetto contagio è la quota di spread che non deriva dalla situazione macroeconomica e di finanza pubblica del singolo paese, ma dalla \"crisi di fiducia\" degli operatori di mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1225", "question": "Cosa evidenzia lo studio Consob del 2012 sui differenziali di rendimento?", "answer": "Lo studio Consob del 2012 mostra che, a partire dalla crisi finanziaria del 2007-2008, alcuni paesi europei hanno registrato differenziali di rendimento sempre meno guidati dai fondamentali economici e sempre più legati a fenomeni di contagio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1226", "question": "Cos'è il Fondo europeo di stabilità finanziaria (FESF) e quale ruolo ebbe?", "answer": "Il Fondo europeo di stabilità finanziaria (FESF) fu costituito nel 2010 per aiutare gli Stati membri in difficoltà, fornendo prestiti, ricapitalizzando banche e comprando titoli di debito sovrano.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1227", "question": "Quale fu il giudizio dei mercati sugli interventi del FESF?", "answer": "Le iniziative del FESF determinarono un'attenuazione solo temporanea delle tensioni sul debito sovrano europeo, apparendo agli operatori di mercato come interventi poco risolutivi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1228", "question": "Quali misure adottò la BCE per sostenere la liquidità degli intermediari?", "answer": "La BCE adottò misure volte a sostenere la liquidità degli intermediari, tra cui aste a scadenza annuale con soddisfacimento illimitato e l'acquisto di titoli di Stato dell'area euro sul mercato secondario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1229", "question": "Cosa furono le LTROs e quali effetti ebbero?", "answer": "Le due Long Term Refinancing Operations (LTROs) ebbero effetti positivi parziali e servirono solo ad arginare la crisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1230", "question": "Cosa rappresentò l'OMT del 2012?", "answer": "L'OMT di settembre 2012, con l'acquisto illimitato di titoli governativi, ha rappresentato un forte segnale da parte della BCE.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1231", "question": "Quali misure straordinarie furono assunte dalla BCE nel 2014?", "answer": "Nel settembre 2014 la BCE ha assunto due misure straordinarie, il Targeted Long Term Refinancing Operation (TLTRO) e l'acquisto di titoli ABS e Covered Bond.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1232", "question": "Quale fu l'obiettivo del programma EAPP approvato nel 2015?", "answer": "Il programma di acquisto di titoli della BCE (EAPP, cosiddetto quantitative easing) era finalizzato a influenzare variabili finanziarie e reali attraverso il canale del tasso di interesse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1233", "question": "Quali furono gli effetti del quantitative easing sui rendimenti sovrani?", "answer": "In seguito all'annuncio dell'EAAP, i rendimenti del debito sovrano sono scesi a livelli eccezionalmente bassi in tutta l'area euro e su tutte le scadenze.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1234", "question": "Come il quantitative easing influenzò la percezione del rischio sovrano?", "answer": "La percezione del rischio sovrano per i paesi dell'Eurozona si è notevolmente attenuata, come si rileva dall'andamento dei prezzi dei CDS sul debito pubblico e dai rating impliciti nelle quotazioni di mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1235", "question": "Come il calo dei rendimenti pubblici influì sui bilanci degli Stati?", "answer": "Il calo dei rendimenti di titoli pubblici ridurrà la spesa per il servizio del debito e renderà più agevole la realizzazione delle misure di contenimento del deficit da parte dei paesi con maggiori squilibri di finanza pubblica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-debito-sovrano-2010-2011"}},
{"id": "chunk_1236", "question": "Quando ha avuto inizio la crisi finanziaria dei mutui subprime?", "answer": "La crisi finanziaria dei mutui subprime ha avuto inizio negli Stati Uniti nel 2006.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1237", "question": "Quali furono i presupposti della crisi dei mutui subprime?", "answer": "I presupposti della crisi risalgono al 2003, quando cominciò ad aumentare in modo significativo l'erogazione di mutui ad alto rischio, ossia a clienti che in condizioni normali non avrebbero ottenuto credito poiché non sarebbero stati in grado di fornire sufficienti garanzie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1238", "question": "Cosa favorì la formazione della bolla immobiliare negli Stati Uniti?", "answer": "A partire dal 2000 e fino alla metà del 2006, negli Stati Uniti i prezzi delle abitazioni sono cresciuti in maniera costante e significativa, generando una vera e propria bolla immobiliare. Tale dinamica era favorita dalla politica monetaria accomodante della Federal Reserve (FED), che mantenne i tassi di interesse su valori storicamente bassi fino al 2004, in risposta alla crisi della bolla internet e all'attacco dell'11 settembre 2001.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1239", "question": "In che modo i tassi di interesse bassi hanno influenzato la domanda di abitazioni?", "answer": "Tassi di interesse bassi equivalevano a un basso costo del denaro per i prenditori dei fondi, ossia per le famiglie che richiedevano mutui ipotecari, e finirono pertanto con lo stimolare la domanda di abitazioni alimentandone ulteriormente i relativi prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1240", "question": "Che cos'è la cartolarizzazione e quale ruolo ha avuto nella crisi?", "answer": "La cartolarizzazione è la possibilità per gli istituti creditizi di trasferire i mutui, dopo averli 'trasformati' in un titolo, a soggetti terzi (le cosiddette 'società veicolo') e di recuperare immediatamente buona parte del credito che altrimenti avrebbero riscosso solo al termine dei mutui stessi. Essa consentiva alle banche di liberarsi del rischio di insolvenza dei prenditori dei fondi e indeboliva così l'incentivo a valutare correttamente l'affidabilità dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1241", "question": "Come le cartolarizzazioni hanno contribuito all'espansione della leva finanziaria?", "answer": "Le cartolarizzazioni hanno comportato il passaggio del modello di business delle banche dall'approccio originate and hold all'approccio originate and distribute. Per effetto delle cartolarizzazioni, le banche rientravano in tempi rapidi nella disponibilità del denaro prestato, che potevano riutilizzare per erogare altri mutui a clienti la cui affidabilità veniva valutata in maniera sempre meno accurata. Ciò consentiva loro di espandere enormemente le attività in rapporto al capitale proprio (fenomeno del leverage o leva finanziaria).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1242", "question": "Quale ruolo hanno avuto le agenzie di rating nella crisi finanziaria?", "answer": "Le agenzie di rating avevano assunto un'importanza crescente in quanto riferimento condiviso per la valutazione dei prodotti strutturati, ma i loro giudizi si basavano su modelli di valutazione soggetti a limiti. In seguito allo scoppio della crisi subprime divenne chiaro che le agenzie avevano utilizzato modelli non sufficientemente sofisticati o troppo ottimistici, assegnando rating troppo generosi e dimostrandosi troppo caute nel rivedere i propri giudizi sugli emittenti in crisi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1243", "question": "Cosa accadde quando la FED aumentò i tassi di interesse nel 2004?", "answer": "All'inizio del 2004, la FED cominciò a innalzare i tassi di interesse in risposta alla ripresa dell'economia statunitense. I mutui divennero sempre più costosi e aumentarono i casi di insolvenze delle famiglie incapaci di restituire rate sempre più onerose. La domanda di immobili si ridusse, con conseguente scoppio della bolla immobiliare e contrazione del valore delle ipoteche a garanzia dei mutui esistenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1244", "question": "Come si trasmise la crisi al settore bancario?", "answer": "Le istituzioni finanziarie più coinvolte nell'erogazione dei mutui subprime registrarono pesanti perdite. I titoli cartolarizzati persero valore e divennero illiquidabili, costringendo le società veicolo a chiedere fondi alle banche che li avevano emessi. Alcune banche non furono in grado di reperire la liquidità necessaria, poiché nessun istituto era disposto a fare loro credito. Ne derivò una crisi di fiducia e di liquidità che portò alcune tra le maggiori banche statunitensi al fallimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1245", "question": "Quali furono le conseguenze del fallimento di Lehman Brothers?", "answer": "L'insolvenza della banca d'affari americana Lehman Brothers innescò una nuova fase di intensa instabilità. La decisione di lasciar fallire una grande istituzione finanziaria scosse profondamente la fiducia degli operatori, generando un clima di fortissima tensione e incertezza sui mercati e una drastica riduzione della liquidità sul mercato interbancario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1246", "question": "In che modo la crisi si è trasmessa all'economia reale?", "answer": "La crisi dei mutui subprime si trasferì all'economia reale statunitense ed europea, provocando una caduta di reddito e occupazione. Contribuirono la restrizione del credito bancario, il crollo dei mercati azionari e dei prezzi delle abitazioni e il deterioramento delle aspettative di famiglie e imprese, con conseguenti ripercussioni su consumi e investimenti e una pesante riduzione del commercio mondiale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1247", "question": "Quali misure adottò il governo americano per fronteggiare la crisi?", "answer": "Il governo americano intervenne con un piano di salvataggio del sistema finanziario e dei grandi istituti di credito, articolato in operazioni di nazionalizzazione e programmi di acquisto di titoli privati. Il programma Tarp (Troubled asset relief program) comportò immissioni di liquidità per complessivi 7.700 miliardi di dollari, con tassi prossimi allo zero dalla FED a sostegno di banche e compagnie di assicurazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1248", "question": "Come reagirono le istituzioni europee alla crisi finanziaria?", "answer": "In Europa, la crisi toccò per prima Northern Rock, quinto istituto di credito britannico, che fu nazionalizzato. Seguirono altri interventi in diversi Paesi europei, anche sotto forma di ricapitalizzazioni e acquisti di obbligazioni. Complessivamente, gli aiuti erogati dai governi europei alle banche raggiunsero 3.166 miliardi di euro sotto forma di garanzie, ricapitalizzazioni e prestiti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1249", "question": "Quali effetti ebbero i salvataggi bancari sui conti pubblici?", "answer": "I salvataggi bancari accrebbero in modo significativo il debito pubblico dei paesi coinvolti, gettando i presupposti per la cosiddetta crisi del debito sovrano.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1250", "question": "Come intervenne lo Stato italiano durante la crisi finanziaria?", "answer": "In Italia, il sistema bancario non fu assistito da significativi interventi pubblici sino alla fine del 2011. Lo Stato sottoscrisse obbligazioni subordinate per poco più di 4 miliardi di euro emesse da quattro banche, e successivamente garantì obbligazioni per circa 120 miliardi per facilitare l'accesso al rifinanziamento presso la BCE.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1251", "question": "Quali misure adottarono i securities regulators durante la crisi?", "answer": "I securities regulators, tra cui la Consob, attivarono misure urgenti come il divieto di vendite allo scoperto di titoli azionari. Successivamente fu adottato un Regolamento europeo in materia, in vigore dal novembre 2012.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1252", "question": "Quali riforme furono introdotte dopo la crisi del 2007-2009?", "answer": "La crisi mise in discussione la regolamentazione del sistema finanziario, rivelando la necessità di rivedere i requisiti di capitale, i principi contabili e le regole di governance, in particolare per quanto riguarda la remunerazione dei manager e la gestione dei rischi. In Europa fu disegnata una nuova architettura istituzionale per promuovere regole armonizzate e prassi uniformi di vigilanza e applicazione delle norme.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/crisi-finanziaria-del-2007-2009"}},
{"id": "chunk_1253", "question": "Che cosa ha generato la crisi del Dot.com a metà degli anni '90?", "answer": "A metà degli anni '90, una bolla speculativa legata alla scoperta delle nuove tecnologie informatiche ha generato la crisi del Dot.com.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1254", "question": "Qual è la sequenza tipica attraverso cui si sviluppa una crisi generata da una bolla speculativa?", "answer": "Come ogni altra crisi generata da una bolla speculativa, la crisi del Dot.com si è sviluppata attraverso la classica sequenza: estrema fiducia da parte degli investitori nelle potenzialità di un prodotto/azienda, crescita rapida del prezzo del prodotto, evento che fa vacillare le aspettative di importanti guadagni, elevati flussi di vendite, crollo finale del prezzo del prodotto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1255", "question": "In quali altri periodi storici si è osservata la stessa sequenza di eventi di una bolla speculativa?", "answer": "Questa sequenza di eventi si era osservata, infatti, nel 1840 in occasione del boom delle ferrovie, nel 1920 per automobili e radio, nel 1950 rispetto ai transistor elettronici e nel 1980 per home computer e biotecnologie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1256", "question": "Che cosa accadde nel 1994 con la quotazione di Netscape?", "answer": "Nel 1994, con la quotazione di Netscape - la società che sviluppò il primo browser commerciale per internet - prese il via un nuovo ciclo economico, definito New Economy.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1257", "question": "Che differenza c'era tra la New Economy e la Old Economy?", "answer": "La New Economy si contrapponeva alla Old Economy basata prevalentemente sul settore manifatturiero.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1258", "question": "Cosa caratterizzò la crescita delle Dot-com companies nella seconda metà degli anni '90?", "answer": "In pochi anni si assistette al sorprendente sviluppo di aziende operanti nel settore Internet o, più in generale, nel settore informatico, chiamate Dot-com companies (dal suffisso '.com' dei siti attraverso i quali tipicamente tali società operavano), agevolate anche dal basso costo del capitale in un contesto di bassi tassi di interesse (tra il 1995 e il 1999 la Banca Centrale degli Stati Uniti ridusse il tasso ufficiale dal 6% al 4,75%).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1259", "question": "Da cosa derivava l'euforia generale che alimentò la bolla della New Economy?", "answer": "L'euforia generale derivante dai concetti di 'sviluppo', 'progresso' e 'crescita', associati a un settore all'avanguardia come quello della new economy, alimentò le aspettative di futuri e continui aumenti del valore dei titoli emessi dalle aziende del comparto, a prescindere dalle informazioni espresse dai tradizionali indicatori di redditività.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1260", "question": "Quali indicatori tradizionali di redditività vennero ignorati durante la bolla delle Dot-com?", "answer": "Gli indicatori tradizionali di redditività ignorati erano gli utili prodotti, l'indebitamento, i beni materiali, le disponibilità liquide e le previsioni di crescita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1261", "question": "Perché le aspettative degli investitori durante la bolla del Dot-com finirono con l'autorealizzarsi?", "answer": "Tali aspettative finirono con l'autorealizzarsi, a fronte dei massici acquisti di titoli '.com' che sostenevano i corsi azionari verso una marcata sopravvalutazione delle società emittenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1262", "question": "Quali sono le cause tipiche dello scoppio di una bolla speculativa?", "answer": "Lo scoppio di una bolla speculativa può essere causato, tipicamente, dalla saturazione del mercato, ossia dall'assenza di investitori disposti ad effettuare ulteriori acquisti a un prezzo che nel frattempo è diventato elevato, dall'incentivo a disinvestire per monetizzare il guadagno, ovvero dalla revisione delle prospettive di profitto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1263", "question": "Che cosa accadde nel marzo 2000 che segnò l'inizio dello scoppio della bolla del Dot-com?", "answer": "Nel caso della bolla del Dot-com, inaspettatamente, a marzo 2000, i bilanci pubblicati da diverse aziende mostrarono risultati deludenti, fornendo evidenza che l'investimento nelle società del comparto poteva rivelarsi non profittevole.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1264", "question": "Come reagirono gli investitori dopo la pubblicazione dei bilanci deludenti nel marzo 2000?", "answer": "Le quotazioni cominciarono a calare, per effetto delle vendite da parte di coloro che intendevano disinvestire prima che i titoli in portafoglio si svalutassero ulteriormente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1265", "question": "Di quanto perse il Nasdaq in tre giorni durante lo scoppio della bolla del Dot-com?", "answer": "Il Nasdaq, l'indice azionario di riferimento, perse in tre giorni quasi il 9%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1266", "question": "Che cosa accadde alle Dot-com companies nel corso del 2001?", "answer": "Nel corso del 2001 molte Dot-com companies chiusero o furono oggetto di operazioni di acquisizione e fusione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1267", "question": "Quante società quotate nel 2000 erano ancora attive nel 2004 e a quali condizioni?", "answer": "Nel 2004, solo il 50%' delle società quotate nel 2000 erano ancora attive a quotazioni infinitesimali rispetto ai loro massimi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1268", "question": "Quali aziende solide riuscirono a crescere negli anni successivi alla crisi del Dot-com?", "answer": "Poche le aziende solide che negli anni successivi riuscirono a crescere (Amazon, eBay, Apple).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1269", "question": "Che cosa si intende per herding behaviour nelle bolle speculative?", "answer": "Un elemento tipico delle bolle speculative è costituito dall'attitudine degli individui a mettere in atto comportamenti imitativi (herding behaviour) ispirati all'agire comune e alle prassi maggiormente diffuse tra gli altri investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1270", "question": "Come agiscono gli operatori di mercato durante le fasi di crescita e di scoppio di una bolla?", "answer": "Sia nella fase della crescita sia nella fase dello scoppio della bolla, gli operatori di mercato tendono a operare scelte di investimento e, rispettivamente, disinvestimento indotte dall'euforia del momento e dalla paura diffusa di perdere in pochi istanti l'intero valore dei titoli in portafoglio (il cosiddetto panic selling), piuttosto che da valutazioni oggettive sulle prospettive di futuri rendimenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/la-bolla-delle-c.d.-dotcom"}},
{"id": "chunk_1271", "question": "Cosa hanno in comune CFD, rolling spot forex e opzioni binarie?", "answer": "La caratteristica comune dei CFD, rolling spot forex e opzioni binarie è quella di essere prodotti estremamente rischiosi. Per tale ragione, essi non sono adatti alla maggior parte degli investitori! Inoltre, tali prodotti sono anche particolarmente difficili da comprendere, in quanto il loro valore deriva dall'andamento del valore di un'altra attività (il cosiddetto \"sottostante\": un'azione, una valuta, un indice finanziario, ecc..) ovvero dal verificarsi nel futuro di un evento osservabile: si parla in tal senso di \"prodotti derivati\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/opzioni-binarie"}},
{"id": "chunk_1272", "question": "Qual è la particolarità dei CFD e dei rolling spot forex?", "answer": "La particolarità dei CFD e dei rolling spot forex è che, nel corso dell'investimento, a seconda dell'andamento del sottostante, agli investitori può essere richiesto il versamento di ulteriori somme ad integrazione del capitale inizialmente investito. Il risultato dell'operazione (perdita o guadagno) può essere ben superiore all'importo versato come margine iniziale (infatti, si parla di \"effetto leva\" per dare l'idea dell'effetto moltiplicativo che le caratteristiche del prodotto possono realizzare sulle cifre inizialmente impegnate). Inoltre, i CFD (di frequente) e i rolling spot forex (sempre!) si basano sul valore delle valute scambiate nell'ambito del cosiddetto \"Forex\". Quest'ultimo è un mercato non regolamentato: verificare la validità dei prezzi ai quali si realizzano gli scambi può risultare molto complicato per chi non è un esperto in materia!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/opzioni-binarie"}},
{"id": "chunk_1273", "question": "Perché le opzioni binarie sono considerate scommesse?", "answer": "Le opzioni binarie sono invece delle vere e proprie scommesse! Viene promesso il pagamento di un importo predeterminato se l'evento su cui si \"scommette\" (per esempio, che il prezzo di un'azione raggiunga un determinato livello) si verifica entro la scadenza prevista... talvolta anche dopo pochi minuti! È impossibile fare previsioni fondate in un così breve periodo di tempo. Se l'evento non si verifica, si perde tutta la somma investita!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/opzioni-binarie"}},
{"id": "chunk_1274", "question": "Quali rischi informativi riguardano questi prodotti?", "answer": "Per tutti e tre i prodotti in questione, alla componente rischiosa si aggiunge l'opacità informativa legata ai canali di distribuzione e alle pratiche commerciali che ne promuovono la diffusione: comunicazioni pubblicitarie diffuse e fuorvianti, chiamate telefoniche ripetute e insistenti, invio massivo e non richiesto di e-mail, offerta di bonus iniziali o ricorrenti… si tratta di tecniche tese a mettere sotto pressione i risparmiatori per ottenere facili consensi!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/opzioni-binarie"}},
{"id": "chunk_1275", "question": "Chi offre spesso CFD, rolling spot forex e opzioni binarie?", "answer": "CFD, rolling spot forex e opzioni binarie sono spesso offerti da imprese di investimento o banche comunitarie che operano in Italia sulla base dell'autorizzazione concessa dall'Autorità di vigilanza del loro Paese di origine, nonché da numerosi soggetti abusivi, ossia soggetti sprovvisti di autorizzazione ad operare nel nostro Paese, che offrono tali contratti tramite internet e che non sono sottoposti a vigilanza da parte di alcuna Autorità. I poteri della Consob nei confronti di tali soggetti sono davvero limitati!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/opzioni-binarie"}},
{"id": "chunk_1276", "question": "Cosa bisogna fare prima di investire in CFD, rolling spot forex o opzioni binarie?", "answer": "In conclusione: CFD, rolling spot forex e opzioni binarie sono prodotti estremamente rischiosi, non adatti alla maggior parte degli investitori. Se stiamo riflettendo sull'opportunità di investire in questi prodotti, accertiamoci che il soggetto offerente sia autorizzato ad operare in Italia, consultando gli appositi elenchi tenuti dalla Consob e dalla Banca d'Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/opzioni-binarie"}},
{"id": "chunk_1277", "question": "Che cos'è il moltiplicatore dei depositi?", "answer": "Il moltiplicatore dei depositi indica il numero per il quale si deve moltiplicare il valore del deposito iniziale per ottenere la creazione complessiva dei depositi, e quindi di moneta, da parte del sistema bancario. Esso è rappresentato da 1/k > 1.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1278", "question": "Come funziona il processo di creazione dei depositi nel sistema bancario?", "answer": "Indichiamo con k < 1 la somma delle quote di riserva obbligatoria e libera, e con C il deposito di contante effettuato inizialmente da un soggetto economico. La banca che riceve questo deposito è in grado di effettuare prestiti nella misura di (1 - k)C. Se il pubblico deposita tutto presso una banca, si origina un nuovo deposito pari a (1 - k)C. La banca che riceve questo nuovo deposito concederà nuovi prestiti per un ammontare pari a (1 - k)^2 C, e così via. In definitiva, l'ammontare complessivo di depositi D creato dal sistema bancario sarà pari a D = C + (1 - k)C + (1 - k)^2 C + (1 - k)^3 C +...", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1279", "question": "Come si ricava la formula del moltiplicatore bancario?", "answer": "Il secondo membro della [1] è costituito dalla somma di una progressione geometrica di ragione (1 - k) < 1 che si può scrivere come D = 1/k C, dove 1/k > 1 è detto moltiplicatore bancario (o moltiplicatore dei depositi).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1280", "question": "Qual è un esempio numerico di applicazione del moltiplicatore bancario?", "answer": "Se le banche, tra riserva obbligatoria e libera, trattengono il 20% dell'ammontare dei depositi e danno a prestito il rimanente 80%, la decisione di un soggetto economico di depositare in contanti 1 milione provocherà un'espansione complessiva dei depositi pari a 5 milioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1281", "question": "Che cosa si intende per base monetaria o moneta ad alto potenziale?", "answer": "Per base monetaria si intende quel complesso di attività che sono trasformabili in contante immediatamente e senza costo (o a costo prefissato) e che possono essere depositate come riserva obbligatoria presso la banca centrale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1282", "question": "Quali elementi costituiscono la base monetaria?", "answer": "Essa è costituita dalle passività a vista (contante e depositi liberi delle aziende di credito) delle autorità monetarie, dai depositi indisponibili del sistema bancario presso la Banca centrale per la riserva obbligatoria, oltre che dal credito aperto dalla Banca centrale a favore delle banche e da esse non utilizzato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1283", "question": "Cosa accade se il pubblico trattiene una parte della base monetaria?", "answer": "Se il pubblico trattiene presso di sé una parte della base monetaria complessiva, questa parte non è a disposizione delle banche e non può quindi rappresentare la base di partenza del processo di moltiplicazione dei depositi che avrà, corrispondentemente, minore intensità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1284", "question": "Come viene rappresentata la base monetaria complessiva?", "answer": "Si indichi con B la base monetaria totale, con Bb quella a disposizione delle banche e con Bp quella trattenuta dal pubblico, essendo: [3] B = Bb + Bp.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1285", "question": "Come si definisce la relazione tra base monetaria trattenuta dal pubblico e depositi?", "answer": "Si suppone che la base monetaria trattenuta dal pubblico stia in un rapporto pari a b rispetto ai depositi: [4] Bp = bD.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1286", "question": "Come si determina il volume dei depositi sulla base della base monetaria depositata presso le banche?", "answer": "La base monetaria depositata presso le banche permette, sulla base della [2], la determinazione di un volume di depositi pari a: [5] D = 1/k Bb, dove k è la percentuale delle riserve obbligatorie e libere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1287", "question": "Qual è la relazione complessiva tra base monetaria e depositi?", "answer": "Sostituendo la [4] e la [5] nella [3], si ottiene: [6] B = kD + bD = (k + b)D, e cioè: [7] D = 1/(k + b) B. Questa relazione rappresenta l'estensione della precedente [2].", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1288", "question": "Cosa rappresenta il fattore 1/(k + b)?", "answer": "Il fattore 1/(k + b) è il nuovo moltiplicatore dei depositi che ora è applicato alla base monetaria invece che al solo contante. Esso risulta inferiore a quello trovato nella [2] perché ora si è ipotizzato che il pubblico trattenga una quota di base monetaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1289", "question": "Come si definisce la quantità complessiva di moneta in circolazione?", "answer": "La quantità di moneta M è costituita dalla moneta bancaria (depositi) più la base monetaria non trattenuta in riserva dalle banche e posseduta dal pubblico. Si ha: [8] M = D + Bp.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1290", "question": "Come si ricava la relazione tra base monetaria e quantità di moneta in circolazione?", "answer": "Utilizzando la [4] e la [7], si ottiene: [9] M = 1/(k + b) B + bD = (1 + b)/(k + b) B. Il coefficiente (1 + b)/(k + b) è chiamato moltiplicatore monetario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1291", "question": "Che cos'è il moltiplicatore monetario?", "answer": "Il coefficiente (1 + b)/(k + b) che, una volta nota la base monetaria, permette di ottenere la quantità di moneta in circolazione, è chiamato moltiplicatore monetario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1292", "question": "Come si definisce il credito bancario?", "answer": "Il credito bancario, indicato con Cb, viene definito come il volume dei depositi meno la quantità di base monetaria trattenuta in riserva dalle banche. Si può quindi scrivere: [10] Cb = D - Bb.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1293", "question": "Come si determina il credito bancario in funzione della base monetaria?", "answer": "Mediante sostituzione dalla [5] e dalla [7], si ottiene: [11] Cb = D - kD = (1 - k)D = (1 - k)/(k + b) B, che mostra come si possa determinare il credito bancario effettuando il prodotto della base monetaria per il coefficiente (1 - k)/(k + b), che è il moltiplicatore creditizio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/elementi-di-macroeconomia"}},
{"id": "chunk_1294", "question": "Che cosa si intende per servizio di esecuzione di ordini per conto dei clienti?", "answer": "Se vogliamo acquistare o vendere un titolo (azione, titolo di Stato, ecc.) possiamo rivolgerci ad un intermediario che svolga il servizio di esecuzione di ordini per conto dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1295", "question": "Cosa fa l'intermediario quando riceve un ordine di acquisto o vendita di un titolo?", "answer": "L'intermediario, ricevuto l'ordine di acquisto o vendita di un titolo, lo esegue (comunemente si dice che negozia il titolo) scegliendo fra più sedi di negoziazione: mercati regolamentati; sistemi multilaterali di negoziazione; internalizzazione dell'ordine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1296", "question": "Che cosa sono i mercati regolamentati?", "answer": "I mercati regolamentati sono luoghi di scambio di titoli, preventivamente ammessi a negoziazione sui mercati stessi, dove le proposte di acquisto e vendita di più operatori si incontrano in modo organizzato e sulla base di regole predeterminate dando luogo alla conclusione di contratti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1297", "question": "Chi autorizza e gestisce i mercati regolamentati?", "answer": "I mercati regolamentati sono autorizzati dalla Consob e gestiti da una apposita società di gestione (ad esempio Borsa Italiana spa, la principale società di gestione italiana) sulla base di un regolamento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1298", "question": "Che cosa sono i sistemi multilaterali di negoziazione?", "answer": "I sistemi multilaterali di negoziazione sono anch'essi luoghi di incontro fra molteplici proposte di acquisto e di vendita per la conclusione di contratti. Possono essere gestiti da società di gestione dei mercati regolamentati o da sim e banche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1299", "question": "Chi può gestire un sistema multilaterale di negoziazione?", "answer": "Possono essere gestiti da società di gestione dei mercati regolamentati o da sim e banche. Più precisamente, la gestione di tali sistemi costituisce un distinto servizio di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1300", "question": "Che cos'è l'internalizzatore dell'ordine?", "answer": "L'internalizzatore dell'ordine è una banca o una sim che, su richiesta del cliente, vende al cliente strumenti finanziari di sua proprietà ovvero li acquista direttamente dal cliente stesso, operando quindi in contropartita diretta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1301", "question": "Qual è l'obiettivo principale dell'intermediario che esegue ordini per conto dei clienti?", "answer": "L'intermediario che esegue gli ordini deve avere come obiettivo quello di perseguire nel miglior modo l'interesse del cliente, avendo riguardo ai seguenti fattori: prezzo del titolo che si acquista o si vende; costi di esecuzione dell'ordine; rapidità e probabilità di esecuzione; dimensione e natura dell'ordine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1302", "question": "Quali fattori deve considerare l'intermediario per perseguire il miglior interesse del cliente?", "answer": "Prezzo del titolo che si acquista o si vende; costi di esecuzione dell'ordine; rapidità e probabilità di esecuzione; dimensione e natura dell'ordine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1303", "question": "Cosa deve privilegiare l'intermediario se l'ordine proviene da un comune risparmiatore?", "answer": "Se l'ordine proviene da un comune risparmiatore (e non da una banca, compagnia di assicurazione o altro), l'intermediario deve privilegiare il prezzo del titolo e i costi di negoziazione, trovando la soluzione che assicuri al cliente il corrispettivo totale (prezzo + costi) più vantaggioso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1304", "question": "Che cosa si intende per strategia di esecuzione degli ordini?", "answer": "La strategia di esecuzione determina per ciascuna categoria di strumenti finanziari le sedi di negoziazione che, secondo l'intermediario, permettono di ottenere in maniera duratura il miglior risultato possibile. La strategia contiene poi i criteri che, di volta in volta, in relazione al singolo ordine, orienteranno la scelta della specifica sede.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1305", "question": "Come deve informare il cliente l'intermediario riguardo la propria strategia di esecuzione?", "answer": "L'intermediario deve informare il cliente, su supporto duraturo o tramite sito internet, dei tratti principali della propria strategia. Anche le successive modifiche, se rilevanti, dovranno essergli comunicate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1306", "question": "Perché è utile conoscere la strategia di esecuzione dell'intermediario?", "answer": "Se siamo risparmiatori attenti, potremmo trarne un giudizio sulla qualità del servizio che ci verrà prestato dall'intermediario. Più sono le sedi di esecuzione contemplate dagli intermediari, maggiore sarà l'impegno volto ad ottenere il miglior risultato possibile per il cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1307", "question": "Come può il cliente verificare se l'intermediario ha rispettato la strategia di esecuzione?", "answer": "Ci consente di verificare se l'intermediario ha rispettato la strategia al fine di ottenere il miglior risultato possibile: su nostra richiesta, infatti, l'intermediario deve dimostrarci di aver eseguito l'ordine nel rispetto della strategia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1308", "question": "Cosa accade se il cliente dà istruzioni specifiche sull'esecuzione dell'ordine?", "answer": "Il cliente può anche dare istruzioni specifiche, magari indicando che l'ordine venga eseguito su un mercato regolamentato piuttosto che su un sistema multilaterale di negoziazione. In questo caso l'intermediario, esclusivamente per gli aspetti connessi alle istruzioni ricevute, è sollevato dal rispettare la strategia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1309", "question": "Con quali modalità può essere conferito un ordine?", "answer": "Il cliente può conferire l'ordine con le modalità indicate nel contratto. Potranno così esserci ordini scritti, verbali, telefonici o via internet.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1310", "question": "Quali informazioni deve fornire l'intermediario prima di eseguire un ordine di acquisto?", "answer": "Prima di eseguire un ordine di acquisto, l'intermediario deve informare il cliente sulle caratteristiche della tipologia di strumento finanziario che gli sta chiedendo di acquistare e sui relativi rischi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1311", "question": "Che cosa deve valutare l'intermediario prima di eseguire un'operazione?", "answer": "L'intermediario deve anche valutare che l'operazione sia appropriata per il cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1312", "question": "Quali informazioni deve raccogliere l'intermediario per valutare l'appropriatezza di un'operazione?", "answer": "Deve informarsi sul grado di esperienza e conoscenza del cliente relativamente al tipo di strumento finanziario chiesto o proposto e, in particolare, deve tenere conto della sua familiarità con il tipo di operazione chiesta o proposta; del volume, della frequenza, della natura delle operazioni realizzate in passato; del suo livello di istruzione; della sua professione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1313", "question": "Perché è importante fornire le informazioni richieste all'intermediario?", "answer": "Senza queste informazioni non può valutare la nostra capacità di comprendere i rischi dell'investimento e, quindi, di valutare se è per noi appropriato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1314", "question": "Cosa accade se il cliente non fornisce le informazioni richieste?", "answer": "Se non forniamo le informazioni, l'intermediario non potrà dirci (e ci avvertirà di questa circostanza) se l'investimento è appropriato o meno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1315", "question": "Che cosa deve fare l'intermediario se ritiene un'operazione non appropriata?", "answer": "Se invece diamo le informazioni, l'intermediario dovrà avvertirci nel caso ritenga l'operazione non appropriata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1316", "question": "In quale caso l'intermediario non valuta l'appropriatezza dell'operazione?", "answer": "C'è un altro caso in cui l'intermediario non valuta l'appropriatezza dell'operazione: quando il cliente gli chiede di operare, sussistendone i requisiti normativi, quale mero esecutore di ordini (cosiddetto execution only su strumenti finanziari non complessi).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1317", "question": "Cosa deve fare l'intermediario dopo aver eseguito un ordine?", "answer": "Dopo aver eseguito l'ordine, l'intermediario deve inviare al cliente una comunicazione, su supporto duraturo, dove conferma l'esecuzione e indica il giorno e l'ora di esecuzione; la tipologia dell'ordine; la sede di esecuzione; lo strumento finanziario oggetto di negoziazione; il quantitativo di strumenti finanziari scambiati, il loro prezzo unitario e il corrispettivo pagato in totale; la somma totale delle competenze e degli oneri pagati; gli eventuali adempimenti a carico del cliente per poter regolare l'operazione; la circostanza che il cliente abbia avuto come controparte lo stesso intermediario, un'impresa appartenente al suo stesso gruppo oppure un altro cliente dell'intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1318", "question": "Perché è importante leggere e conservare la comunicazione di esecuzione dell'ordine?", "answer": "Sono tutte informazioni utili per verificare l'operato dell'intermediario. Leggiamole e conserviamole: se sorgerà una controversia sarà utile averle.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1319", "question": "Che cosa si intende per negoziazione per conto proprio?", "answer": "La negoziazione per conto proprio è l'attività con cui l'intermediario, su ordine del cliente, gli vende strumenti finanziari di sua proprietà ovvero li acquista direttamente dal cliente stesso (comunemente, si dice che l'intermediario opera in contropartita diretta).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1320", "question": "Quali caratteristiche ha l'attività di negoziazione per conto proprio?", "answer": "Nell'attività di negoziazione per conto proprio l'intermediario impegna posizioni proprie e cioè soddisfa le esigenze di investimento o di disinvestimento della clientela con strumenti finanziari già presenti nel proprio portafoglio; entra nel contratto di compravendita come controparte diretta dei clienti; esegue gli ordini dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1321", "question": "In che relazione è la negoziazione per conto proprio con il servizio di esecuzione di ordini per conto dei clienti?", "answer": "Così intesa, l'attività di negoziazione per conto proprio costituisce una modalità di svolgimento di un altro servizio di investimento: l'esecuzione di ordini per conto dei clienti, descritto al capitolo precedente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1322", "question": "Quali autorizzazioni deve possedere un intermediario che negozia per conto proprio?", "answer": "L'intermediario che negozia per conto proprio deve non solo essere autorizzato per questo servizio ma, anche, per il servizio di esecuzione di ordini per conto dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1323", "question": "A chi deve rivolgersi un investitore per acquistare o vendere titoli?", "answer": "Per acquistare o vendere titoli dobbiamo rivolgerci ad un intermediario autorizzato all'esecuzione degli ordini per conto dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1324", "question": "In quali condizioni l'intermediario può internalizzare l'ordine del cliente?", "answer": "Se questo intermediario è anche autorizzato alla negoziazione per conto proprio, potrà internalizzare l'ordine a condizione che questa soluzione possa ottenere il miglior risultato possibile per il cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1325", "question": "Quali regole deve rispettare il negoziatore per conto proprio nell'eseguire un ordine?", "answer": "Nell'eseguire l'ordine del cliente il negoziatore per conto proprio dovrà rispettare tutte le regole disposte per il servizio di esecuzione di ordini descritte al capitolo precedente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1326", "question": "Che cosa si intende per gestione di sistemi multilaterali di negoziazione?", "answer": "La gestione di sistemi multilaterali di negoziazione è un servizio di investimento che consente di far incontrare, sulla base di regole predeterminate, proposte di acquisto e di vendita provenienti da una pluralità di operatori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1327", "question": "A cosa sono assimilabili i sistemi multilaterali di negoziazione?", "answer": "I sistemi multilaterali di negoziazione sono assimilabili ai mercati regolamentati, con la differenza che possono essere gestiti non solo da società di gestione di mercati regolamentati ma anche da sim e banche autorizzate alla prestazione di questo servizio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1328", "question": "Chi può gestire un sistema multilaterale di negoziazione?", "answer": "Possono essere gestiti non solo da società di gestione di mercati regolamentati ma anche da sim e banche autorizzate alla prestazione di questo servizio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1329", "question": "Quali obblighi hanno i soggetti autorizzati alla gestione di sistemi multilaterali di negoziazione?", "answer": "I soggetti autorizzati devono rispettare determinati requisiti e regole per garantire un processo di negoziazione equo, ordinato e trasparente nei confronti degli utenti e comunicare alla Consob una serie di informazioni relative ai soggetti e agli strumenti ammessi alla negoziazione, alle regole di funzionamento del sistema e alle regole di vigilanza adottate per garantire l'ordinato svolgimento delle negoziazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1330", "question": "Il servizio di gestione di sistemi multilaterali di negoziazione è rivolto direttamente ai risparmiatori?", "answer": "E' comunque un servizio che non viene di norma prestato direttamente a favore del risparmiatore in quanto da lui richiesto o a lui proposto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1331", "question": "Qual è il ruolo dei sistemi multilaterali di negoziazione dal punto di vista dei risparmiatori?", "answer": "Dal punto di vista dei risparmiatori, il sistema multilaterale di negoziazione non è altro che una delle sedi di negoziazione che l'intermediario esecutore di ordini utilizza al fine di conseguire il miglior risultato possibile per i clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1332", "question": "Che cosa si intende per servizio di ricezione e trasmissione di ordini?", "answer": "Se vogliamo acquistare o vendere un titolo possiamo rivolgerci, oltre che a un intermediario autorizzato all'esecuzione di ordini, anche ad un intermediario che offre il servizio di ricezione e trasmissione di ordini.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1333", "question": "Come opera un intermediario che offre il servizio di ricezione e trasmissione di ordini?", "answer": "Attraverso questo servizio, l'intermediario che ha ricevuto un ordine di acquisto o di vendita non lo esegue direttamente, ma lo trasmette a un altro intermediario per la sua esecuzione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1334", "question": "Perché un investitore dovrebbe rivolgersi a un trasmettitore di ordini invece che a un esecutore?", "answer": "Attraverso il servizio di trasmissione di ordini, deleghiamo al nostro intermediario la scelta di un altro intermediario che dovrà eseguire l'ordine. Sarà quindi il trasmettitore di ordini che dovrà individuare il negoziatore capace di ottenere il miglior risultato possibile che, se siamo comuni risparmiatori, è dato dalla soluzione che assicura il miglior corrispettivo totale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1335", "question": "Come individua il trasmettitore di ordini il negoziatore più adeguato?", "answer": "Per individuare il negoziatore più adeguato, il trasmettitore di ordini sfrutterà la sua esperienza e professionalità per valutare le strategie di esecuzione di ordini dei vari intermediari presenti sul mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1336", "question": "Che cos'è la strategia di trasmissione di un intermediario?", "answer": "La strategia di trasmissione è quella con la quale l'intermediario individua per ciascuna categoria di strumenti finanziari i soggetti negoziatori ai quali trasmettere l'ordine.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1337", "question": "Quali sono le analogie tra il servizio di ricezione e trasmissione di ordini e quello di esecuzione di ordini?", "answer": "A parte queste differenze ci sono molte analogie con il servizio di esecuzione di ordini per quanto riguarda le modalità di conferimento degli ordini, gli obblighi dell'intermediario di informare correttamente il cliente, di valutare l'appropriatezza delle operazioni e di fornire la rendicontazione del servizio prestato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1338", "question": "Che cosa si intende per servizio di sottoscrizione e/o collocamento?", "answer": "Il servizio di sottoscrizione e/o collocamento consiste nella distribuzione di strumenti finanziari, nell'ambito di un'offerta standardizzata, sulla base di un accordo con l'emittente o offerente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1339", "question": "Come avviene l'offerta di strumenti finanziari ai risparmiatori?", "answer": "Le società che emettono strumenti finanziari generalmente li offrono ai risparmiatori attraverso offerte al pubblico anche dette sollecitazioni all'investimento. L'offerta avviene per il tramite di intermediari che contattano gli investitori attraverso le reti di distribuzione come sportelli bancari e promotori finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1340", "question": "Qual è la differenza tra sottoscrizione e collocamento?", "answer": "Si ha sottoscrizione quando i titoli offerti sono di nuova emissione e vengono immessi per la prima volta sul mercato. Si ha invece collocamento quando si tratta di titoli già emessi che vengono successivamente venduti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1341", "question": "Qual è la differenza tra collocamento pubblico e collocamento privato?", "answer": "Il collocamento o la sottoscrizione possono essere realizzati in forma pubblica e quindi rivolti a tutti gli investitori indistintamente, ovvero in forma privata cioè indirizzati ad una selezionata cerchia di investitori di norma professionali come banche e compagnie di assicurazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1342", "question": "Cosa significa collocamento con o senza assunzione a fermo o garanzia?", "answer": "Il collocamento o la sottoscrizione possono avvenire con o senza assunzione a fermo o assunzione di garanzia nei confronti dell'emittente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1343", "question": "Che cosa comporta il collocamento senza assunzione a fermo?", "answer": "Nel caso di collocamento senza, l'intermediario assume solo l'obbligo di ricercare presso il pubblico i soggetti interessati alla sottoscrizione o all'acquisto degli strumenti finanziari da collocare; il rischio di un insuccesso nel collocamento grava solo sull'emittente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1344", "question": "Cosa succede se l'intermediario sottoscrive o acquista preventivamente i titoli?", "answer": "Nel caso in cui l'intermediario sottoscriva o acquisti egli stesso preventivamente i titoli o comunque presti una garanzia per la riuscita dell'operazione, assume su di sé il rischio del buon esito dell'operazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1345", "question": "Cosa accade se rimangono titoli invenduti in un'operazione di collocamento?", "answer": "Se dovessero rimanere dei titoli invenduti, l'intermediario collocatore ne resterebbe proprietario se li aveva preventivamente acquistati, ovvero sarebbe obbligato ad acquistarli lui stesso qualora aveva assunto una garanzia in questo senso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1346", "question": "Perché l'intermediario ha interesse a collocare tutti i titoli offerti?", "answer": "E' evidente che se l'intermediario assume su di sé il rischio dell'operazione ha un ulteriore interesse a collocare tutti i titoli offerti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1347", "question": "Quali obblighi ha l'intermediario nella prestazione del servizio di collocamento?", "answer": "Nella prestazione del servizio, l'intermediario deve operare nell'interesse del cliente e adempiere a tutti gli obblighi imposti per la prestazione dei servizi di investimento. Dovrà quindi fornire le necessarie informazioni ai clienti, valutare l'appropriatezza dell'operazione, gestire correttamente eventuali conflitti di interesse e operare sulla base di un contratto scritto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1348", "question": "Che cosa sono gli incentivi retrocessi dall'emittente al collocatore?", "answer": "Può accadere che l'emittente anche detto società prodotto retroceda al collocatore delle somme di denaro sotto forma di incentivi. La percezione di tali incentivi deve essere volta ad accrescere la qualità del servizio fornito al cliente e non deve ostacolare l'adempimento da parte dell'intermediario dell'obbligo di servire al meglio gli interessi dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1349", "question": "Chi può svolgere attività di collocamento di strumenti finanziari?", "answer": "I soggetti autorizzati alla prestazione del servizio di collocamento con o senza assunzione a fermo o assunzione di garanzia nei confronti dell'emittente possono svolgere attività di offerta fuori sede ai sensi dell'art. 30 del D.Lgs n. 58/1998 Testo Unico della Finanza tramite il ricorso alla figura professionale del promotore finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1350", "question": "Che cosa si intende per offerta fuori sede?", "answer": "Per offerta fuori sede si intendono la promozione ed il collocamento presso il pubblico di strumenti finanziari e di servizi e attività di investimento in luogo diverso dalla sede legale o dalle dipendenze dell'emittente o del soggetto incaricato della promozione o del collocamento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1351", "question": "Che cosa si intende per servizio di gestione di portafogli?", "answer": "Il servizio di gestione di portafogli consente di incaricare un intermediario di impiegare in tutto o in parte il nostro patrimonio in strumenti finanziari. L'intermediario deciderà per nostro conto quali strumenti finanziari andranno a comporre il nostro portafoglio al fine di valorizzarlo e provvederà anche a tutte le operazioni necessarie per acquistarli o venderli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1352", "question": "Cosa deve valutare l'intermediario prima di prestare il servizio di gestione di portafogli?", "answer": "Prima di prestare il servizio, l'intermediario deve valutare che il servizio offerto o richiesto sia adeguato per il cliente e cioè che, sulla base delle informazioni acquisite dal cliente stesso, corrisponda ai suoi obiettivi di investimento senza esporlo a rischi da lui non sopportabili o non comprensibili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1353", "question": "Che cosa riguarda il giudizio di adeguatezza nella gestione di portafogli?", "answer": "Il giudizio di adeguatezza riguarderà innanzi tutto il servizio stesso: non tutte le gestioni o linee sono uguali, differenziandosi in base alle caratteristiche e al grado di rischio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1354", "question": "Qual è l'obbligo dell'intermediario nello svolgimento del servizio di gestione di portafogli?", "answer": "Nello svolgimento del servizio l'intermediario dovrà poi sempre valutare che ogni singola operazione di investimento sia adeguata per il cliente, calibrando così la gestione sulle specifiche caratteristiche e esigenze del cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1355", "question": "Quali informazioni deve chiedere l'intermediario al cliente per valutare l'adeguatezza della gestione di portafogli?", "answer": "Per valutare seriamente l'adeguatezza, l'intermediario deve chiedere al cliente alcune informazioni: non si può stabilire se un'operazione è adeguata se non si conosce l'esperienza in materia di investimenti, la situazione finanziaria e gli obiettivi di investimento del cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1356", "question": "Cosa accade se il cliente si rifiuta di fornire le informazioni richieste?", "answer": "Se il cliente si rifiuta di fornire le informazioni, l'intermediario dovrà astenersi dal fornire il servizio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1357", "question": "Quali informazioni specifiche deve fornire l'intermediario sul servizio di gestione di portafogli?", "answer": "Oltre a quelle comuni a tutti i servizi, dovremo anche sapere: le caratteristiche della gestione del nostro portafoglio; se significativo il parametro di riferimento; l'eventuale effetto leva; l'eventuale delega di gestione; il metodo e la frequenza di valutazione degli strumenti finanziari; la soglia di perdita oltre la quale il cliente deve essere avvertito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1358", "question": "Quali dettagli sulle caratteristiche della gestione del portafoglio deve fornire l'intermediario?", "answer": "L'intermediario dovrà indicarci gli obiettivi come l'incremento del capitale nel lungo periodo o la conservazione del capitale, i livelli di rischio della gestione, i tipi di strumenti finanziari e le relative proporzioni che possono comporre il portafoglio e i tipi di operazioni che possono essere compiute dal gestore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1359", "question": "Che cos'è il parametro di riferimento nella gestione di portafogli?", "answer": "Il parametro di riferimento è un indicatore al quale raffrontare il rendimento del portafoglio del cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1360", "question": "Che cosa si intende per effetto leva nella gestione di portafogli?", "answer": "L'intermediario dovrà dirci se intende sfruttare la possibilità dell'effetto leva, che consiste nell'utilizzo di capitale preso a prestito per aumentare il rendimento potenziale, ma anche il rischio del portafoglio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1361", "question": "Che obblighi ha l'intermediario in materia di delega di gestione?", "answer": "L'intermediario deve dirci se intende delegare a terzi la gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1362", "question": "Quali altre informazioni devono essere riportate nel contratto di gestione di portafogli?", "answer": "Il contratto deve riportare le caratteristiche della gestione, il parametro di riferimento, l'eventuale effetto leva, la delega di gestione, il metodo e la frequenza di valutazione degli strumenti finanziari e la soglia di perdita oltre la quale il cliente deve essere avvertito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1363", "question": "Quali obblighi ha il gestore in materia di conflitti di interessi?", "answer": "Fra gli obblighi del gestore c'è anche quello di evitare o di gestire correttamente i conflitti di interessi e di informare esaurientemente il cliente al riguardo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1364", "question": "Chi negozia i titoli nel servizio di gestione di portafogli?", "answer": "Oltre a decidere quali titoli acquistare o vendere, l'intermediario deve anche negoziarli. Potrà provvedervi da solo, ovvero trasmettere gli ordini ad altro intermediario autorizzato. In ogni caso, dovrà applicare ogni misura per raggiungere il migliore risultato possibile.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1365", "question": "Con quale frequenza deve essere fornita la rendicontazione delle attività di gestione di portafogli?", "answer": "Il cliente riceve, almeno ogni sei mesi e su supporto duraturo, la rendicontazione delle attività di gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1366", "question": "Quali informazioni contiene la rendicontazione della gestione di portafogli?", "answer": "Potremo conoscere i titoli contenuti nel portafoglio e la loro valutazione; il saldo contante all'inizio ed alla fine del periodo; il totale dei costi a carico del cliente con indicazione delle singole voci; il rendimento conseguito nel periodo raffrontato con quello del parametro di riferimento; l'importo dei dividendi, interessi e altri pagamenti ricevuti nel periodo; i dettagli delle operazioni eseguite nel periodo; i diritti conferiti dai titoli in portafoglio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1367", "question": "In quali casi la rendicontazione della gestione di portafogli deve essere inviata con frequenza diversa?", "answer": "La regola è che il rendiconto venga inviato ogni sei mesi. In alcuni casi è invece trasmesso ogni tre mesi se il cliente lo chiede espressamente; almeno una volta al mese se il contratto con l'intermediario autorizza la gestione di un portafoglio caratterizzato da effetto leva; almeno ogni dodici mesi se il cliente ha anche chiesto di ricevere volta per volta le informazioni sulle singole operazioni eseguite dal gestore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1368", "question": "Qual è l'obbligo dell'intermediario in caso di perdite nella gestione di portafogli?", "answer": "L'intermediario deve tempestivamente comunicare al cliente le eventuali perdite che superino la soglia indicata nel contratto: un ulteriore strumento per tenere sotto controllo il suo operato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1369", "question": "Che cosa si intende per consulenza in materia di investimenti?", "answer": "La consulenza in materia di investimenti è un servizio di investimento in cui il consulente, su sua iniziativa o dietro richiesta del cliente, fornisce consigli o raccomandazioni personalizzate circa una o più operazioni relative ad un determinato strumento finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1370", "question": "Che cosa significa che i consigli o le raccomandazioni sono personalizzati?", "answer": "Consigli e raccomandazioni personalizzati vuol dire che questi sono presentati come adatti al cliente o basati sulle sue caratteristiche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1371", "question": "Quali tipi di raccomandazioni non costituiscono consulenza in senso proprio?", "answer": "Non sono consulenza le raccomandazioni e i consigli rivolti al pubblico con mezzi di comunicazione di massa come giornali, televisioni, internet e simili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1372", "question": "Che cosa devono suggerire le raccomandazioni per essere considerate consulenza in senso proprio?", "answer": "Le raccomandazioni e i consigli devono suggerire di acquistare, vendere, scambiare o anche continuare a detenere uno specifico strumento finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1373", "question": "Che cosa si intende per consulenza generica?", "answer": "Non costituiscono consulenza in senso proprio, ma consulenza generica, quei consigli che normalmente gli intermediari danno in merito non ad un determinato strumento finanziario ma ad un tipo di strumento finanziario, ovvero alla composizione del portafoglio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1374", "question": "Chi può prestare la consulenza in materia di investimenti?", "answer": "Possono prestare la consulenza in materia di investimenti gli intermediari, anche tramite promotori finanziari, e le persone fisiche e le società in possesso di particolari requisiti di professionalità, onorabilità, indipendenza e solidità patrimoniale iscritti in un apposito albo di consulenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1375", "question": "Perché la consulenza in materia di investimenti assicura un elevato grado di tutela?", "answer": "La consulenza in senso proprio assicura un elevato grado di tutela perché mette al servizio dell'investitore la professionalità del consulente che suggerirà solo operazioni ritenute adeguate, assumendosene anche la responsabilità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1376", "question": "Quali informazioni deve chiedere il consulente al cliente per fornire una consulenza adeguata?", "answer": "Per svolgere seriamente il compito, l'intermediario deve chiedere al cliente alcune informazioni: non si può stabilire se un'operazione è adeguata se non si hanno notizie su conoscenza e esperienza in materia di investimenti, situazione finanziaria e obiettivi di investimento del cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1377", "question": "Cosa deve fare l'intermediario se non possiede le informazioni necessarie per valutare l'adeguatezza?", "answer": "Senza queste informazioni, l'intermediario non può raccomandarci nulla e, quindi, deve astenersi dal fornirci il servizio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1378", "question": "Quali obblighi ha il consulente oltre alla valutazione di adeguatezza?", "answer": "Oltre a valutare l'adeguatezza, il consulente dovrà fornirci tutte le informazioni necessarie ed evitare o gestire correttamente i conflitti di interessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1379", "question": "Qual è la connessione tra il servizio di consulenza e gli altri servizi di investimento?", "answer": "Di norma è riscontrabile una connessione tra la prestazione del servizio di consulenza e la prestazione di altri servizi di esecuzione di ordini, ricezione e trasmissione o collocamento, nel senso che chi, ad esempio, esegue l'ordine del cliente gli fornisce anche il servizio di consulenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1380", "question": "Che relazione può esserci tra il consulente e la società che emette i prodotti raccomandati?", "answer": "Può accadere che il soggetto stesso che presta la consulenza sia emittente di strumenti finanziari o che lo siano altre società del suo gruppo, come una banca appartenente a un gruppo di cui fa parte anche una società di gestione di fondi comuni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1381", "question": "Cosa succede se il consulente riceve incentivi dalla società che emette i prodotti consigliati?", "answer": "Può anche accadere che il consulente riceva degli incentivi sotto forma di compensi, commissioni o prestazioni non monetarie dalla società che emette i prodotti consigliati. Sono situazioni che il consulente deve gestire con correttezza e delle quali deve informarci.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1382", "question": "Come può il cliente valutare le informazioni relative agli incentivi e ai conflitti di interesse?", "answer": "Valutiamo queste informazioni: nulla ci impedisce di scegliere fra più consulenti quello che riteniamo si trovi in situazione migliore per operare in assoluta indipendenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1383", "question": "Che cosa si intende per servizi accessori nel contesto dei servizi di investimento?", "answer": "I soggetti autorizzati alla prestazione dei servizi di investimento possono prestare anche i seguenti servizi accessori: custodia e amministrazione di strumenti finanziari; locazione di cassette di sicurezza; concessione di finanziamenti per effettuare operazioni relative a strumenti finanziari nelle quali interviene il soggetto che concede i finanziamenti; consulenza alle imprese in materia di struttura finanziaria, industriale e in materia di concentrazione e acquisti di imprese; servizi connessi all'emissione o al collocamento di strumenti finanziari; ricerca in materia di investimenti, analisi finanziaria o altre forme di raccomandazione generale riguardanti strumenti finanziari; intermediazione in cambi collegata alla prestazione di servizi di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1384", "question": "Quali sono alcuni esempi di servizi accessori che possono essere prestati?", "answer": "Custodia e amministrazione di strumenti finanziari; locazione di cassette di sicurezza; concessione di finanziamenti per effettuare operazioni relative a strumenti finanziari; consulenza alle imprese in materia di struttura finanziaria, industriale e in materia di concentrazione e acquisti di imprese; servizi connessi all'emissione o al collocamento di strumenti finanziari; ricerca in materia di investimenti, analisi finanziaria o altre forme di raccomandazione generale riguardanti strumenti finanziari; intermediazione in cambi collegata alla prestazione di servizi di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1385", "question": "È necessaria un'autorizzazione per prestare servizi accessori?", "answer": "Per prestare servizi accessori non occorre, a differenza dei servizi di investimento, alcuna autorizzazione e, quindi, li possono prestare anche soggetti non autorizzati alla prestazione dei servizi di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1386", "question": "Quali regole devono rispettare gli intermediari autorizzati quando prestano servizi accessori?", "answer": "Se però vengono prestati da intermediari autorizzati, questi devono rispettare le regole di condotta previste per i servizi di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-singoli-servizi-di-investimento"}},
{"id": "chunk_1387", "question": "Che cos'è il trading algoritmico?", "answer": "Il trading algoritmico è una modalità di negoziazione basata sull'utilizzo di algoritmi e programmi informatici, in genere molto complessi, che raccolgono ed elaborano le informazioni e i dati di mercato in tempo reale e avviano in automatico gli ordini (di vendita o di acquisto di strumenti finanziari) sulle diverse piattaforme di negoziazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1388", "question": "Che cos'è il trading ad alta frequenza o high-frequency trading (HFT)?", "answer": "Quando il trading algoritmico viene svolto a velocità molto elevata prende il nome di trading ad alta frequenza o high-frequency trading (di seguito HFT).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1389", "question": "Quando si è diffuso il trading algoritmico e l'HFT?", "answer": "Si tratta di un tipo di attività che si è diffusa solo di recente, grazie al progresso tecnologico e all'innovazione finanziaria, e sulla quale non si hanno ancora a disposizione molti dati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1390", "question": "Qual è il peso stimato dell'HFT in Europa secondo l'ESMA?", "answer": "In Europa, i dati più aggiornati contenuti in uno studio curato dalla European Securities Market Authority (ESMA) indicano che il peso degli scambi riconducibili all'HFT è stimabile in media tra il 24% e il 43%, a seconda delle borse e dei paesi considerati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1391", "question": "Chi sono i soggetti che svolgono HFT e quali caratteristiche comuni presentano?", "answer": "I soggetti che svolgono HFT (high frequency traders - HFTr) sono molto eterogenei. È possibile, tuttavia, individuare alcune caratteristiche che accomunano l'operatività di questi soggetti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1392", "question": "Quanti ordini possono inviare gli HFTr in un secondo?", "answer": "Gli HFTr, grazie all'utilizzo di supporti informatici hardware e software estremamente sofisticati, in un solo secondo possono inviare alle piattaforme di negoziazione numerosi ordini, anche più di 5.000.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1393", "question": "Che cos'è l'order-to-trade ratio?", "answer": "L'operatività degli HFTr è spesso caratterizzata da un elevato rapporto tra ordini inviati e transazioni effettivamente realizzate, comunemente definito order-to-trade ratio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1394", "question": "Che tipo di titoli preferiscono gli HFTr?", "answer": "Gli HFTr preferiscono i titoli caratterizzati da una maggiore liquidità. Gli strumenti più liquidi, infatti, sono quelli dai quali è possibile disinvestire rapidamente poiché hanno un mercato più grande che è in grado di assorbire e soddisfare ordini anche di importi elevati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1395", "question": "Perché gli HFTr utilizzano la co-location?", "answer": "Per ridurre ulteriormente i tempi di trasmissione degli ordini, gli HFTr posizionano le proprie apparecchiature elettroniche in locali vicini alle sedi della piattaforma di negoziazione (cosiddetta co-location), in modo da ridurre il percorso che i dati devono compiere lungo la fibra ottica per giungere alla piattaforma elettronica.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1396", "question": "Quali rischi può comportare la diffusione dell'HFT?", "answer": "La crescente diffusione dell'HFT sul mercato ha sollevato una sempre maggiore attenzione delle autorità di vigilanza riguardo ai rischi che essa potrebbe comportare. La diffusione dell'HFT e, più in generale, del trading algoritmico può destabilizzare i mercati se gli HFTr tendono a utilizzare strategie simili in misura maggiore rispetto agli altri operatori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1397", "question": "Che cos'è il fenomeno della 'patata bollente' (hot potato trading)?", "answer": "Il fenomeno della 'patata bollente' (hot potato trading) si verifica quando gli HFTr continuano a vendere solo perché anche altri lo stanno facendo, innescando ordini in vendita di altri HFTr e amplificando la caduta dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1398", "question": "Che cosa è accaduto durante il 'flash crash' del 6 maggio 2010?", "answer": "Durante il cosiddetto 'flash crash' del 6 maggio 2010, i mercati azionari USA hanno perso oltre il 10% in pochi minuti per poi recuperare rapidamente nella stessa giornata. In quella circostanza gli HFTr hanno avuto un ruolo decisivo nell'amplificare la caduta dei prezzi, pur non avendone rappresentato la causa scatenante.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1399", "question": "In che modo l'HFT può incidere sulla volatilità dei titoli?", "answer": "La diffusione dell'HFT può incidere sulla volatilità dei titoli e amplificare movimenti anomali dei prezzi. Al tempo stesso, gli HFTr sono più propensi a negoziare quando sul mercato la volatilità è elevata, perché le strategie utilizzate consentono di realizzare maggiori profitti in contesti di elevata volatilità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1400", "question": "Che cosa si intende per 'ghost liquidity'?", "answer": "La liquidità offerta dagli HFTr viene chiamata 'ghost liquidity' che, in condizioni di mercato particolari, tende a scomparire in brevissimo tempo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1401", "question": "In che modo l'HFT può influenzare il processo di formazione dei prezzi?", "answer": "La diffusione dell'HFT può avere ripercussioni anche sul processo di formazione dei prezzi. Gli HFTr mettono in atto strategie di brevissimo periodo e i loro ordini di acquisto o di vendita si basano sull'osservazione di ciò che succede sul mercato in un dato istante, con scarsa considerazione per i fondamentali economici sottostanti. Questo può determinare un allontanamento dei prezzi di mercato dai fondamentali economici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1402", "question": "Qual è il problema di equo accesso al mercato legato all'HFT?", "answer": "La partecipazione degli HFTr ai mercati finanziari rappresenta un problema per l'equo accesso al mercato. Non tutti i partecipanti possono utilizzare tecnologie HFT, che richiedono notevoli investimenti in infrastrutture tecnologiche, informatiche e capitale umano. Gli operatori che le utilizzano hanno un vantaggio oggettivo in termini di maggiore velocità rispetto agli altri, creando disparità nelle condizioni di accesso al mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1403", "question": "Quali sono i risultati degli studi sull'impatto dell'HFT?", "answer": "I principali studi teorici ed empirici che hanno analizzato l'impatto dell'HFT sui mercati sono giunti a risultati contrastanti: in alcuni casi l'operatività degli HFTr può produrre effetti benefici per il mercato, in altri casi può danneggiarlo, in particolare in momenti di estrema turbolenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1404", "question": "Cosa ha mostrato lo studio della Consob sul mercato italiano nel periodo 2011-2013?", "answer": "Un recente Quaderno di finanza Consob mostra come, nel periodo 2011-2013, un incremento del livello di attività HFT abbia determinato un significativo incremento della volatilità dei rendimenti giornalieri dei 35 titoli a maggiore capitalizzazione. Un incremento di 10 punti percentuali del peso degli HFT 'puri' sul totale degli scambi ha portato a un aumento della volatilità tra il 4% e il 6%.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1405", "question": "Come è regolamentato l'HFT negli Stati Uniti?", "answer": "Negli USA, gli HFTr sono tenuti, in base alla regolamentazione sui cosiddetti 'large traders', ad identificarsi presso l'autorità di vigilanza sui mercati (Securities and Exchange Commission o SEC) e a fornire su richiesta dati sulla propria operatività.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1406", "question": "Come è regolamentato l'HFT in Europa?", "answer": "In Europa la regolamentazione sugli HFT e sul trading algoritmico, la direttiva MiFID 2, impone agli HFTr e ai gestori delle piattaforme di negoziazione l'obbligo di predisporre adeguati sistemi di controllo interni. Gli HFT e i trader che utilizzano algoritmi sono soggetti a numerosi obblighi informativi per consentire alle autorità di monitorare meglio il fenomeno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#trading"}},
{"id": "chunk_1407", "question": "Quali riflessioni hanno avuto luogo dopo la crisi finanziaria del 2008?", "answer": "La crisi finanziaria del 2008 ha contribuito a determinare una profonda riflessione da parte delle Autorità di vigilanza e degli Organismi internazionali su alcune importanti questioni di policy. È emersa la necessità di rivedere l'approccio tradizionalmente improntato all'autodisciplina in alcuni settori del mercato finanziario, con particolare riferimento ad agenzie di rating, fondi speculativi e mercati cosiddetti over the counter.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1408", "question": "Quali comparti della regolamentazione del sistema finanziario sono stati riconsiderati dopo la crisi?", "answer": "Sono stati riconsiderati alcuni comparti della regolamentazione del sistema finanziario, dai requisiti di capitale ai principi contabili, per la loro attitudine a creare un sistema di incentivi distorto e deresponsabilizzante.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1409", "question": "Quali nuove esigenze sono emerse in materia di governance delle imprese dopo la crisi finanziaria?", "answer": "Si è avvertita la necessità di dettare standard più vincolanti in materia di governance delle imprese, soprattutto con riguardo alle politiche di remunerazione dei manager e di gestione dei rischi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1410", "question": "Qual era l'obiettivo della riforma degli assetti istituzionali di supervisione finanziaria?", "answer": "La riforma degli assetti istituzionali della supervisione finanziaria era finalizzata anche a migliorare la gestione di rischi sistemici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1411", "question": "Chi ha guidato il gruppo di lavoro per rafforzare la sorveglianza sul sistema finanziario europeo?", "answer": "È stato istituito un gruppo di lavoro, composto da esperti e guidato da Jacques de Larosière, al fine di individuare alcune raccomandazioni per rafforzare la sorveglianza sul sistema finanziario europeo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1412", "question": "Cosa ha approvato il Consiglio dell'Unione europea nel luglio 2009 riguardo alla vigilanza finanziaria?", "answer": "Il Consiglio dell'Unione europea nella riunione del 18 e 19 luglio 2009 ha approvato la creazione di un Comitato europeo per il rischio sistemico o CERS per il monitoraggio della stabilità finanziaria a livello europeo, ridisegnando il sistema delle autorità di vigilanza europee, coinvolte anche nel processo di regolamentazione finanziaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1413", "question": "Quali nuove autorità europee di vigilanza sono state istituite?", "answer": "Il Consiglio ha approvato anche l'istituzione di tre nuove autorità europee (European supervisory authorities - ESAs): l'Autorità bancaria europea (EBA), l'Autorità europea delle assicurazioni e delle pensioni aziendali e professionali (EIOPA) e l'Autorità europea degli strumenti finanziari e dei mercati (ESMA).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1414", "question": "Qual è il compito del Comitato congiunto delle ESAs?", "answer": "Le tre nuove autorità europee costituiscono il Comitato congiunto, al quale è assegnato il compito di favorire la cooperazione e la coerenza degli approcci di vigilanza adottati dalle tre Autorità europee, soprattutto rispetto ai conglomerati finanziari e alle istituzioni attive su base transfrontaliera.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1415", "question": "Quando è entrata in vigore la legislazione che istituisce il CERS?", "answer": "La legislazione che stabilisce il Comitato europeo per il rischio sistemico è entrata in vigore il 16 dicembre 2010.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1416", "question": "Quali organismi formano il Sistema europeo di vigilanza finanziaria (SEVIF)?", "answer": "Il CERS insieme alle tre autorità europee e alle autorità degli Stati Membri formano il Sistema europeo di vigilanza finanziaria (SEVIF).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1417", "question": "Quali sono i poteri delle Autorità Europee di Vigilanza (ESAs)?", "answer": "Le ESAs sono dotate di poteri di natura prevalentemente regolamentare nonché di alcuni poteri operativi e di intervento diretto in particolari situazioni di emergenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1418", "question": "Quali poteri di vigilanza diretti ha l'ESMA?", "answer": "Nel settore dei valori mobiliari, l'Esma ha poteri di vigilanza diretti su taluni soggetti, la cui operatività ha una forte connotazione internazionale (agenzie di rating e alcune infrastrutture di mercato).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1419", "question": "Quali sono gli strumenti che compongono il quadro regolamentare europeo?", "answer": "Il quadro regolamentare europeo si compone di atti giuridici dell'Unione Europea, atti delegati della Commissione Europea, progetti di norme tecniche elaborate dalle Autorità Europee di Vigilanza e orientamenti, raccomandazioni e altri strumenti di convergenza elaborati dall'ESMA.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1420", "question": "Qual è la funzione del Comitato europeo per il rischio sistemico (ESRB)?", "answer": "L'EUROPEAN SYSTEMIC RISK BOARD (ESRB) è l'organismo che controlla i rischi sistemici, cioè quelli che potrebbero compromettere la stabilità dell'intero sistema finanziario europeo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1421", "question": "Quali sono le tre Autorità europee di vigilanza e i loro ambiti di competenza?", "answer": "EBA - European Banking Authority: vigilanza sul settore bancario. EIOPA - European Insurance and Occupational Pensions Authority: vigilanza su assicurazioni e fondi pensione. ESMA - European Securities and Markets Authority: vigilanza sui mercati finanziari e gli strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1422", "question": "Quali sono le autorità di vigilanza nazionali in Italia e le loro competenze?", "answer": "In Italia, le autorità di vigilanza nazionali sono: Banca d'Italia per le banche, IVASS per le assicurazioni e CONSOB per i mercati finanziari (azioni, obbligazioni, ecc.). La CONSOB è inoltre indicata come membro permanente con diritto di voto all'interno dell'ESMA.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1423", "question": "Come si collegano tra loro i diversi livelli di vigilanza?", "answer": "L'ESRB segnala i rischi alle autorità di vigilanza nazionali e alle ESAs; le autorità nazionali e le ESAs forniscono all'ESRB informazioni sullo stato dei mercati e delle istituzioni; tra le autorità europee vi è costante cooperazione per assicurare coerenza e coordinamento delle regole.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1424", "question": "Quali cambiamenti ha subito il quadro normativo europeo dopo la crisi?", "answer": "Il quadro normativo europeo in materia di regolamentazione di mercati e intermediari finanziari, infrastrutture di mercato, trasparenza di prodotti ed emittenti, credito e intermediazione bancaria ha subito un profondo cambiamento a seguito dei processi di revisione di varie direttive e di nuove iniziative su specifici temi evidenziati dalla crisi finanziaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1425", "question": "Qual era l'obiettivo del Regolamento UE 236/12 su vendite allo scoperto?", "answer": "Il Regolamento UE 236/12 su vendite allo scoperto e taluni aspetti dei Cds (cosiddetto Regolamento Short selling) è teso a disciplinare pratiche operative potenzialmente negative per i mercati finanziari in periodi di turbolenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1426", "question": "Cosa introduce la revisione della Direttiva MiFID del 2014?", "answer": "La revisione della MiFID del 2014 si propone di garantire una maggiore trasparenza delle transazioni, rendere più efficace il funzionamento del mercato interno degli strumenti finanziari, tutelare gli investitori, rafforzare la fiducia e assicurare che le autorità di vigilanza dispongano di poteri adeguati per svolgere i loro compiti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1427", "question": "Quali obiettivi ha il Regolamento UE 648/2012 (EMIR)?", "answer": "Il Regolamento UE 648/2012 (EMIR) accresce la trasparenza del mercato e la capacità delle autorità di vigilanza di disporre di un quadro completo sulla distribuzione dei rischi all'interno del sistema finanziario, imponendo l'obbligo di comunicazione di tutti i contratti derivati conclusi a repertori di dati sulle negoziazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1428", "question": "Cosa prevede il Regolamento UE 909/2014 in materia di infrastrutture di mercato?", "answer": "Il Regolamento UE 909/2014, relativo al miglioramento dell'attività di regolamento dei titoli nell'Unione Europea e all'attività dei depositari centrali, contiene disposizioni in materia di autorizzazione e vigilanza dei depositari centrali che operano sistemi di regolamento titoli e obblighi a carico dei partecipanti al mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1429", "question": "Qual è lo scopo del Regolamento UE 1286/2014 (PRIIPs)?", "answer": "Il Regolamento UE 1286/2014 sui documenti informativi chiave per i prodotti finanziari preassemblati e i prodotti assicurativi di investimento (PRIIPs) introduce l'obbligo di redigere un Documento informativo (Key Information Document) chiaro e succinto per agevolare l'investitore retail nella comprensione e comparazione dei prodotti d'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1430", "question": "Cosa prevede la Direttiva 2011/61/UE (AIFMD)?", "answer": "La Direttiva 2011/61/UE sui gestori di fondi di investimento alternativi (AIFMD) mira a contenere i rischi per la stabilità del sistema finanziario assoggettando gli hedge funds a una disciplina armonizzata in materia di gestione dei conflitti di interessi, trasparenza, gestione dei rischi e ricorso alla leva finanziaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1431", "question": "Qual è l'obiettivo del pacchetto CRD IV (Direttiva 2013/36/UE e Regolamento 575/2013)?", "answer": "Il pacchetto CRD IV ha innalzato i requisiti di capitale, necessario ai fini del contenimento dell'azzardo morale e dei costi collettivi di fallimento delle banche, e ha rafforzato aree della regolamentazione dell'intermediazione finanziaria, con particolare riguardo alla disciplina in materia di governo societario, politiche di remunerazione e sanzioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1432", "question": "Quali misure introduce la Direttiva 2014/59/UE (BRRD)?", "answer": "La Direttiva 2014/59/UE Bank Recovery and Resolution Directive (BRRD) introduce norme in materia di risanamento e risoluzione delle crisi di banche e imprese di investimento, dettando procedure armonizzate di risoluzione che dovranno essere applicate in ipotesi di dissesto o crisi degli enti soggetti all'ambito di applicazione della Direttiva.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1433", "question": "Qual è l'obiettivo di fondo perseguito nel quadro normativo delineato dalla Direttiva BRRD?", "answer": "L'obiettivo di fondo perseguito nel quadro normativo così delineato è ripristinare la solidità finanziaria degli enti soggetti a risoluzione, preservandone, ove possibile, la continuità delle funzioni aziendali nonché evitare la destabilizzazione dei mercati finanziari, possibili effetti di contagio e costi a carico dei contribuenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#evoluzione"}},
{"id": "chunk_1434", "question": "Come si formano i prezzi nei mercati finanziari secondari?", "answer": "I prezzi che si formano sui mercati finanziari secondari derivano dall'incrocio di ordini caratterizzati da parametri di prezzo, quantità e tempo che esprimono le condizioni alle quali gli operatori che li conferiscono sono disposti a concludere contratti. In questo modo, gli operatori trasmettono al mercato elementi informativi sulle loro personali aspettative e percezioni del rischio sul prossimo andamento dell'attività sottostante allo strumento finanziario. I prezzi finiscono così per \"incorporare\" gradualmente tali elementi informativi e, dunque, per \"rifletterli\" in modo sintetico alla globalità degli operatori, che, a loro volta, sulla base di questi segnali correggono le rispettive aspettative iniziali e, eventualmente, conferiscono nuovi ordini. Tale processo circolare conduce in modo fisiologico alla graduale scoperta del vero valore dello strumento finanziario (cosiddetto processo di price discovery).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1435", "question": "Quali effetti informativi producono le variazioni dei prezzi nei mercati secondari?", "answer": "I segnali informativi che provengono dalle variazioni dei prezzi che si formano nei mercati secondari sono oggetto di attenzione anche da parte degli operatori attivi nel mercato primario. Ad esempio, il management di una società quotata è interessato a conoscere il sentiment degli azionisti nel loro complesso. I governi, che gestiscono la cosa pubblica, monitorano i prezzi dei titoli emessi dallo Stato in modo da leggere immediatamente le aspettative, i timori e le preoccupazioni degli investitori, spesso numerosi e distribuiti presso larghi strati della popolazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1436", "question": "Perché si dice che i mercati votano ogni giorno?", "answer": "Un noto finanziere, nel commentare la crescente importanza che assumono i prezzi di mercato nelle democrazie evolute, ha efficacemente osservato che \"i mercati votano ogni giorno e forzano i governi perché prendano le iniziative necessarie benché impopolari\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1437", "question": "Da cosa dipende il corretto funzionamento dei mercati finanziari?", "answer": "Pur producendo in modo fisiologico una serie di pregevoli effetti, il meccanismo di funzionamento dei mercati finanziari si basa su un insieme di regole e di fattori molto fragili che potrebbero prestarsi ad abusi da parte di pochi malintenzionati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1438", "question": "Qual è l'importanza della fiducia nei mercati finanziari?", "answer": "Un fattore fondamentale è dato dalla fiducia degli operatori nei meccanismi di funzionamento dei mercati finanziari e nella correttezza del comportamento di tutti. Esempio emblematico di tale fiducia è dato dal frequente utilizzo di ordini \"al meglio\", cioè senza limiti di prezzo. Il superamento di tali timori costituisce, dunque, un bene preziosissimo per il migliore funzionamento dei mercati finanziari, la cui perdita avrebbe gravi conseguenze, cioè l'abbandono del mercato da parte di soggetti inizialmente disponibili a partecipare, cioè a conferire le proprie personali informazioni sullo strumento finanziario: una perdita secca per tutti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1439", "question": "Perché è importante l'anonimato degli scambi?", "answer": "Altra basilare e fragile regola sottostante all'ordinario funzionamento dei mercati finanziari è quella dell'anonimato degli scambi, che richiede a chi compra o vende strumenti finanziari di avvalersi di un intermediario, così da evitare, tra l'altro, l'eventuale diffidenza delle controparti, che, una volta conosciuta l'identità del mandante, potrebbero rivedere l'iniziale disponibilità a negoziare o alcune delle relative condizioni, rallentando la velocità del processo di formazione dei prezzi. Diverse tipologie di comportamenti illeciti fanno leva sull'utilizzo distorto di tale regola.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1440", "question": "Qual è il ruolo dello Stato nella tutela dei mercati finanziari?", "answer": "Lo Stato pone, quindi, presidi contro possibili scorrettezze, definendo quali sono i comportamenti vietati e assegnando specifici poteri ad autorità pubbliche di vigilanza, come la Consob, che, grazie alla possibilità di monitorare al contempo le informazioni rese pubbliche dagli emittenti e l'andamento degli scambi che si concludono sui mercati finanziari, sono in grado di intervenire rapidamente comminando dissuasive sanzioni amministrative per quanti incorrano in abusi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1441", "question": "Qual è la funzione delle autorità di vigilanza come la Consob?", "answer": "Tali autorità hanno, altresì, il potere regolamentare di definire specifiche regole preventive per le varie categorie di soggetti che partecipano al mercato, così da ridurre il rischio di abusi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1442", "question": "Che cosa significa garantire l'integrità del processo di formazione dei prezzi?", "answer": "Tornando all'influenza quotidiana che i mercati finanziari esercitano sullo sviluppo delle moderne democrazie, si potrebbe concludere che tali autorità hanno il compito di garantire la validità del voto espresso dai mercati assicurando l'integrità del processo di formazione dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1443", "question": "Quali sono i principali comportamenti che violano l'integrità dei mercati finanziari?", "answer": "I comportamenti che violano l'integrità dei mercati sono solitamente raccolti in due gruppi: l'abuso di informazioni privilegiate e la manipolazione del mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1444", "question": "Che cos'è l'abuso di informazioni privilegiate?", "answer": "L'abuso di informazioni privilegiate ruota attorno alla fattispecie dell'insider trading, che consiste nell'immissione di ordini nel mercato utilizzando informazioni privilegiate, dette così perché non pubbliche, non generiche e idonee, se pubblicate, ad influenzare il prezzo di strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1445", "question": "Quali tipi di informazioni possono essere considerate privilegiate?", "answer": "Le informazioni privilegiate possono riguardare sia la società emittente lo strumento finanziario (cosiddetto company information), quali quelle relative ai risultati economici di periodo o alle operazioni di finanza straordinaria, sia altri eventi capaci, comunque, di influire sull'andamento dei prezzi (cosiddetta market information).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1446", "question": "Chi sono gli insider primari e secondari?", "answer": "Si usa distinguere, tra insider primari, cioè coloro che sono a conoscenza dell'informazione in quanto partecipano alla formazione della stessa, e insider secondari, cioè coloro che ne vengono a conoscenza in diverso modo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1447", "question": "Cosa si intende per tipping e tuyautage?", "answer": "Altre fattispecie di abuso di informazioni privilegiate consistono nel comunicare l'informazione a terzi senza giustificato motivo (tipping) e nel raccomandare ad altri, sulla base dell'informazione, di operare in una certa direzione su un determinato strumento finanziario (tuyautage).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1448", "question": "Quali sono le principali forme di manipolazione del mercato?", "answer": "Poiché i prezzi dipendono sia dalle informazioni attinenti allo strumento finanziario sia dagli ordini immessi sul mercato dagli operatori, chi intenda manipolare i prezzi può fare leva o sulla diffusione di informazioni false o fuorvianti (cosiddetta manipolazione informativa) o sull'immissione di ordini capaci di alterare il naturale processo di formazione dei prezzi (cosiddetta manipolazione operativa).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1449", "question": "Che cos'è la manipolazione informativa?", "answer": "Casi di manipolazione informativa possono essere implementati da quanti abbiano il potere di influire con le proprie dichiarazioni sull'andamento dei prezzi (market power): società quotate, manager, analisti finanziari, giornalisti, investitori, funzionari di autorità di vigilanza o di settore, politici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1450", "question": "Qual è lo scopo della manipolazione informativa?", "answer": "Tipicamente, il fine di una manipolazione informativa è quello di generare un particolare rialzo o ribasso del prezzo di uno strumento finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1451", "question": "Che cos'è la manipolazione operativa?", "answer": "La manipolazione di tipo operativo viene realizzata tramite strategie che fanno leva sull'immissione di ordini e l'eventuale conclusione di contratti che interferiscono sul processo di formazione dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1452", "question": "Quali sono le principali categorie di strategie di manipolazione operativa?", "answer": "Le strategie di manipolazione operativa sono molto varie: si usa raggrupparle in due categorie, a seconda che gli ordini e le eventuali operazioni siano idonei a fornire falsi segnali sul reale valore dello strumento finanziario (misleading transaction), o siano meramente idonei a fissare il prezzo a valori anomali ed utili agli interessi del manipolatore (price positioning).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1453", "question": "Che cos'è una strategia di tipo pump & dump?", "answer": "Tipica strategia di misleading transaction è la creazione di una \"bolla\" nell'andamento dei prezzi tramite l'immissione di una serie di ordini a prezzi crescenti in modo da concludere contratti, avviare un trend nel corso del titolo e poter, dunque, vendere con profitto ai prezzi più elevati generati dagli acquisti effettuati dai follower che ritenevano il trend basato su nuove valide informazioni (pump & dump).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1454", "question": "Cosa prevede la normativa comunitaria per evitare abusi di mercato?", "answer": "La normativa comunitaria stabilisce opportunamente che la persona che pone in essere operazioni di speculazione o investimento non è assoggettata a sanzione se dimostra di aver operato per motivi legittimi. Inoltre, esime da sanzione (safe harbour) sia le operazioni effettuate nell'ambito di programmi di riacquisto di azioni proprie, se poste in essere con tre specifiche finalità, sia le operazioni di stabilizzazione che vengono effettuate nelle settimane seguenti ai collocamenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1455", "question": "Cosa consente la disciplina comunitaria in materia di prassi di mercato?", "answer": "In aggiunta, la disciplina comunitaria consente alle autorità di vigilanza di ammettere eventuali \"prassi di mercato\", cioè comportamenti che di regola non presentano intenti manipolativi ma la cui attuazione rischia comunque di produrre, anche involontariamente, effetti manipolativi. In tali casi l'autorità di vigilanza deve, però, specificare quali sono le precise condizioni che devono essere rispettate dagli operatori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1456", "question": "Quali misure preventive prevede la normativa sugli abusi di mercato?", "answer": "La citata normativa sugli abusi di mercato affianca alla definizione dei comportamenti vietati l'indicazione di una serie di misure preventive che le varie categorie di partecipanti al mercato devono porre in essere per ridurre il rischio che si incorra in abusi: gli emittenti devono pubblicare le informazioni privilegiate appena possibile, evitare la comunicazione selettiva delle informazioni (fair disclosure) e istituire un registro delle persone che hanno accesso a informazioni privilegiate; i top manager dell'emittente devono pubblicare le operazioni che effettuano sulle azioni emesse; coloro che diffondono raccomandazioni d'investimento, siano essi analisti finanziari, commentatori o giornalisti, devono attenersi a obblighi di corretta presentazione e di trasparenza sui conflitti di interesse; le società di gestione dei mercati devono disegnare la microstruttura del mercato in modo da limitare il rischio che vengano commessi abusi; gli intermediari hanno l'obbligo di comunicare alle autorità di vigilanza le operazioni effettuate per conto della clientela che ritengono sospette; le istituzioni che pubblicano dati suscettibili di influire sui prezzi di mercato devono attenersi a regole di corretta e trasparente diffusione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1457", "question": "Qual è la connessione tra la regolamentazione dei mercati e la prevenzione della manipolazione informativa?", "answer": "In realtà, larga parte della regolamentazione dei mercati finanziari può essere interpretata in tale prospettiva; ad esempio, le norme che stabiliscono gli standard di redazione dei bilanci sono utili a prevenire casi di manipolazione informativa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1458", "question": "Cosa è accaduto dopo lo scandalo Parmalat?", "answer": "Negli anni successivi allo scandalo Parmalat le imprese quotate hanno avuto serie difficoltà a collocare nuove obbligazioni per la mancanza di investitori retail disposti ad offrire la loro fiducia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1459", "question": "Su cosa si basa la vigente disciplina comunitaria in materia di abusi di mercato?", "answer": "La vigente disciplina comunitaria in materia di abusi di mercato si basa sulla direttiva 2003/6/CE, che si applica a tutti gli strumenti finanziari ammessi (o in via di ammissione) in mercati regolamentati ovunque negoziati, prevedendo sanzioni e misure di tipo amministrativo. Il D. Lgs. n. 58/1998, che recepisce tale disciplina, estende i divieti di abuso agli strumenti ammessi solo in sistemi multilaterali di negoziazione e prevede sanzioni sia penali sia amministrative.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1460", "question": "Quali sono le sanzioni previste per gli abusi di mercato?", "answer": "In particolare, i massimi edittali per quelle amministrative sono pari a € 45mln per l'abuso di informazioni privilegiate e a € 75mln per la manipolazione del mercato, che, se dovessero risultare inadeguati, possono essere aumentati fino a 10 volte il profitto conseguito. A partire dal 3 luglio 2016 la citata direttiva sarà sostituita da quanto stabilito nel regolamento n. 596/2014. Dalla stessa data si applicheranno le previsioni penali indicate nella direttiva 2014/57/UE.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1461", "question": "Come si collega il divieto di uso di informazioni privilegiate all'efficienza informativa dei mercati?", "answer": "Nel paradigma di Eugene Fama che distingue l'efficienza informativa in forte, semi-forte e debole, a seconda che i prezzi riflettano tutte le informazioni esistenti (quindi anche quelle privilegiate), solo quelle pubbliche e solo quelle ricavabili dai prezzi precedenti, il divieto di utilizzo delle informazioni privilegiate comporta una riduzione dell'efficienza informativa dei mercati, dal momento che il processo di price discovery risulta impossibilitato a far emergere tali informazioni privilegiate. Il dibattito accademico ha mostrato come tale effetto negativo sia comunque minore di quello che l'assenza del divieto avrebbe sulla fiducia nel mercato e, di conseguenza, sul processo di formazione dei prezzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1462", "question": "Cosa consente di fare il trading book nelle fasi di negoziazione continua?", "answer": "Nelle fasi di negoziazione continua il trading book consente all'operatore (anche retail) di vedere per ciascun livello di prezzo quali sono le quantità offerte dagli altri partecipanti. L'operatore è, quindi, in grado di calibrare l'ordine che va ad immettere nel trading book in modo da scalare (\"applicare\") gli ordini presenti dal lato opposto e concludere contratti ai prezzi voluti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1463", "question": "Cosa si intende per fundamentals?", "answer": "I cosiddetti fundamentals sono i dati di base che riguardano l'attività sottostante allo strumento finanziario. Ad esempio, nel caso delle azioni, i dati della società emittente su attività, passività, fatturato, margini operativi, utile, ecc..", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1464", "question": "Cosa si intende per consensus nelle valutazioni degli analisti?", "answer": "Per valutare in quale misura i prezzi che si formano nei mercati sono coerenti con i fundamentals, gli analisti finanziari inseriscono tali dati nei loro modelli di valutazione. Poiché tali modelli presentano differenze, le conseguenti valutazioni sulla adeguatezza dei prezzi di mercato possono differire significativamente tra loro. Per tale ragione, si fa solitamente riferimento ad una media (ponderata) delle valutazioni pubblicate dagli analisti, il cosiddetto consensus.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1465", "question": "A quali documenti si può fare riferimento per le strategie di manipolazione operativa?", "answer": "Per una più ampia indicazione delle principali strategie di manipolazione operativa si rinvia alle comunicazioni Consob DME/5078692 del 29 novembre 2005 e DME/10039224 del 30 aprile 2010.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1466", "question": "Che cos'è la strategia trash&cash?", "answer": "La simmetrica strategia che origina dal lato delle vendite è chiamata trash&cash.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1467", "question": "Quali prassi di mercato ha ammesso la Consob in Italia?", "answer": "In Italia, la Consob ha ammesso tre prassi di mercato, relative ai contratti di liquidità, in base ai quali un intermediario è incaricato dall'emittente di offrire liquidità sulle azioni emesse, ai programmi di riacquisto di azioni proprie finalizzati alla costituzione di un cosiddetto \"magazzino\" titoli da utilizzare in caso di operazioni di finanza straordinaria e alle operazioni di riacquisto di prestiti obbligazionari a condizioni predeterminate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/mercati-finanziari#integrita"}},
{"id": "chunk_1468", "question": "Qual è la finalità del documento sui rischi dell'investimento?", "answer": "Questo documento non descrive tutti i rischi ed altri aspetti significativi riguardanti gli investimenti in strumenti finanziari ed i servizi di gestione patrimoniale personalizzata, ma ha la finalità di fornire alcune informazioni di base sui rischi connessi a tali investimenti e servizi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1469", "question": "Cosa deve fare l'investitore prima di effettuare un investimento in strumenti finanziari?", "answer": "Prima di effettuare un investimento in strumenti finanziari l'investitore deve informarsi presso il proprio intermediario sulla natura e i rischi delle operazioni che si accinge a compiere. L'investitore deve concludere un'operazione solo se ha ben compreso la sua natura ed il grado di esposizione al rischio che essa comporta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1470", "question": "Quali sono gli elementi da tenere presenti per apprezzare il rischio di un investimento in strumenti finanziari?", "answer": "Per apprezzare il rischio derivante da un investimento in strumenti finanziari è necessario tenere presenti i seguenti elementi: 1 La variabile del prezzo dello strumento finanziario 2 La sua liquidità 3 La divisa in cui è denominato 4 Gli altri fattori fonti di rischi generali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1471", "question": "Qual è la differenza tra titoli di capitale e titoli di debito?", "answer": "Acquistando titoli di capitale si diviene soci della società emittente, partecipando per intero al rischio economico della medesima; chi investe in titoli azionari ha diritto a percepire annualmente il dividendo sugli utili conseguiti nel periodo di riferimento che l'assemblea dei soci deciderà di distribuire. L'assemblea dei soci può comunque stabilire di non distribuire alcun dividendo. Acquistando titoli di debito si diviene finanziatori della società o degli enti che li hanno emessi e si ha diritto a percepire periodicamente gli interessi previsti dal regolamento dell'emissione e, alla scadenza, al rimborso del capitale prestato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1472", "question": "Perché un titolo di capitale è più rischioso di un titolo di debito?", "answer": "A parità di altre condizioni, un titolo di capitale è più rischioso di un titolo di debito, in quanto la remunerazione spettante a chi lo possiede è maggiormente legata all'andamento economico della società emittente. Il detentore di titoli di debito invece rischierà di non essere remunerato solo in caso di dissesto finanziario della società emittente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1473", "question": "Cosa accade in caso di fallimento della società emittente?", "answer": "In caso di fallimento della società emittente, i detentori di titoli di debito potranno partecipare, con gli altri creditori, alla suddivisione dei proventi derivanti dal realizzo delle attività della società, mentre è pressoché escluso che i detentori di titoli di capitale possano vedersi restituire una parte di quanto investito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1474", "question": "Che cosa si intende per rischio specifico e rischio generico?", "answer": "Il rischio specifico dipende dalle caratteristiche peculiari dell'emittente e può essere diminuito sostanzialmente attraverso la suddivisione del proprio investimento tra titoli emessi da emittenti diversi (diversificazione del portafoglio), mentre il rischio sistematico rappresenta quella parte di variabilità del prezzo di ciascun titolo che dipende dalle fluttuazioni del mercato e non può essere eliminato per il tramite della diversificazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1475", "question": "Da cosa origina il rischio sistematico per i titoli di capitale trattati su un mercato organizzato?", "answer": "Il rischio sistematico per i titoli di capitale trattati su un mercato organizzato si origina dalle variazioni del mercato in generale; variazioni che possono essere identificate nei movimenti dell'indice del mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1476", "question": "Da cosa origina il rischio sistematico dei titoli di debito?", "answer": "Il rischio sistematico dei titoli di debito si origina dalle fluttuazioni dei tassi d'interesse di mercato che si ripercuotono sui prezzi (e quindi sui rendimenti) dei titoli in modo tanto più accentuato quanto più lunga è la loro vita residua.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1477", "question": "Cosa si intende per rischio emittente?", "answer": "Per gli investimenti in strumenti finanziari è fondamentale apprezzare la solidità patrimoniale delle società emittenti e le prospettive economiche delle medesime tenuto conto delle caratteristiche dei settori in cui le stesse operano. Il rischio che le società o gli enti finanziari emittenti non siano in grado di pagare gli interessi o di rimborsare il capitale prestato si riflette nella misura degli interessi che tali obbligazioni garantiscono all'investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1478", "question": "Cosa indica un tasso di interesse più alto su un titolo di debito?", "answer": "Quanto maggiore è la rischiosità percepita dell'emittente tanto maggiore è il tasso d'interesse che l'emittente dovrà corrispondere all'investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1479", "question": "Cosa deve considerare l'investitore per valutare la congruità del tasso d'interesse di un titolo?", "answer": "Per valutare la congruità del tasso d'interesse pagato da un titolo si devono tenere presenti i tassi d'interessi corrisposti dagli emittenti il cui rischio è considerato più basso, ed in particolare il rendimento offerto dai titoli di Stato, con riferimento a emissioni con pari scadenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1480", "question": "Che cos'è il rischio d'interesse?", "answer": "Con riferimento ai titoli di debito, l'investitore deve tener presente che la misura effettiva degli interessi si adegua continuamente alle condizioni di mercato attraverso variazioni del prezzo dei titoli stessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1481", "question": "Quando il rendimento di un titolo di debito coincide con quello incorporato al momento dell'acquisto?", "answer": "Il rendimento di un titolo di debito si avvicinerà a quello incorporato nel titolo stesso al momento dell'acquisto solo nel caso in cui il titolo stesso venisse detenuto dall'investitore fino alla scadenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1482", "question": "Cosa accade se l'investitore deve smobilizzare il titolo prima della scadenza?", "answer": "Qualora l'investitore avesse necessità di smobilizzare l'investimento prima della scadenza del titolo, il rendimento effettivo potrebbe rivelarsi diverso da quello garantito dal titolo al momento del suo acquisto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1483", "question": "Che cosa rappresenta il rischio di credito?", "answer": "E' il rischio che l'emittente non paghi le cedole e/o rimborsi il capitale, perché è in grosse difficoltà o perché è fallito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1484", "question": "Come si misura il rischio di credito?", "answer": "Si può misurare con la probabilità attesa di fallimento dell'emittente (cosiddetto default) e la valutazione delle agenzie di rating, tipicamente espressa in lettere (cosiddetto rating). Se sale la probabilità attesa di fallimento (default) sale il rischio di credito. Se il rating scende sale il rischio di credito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1485", "question": "Che cos'è il rischio di mercato?", "answer": "E' il rischio di subire perdite a causa delle variazioni dei prezzi o dell'andamento generale del mercato. Si può misurare con la volatilità e il valore a rischio (cosiddetto VaR). Se sale la volatilità e/o il VaR sale il rischio di mercato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1486", "question": "Che cos'è il rischio di liquidità?", "answer": "E' il rischio di non riuscire a disinvestire rapidamente il titolo acquistato, qualora se ne presenti la necessità, ovvero di farlo perdendo molto rispetto alla somma investita. Si può anche misurare tenendo conto del numero e della frequenza degli scambi (cosiddetto turn-over) realizzati sul titolo. Tipicamente, quanto maggiori sono gli scambi (turn-over) tanto minore è il rischio di liquidità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1487", "question": "Come può l'investitore ridurre il rischio specifico?", "answer": "Il rischio specifico di un particolare strumento finanziario può essere eliminato attraverso la diversificazione, cioè suddividendo l'investimento tra più strumenti finanziari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1488", "question": "Che vantaggi offre la diversificazione tramite fondi comuni o SICAV?", "answer": "L'investitore può raggiungere un elevato grado di diversificazione a costi contenuti investendo il proprio patrimonio in quote o azioni di organismi di investimento collettivo (fondi comuni d'investimento e Società d'investimento a capitale variabile - SICAV). Questi organismi investono le disponibilità versate dai risparmiatori tra le diverse tipologie di titoli previsti dai regolamenti o programmi di investimento adottati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1489", "question": "Cosa rappresenta la liquidità di uno strumento finanziario?", "answer": "La liquidità di uno strumento finanziario consiste nella sua attitudine a trasformarsi prontamente in moneta senza perdita di valore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1490", "question": "Da cosa dipende la liquidità di un titolo?", "answer": "Essa dipende in primo luogo dalle caratteristiche del mercato in cui il titolo è trattato. In generale, a parità di altre condizioni, i titoli trattati su mercati organizzati sono più liquidi dei titoli non trattati su detti mercati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1491", "question": "Qual è il rischio associato alla divisa in cui è denominato un investimento?", "answer": "Qualora uno strumento finanziario sia denominato in una divisa diversa da quella di riferimento per l'investitore, al fine di valutare la rischiosità complessiva dell'investimento occorre tenere presente la volatilità del rapporto di cambio tra la divisa di riferimento e la divisa estera in cui è denominato l'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1492", "question": "Perché i rapporti di cambio possono influire sul risultato dell'investimento?", "answer": "L'investitore deve considerare che i rapporti di cambio con le divise di molti paesi, in particolare di quelli in via di sviluppo, sono altamente volatili e che comunque l'andamento dei tassi di cambio può condizionare il risultato complessivo dell'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1493", "question": "Cosa deve fare l'investitore riguardo alle somme di denaro e valori depositati?", "answer": "L'investitore deve informarsi circa le salvaguardie previste per le somme di denaro ed i valori depositati per l'esecuzione delle operazioni, in particolare, nel caso di insolvenza dell'intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1494", "question": "Cosa deve conoscere l'investitore prima di avviare l'operatività?", "answer": "Prima di avviare l'operatività, l'investitore deve ottenere dettagliate informazioni a riguardo di tutte le commissioni, spese ed altri oneri che saranno dovute all'intermediario. Tali informazioni devono essere comunque riportate nel contratto d'intermediazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1495", "question": "Quali rischi comportano le operazioni su mercati esteri?", "answer": "Le operazioni eseguite su mercati aventi sede all'estero potrebbero esporre l'investitore a rischi aggiuntivi. Tali mercati potrebbero essere regolati in modo da offrire ridotte garanzie e protezioni agli investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1496", "question": "Che rischi sono associati ai sistemi elettronici di supporto alle negoziazioni?", "answer": "Come tutte le procedure automatizzate, i sistemi di negoziazione elettronici possono subire temporanei arresti o essere soggetti a malfunzionamenti. La possibilità per l'investitore di essere risarcito per perdite derivanti da tali eventi potrebbe essere compromessa da limitazioni di responsabilità stabilite dai fornitori dei sistemi o dai mercati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1497", "question": "Che cosa comportano le operazioni eseguite fuori dai mercati organizzati?", "answer": "Per le operazioni effettuate fuori dai mercati organizzati può risultare difficoltoso o impossibile liquidare uno strumento finanziario o apprezzarne il valore effettivo e valutare l'effettiva esposizione al rischio, in particolare qualora lo strumento finanziario non sia trattato su alcun mercato organizzato. Per questi motivi, tali operazioni comportano l'assunzione di rischi più elevati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1498", "question": "Cosa caratterizza la rischiosità degli investimenti in strumenti finanziari derivati?", "answer": "Gli strumenti finanziari derivati sono caratterizzati da una rischiosità molto elevata il cui apprezzamento da parte dell'investitore è ostacolato dalla loro complessità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1499", "question": "Quando l'investitore dovrebbe concludere un'operazione avente ad oggetto strumenti finanziari derivati?", "answer": "E' necessario che l'investitore concluda un'operazione avente ad oggetto tali strumenti solo dopo averne compreso la natura ed il grado di esposizione al rischio che essa comporta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1500", "question": "Perché la complessità degli strumenti derivati può essere un rischio?", "answer": "La complessità di tali strumenti può favorire l'esecuzione di operazioni non adeguate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1501", "question": "La negoziazione di strumenti derivati è adatta a tutti gli investitori?", "answer": "In generale, la negoziazione di strumenti finanziari derivati non è adatta per molti investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1502", "question": "Quali verifiche devono fare l'investitore e l'intermediario prima di investire in strumenti derivati?", "answer": "Devono verificare se l'investimento è adeguato per l'investitore, con particolare riferimento alla situazione patrimoniale, agli obiettivi d'investimento ed alla esperienza nel campo degli investimenti in strumenti finanziari derivati di quest'ultimo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1503", "question": "Cosa si intende per effetto leva nei futures?", "answer": "L'ammontare del margine iniziale è ridotto rispetto al valore dei contratti e ciò produce il così detto \"effetto di leva\". Questo significa che un movimento dei prezzi di mercato relativamente piccolo avrà un impatto proporzionalmente più elevato sui fondi depositati presso l'intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1504", "question": "Cosa può accadere se i movimenti di mercato sono sfavorevoli per l'investitore in futures?", "answer": "Se i movimenti di mercato sono a sfavore dell'investitore, egli può essere chiamato a versare fondi ulteriori con breve preavviso al fine di mantenere aperta la propria posizione in futures. Se non provvede, la posizione può essere liquidata in perdita e l'investitore debitore di ogni altra passività prodottasi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1505", "question": "Perché alcune tipologie di ordini di riduzione del rischio possono risultare inefficaci?", "answer": "Particolari condizioni di mercato potrebbero rendere impossibile l'esecuzione di tali ordini.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1506", "question": "Qual è il rischio principale nell'acquisto di un'opzione?", "answer": "L'acquisto di un'opzione è un investimento altamente volatile ed è molto elevata la probabilità che l'opzione giunga a scadenza senza alcun valore. In tal caso, l'investitore avrà perso l'intera somma utilizzata per l'acquisto del premio più le commissioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1507", "question": "Cosa comporta l'esercizio di un'opzione?", "answer": "L'esercizio dell'opzione può comportare o il regolamento in denaro di un differenziale oppure l'acquisto o la consegna dell'attività sottostante.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1508", "question": "Cosa deve considerare un investitore che acquista un'opzione deep out of the money?", "answer": "Deve considerare che la possibilità che l'esercizio dell'opzione diventi profittevole è remota.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1509", "question": "Perché la vendita di un'opzione è più rischiosa del suo acquisto?", "answer": "La vendita di un'opzione comporta in generale l'assunzione di un rischio molto più elevato di quello relativo al suo acquisto. Anche se il premio ricevuto per l'opzione venduta è fisso, le perdite che possono prodursi in capo al venditore dell'opzione possono essere potenzialmente illimitate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1510", "question": "Come può essere ridotta l'esposizione al rischio del venditore di un'opzione?", "answer": "L'esposizione al rischio del venditore può essere ridotta detenendo una posizione sul sottostante corrispondente a quella con riferimento alla quale l'opzione è stata venduta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1511", "question": "Cosa deve fare l'investitore prima di operare con contratti derivati?", "answer": "L'investitore deve informarsi presso il proprio intermediario circa i termini e le condizioni dei contratti derivati su cui ha intenzione di operare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1512", "question": "Quali effetti possono avere condizioni di illiquidità del mercato o regole come i circuit breakers?", "answer": "Condizioni particolari di illiquidità del mercato nonché l'applicazione di talune regole vigenti su alcuni mercati possono accrescere il rischio di perdite rendendo impossibile effettuare operazioni o liquidare o neutralizzare le posizioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1513", "question": "Cosa rappresenta il rischio di cambio per i contratti denominati in valute diverse?", "answer": "I guadagni e le perdite relativi a contratti denominati in divise diverse da quella di riferimento per l'investitore potrebbero essere condizionati dalle variazioni dei tassi di cambio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1514", "question": "Perché le operazioni su strumenti derivati fuori dai mercati organizzati sono più rischiose?", "answer": "Perché può risultare difficoltoso o impossibile liquidare una posizione o apprezzarne il valore effettivo e valutare l'effettiva esposizione al rischio. Per questi motivi, tali operazioni comportano l'assunzione di rischi più elevati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1515", "question": "Cosa distingue i contratti di swaps rispetto ad altri strumenti derivati?", "answer": "Per i contratti di swaps non esiste un mercato secondario e non esiste una forma standard. Esistono modelli standardizzati di contratto che sono solitamente adattati caso per caso nei dettagli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1516", "question": "Da cosa dipende la rischiosità della linea di gestione patrimoniale?", "answer": "La rischiosità della linea di gestione è espressa dalla variabilità dei risultati economici conseguiti dal gestore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1517", "question": "Cosa deve fare l'investitore prima di concludere un contratto di gestione patrimoniale?", "answer": "L'investitore deve informarsi approfonditamente presso l'intermediario sulle caratteristiche e sul grado di rischio della linea di gestione che intende prescegliere e deve concludere il contratto solo se è ragionevolmente sicuro di aver compreso la natura della linea di gestione ed il grado di esposizione al rischio che essa comporta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1518", "question": "Cosa devono valutare l'investitore e l'intermediario prima di concludere un contratto di gestione patrimoniale?", "answer": "Prima di concludere il contratto, una volta apprezzato il grado di rischio della linea di gestione prescelta, l'investitore e l'intermediario devono valutare se l'investimento è adeguato per l'investitore, con particolare riferimento alla situazione patrimoniale, agli obiettivi d'investimento ed alla esperienza nel campo degli investimenti in strumenti finanziari di quest'ultimo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1519", "question": "Che cosa si intende per rischiosità di una linea di gestione di patrimoni personalizzata?", "answer": "La rischiosità di una linea di gestione di patrimoni personalizzata dipende principalmente dalla definizione delle categorie di strumenti finanziari in cui può essere investito il patrimonio del risparmiatore e dai limiti previsti per ciascuna categoria, nonché dal grado di leva finanziaria utilizzabile nell'ambito della linea di gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1520", "question": "Da cosa dipendono le caratteristiche di rischio di una linea di gestione?", "answer": "Le caratteristiche di rischio di una linea di gestione tenderanno a riflettere la rischiosità degli strumenti finanziari in cui essa può investire, in relazione alla quota che tali strumenti rappresentano rispetto al patrimonio gestito.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1521", "question": "Cosa accade se una linea di gestione investe una parte rilevante del patrimonio in titoli a basso rischio?", "answer": "Una linea di gestione che preveda l'investimento di una percentuale rilevante del patrimonio in titoli a basso rischio avrà caratteristiche di rischio similari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1522", "question": "E se la percentuale di investimenti a basso rischio è relativamente piccola?", "answer": "Ove la percentuale d'investimenti a basso rischio prevista fosse relativamente piccola, la rischiosità complessiva della linea di gestione sarà diversa e più elevata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1523", "question": "Che cosa rappresenta la leva finanziaria?", "answer": "La leva finanziaria misura di quante volte l'intermediario può incrementare il controvalore degli strumenti finanziari detenuti in gestione per conto del cliente rispetto al patrimonio di pertinenza del cliente stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1524", "question": "Qual è la misura della leva finanziaria che può considerarsi adeguata per molti investitori?", "answer": "Per molti investitori deve considerarsi adeguata una leva finanziaria pari ad uno.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1525", "question": "Che effetto ha una leva finanziaria pari ad uno sulla rischiosità della linea di gestione?", "answer": "Una leva finanziaria pari ad uno non influisce sulla rischiosità della linea di gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1526", "question": "Cosa comporta l'incremento della leva finanziaria utilizzata?", "answer": "L'incremento della leva finanziaria utilizzata comporta un aumento della rischiosità della linea di gestione patrimoniale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1527", "question": "Come può l'intermediario innalzare la misura della leva finanziaria?", "answer": "L'intermediario può innalzare la misura della leva finanziaria facendo ricorso a finanziamenti, oppure concordando con le controparti di regolare in modo differito le operazioni, ovvero utilizzando strumenti finanziari derivati ove previsti dalla linea di gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1528", "question": "Cosa deve fare l'investitore prima di selezionare una leva finanziaria superiore all'unità?", "answer": "L'investitore, prima di selezionare una misura massima della leva finanziaria superiore all'unità, oltre a valutarne con l'intermediario l'adeguatezza in relazione alle proprie caratteristiche personali, deve indicare nel contratto di gestione il limite massimo di perdite al raggiungimento delle quali l'intermediario è tenuto a riportare la leva finanziaria ad un valore pari ad uno, comprendere che variazioni di modesta entità dei prezzi degli strumenti finanziari possono determinare variazioni tanto più elevate quanto maggiore è la misura della leva finanziaria utilizzata, e comprendere che l'uso di una leva finanziaria superiore all'unità può provocare perdite anche eccedenti il patrimonio conferito in gestione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1529", "question": "Quali rischi comporta l'uso di una leva finanziaria superiore all'unità?", "answer": "L'uso di una leva finanziaria superiore all'unità può provocare, in caso di risultati negativi della gestione, perdite anche eccedenti il patrimonio conferito in gestione e l'investitore potrebbe trovarsi in una situazione di debito nei confronti dell'intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1530", "question": "Quali sono gli altri rischi generali connessi al servizio di gestione patrimoniale?", "answer": "Nell'ambito del servizio di gestione patrimoniale vengono effettuate dall'intermediario per conto del cliente operazioni su strumenti finanziari, ed è opportuno che l'investitore prenda conoscenza di quanto riportato nelle parti \"A\" e \"B\" del documento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1531", "question": "Cosa deve fare l'investitore prima di concludere il contratto di gestione patrimoniale riguardo alle commissioni e agli oneri?", "answer": "Prima di concludere il contratto di gestione, l'investitore deve ottenere dettagliate informazioni a riguardo di tutte le commissioni e delle modalità di calcolo delle medesime, delle spese e degli altri oneri dovuti all'intermediario. Tali informazioni devono essere comunque riportate nel contratto d'intermediazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1532", "question": "Cosa deve considerare l'investitore nel valutare la congruità delle commissioni di gestione patrimoniale?", "answer": "Nel valutare la congruità delle commissioni di gestione patrimoniale, l'investitore deve considerare che modalità di applicazione delle commissioni collegate, direttamente o indirettamente, al numero delle operazioni eseguite potrebbero aumentare il rischio che l'intermediario esegua operazioni non necessarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/rischi-dell-investimento"}},
{"id": "chunk_1533", "question": "Chi può prestare i servizi di investimento?", "answer": "I servizi di investimento, appunto perché coinvolgono un tema importante come il risparmio, non possono essere prestati da chiunque, ma solo da soggetti dotati di una specifica autorizzazione rilasciata, per quanto concerne le entità di diritto italiano, a seconda dei casi, dalla Consob o dalla Banca d'Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#2"}},
{"id": "chunk_1534", "question": "Quali soggetti possono essere autorizzati a prestare servizi di investimento?", "answer": "L'autorizzazione può essere rilasciata a: società di intermediazione mobiliare (sim) italiane: possono essere autorizzate dalla Consob ad offrire tutti i servizi di investimento; banche italiane: possono essere autorizzate dalla Banca d'Italia ad offrire tutti i servizi di investimento; società di gestione del risparmio: possono essere autorizzate dalla Banca d'Italia all'esercizio dell'attività di gestione di portafogli, dell'attività di consulenza e di commercializzazione di fondi comuni o sicav; intermediari finanziari iscritti nell'elenco previsto dall'art. 107 del Testo unico bancario tenuto dalla Banca d'Italia: possono essere autorizzati alla negoziazione per conto proprio e all'esecuzione degli ordini dei clienti (limitatamente agli strumenti finanziari derivati), nonché al servizio di sottoscrizione o collocamento; banche di Paesi comunitari: possono offrire in Italia i servizi per i quali sono state autorizzate dall'autorità di vigilanza del Paese d'origine; imprese di investimento di Paesi comunitari: possono offrire in Italia i servizi per i quali sono state autorizzate dall'autorità di vigilanza del Paese d'origine; imprese di investimento extra-comunitarie: possono essere autorizzate dalla Consob ad offrire in Italia tutti i servizi di investimento; banche extra-comunitarie: possono essere autorizzate dalla Banca d'Italia ad offrire in Italia tutti i servizi di investimento; agenti di cambio iscritti nel ruolo unico nazionale tenuto dal Ministero dell'economia e delle finanze: possono svolgere l'attività di esecuzione di ordini, collocamento, gestione di portafogli, ricezione e trasmissione di ordini e consulenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#2"}},
{"id": "chunk_1535", "question": "Perché l'autorizzazione è importante?", "answer": "L'autorizzazione non è un'inutile pratica burocratica. Consente di verificare la sussistenza dei requisiti di professionalità, onorabilità e solidità finanziaria e sottopone i soggetti autorizzati ad un regime di vigilanza continua.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#2"}},
{"id": "chunk_1536", "question": "Cosa deve fare un investitore prima di investire con un intermediario?", "answer": "E' bene quindi, quando si entra in contatto con un intermediario, verificare che sia autorizzato. Verificare, poi, non è difficile, anche perché prima di investire l'intermediario deve dichiarare di essere in possesso dell'autorizzazione e indicare l'autorità (e il relativo recapito) che l'ha rilasciata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#2"}},
{"id": "chunk_1537", "question": "Dove si può verificare se un intermediario è autorizzato?", "answer": "La Consob sul proprio sito internet pubblica l'albo delle imprese di investimento italiane (sim), di quelle comunitarie e di quelle extra-comunitarie. Ciascuno può quindi verificare se l'intermediario con cui è entrato in contatto è autorizzato e a quali servizi. Analoga verifica può essere effettuata presso la Banca d'Italia per i soggetti bancari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#2"}},
{"id": "chunk_1538", "question": "Come funzionano i servizi di investimento in Europa?", "answer": "Nel mercato unico europeo le imprese di investimento e le banche dei Paesi comunitari possono svolgere liberamente la propria attività in tutti gli altri Paesi della Comunità europea. A questo fine occorre che le regole che governano i servizi di investimento siano le stesse in ogni Paese. Per questo motivo, sono le stesse norme comunitarie (direttive e regolamenti) che disciplinano nel dettaglio la materia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1539", "question": "Cosa fanno le normative nazionali riguardo ai servizi di investimento?", "answer": "Le normative nazionali, che recepiscono negli ordinamenti dei singoli Paesi le previsioni comunitarie, si limitano, in sostanza, a riprodurre ed eventualmente dettagliare le norme comunitarie: vi sono infatti forti vincoli a che il legislatore nazionale possa inserire regole e previsioni diverse (anche se più tutelanti per i risparmiatori).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1540", "question": "È possibile che una banca straniera offra servizi di investimento in Italia?", "answer": "E' quindi possibile - anzi, nell'ottica del mercato unico, normale - che una banca ad esempio inglese offra in Italia i servizi di investimento per i quali è stata autorizzata dall'autorità del suo Paese.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1541", "question": "In quali modi un'impresa di investimento può operare in altri Paesi europei?", "answer": "L'impresa di investimento o la banca può operare in altri Paesi sia direttamente, in libera prestazione di servizi o con succursale: nel primo caso opera materialmente dal proprio Paese di origine (tipicamente attraverso strumenti di comunicazione a distanza, quali internet); nel secondo stabilisce nel Paese in cui offre i propri servizi una succursale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1542", "question": "Cambia qualcosa per il risparmiatore se opera con un intermediario estero?", "answer": "Per il risparmiatore dovrebbe essere indifferente essere cliente di un soggetto francese piuttosto che inglese o italiano: i livelli di tutela, infatti, sono sempre quelli fissati dalla normativa comunitaria.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1543", "question": "Qual è l'autorità di vigilanza competente se un intermediario opera in libera prestazione di servizi o tramite succursale?", "answer": "L'autorità di vigilanza che controlla l'intermediario è diversa: se l'intermediario opera in libera prestazione di servizi, l'autorità competente sarà quella del Paese di origine dell'intermediario; se invece opera attraverso una succursale, all'autorità del Paese dove è situata la succursale (Paese ospitante) spetta il compito di vigilare sulle regole di condotta, mentre all'autorità del Paese di origine spetta il compito di vigilare sulla sana e prudente gestione dell'intermediario (cioè sulla sua stabilità patrimoniale).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1544", "question": "Cosa deve considerare il risparmiatore in caso di controversie con un intermediario estero?", "answer": "Occorre poi considerare che, in caso di controversie, il risparmiatore potrebbe dover adire organi giurisdizionali o di risoluzione stragiudiziale delle controversie (sistemi di conciliazione e di arbitrato) stranieri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1545", "question": "A chi può rivolgersi il risparmiatore per individuare l'organismo di risoluzione stragiudiziale competente?", "answer": "Per individuare l'organismo di risoluzione stragiudiziale competente, il risparmiatore può rivolgersi all'organismo del proprio Paese (per l'Italia, attualmente, la Camera di Conciliazione e Arbitrato).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1546", "question": "Cosa deve considerare il risparmiatore in caso di controversie con un intermediario estero e come può individuare l'organismo competente?", "answer": "Occorre poi considerare che, in caso di controversie, il risparmiatore potrebbe dover adire organi giurisdizionali o di risoluzione stragiudiziale delle controversie (sistemi di conciliazione e di arbitrato) stranieri. Per individuare l'organismo di risoluzione stragiudiziale competente, il risparmiatore può rivolgersi all'organismo del proprio Paese (per l'Italia, attualmente, la Camera di Conciliazione e Arbitrato).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#3"}},
{"id": "chunk_1547", "question": "Qual è l'obiettivo principale delle regole che disciplinano i servizi di investimento?", "answer": "Assicurare la correttezza del comportamento degli intermediari e consentire al cliente scelte di investimento informate, consapevoli e rispondenti alle proprie esigenze.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1548", "question": "Quali principi generali impone il Testo unico della finanza ai soggetti abilitati?", "answer": "Comportarsi con diligenza, correttezza e trasparenza, per servire al meglio l'interesse dei clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1549", "question": "Cosa significa comportarsi con diligenza per un intermediario?", "answer": "Agire in maniera professionalmente adeguata, cioè conoscere e fare bene il proprio mestiere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1550", "question": "Cosa implica la correttezza nella prestazione dei servizi di investimento?", "answer": "Comportarsi con lealtà, senza secondi fini oltre quello dell'interesse del cliente, e rispettare tutte le prescrizioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1551", "question": "Cosa si intende per trasparenza nel contesto dei servizi di investimento?", "answer": "Rendere al cliente tutte le informazioni necessarie sul servizio prestato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1552", "question": "Perché è importante l'informazione quando si parla di investimenti?", "answer": "Conoscere per investire: è la regola fondamentale. Se non si conosce, è meglio non investire: il corollario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1553", "question": "Quali informazioni deve fornire l'intermediario prima che il cliente investa?", "answer": "Deve fornire informazioni sul servizio offerto, sugli strumenti finanziari e sui costi, in tempo utile prima di investire e su supporto duraturo oppure, se il cliente acconsente, su un sito internet.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1554", "question": "Che tipo di informazioni l'intermediario deve fornire su se stesso e sul servizio offerto?", "answer": "I recapiti e la lingua da usare per comunicare, la dichiarazione di essere autorizzato e l'autorità che ha rilasciato l'autorizzazione, i metodi di comunicazione tra cliente e impresa, le modalità di rendicontazione, la tutela delle somme o dei titoli dei clienti, il sistema di indennizzo o garanzia e la politica sui conflitti di interessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1555", "question": "Quali informazioni deve dare l'intermediario sui rischi degli strumenti finanziari?", "answer": "Deve descrivere le caratteristiche e i rischi del tipo di strumento finanziario, evidenziando, se pertinenti, il rischio di perdita totale, l'effetto leva, le oscillazioni di prezzo, i limiti alla liquidabilità, eventuali obbligazioni aggiuntive e pratiche di marginatura connesse all'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1556", "question": "Cosa deve comunicare l'intermediario riguardo ai costi del servizio?", "answer": "Il prezzo totale comprensivo di ogni competenza, commissione, onere, spesa e imposta, i singoli elementi che compongono il costo totale, le spese e i tassi di cambio per gli investimenti in valuta e la possibilità di costi e imposte ulteriori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1557", "question": "Perché è importante conoscere i costi di un investimento?", "answer": "Perché il loro ammontare limita il rendimento dell'investimento, a volte anche in maniera significativa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1558", "question": "Cosa deve fare l'intermediario dopo che il cliente ha investito?", "answer": "Deve inviare ai clienti la rendicontazione dell'attività prestata, comprensiva anche dei costi per il cliente, secondo modalità specifiche per ciascun servizio di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1559", "question": "Perché il contratto per i servizi di investimento deve essere scritto?", "answer": "Per enfatizzare l'importanza dell'atto, attrarre l'attenzione di chi lo compie e fissare in un documento i contenuti dell'accordo fra le parti per poterli dimostrare in futuro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1560", "question": "Quali elementi deve contenere il contratto di investimento?", "answer": "Il servizio e le prestazioni dovute, le modalità di modifica e rinnovo, le istruzioni del cliente, la frequenza della rendicontazione, la soglia di perdita, la remunerazione dell'intermediario, la consulenza collegata e le procedure di conciliazione e arbitrato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1561", "question": "Cosa significa valutare l'adeguatezza di un investimento?", "answer": "Significa verificare se il servizio o l'operazione corrisponde agli obiettivi di investimento del cliente, non pone rischi non sopportabili e comporta rischi che il cliente può comprendere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1562", "question": "Quali informazioni deve raccogliere l'intermediario per valutare l'adeguatezza di un investimento?", "answer": "Deve conoscere la conoscenza ed esperienza del cliente in materia di investimenti, la situazione finanziaria e gli obiettivi di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1563", "question": "Che differenza c'è tra adeguatezza e appropriatezza?", "answer": "L'adeguatezza è una valutazione più ampia, che considera conoscenza, esperienza, situazione finanziaria e obiettivi del cliente; l'appropriatezza è più limitata e riguarda solo la conoscenza ed esperienza del cliente in relazione al tipo di strumento o servizio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1564", "question": "Quando l'intermediario deve valutare l'appropriatezza di un investimento?", "answer": "Per tutti i servizi di investimento tranne la consulenza in materia di investimenti e la gestione di portafogli.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1565", "question": "Cosa deve fare l'intermediario se ritiene non appropriato un investimento?", "answer": "Deve avvertire il cliente che il prodotto non è appropriato, segnalando che il cliente non è in grado di valutare i rischi connessi al prodotto stesso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1566", "question": "Cos'è la mera esecuzione di ordini?", "answer": "È una modalità di svolgimento dei servizi di esecuzione o ricezione e trasmissione di ordini, nella quale l'intermediario esegue l'ordine senza valutare l'appropriatezza e senza chiedere informazioni al cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1567", "question": "A quali strumenti si può applicare la mera esecuzione di ordini?", "answer": "Azioni quotate in un mercato regolamentato, strumenti del mercato monetario, obbligazioni e altri titoli di debito, fondi armonizzati e altri strumenti finanziari non complessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1568", "question": "Chi dovrebbe evitare la mera esecuzione di ordini?", "answer": "Chi non è particolarmente esperto della materia, perché si priverebbe della tutela derivante dall'obbligo dell'intermediario di valutare l'appropriatezza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1569", "question": "Cosa sono gli incentivi nel contesto dei servizi di investimento?", "answer": "Sono compensi, commissioni o prestazioni non monetarie pagati o ricevuti da un intermediario in connessione alla prestazione di un servizio di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1570", "question": "Quando gli incentivi sono ammessi?", "answer": "Quando sono ricevuti o pagati al cliente, quando sono ricevuti o pagati a soggetti diversi ma accrescono la qualità del servizio e sono compatibili con l'interesse del cliente, o quando sono necessari alla prestazione dei servizi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1571", "question": "Cosa deve fare l'intermediario in presenza di conflitti di interessi?", "answer": "Deve individuare le situazioni che possono generare conflitti, gestirle con misure organizzative adeguate, redigere una politica scritta e informare il cliente nei casi eccezionali in cui il conflitto non possa essere neutralizzato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1572", "question": "Cosa deve contenere la politica di gestione dei conflitti di interessi?", "answer": "L'individuazione delle situazioni di conflitto e le misure organizzative per gestirle, garantendo che i soggetti coinvolti agiscano con un adeguato livello di indipendenza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1573", "question": "Cosa deve fare il cliente se riceve una comunicazione di conflitto di interessi dall'intermediario?", "answer": "Deve leggere attentamente la comunicazione, capire se e come l'interesse dell'intermediario può nuocere al proprio e, in caso di dubbio, può rivolgersi a un altro intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1574", "question": "Cosa succede se l'intermediario informa il cliente di un conflitto di interessi?", "answer": "La comunicazione non esime l'intermediario dall'adottare tutti gli accorgimenti per evitare che la situazione crei un danno al cliente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/i-servizi-di-investimento1#4"}},
{"id": "chunk_1575", "question": "Perché è importante proteggere i propri risparmi?", "answer": "Il nostro risparmio è quindi un bene prezioso - che può permetterci soddisfazioni future o, più semplicemente, la serenità della nostra famiglia - e bisogna salvaguardarlo. L'ultima cosa che deve capitarci è vederlo volatilizzato nelle mani di truffatori o persone che non hanno i requisiti e la capacità per proteggerlo e farlo fruttare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1576", "question": "Chi può offrire servizi di investimento in Italia?", "answer": "I servizi di investimenti, nel nostro Paese, possono essere offerti solamente da soggetti che siano stati autorizzati, dopo aver verificato il possesso di requisiti di onorabilità, professionalità e organizzativi. Il perché è semplice: per gestire investimenti occorrono capacità e organizzazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1577", "question": "Cosa accade se consegniamo denaro a un soggetto abusivo o truffatore?", "answer": "Quando poi consegniamo il nostro denaro ad un soggetto che non solo è un abusivo, ma è anche un truffatore, allora … le probabilità di rivederlo indietro sono veramente prossime allo zero.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1578", "question": "Come possiamo difenderci dai truffatori finanziari?", "answer": "Difenderci dai truffatori non è difficile, e in questa sezione si trovano utili suggerimenti. Il primo è che nessuno regala nulla e, quindi, non esiste l'\"affare del secolo\" e non esistono metodi facili per assicurarsi guadagni sicuri tali, magari, da consentirvi di arrotondare lo stipendio o, addirittura, licenziarvi. E men che meno sono \"affari del secolo\" quelli che vengono propugnati come tali, con l'invito a sbrigarsi perché è un'opportunità da cogliere \"al volo\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1579", "question": "Perché gli operatori abusivi sono pericolosi per i risparmiatori?", "answer": "Altrettanto pericolosi per i nostri risparmi sono i soggetti che operano abusivamente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1580", "question": "Cosa sono le truffe e come si manifestano nel tempo?", "answer": "Le truffe sono sempre esistite, come sempre sono esistiti altri fenomeni criminali. Lo Stato predispone un'articolata organizzazione - formata da forze dell'ordine, magistratura, enti pubblici - con il compito di contrastarli. Non sempre, malgrado l'impegno, si riesce a reprimere totalmente questi fenomeni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1581", "question": "Qual è il ruolo personale nella difesa dai rischi di truffe?", "answer": "Difenderci è anche compito nostro. E, più o meno consapevolmente, lo facciamo continuamente: ad esempio, la mattina quando usciamo e diamo doppia mandata alla porta blindata, oppure quando saliamo sull'autobus e controlliamo che la borsa sia ben chiusa e la stringiamo a noi. Piccoli accorgimenti che, quasi sempre, ci consentono di condurre serenamente la nostra vita al riparo da fatti sgraditi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1582", "question": "Come possiamo difendere i risparmi dagli abusivismi finanziari?", "answer": "Anche per gli abusivismi finanziari potrete trovare in questa sezione i casi più ricorrenti e suggerimenti per scoprire in tempo di essersi imbattuti in un intermediario abusivo. Non è difficile, e internet aiuta molto. Basta dedicare un po' di tempo sul sito della Consob e delle altre Autorità di vigilanza, nonché sui motori di ricerca, per potersi fare un'idea del soggetto con cui pensiamo di intrattenere rapporti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1583", "question": "Cosa possiamo fare per evitare di cadere in trappole finanziarie?", "answer": "Spesso basta un \"clic\" per salvare i nostri risparmi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1584", "question": "Perché non bisogna fidarsi di chi promette guadagni facili?", "answer": "Nessuno regala nulla e, quindi, non esiste l'\"affare del secolo\" e non esistono metodi facili per assicurarsi guadagni sicuri tali, magari, da consentirvi di arrotondare lo stipendio o, addirittura, licenziarvi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1585", "question": "Cosa offre la sezione del sito CONSOB sulle truffe finanziarie?", "answer": "In questa sezione del sito forniamo una descrizione delle truffe più frequenti, anche con un interessante richiamo a truffe \"storiche\" che costituiscono una sorta di \"evergreen\", con la loro capacità di riproporsi con forme diverse ma con la stessa sostanza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe"}},
{"id": "chunk_1586", "question": "Cosa si intende per truffe finanziarie?", "answer": "In considerazione dei grandi flussi di denaro che possono movimentare, le attività finanziarie offerte al pubblico si prestano, purtroppo, a fenomeni fraudolenti, genericamente definiti \"truffe finanziarie\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-finanziarie"}},
{"id": "chunk_1587", "question": "Quali tipi di condotte possono rientrare nelle truffe finanziarie?", "answer": "Tali condotte possono essere di vario genere, potendosi distinguere i comportamenti illeciti messi in atto da soggetti autorizzati allo svolgimento di attività finanziaria, mediante lo sfruttamento del contatto diretto con la propria clientela, dalle condotte di soggetti non autorizzati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-finanziarie"}},
{"id": "chunk_1588", "question": "Cosa si aggiunge al comportamento fraudolento quando la truffa è compiuta da soggetti non autorizzati?", "answer": "In questo caso, al comportamento fraudolento si aggiunge un altro elemento: l'abusivismo finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-finanziarie"}},
{"id": "chunk_1589", "question": "Qual è la costante nelle truffe finanziarie?", "answer": "La costante nelle truffe finanziarie è sempre una: la perdita di tutto o gran parte del patrimonio investito che, di norma, è purtroppo difficilmente recuperabile dal malcapitato investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-finanziarie"}},
{"id": "chunk_1590", "question": "Quali sono le modalità con cui può essere architettata una truffa finanziaria?", "answer": "Molteplici sono, invece, le modalità concrete con cui la truffa può essere architettata. L'astuzia e l'immaginazione dei truffatori sembra non avere limiti: ogni giorno si devono fare i conti con inganni nuovi e sempre più elaborati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-finanziarie"}},
{"id": "chunk_1591", "question": "Esistono truffe facilmente individuabili?", "answer": "Accanto a truffe grossolane, individuabili con il buon senso e un po' di attenzione, esistono truffe molto sofisticate e ben orchestrate, che possono rappresentare una grave insidia per i risparmiatori e, talvolta, per l'intero sistema finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-finanziarie"}},
{"id": "chunk_1592", "question": "Da cosa deriva il grande successo delle truffe finanziarie?", "answer": "Il grande successo delle truffe finanziarie, è giusto dirlo, non deriva solo dalla scaltrezza dei truffatori ma, spesso, anche dal comportamento dell'investitore che, a volte accecato da un'eccessiva bramosia di guadagno, non si sofferma a chiedersi la ragione dei lauti interessi promessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1593", "question": "Chi sono gli attori coinvolti nelle truffe finanziarie?", "answer": "Truffatore e truffato sono spesso attori di uno stesso gioco nel quale, però, chi è destinato a rimetterci è sempre l'investitore.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1594", "question": "Qual è la difesa più efficace rispetto alle truffe finanziarie?", "answer": "La difesa più efficace rispetto a questi fenomeni sta nel comportamento del risparmiatore stesso il quale deve sempre: confrontare il rendimento promesso con quello offerto nello stesso periodo dagli intermediari tradizionali (ad es. banche) e chiedere le ragioni concrete di uno scostamento così rilevante dei guadagni promessi; diffidare dagli investimenti \"a rischio zero\" ma che al contempo assicurano alti rendimenti; indagare, anche attraverso l'utilizzo di banche dati private o chiedendo alla Consob, le caratteristiche dello strumento finanziario proposto dal soggetto che lo propone; acquisire una conoscenza quanto più possibile estesa dei prodotti offerti, anche attraverso l'attenta lettura della documentazione disponibile che dobbiamo sempre richiedere; effettuare i pagamenti attraverso strumenti tracciabili; meditare a fondo prima di coinvolgere amici e parenti nello stesso investimento (anche se avete già avuto dei guadagni), in quanto ci si potrebbe trovare incolpevolmente \"complici\" della truffa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1595", "question": "Perché è importante confrontare il rendimento promesso con quello offerto dagli intermediari tradizionali?", "answer": "È importante confrontare il rendimento promesso con quello offerto nello stesso periodo dagli intermediari tradizionali (ad es. banche) e chiedere le ragioni concrete di uno scostamento così rilevante dei guadagni promessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1596", "question": "Perché bisogna diffidare dagli investimenti \"a rischio zero\" che promettono alti rendimenti?", "answer": "Bisogna diffidare dagli investimenti \"a rischio zero\" ma che al contempo assicurano alti rendimenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1597", "question": "Come si possono indagare le caratteristiche di uno strumento finanziario proposto?", "answer": "Si possono indagare le caratteristiche dello strumento finanziario proposto anche attraverso l'utilizzo di banche dati private o chiedendo alla Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1598", "question": "Perché è importante acquisire conoscenza dei prodotti finanziari offerti?", "answer": "È importante acquisire una conoscenza quanto più possibile estesa dei prodotti offerti, anche attraverso l'attenta lettura della documentazione disponibile che dobbiamo sempre richiedere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1599", "question": "Perché bisogna effettuare i pagamenti attraverso strumenti tracciabili?", "answer": "Bisogna effettuare i pagamenti attraverso strumenti tracciabili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1600", "question": "Perché è necessario riflettere prima di coinvolgere amici e parenti in un investimento?", "answer": "È necessario meditare a fondo prima di coinvolgere amici e parenti nello stesso investimento (anche se avete già avuto dei guadagni), in quanto ci si potrebbe trovare incolpevolmente \"complici\" della truffa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dalle-truffe"}},
{"id": "chunk_1601", "question": "Qual è il contesto generale delle truffe finanziarie, soprattutto durante crisi come la pandemia da Covid-19?", "answer": "Ogni giorno la CONSOB vigila su molteplici casi di prestazione abusiva di servizi d'investimento e di offerta abusiva di prodotti finanziari e, ogni anno, le azioni a contrasto di queste condotte sono centinaia. Nei periodi di crisi i tentativi di truffa diventano ancora più frequenti, perché trovano terreno fertile nel clima di incertezza e preoccupazione che connota le congiunture economiche sfavorevoli e, ancor più, le fasi di emergenza sanitaria come quella che stiamo vivendo a seguito della pandemia da Covid-19, vera e propria crisi globale e globalizzata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1602", "question": "Quali sono i principali ingredienti della truffa utilizzati dal truffatore?", "answer": "Il truffatore in genere: - si presenta come un grande esperto, talvolta come un 'mago della finanza' - promette guadagni elevati, guadagni veloci e/o guadagni sicuri (o con rischi molto limitati) - non fornisce informazioni precise, parla con termini tecnici (spesso in inglese e per sigle) che possono confondere un investitore con poca esperienza oppure… - … al contrario, rimanda al proprio sito, ricco di informazioni la cui correttezza, tuttavia, è difficile da verificare - spesso ci offre un bonus (una somma da investire) per 'entrare nell'affare' e testarne la bontà… - … o l'incentivo a 'collaborare' coinvolgendo altre persone nell'affare per guadagnare di più - fa riferimento ad asserite autorizzazioni da parte dell'Autorità di vigilanza (pure indicate nel sito internet della società) - di frequente ci invita a leggere le numerose recensioni 'pilotate' e rilasciate online da altri investitori soddisfatti dei servizi offerti - talvolta fa pressione (anche dal punto di vista psicologico telefonandoci insistentemente) affinché l'affare si concluda al più presto'", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1603", "question": "Quali canali di contatto usano di solito i soggetti che svolgono abusivamente servizi di investimento?", "answer": "I soggetti che abusivamente svolgono servizi di investimento oppure offrono al pubblico prodotti finanziari operano prevalentemente tramite siti web e utilizzano, quali canali di contatto per promuovere le proprie iniziative presso i risparmiatori, soprattutto email, chat, social network e sollecitazioni telefoniche (cosiddette cold calling). Nella grande maggioranza di tali casi l'operatività finanziaria prospettata ai risparmiatori è solo apparente e cela vere e proprie truffe.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1604", "question": "In cosa consiste di solito la proposta iniziale del truffatore ai potenziali clienti?", "answer": "Il più delle volte i potenziali clienti vengono invitati ad aprire conti per il trading di 'titoli' presso la piattaforma on line (il portale/il sito) che l'operatore abusivo/truffatore indica loro. L'apertura del conto di trading consentirebbe, almeno apparentemente, di operare, effettuando acquisti e vendite, comodamente da casa e di seguire il proprio portafoglio-investimenti in tempo reale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1605", "question": "Quali dati personali e finanziari vengono spesso richiesti in fase di apertura del conto di trading?", "answer": "In fase di apertura del conto di trading viene spesso richiesto al potenziale cliente di inviare copia dei propri documenti, gli estremi della carta di credito o del conto corrente e/o di rilasciare un'apposita procura per la 'movimentazione' di tali conti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1606", "question": "Cosa accade quando l'investitore prova a prelevare le somme dal conto presso l'operatore abusivo?", "answer": "Quando l'investitore prova a prelevare in tutto o in parte le somme di denaro presenti sul suo conto tale possibilità gli viene negata e gli vengono addotti i pretesti (economici, fiscali-contrattuali o semplicemente di opportunità) più disparati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1607", "question": "Come appaiono spesso i siti degli operatori abusivi o truffatori?", "answer": "Il sito internet dell'operatore abusivo/truffatore è spesso ben progettato, accattivante, funzionale e apparentemente molto chiaro e facile da consultare. Il sito può richiamare nella denominazione e nella grafica il sito di soggetti autorizzati ben noti (cosiddetti siti-clone).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1608", "question": "Quale ulteriore tecnica promozionale usano i soggetti non autorizzati per attirare i risparmiatori?", "answer": "A volte i soggetti non autorizzati alla prestazione di servizi di investimento sfruttano l'immagine di personaggi noti in vari settori, all'insaputa di questi ultimi, per promuovere presso i risparmiatori i servizi abusivamente offerti/svolti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1609", "question": "Quali strumenti finanziari o schemi vengono spesso proposti come oggetto dell'investimento?", "answer": "Spesso si propone di investire, tramite l'apertura di conti per il trading, in contract for difference (CFD) o in altri prodotti derivati, con sottostante rappresentato da valute aventi corso legale, strumenti finanziari (quali azioni e obbligazioni), indici finanziari, materie prime e cripto-valute. In altri casi, sono proposti investimenti in 'programmi ad alto rendimento' o in contratti con promesse di rendimenti finanziari collegati a beni commerciali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1610", "question": "In cosa consistevano le offerte abusive legate a initial coin offering (ICO) descritte?", "answer": "Più di recente sono state promosse offerte abusive di prodotti finanziari aventi la veste di initial coin offering (ICO). Tali offerte promettevano agli investitori rendimenti finanziari correlati all'asserita vendita di digital token. I token sono risultati essere prodotti finanziari poiché incorporavano (esclusivamente o prevalentemente) il diritto a percepire un rendimento predefinito o predefinibile in base a parametri predeterminati, compreso tra un minimo e un massimo, espresso in misura percentuale sul capitale conferito dall'investitore. Il diritto non si riferiva dunque alla fruizione di beni o futuri servizi ovvero ad altre attività secondarie, pure prospettate nei progetti lanciati dalle società offerenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1611", "question": "Come sono strutturate e dove hanno sede le società proponenti nei casi di abusivismo?", "answer": "Gli operatori abusivi/truffatori sono spesso società fittizie o comunque società che hanno o dichiarano di avere sede in paesi extra-comunitari oppure sono apparentemente localizzate in paesi europei ma di fatto si rendono irreperibili. Spesso queste società dichiarano falsamente di essere autorizzate a operare da Autorità europee.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1612", "question": "Qual è un ulteriore schema truffaldino che colpisce le vittime dopo la truffa iniziale?", "answer": "Un ulteriore schema truffaldino prevede che, quando l'investitore ha ormai compreso di essere vittima di un soggetto abusivo, sia contattato da una sedicente società di recupero crediti che - a volte anche utilizzando illegittimamente il logo o latri segni distintivi della CONSOB - gli prospetta, a fronte di un corrispettivo in denaro, la possibilità di ottenere il rimborso delle somme già investite, salvo poi sottrargli anche queste ulteriori somme senza fornire alcun servizio.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1613", "question": "Quali sono le principali leve psicologiche su cui fa presa una proposta di investimento allettante?", "answer": "Una proposta di investimento allettante fa presa grazie ad alcuni meccanismi psicologici: - la fiducia nel truffatore: tendiamo ad affidarci ciecamente a chi ci promette quello che desideriamo, agli affabulatori, agli abili comunicatori - l'effetto gregge (così fan tutti). Quando non sappiamo cosa scegliere ci fidiamo del giudizio della folla: se in tanti hanno affidato i propri risparmi a quel mago della finanza perché non farlo anche noi?! E poi su internet si trovano tante recensioni positive! Nel nostro subconscio, inoltre, c'è anche una voce che ci sussurra che, se tutto dovesse andar male, non avremo sbagliato da soli e potremo condividere il peso della decisione sbagliata con tanti compagni di sventura! - la paura di perdere un'occasione unica (paura del rimpianto, regret avoidance o fear of missing out): sentiamo sempre dire che certi treni passano una volta sola e noi non vogliamo in futuro guardarci indietro e rimpiangere di non aver colto l'opportunità che ci stanno offrendo - l'attrazione per il guadagno facile o apparentemente privo di rischio (l'avidità): il desiderio di ricchezza può indurre a decisioni avventate anche persone molto prudenti e/o con pochi risparmi - l'impulsività: a volte si cede all'impulso e all'istinto, ma nel caso delle truffe, è sufficiente che ciò accada una volta sola per perdere i risparmi di una vita - il fascino dell'azzardo: anche se non siamo degli habitué del tavolo da gioco o dei patiti di poker avvertiamo il brivido legato alla possibilità di rischiare tutto pur di cambiare la nostra vita vincendo una somma che non potremo mai guadagnare in così poco tempo - l'eccessiva fiducia in noi stessi (overconfidence). Anche se intuiamo che l'affare proposto potrebbe essere rischioso, riteniamo di poter contare sulle nostre conoscenze o sulla nostra furbizia e siamo convinti che sapremo uscirne al momento giusto!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1614", "question": "Quale reazione può avere il truffato dopo essere caduto nella rete del truffatore?", "answer": "Una volta che l'investitore è caduto nella sua rete, il truffatore fa leva inoltre sulla propensione del truffato a negare anche l'evidenza: la vergogna di esserci 'cascati con tutte le scarpe' è tanta che si preferisce continuare a sperare e si rinuncia a denunciare!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1615", "question": "Qual è una legge base della finanza utile per proteggersi dalle truffe?", "answer": "Le leggi base della finanza. Non esistono pasti gratis: un investimento che promette un alto rendimento è anche un investimento rischioso.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1616", "question": "Chi può esercitare servizi e attività di investimento e qual è la sanzione per l'esercizio abusivo?", "answer": "L'esercizio nei confronti del pubblico di servizi e attività di investimento è riservato ai soggetti autorizzati dalle Autorità competenti (in Italia la CONSOB). La prestazione abusiva di servizi e attività di investimento consiste nello svolgimento di attività riservate (quali il collocamento di strumenti finanziari, la gestione di portafogli, la negoziazione di strumenti finanziari tra cui i contratti derivati su valute, la consulenza in materia di investimenti) in assenza di autorizzazione: l'esercizio abusivo di servizi e attività di investimento è un reato punito con la reclusione fino a un massimo di 8 anni (art. 166 del Testo unico della Finanza - Tuf).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1617", "question": "Quando si configura l'offerta abusiva di prodotti finanziari e quale documentazione deve esistere?", "answer": "Le proposte di investimento finanziario devono essere illustrate in un prospetto autorizzato da CONSOB. L'offerta abusiva di prodotti finanziari e attività pubblicitaria relativa all'offerta al pubblico si configura quando viene posta in essere o pubblicizzata un'offerta di prodotti finanziari (ad esempio, azioni, obbligazioni, fondi comuni d'investimento, polizze assicurative a carattere finanziario) senza la pubblicazione e il deposito presso la CONSOB o altra Autorità di un prospetto informativo, laddove la legge lo preveda.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1618", "question": "Quali verifiche fare se ricevi una proposta di servizio di trading online o di investimento?", "answer": "Se ti propongono un servizio di trading online o se vieni raggiunto da una proposta di investimento… - verifica sul sito CONSOB se il soggetto è autorizzato e/o se è stato già segnalato per abusivismo (consulta la sezione 'Avvisi ai risparmiatori') - chiedi informazioni al soggetto che ti ha contattato e fatti dire… - ... il nome della società e dove ha sede - ... se è autorizzata, da chi è stata autorizzata e il numero di autorizzazione - ... il sito internet - ... il nome e cognome di chi ti sta chiamando e i contatti telefonici a cui è possibile rintracciarlo - svolgi semplici ma basilari verifiche sul web - ... se possibile consulta il sito dell'autorità che avrebbe autorizzato il soggetto - ... inserisci il nome della società o del sito internet nel motore di ricerca e verifica cosa si legge sul web - verifica che il tipo di investimento che ti è stato proposto non rientri tra quelli che la CONSOB ha vietato o sconsigliato (Contract for difference - CFD, rolling spot forex e opzioni binarie;) - chiedi (nel caso in cui tu abbia ricevuto una proposta di investimento) se c'è un prospetto autorizzato, verifica sul sito CONSOB e, se non trovi il prospetto, scrivi a CONSOB per avere informazioni prima di investire - ricorda che, in generale, il trading online è una modalità di investimento adatta solo a investitori particolarmente esperti e che le perdite molto spesso in media superano ampiamente in guadagni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1619", "question": "Quali accorgimenti generali adottare prima di investire?", "answer": "In ogni caso… - prendi tutto il tempo necessario per raccogliere informazioni e fare verifiche - confronta il rendimento promesso con quello offerto nello stesso periodo da altri operatori del mercato - medita a fondo prima di coinvolgere amici e parenti (anche se hai già avuto dei guadagni)", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1620", "question": "Quali azioni intraprendere se hai già investito con un soggetto abusivo?", "answer": "Se hai già investito e hai scoperto che il soggetto è abusivo: - invia un esposto alla CONSOB - denuncia il soggetto anche alle autorità di pubblica sicurezza per le implicazioni per la privacy (ha il tuo telefono, gli estremi dei tuoi documenti personali, i dati bancari…) - segnala il soggetto a CONSOB", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/truffe-finanziarie-covid"}},
{"id": "chunk_1621", "question": "Quali sono le truffe finanziarie più pericolose e ricorrenti?", "answer": "Le truffe finanziarie più pericolose e ricorrenti utilizzano quasi sempre le medesime modalità. Si tratta di schemi da tempo \"collaudati\", che però sembrano aver trovato una nuova linfa con la diffusione di internet.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1622", "question": "Qual è la tipologia di truffa finanziaria più frequente?", "answer": "La tipologia di truffa finanziaria più frequente è sicuramente il cosiddetto \"schema piramidale\" detto anche \"schema Ponzi\", dal nome del suo ideatore, operante negli Stati Uniti agli inizi del ‘900. È uno schema che non sembra preoccuparsi dei segni del tempo, essendo stato utilizzato anche in anni recenti da Bernard Madoff per una delle truffe più eclatanti di tutti i tempi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1623", "question": "Che cos'è lo schema Ponzi?", "answer": "Lo schema Ponzi è un'attività truffaldina nella quale chi entra per primo ottiene ritorni economici a spese dei successivi \"investitori\". Si tratta, in parole diverse, di una specie di \"catena di Sant'Antonio\", nella quale vengono promessi interessi molto elevati, pagati agli \"investitori\" mediante il denaro apportato dai nuovi soggetti che hanno aderito successivamente allo schema.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1624", "question": "Fino a quando riesce a funzionare lo schema Ponzi?", "answer": "Il gioco funziona fino a quando resta elevata la capacità di attrarre nuovi partecipanti. Quando, invece, il nuovo denaro in entrata non riesce più a coprire gli interessi promessi a coloro che già sono coinvolti nello schema, il circuito si blocca, manifestando la sua natura di truffa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1625", "question": "Quali sono le principali caratteristiche dello schema Ponzi?", "answer": "Le principali caratteristiche dello schema Ponzi sono: - la prospettata possibilità di realizzare ingenti guadagni in poco tempo e con poco rischio, grazie all'operato di un \"mago della fnanza\"; - una documentazione fumosa, parzialmente coperta da segreto o caratterizzata da investimenti speculativi genericamente qualificati come di \"alta finanza\"; - un insieme di partecipanti non competenti in materia finanziaria o che hanno riposto una grande fiducia personale nell'organizzatore del sistema; - un'attività di investimento legata ad un solo promotore o azienda o prodotto; - un'elevatissima rischiosità che cresce con l'aumentare dei partecipanti e non viene, però, normalmente percepita da chi ha aderito allo schema: la remunerazione regolarmente ricevuta nei primi tempi induce, infatti, a pensare che la partecipazione allo schema sia una seria e solida opportunità di investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1626", "question": "Cosa accade quando il flusso di nuovi investitori nello schema Ponzi si interrompe?", "answer": "Come detto, lo schema riesce a funzionare sino a quando le richieste di rimborso, sommate agli interessi da pagare, non superano gli apporti di denaro dei nuovi aderenti. Quando, però, sorgono i primi problemi nel pagamento delle somme a cui si ha diritto, di norma è già troppo tardi. Il truffatore è già sparito o ha fatto sparire tutti i soldi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1627", "question": "Cosa insegnano gli esempi di truffe Ponzi agli investitori?", "answer": "I due esempi sotto illustrati aiutano a comprendere come l'avidità, ma a volte anche il bisogno di sicurezza, possano accecare gli investitori togliendogli la lucidità necessaria per comprendere che certe promesse di guadagno sono semplicemente troppo belle per essere vere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1628", "question": "Chi era Carlo Ponzi?", "answer": "Carlo Ponzi, l'ideatore dello schema truffaldino che porta il suo nome, nacque nel 1882 ed è universalmente considerato uno dei più grandi truffatori della storia americana. Nel 1903, arrivò a Boston con soli 2 dollari e 50 centesimi, in quanto i risparmi che si era portato dall'Italia erano stati persi con il gioco d'azzardo durante la lunga traversata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1629", "question": "Dove trovò lavoro Ponzi nel 1907 e che tipo di attività svolgeva?", "answer": "Nel 1907 Ponzi trovò lavoro a Montreal come consulente di una banca fondata da Luigi Zarossi, il Banco Zarossi. Il tasso di mercato dell'epoca era circa il 3% ma questa banca, che gestiva i risparmi degli immigrati, garantiva ben il 6'%' facendo, ovviamente, incetta di risparmi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1630", "question": "Perché fallì il Banco Zarossi?", "answer": "Ben presto Ponzi si rese conto della situazione critica e delle difficoltà economiche della banca, che pagava i cospicui interessi utilizzando il denaro dei nuovi correntisti attraverso un sistema destinato a fallire e, infatti, la banca fallì e Zarossi scappò in Messico con il denaro rimasto in cassa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1631", "question": "Quale nuova attività cercò di avviare Ponzi dopo il fallimento della banca?", "answer": "Successivamente, Ponzi cercò di creare un volume unico con gli annunci pubblicitari di vari commercianti, una sorta di Pagine Gialle, che però, sfortunatamente, non riuscì a trasformarsi in un business redditizio e l'impresa fallì miserabilmente.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1632", "question": "Come scoprì Ponzi i buoni di risposta internazionale?", "answer": "Nonostante l'impresa di Ponzi fosse oramai fallita, qualche settimana dopo una società spagnola richiese informazioni in merito ai cataloghi e dentro la busta inserì un buono di risposta internazionale (in inglese: International Reply Coupon o anche IRC), una cosa che Ponzi, pur avendo lavorato per le Poste italiane, non aveva mai visto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1633", "question": "Che cos'era il buono di risposta internazionale e quando nacque?", "answer": "Il buono di risposta internazionale - nato il 26 maggio 1906 durante il congresso UPU (Unione Postale Universale) di Roma e venduto a partire dal 1° ottobre 1907 in una sessantina di paesi - era un buono postale che consentiva al mittente di pagare la tariffa di risposta del ricevente nell'ambito di una corrispondenza internazionale.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1634", "question": "Qual era l'utilità del buono di risposta internazionale?", "answer": "L'utilità del buono di risposta internazionale era indubbia: permetteva, infatti, ai residenti di una nazione di rimborsare il costo della risposta del destinatario di un messaggio semplicemente usando il buono per richiedere, nel proprio Paese, i francobolli necessari alla risposta.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1635", "question": "Come funzionava il buono di risposta internazionale nelle corrispondenze tra Paesi diversi?", "answer": "Se la lettera avesse richiesto una risposta nello stesso Stato dell'invio non ci sarebbero stati problemi, poiché sarebbe stato sufficiente inserire dei francobolli validi in tutto il territorio dello Stato, ma se la risposta era richiesta da un soggetto di una nazione diversa da quella del destinatario, ecco che i francobolli non potevano essere inviati perché non avevano alcun valore. Con il buono di risposta internazionale era sufficiente recarsi in un ufficio postale per ottenere l'affrancatura minima per un invio di posta aerea per l'estero.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1636", "question": "Perché i buoni di risposta internazionale potevano generare un arbitraggio?", "answer": "In quegli anni i buoni venivano venduti al prezzo dell'affrancatura del Paese di emissione ma, se nel Paese dove venivano scambiati con francobolli la tariffa era diversa, ecco che si creava una condizione che rendeva possibile un'operazione che rendeva possibile un guadagno senza rischio (cosiddetto Arbitraggio).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1637", "question": "Come sfruttò Ponzi la differenza di valore dei buoni di risposta internazionale?", "answer": "Nel primo dopoguerra, in Italia, l'elevata inflazione aveva, di fatto, diminuito il costo dell'affrancatura in dollari statunitensi e Ponzi aveva immediatamente colto l'affare: acquistando i buoni in Italia e scambiandoli con francobolli statunitensi, la cifra spesa e quella ricavata erano molto diverse.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1638", "question": "Che cos'era la Securities Exchange Company?", "answer": "Carlo Ponzi costituì immediatamente una società per gestire questo business, la Securities Exchange Company. L'affare consisteva nel comperare gli IRC in Italia, spedirli in America e scambiarli con il controvalore in francobolli statunitensi; questo arbitraggio non era illegale e permise, sulla carta, profitti del 400%. In questo modo Ponzi poté promettere ai potenziali investitori un tasso di rendimento del 50'%' in soli 90 giorni e iniziò a raccogliere i primi capitali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1639", "question": "Perché l'affare di Ponzi esplose?", "answer": "L'affare esplose tra le mani di Ponzi: tutti volevano entrare nel business anche perché si era sparsa la voce dei favolosi rendimenti che venivano, effettivamente, pagati. Gli agenti assunti da Ponzi per raccogliere fondi ebbero gioco facile perché i primi investitori furono profumatamente remunerati e non c'era nulla di meglio del passaparola entusiasta per convincere anche i più scettici.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1640", "question": "Cosa dichiarò Ponzi nel suo discorso a Boston del 10 agosto 1920?", "answer": "Durante un discorso pronunciato a Boston, il 10 agosto 1920, lo stesso Ponzi esemplificò la situazione: \"Prendo un dollaro, con il cambio di oggi ottengo 18 lire italiane che mi bastano per comprare in Italia 60 buoni di risposta internazionali che poi converto negli Stati Uniti per 3 dollari\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1641", "question": "Perché l'operazione di arbitraggio di Ponzi non era realmente conveniente?", "answer": "La realtà era ben diversa; sulla carta, infatti, era possibile fare un arbitraggio ben remunerato, nella realtà però i costi di acquisto, trasporto e conversione annullavano qualsiasi convenienza dell'operazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1642", "question": "Cosa fece Ponzi dopo aver raccolto ingenti somme di denaro?", "answer": "Con l'aumentare dei fondi Ponzi cominciò a pensare in grande, aprì un conto nella Hannover Trust Bank e nel luglio 1920, quando oramai aveva raccolto svariati milioni di dollari, ne assunse il controllo, rilevando il 38'%' delle azioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1643", "question": "Perché Ponzi acquistò la Hannover Trust Bank?", "answer": "L'acquisto della banca permise a Ponzi di effettuare le operazioni finanziarie necessarie al suo business senza essere soggetto a possibili controlli esterni che avrebbero potuto far emergere la verità: non c'era nessun business; semplicemente gli interessi venivano pagati con i soldi dei nuovi sottoscrittori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1644", "question": "Come reagirono gli investitori allo schema di Ponzi?", "answer": "Si scatenò una vera febbre isterica: tutti volevano investire e la gente ipotecava le proprie case per poter investire la maggior quantità di denaro possibile. In quel periodo, Ponzi, riuscì a raccogliere oltre 250.000 di dollari al giorno, una cifra incredibilmente alta per l'epoca.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1645", "question": "Come riusciva Ponzi a mantenere la fiducia degli investitori?", "answer": "Fu creato un \"solido\" castello di carta, dove Ponzi remunerava gli investitori con i soldi dei nuovi flussi di denaro e rimborsava gli investitori che dubitano del suo business, mettendo a tacere le voci di insolvenza che cominciavano a comparire.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1646", "question": "Come venne smascherato lo schema di Ponzi?", "answer": "Il castello iniziò a vacillare quando Clarence Barron, un analista finanziario, esaminò la società di Ponzi e arrivò alla conclusione che, per poter garantire quello che prometteva, Ponzi avrebbe avuto bisogno di 160.000.000 di Buoni di Risposta Internazionale; il problema era che in circolazione ve ne erano solamente 27.000.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1647", "question": "Come reagirono gli investitori dopo la scoperta di Barron?", "answer": "Gli investitori, presi dal panico, assediarono l'ufficio di Ponzi che restituì 2.000.000 di dollari, discutendo con gli investitori che, ancora una volta, si sentirono rincuorati e decisero di lasciargli i loro risparmi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1648", "question": "Quale decisione prese l'amministrazione postale il 28 luglio 1920?", "answer": "Il clamore della faccenda non sfuggì ai dirigenti delle Poste che il 28 luglio 1920, con effetto dal 15 agosto, modificarono i tassi di conversione postale per la prima volta dal dopoguerra, rendendo l'arbitraggio di Ponzi non più conveniente nemmeno a livello teorico.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1649", "question": "Cosa accadde dopo la modifica dei tassi di conversione postale?", "answer": "Il 10 agosto gli agenti federali misero i sigilli sia alla Securities Exchange Company che alla Hannover Trust Bank e, il 13 agosto, Ponzi fu arrestato. Non si trovò neanche un buono di risposta internazionale e 40.000 investitori, che avevano conferito 15.000.000 di dollari, restarono nella disperazione più profonda.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1650", "question": "Come si concluse la vicenda di Carlo Ponzi?", "answer": "Nel 1934 Ponzi uscì definitivamente di prigione e fu fatto rimpatriare in Italia. Dopo avere svolto alcune attività in Italia, emigrò in Brasile dove morì nel 1949 in un ricovero per poveri.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1651", "question": "Chi era Bernard Madoff?", "answer": "Bernard Madoff, per operare a Wall Street dal 1980 fino al 2008, adottò uno schema Ponzi, generando un buco di 50 miliardi di dollari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1652", "question": "Quando e dove nacque Bernard Madoff?", "answer": "Madoff nacque a New York il 29 aprile 1938 da una famiglia di origine ebraica e, fin da giovane, dimostrò di avere talento per la gestione del denaro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1653", "question": "Quando iniziò la carriera di Madoff nella finanza e quale società fondò?", "answer": "A 22 anni iniziò la sua avventura nel mondo della finanza e fondò la sua prima società: la Bernard Madoff Investment Securities.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1654", "question": "In quali attività era impegnata la Bernard Madoff Investment Securities?", "answer": "L'attività della sua società spaziava dalla negoziazione titoli allo sviluppo di piattaforme elettroniche di trading per azioni e derivati, attività per le quali ebbe come partner le più prestigiose firme di Wall Street, da Goldman Sachs a Merrill Lynch.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1655", "question": "Quali furono le principali tappe della carriera di Madoff?", "answer": "Nell'83 divenne uno dei primi membri americani del London Stock Exchange, fu tra i pionieri della borsa elettronica e, nel 1990, diventò presidente del Nasdaq.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1656", "question": "Perché Madoff era conosciuto come \"Jewish Bond\"?", "answer": "La sua fama, in particolare nella comunità ebraica, fu talmente forte che fu soprannominato \"Jewish Bond\", ossia l'obbligazione ebraica, per la sua sicurezza e stabilità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1657", "question": "Chi erano i clienti di Madoff?", "answer": "Tra i suoi clienti c'erano banchieri di tutto il mondo, personaggi dello spettacolo, imprenditori e ignari investitori, tutti attirati dai rendimenti elevati che venivano promessi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1658", "question": "Qual era il rendimento medio che Madoff prometteva?", "answer": "Madoff, effettivamente, ogni anno, sia con posizioni rialziste che ribassiste, riusciva a guadagnare circa il 10%. Sempre.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1659", "question": "Quale attività dichiarava ufficialmente Madoff?", "answer": "Ufficialmente Madoff comperava e vendeva titoli per conto di altri broker e istituzioni: era, in altre parole, un grande market maker. I suoi guadagni sembravano giustificati proprio dall'attività di intermediazione che, grazie alla sua particolare posizione sul mercato, gli permetteva di guadagnare piccole somme su un enorme numero di transazioni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1660", "question": "Su quale leva faceva affidamento Madoff per attrarre investitori?", "answer": "Madoff non prometteva agli investitori guadagni eccessivamente alti, ma dava garanzie di stabilità e rischi minimi. Anziché sfruttare l'avidità, faceva leva sul desiderio di sicurezza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1661", "question": "Chi mise in dubbio la solidità dello schema di Madoff?", "answer": "Il fatto che i rendimenti non scendevano mai sotto il 10'%' annuo attirò l'attenzione di un analista finanziario, Harry Markopolos, un dipendente di una società concorrente di Madoff, che nel 1999 sottopose all'attenzione della Securities and Exchange Commission (SEC), l'Autorità di vigilanza statunitense, le strategie del fondo di Madoff ritenendole irrealistiche.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1662", "question": "Quando e cosa denunciò Harry Markopolos alla SEC?", "answer": "A fine del 2005 Markopolos denunciò nuovamente alla SEC che «Madoff Securities era il più gigantesco schema Ponzi del mondo». Ma le sue accuse caddero inascoltate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1663", "question": "Cosa causò il crollo dello schema Ponzi di Madoff?", "answer": "La situazione implose quando la crisi del 2008 bloccò nuovi afflussi di capitale e cominciarono i disinvestimenti. Madoff non riuscì ad arginare il flusso negativo di denaro, pressato da 7 miliardi di riscatti che non era in grado di onorare, e il 10 dicembre 2008 confessò che una branca della sua società finanziaria non era altro che uno schema Ponzi.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1664", "question": "Quando fu arrestato Bernard Madoff e cosa dichiarò?", "answer": "L'11 dicembre quando gli agenti dell'FBI giunsero nel suo appartamento per arrestarlo, Madoff, candidamente dichiarò di non avere spiegazioni innocenti per giustificare il buco da 50 miliardi di dollari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1665", "question": "Chi furono le vittime della truffa di Madoff?", "answer": "Vittime della truffa furono fondazioni benefiche, organizzazioni caritatevoli, amici da una vita e, perfino, la fondazione per le vittime dell'olocausto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1666", "question": "Qual era il metodo di fund management usato da Madoff?", "answer": "Il metodo proprietario di fund management adottato era uno \"schema Ponzi\" in cui il denaro dei nuovi sottoscrittori era servito a pagare gli interessi di chi aveva già sottoscritto e non era stato effettuato nessun investimento rilevante. Tutto si reggeva unicamente su una \"catena di Sant'Antonio\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1667", "question": "Quando iniziò il processo a Bernard Madoff e quale fu la sentenza?", "answer": "Il 13 marzo 2009 iniziò il processo; Bernard Madoff fu condannato a 150 anni di carcere.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1668", "question": "Cosa dimostrò l'affare Madoff?", "answer": "L'affare Madoff - di cui furono vittime anche primari banchieri di livello mondiale - dimostra che non solo dei piccoli risparmiatori \"sprovveduti\", ma anche le più grandi banche d'affari possono essere colpite da questi comportamenti \"truffaldini\".", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-truffe-piu-frequenti"}},
{"id": "chunk_1669", "question": "Cosa bisogna fare se si sospetta che una società con cui si è investito non sia autorizzata?", "answer": "Se avete il dubbio che la società con cui avete investito non sia autorizzata a prestare e offrire strumenti finanziari o, comunque, di essere incappati in comportamenti illeciti, è bene segnalare tempestivamente alla Consob la vicenda.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1670", "question": "Perché è importante segnalare i casi di abusivismo finanziario alla Consob?", "answer": "Le segnalazioni dei cittadini rivestono molta importanza per la tutela del pubblico risparmio, vista la pericolosità e la diffusione esponenziale del fenomeno dell'abusivismo finanziario che in alcuni casi integra, tra l'altro, anche un reato punito con la reclusione fino a 4 anni.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1671", "question": "Quali poteri ha la Consob contro il fenomeno dell'abusivismo finanziario?", "answer": "Occorre precisare quali sono i poteri che la legge attribuisce alla nostra Autorità contro il fenomeno dell'abusivismo finanziario, che sono diversi a secondo del tipo di abusivismo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1672", "question": "Cosa fa la Consob in caso di prestazione abusiva di servizi di investimento o di attività di promotore finanziario?", "answer": "In caso di prestazione abusiva di servizi d'investimento o di svolgimento abusivo dell'attività di promotore finanziario, la Consob, una volta svolti i relativi accertamenti, deve denunciare la vicenda all'Autorità giudiziaria, che può intervenire con i più incisivi mezzi di cui dispone, fra i quali anche l'oscuramento dei siti internet.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1673", "question": "Quali sanzioni può infliggere la Consob alle società coinvolte in casi di abusivismo finanziario?", "answer": "La Consob, ove ricorrano i presupposti previsti dalla legge, può infliggere sanzioni di tipo amministrativo nei confronti dei soggetti che svolgono funzioni di amministrazione o di direzione e dei dipendenti delle società coinvolte.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1674", "question": "Quali poteri ha la Consob in caso di offerte abusive di prodotti finanziari?", "answer": "Con riguardo alle offerte abusive di prodotti finanziari, la Consob è dotata di poteri più incisivi quali quello di poter dapprima sospendere e poi eventualmente vietare l'offerta e, in caso di mancato rispetto del divieto, di oscurare il sito internet.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1675", "question": "Come informa la Consob i risparmiatori sui rischi delle offerte o prestazioni abusive?", "answer": "Sia per le offerte che per la prestazione di servizi di investimento abusive, la Consob, una volta accertati fatti, utilizza i suoi strumenti di comunicazione (sito internet e newsletter settimanale \"Consob-Informa\") per pubblicizzare delle \"comunicazioni a tutela dei risparmiatori\" il cui fine è allertare tutti gli investitori del pericolo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1676", "question": "Qual è lo scopo delle comunicazioni pubblicate dalla Consob riguardo società non autorizzate?", "answer": "Si spera in tal modo che nuovi clienti non cadano nella rete di quella società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1677", "question": "Cosa bisogna fare se l'abusivismo finanziario integra un reato o una truffa?", "answer": "In tutti in quei casi in cui l'abusivismo finanziario integra anche un reato (ad esempio nei casi di svolgimento di servizi di investimento o di prestazione abusiva dell'attività di promotore finanziario) o, comunque, nei casi di truffa, è bene denunciare l'accaduto anche all'autorità giudiziaria, la quale è dotata di poteri cautelari più penetranti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1678", "question": "È possibile chiedere un risarcimento per i danni causati da società abusive?", "answer": "Rimane poi sempre possibile rivolgersi al giudice civile nel tentativo di chiedere il risarcimento del danno subito. Bisogna, tuttavia, tener conto della problematicità di un'azione del genere, vista la difficoltà nell'individuazione dei reali soggetti che stanno dietro le società abusive, spesso con sede fuori dai confini nazionali.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1679", "question": "Cosa si deve fare alle prime avvisaglie di un investimento abusivo?", "answer": "Alle prime avvisaglie, è bene tentare di uscire subito dall'investimento. E' possibile che la società abusiva, soprattutto se in fase di operatività iniziale, restituisca le somme per paura della cattiva pubblicità, anche presso l'autorità di vigilanza, che potreste farle.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1680", "question": "Cosa bisogna fare se si sono comunicati gli estremi della carta di credito a una società abusiva?", "answer": "E' bene, innanzi tutto, non dare mai questi dati. Se lo avete fatto, è opportuno bloccare carte di credito, prepagate e postpay. Evitate così che vengano fatti addebiti a vostra insaputa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1681", "question": "Perché è importante raccogliere tutta la documentazione in caso di abusivismo finanziario?", "answer": "E' importante, una volta che abbiamo preso coscienza di essere stati oggetto di un'attività illecita, ricostruire nel dettaglio la vicenda, andando a recuperare la documentazione eventualmente firmata, i pagamenti effettuati nonché le e-mail scambiate. Tutto questo potrà essere utile per redigere l'esposto alla Consob, per la denuncia all'autorità giudiziaria e anche nel caso si voglia intraprendere una azione risarcitoria nei confronti della società.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-difendersi-dagli-abusivismi"}},
{"id": "chunk_1682", "question": "Cosa bisogna fare quando si naviga su internet per evitare abusivismi finanziari?", "answer": "Quando si naviga su internet - considerata la facilità con la quale è possibile essere contatti e \"allettati\" con promesse di lauti rendimenti attraverso e-mail o messaggi pubblicitari che appaiono durante la navigazione (banner, pop-up) - è importante tenere sempre gli occhi aperti ed essere un po' diffidenti. Anche se abbiamo intenzione di investire solo piccole somme di denaro o di \"provare solo per una volta\" a vedere come funziona una delle numerose piattaforme per il trading on line disponibili su internet, dobbiamo prestare la massima attenzione, perché non sempre è facile tornare indietro e recuperare i soldi investiti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1683", "question": "Quali sono i campanelli di allarme che indicano che un investimento potrebbe essere abusivo?", "answer": "Ci sono dei campanelli di allarme che possono farci pensare che chi ci propone l'investimento non sia autorizzato.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1684", "question": "Perché è importante identificare la società di riferimento quando si investe online?", "answer": "Una società seria e con una buona reputazione non ha motivo di nascondersi, né di non comunicare da quale Autorità è stata autorizzata. Conoscere la vera ed esatta denominazione della società che propone l'investimento è la prima cautela da adottare, perché solo così possiamo verificare se la stessa sia presente negli albi dei soggetti autorizzati alla prestazione dei servizi d'investimenti dalla Consob o da altre Autorità.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1685", "question": "Perché non bisogna fidarsi solo delle informazioni riportate sul sito della società che propone investimenti?", "answer": "Non fidiamoci comunque mai completamente di quanto riportato sul sito internet della società. In particolare, il riferimento alla circostanza che il soggetto è vigilato da un'autorità pubblica (magari con un link alla stessa autorità) non è detto che sia vero: il controllo va sempre fatto direttamente sul sito della Consob o della Banca d'Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1686", "question": "Cosa bisogna fare se la società non è presente negli elenchi Consob o Banca d'Italia?", "answer": "Se la società non è presente sul sito della Consob fra le imprese autorizzate (o sugli elenchi della Banca d'Italia), non bisogna assolutamente investire. D'altronde prendereste mai un aereo guidato da un pilota senza licenza?", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1687", "question": "Perché è importante verificare la sede sociale della società che propone investimenti?", "answer": "E' molto importante, prima di investire, individuare la nazionalità di chi propone investimenti. Anche se il sito è tutto in italiano, e anche chi vi propone e segue gli investimenti parla italiano, non è assolutamente detto che la società abbia la sede nel nostro Paese. Potreste scoprire solo dopo aver investito che l'impresa ha sede in qualche isola sperduta di cui neanche conoscevate l'esistenza, oppure che si trova in qualche posto molto più vicino, come può essere anche la Svizzera o il Liechtenstein, ma che non fa parte dell'Unione Europea.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1688", "question": "Le società extra-comunitarie possono offrire servizi d'investimento in Italia?", "answer": "Nessuna società extra-comunitaria è oggi autorizzata a prestare servizi d'investimenti in Italia. Ciò vuol dire che se una società svizzera, australiana, americana o di qualsiasi altro paese extracomunitario offre servizi d'investimento nel nostro Paese lo sta facendo senza autorizzazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1689", "question": "Cosa bisogna verificare se la società ha sede nell'Unione Europea?", "answer": "Anche se la società ha sede all'interno dell'Unione Europea, dovete stare attenti e verificare che l'autorità di quel Paese la abbia effettivamente autorizzata a prestare servizi d'investimenti (e che sia anche abilitata a prestarli in Italia).", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1690", "question": "Perché bisogna diffidare delle promesse di rendimenti molto alti?", "answer": "Nessuno dà nulla per nulla! Bisogna quindi diffidare di proposte di investimento che assicurano un rendimento molto alto e non in linea con quelli di mercato. Alla promessa di alti rendimenti corrispondono di regola rischi molto elevati o, in alcuni casi, addirittura tentativi di truffa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1691", "question": "Cosa si omette spesso di dire riguardo alle piattaforme di trading online?", "answer": "Ciò che invece si omette di dire è la cosa più importante, ossia che è molto più probabile perdere velocemente tutto quanto investito e che tanta gente si è purtroppo rovinata, perdendo i risparmi di una vita con le società abusive che operano via internet.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1692", "question": "Qual è l'obiettivo delle società abusive quando offrono bonus o incentivi?", "answer": "Ciò che interessa davvero alle società abusive è farvi entrare nella loro \"rete\", perché quando si è già clienti e si ha dimestichezza con la piattaforma è difficile tornare indietro e si è portati ad investire sempre nuove somme.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1693", "question": "Cosa accade spesso ai clienti che iniziano a investire piccole somme su piattaforme abusive?", "answer": "Si investe all'inizio solo per provare, ingolositi soprattutto dai \"bonus\" apparentemente vantaggiosissimi visto che sembra che la società ti regali dei soldi da investire. Successivamente, senza grande sforzo, si inizia da subito a guadagnare e, quando si pensa di essere diventati abili trader e di aver trovato un modo rapido per \"arrotondare\" lo stipendio, si fa il grande errore di investire somme sempre più importanti, anche spinti dai referenti della società che sollecitano il raggiungimento di risultati ancora migliori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1694", "question": "Cosa succede quando la società abusiva fa credere che i guadagni continuano?", "answer": "In alcuni casi, in modo ancor più ingannevole, la società ti fa credere apparentemente di continuare sempre a guadagnare ma, in realtà, il guadagno è solo virtuale perché quando si vuole disinvestire le somme non vengono mai restituite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1695", "question": "Quali sono le modalità di contatto usate dagli operatori abusivi?", "answer": "Una delle modalità di contatto ancora preferita è quella telefonica che è particolarmente insidiosa, in quanto il malcapitato viene preso alla sprovvista ed è naturalmente portato a non meditare con la dovuta attenzione su quello che va a fare. Altre modalità di contatto sempre più diffuse sono l'invio di e-mail nelle quali si riportano i link delle imprese d'investimento, o i banner o pop up che si aprono durante la navigazione.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1696", "question": "Perché i banner o i pop-up non sono sempre affidabili?", "answer": "Può capitare che i banner e i pop up compaiano durante la navigazione su siti da noi ritenuti seri e affidabili, ma ciò non vuol dire che lo siano altrettanto le società pubblicizzate. Considerate che spesso non vi è nessun rapporto tra sito ospitante e la società che si pubblicizza.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1697", "question": "Cos'è il passaparola online e perché è rischioso?", "answer": "Altra forma classica di contatto è il passaparola che oggi, all'epoca di internet, può anche manifestarsi per mezzo dei \"forum di finanza\" nei quali, tra l'altro, a volte si nascondono persone riconducibili alle società abusive in cerca di nuovi clienti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1698", "question": "Quando i clienti scoprono la natura abusiva delle società?", "answer": "Purtroppo la maggior parte dei clienti si accorge troppo tardi della natura abusiva e truffaldina dei soggetti con cui ha investito. I problemi, di norma, si manifestano quando il cliente vuole uscire dall'investimento.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1699", "question": "Quali comportamenti indicano che la società non vuole restituire le somme investite?", "answer": "Spesso, infatti, dopo la richiesta di rimborso la società adduce scuse il più delle volte irragionevoli, pone in atto atteggiamenti dilatori, chiede documentazione suppletiva o afferma di essere sempre in procinto di provvedere. In alcuni casi, addirittura, motiva la mancata restituzione con il fatto che il conto del cliente è sotto investigazione per possibili illeciti compiuti dal cliente stesso!", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1700", "question": "Cosa bisogna fare alle prime avvisaglie di difficoltà nella restituzione del denaro?", "answer": "Alle prime avvisaglie di difficoltà nella restituzione delle somme è buona norma uscire subito dall'investimento, facendo il massimo delle pressioni per la restituzione del denaro. Ovviamente, in questi casi, non cadere nella ulteriore trappola di versare altro denaro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/come-riconoscerli"}},
{"id": "chunk_1701", "question": "Quali sono le fattispecie più frequenti in materia di abusiva prestazione di servizi d'investimento?", "answer": "Le fattispecie più frequenti in materia di abusiva prestazione di servizi d'investimento sono le attività di trading sul forex e le opzioni binarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1702", "question": "Il forex e le opzioni binarie sono strumenti illeciti?", "answer": "Questi strumenti non sono di per sé illeciti; lo diventano se offerti da soggetti non autorizzati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1703", "question": "Cosa si intende per forex?", "answer": "Per forex, in generale, si intendono i contratti di acquisto e vendita di valute regolati per differenza; pertanto, quando si fa riferimento al cosiddetto \"mercato forex\", si è soliti intendere il mercato dei cambi, ossia un mercato finanziario globale fuori borsa (OTC) in cui gli operatori negoziano direttamente fra loro.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1704", "question": "Il mercato forex è simile a una borsa valori come quella di Milano o New York?", "answer": "Questo in realtà non è un vero e proprio mercato o, almeno, è un mercato assai diverso da quelli che generalmente conosciamo, come possono essere la Borsa di Milano o quella di New York. Il mercato forex, infatti, non ha un listino prezzi ma è una rete internazionale 'decentrata', in cui gli operatori acquistano, vendono e scambiano valute 24 ore su 24.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1705", "question": "Quali rischi comporta l'investimento nel forex?", "answer": "L'investimento nel forex è spesso presentato come un'attività semplice e che dà immediati guadagni ma non si deve mai scordare la volatilità delle valute e, soprattutto, la leva finanziaria. L'effetto leva permette anche con piccole somme investite di esporsi su grandi volumi di valuta e ciò comporta che, sia i guadagni, sia soprattutto le perdite, sono amplificati, rischiando di perdere con una certa facilità l'intera somma investita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1706", "question": "Cosa sono i software che generano automaticamente operazioni su valute?", "answer": "Sono software proposti da imprese che generano automaticamente operazioni su valute sulla base di algoritmi predefiniti. Affidandoci a tali strumenti si finisce per perdere completamente il controllo sui nostri investimenti, i quali possono essere effettuati anche quando noi non siamo al computer.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1707", "question": "Secondo lo studio dell'AMF, quanti investitori sul forex perdono denaro?", "answer": "Secondo un recente studio dell'AMF (l'Autorita francese dei mercati finanziari) è emerso che su 10 persone che investono sul forex, e si badi bene con società autorizzate, 9 perdono.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1708", "question": "Perché il rischio è più alto se la società è abusiva?", "answer": "Il rischio è ancora più elevato se la società è abusiva, perché in questo caso potrebbe anche essere probabile che le somme non siano realmente investite dalle società o che i software di trading siano manipolati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1709", "question": "Cosa sono le opzioni binarie?", "answer": "Le opzioni binarie sono strumenti finanziari che si stanno sempre più diffondendo in ragione della loro apparente semplicità. Presentano una struttura simile a quella di una scommessa in quanto assicurano il pagamento di un importo predeterminato se l'evento si verifica entro una determinata scadenza temporale; nel caso in cui l'evento non si verifichi, l'investitore perde tutta la somma investita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1710", "question": "Quali tipi di opzioni binarie esistono?", "answer": "Le opzioni binarie possono essere di vario tipo; le più frequenti sono quelle alto/basso, tocca/non tocca e intervallo, ma in tutti i casi chi investe sa già prima quale sarà il suo eventuale guadagno e la sua eventuale perdita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1711", "question": "Puoi fare un esempio di opzione binaria?", "answer": "Un esempio di opzione binaria può essere il seguente: il valore del rame tra una settimana sarà più alto o più basso di quello di oggi? Se l'investitore scommette che sarà più alto e indovina guadagnerà magari l'80% di quanto investito; nel caso contrario perderà tutto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1712", "question": "Cosa caratterizza le opzioni binarie a durata breve?", "answer": "Ultimamente si stanno diffondendo opzioni binarie con una durata sempre più breve, ad esempio un'ora o un minuto. In tal modo si accentua all'estremo il loro carattere di scommessa perché è davvero difficile, se non impossibile, fare previsioni con un minimo di fondamento a così breve periodo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1713", "question": "Cosa sono le sedicenti piattaforme di crowdfunding?", "answer": "Sono piattaforme abusive che si sono diffuse parallelamente all'equity crowdfunding regolamentato dalla Consob. Quando un fenomeno è ancora poco conosciuto dalla gente è più facile introdursi nel sistema con condotte truffaldine, e così sono emerse sedicenti piattaforme di crowdfunding abusivo.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1714", "question": "Cos'è il crowdfunding regolamentato dalla Consob?", "answer": "Il crowdfunding regolamentato dalla Consob è, ad oggi, solo l'equity crowdfunding, strumento che consente alle imprese che possano qualificarsi come start-up innovative di raccogliere capitale di rischio tramite portali on-line, nel rispetto di tutta una serie di accorgimenti a tutela dei possibili investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1715", "question": "Chi può accedere all'equity crowdfunding regolamentato?", "answer": "Le imprese start up innovative, per poter accedere a tale possibilità di finanziamento, devono offrire le proprie azioni o quote solo attraverso i gestori di portali di crowdfunding autorizzati dalla Consob.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1716", "question": "Come riconoscere un portale di crowdfunding abusivo?", "answer": "Se il gestore del portale con cui entrate in contatto non è ricompreso nell'albo dei portali disponibile sul sito della Consob, è possibile che vi troviate di fronte ad un'attività abusiva e, probabilmente, ad una truffa.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/le-fattispecie-piu-frequenti"}},
{"id": "chunk_1717", "question": "Quali sono le fonti attendibili per effettuare verifiche e accertamenti sugli operatori finanziari?", "answer": "Piuttosto di affidarvi a sedicenti esperti che spesso agiscono in modo interessato nei forum o nei siti che segnalano i presunti migliori operatori del mercato, è meglio cercare le informazioni solo da fonti attendibili.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1718", "question": "Dove si possono cercare informazioni ufficiali sugli operatori autorizzati?", "answer": "Il primo luogo, il posto dove cercare le informazioni è il sito della CONSOB dove, oltre ad approfondire la vostra conoscenza attraverso il portale di educazione finanziaria, potete consultare gli albi delle società autorizzate e le comunicazioni a tutela dei consumatori con le quali si dà conto delle società e delle offerte non autorizzate.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1719", "question": "Quale sezione del sito della CONSOB raccoglie consigli utili per gli investitori?", "answer": "Si consiglia in particolare la consultazione della sezione \"Occhio alle Truffe!\", che raccoglie i consigli utili per gli investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1720", "question": "Cosa contengono i warning pubblicati nella sezione 'Occhio alle Truffe!' della CONSOB?", "answer": "Insieme ai warning della Consob, vengono anche riportati, nella stessa sezione, anche i warning delle altre autorità comunitarie.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1721", "question": "Cosa significa se una società è menzionata in un warning di un'altra autorità europea?", "answer": "Tenete conto che se la società con cui operate è menzionata in un warning di un'altra autorità europea è davvero altamente probabile che quella società non sia neanche autorizzata ad operare in Italia.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1722", "question": "Quale pagina del sito dello IOSCO è utile per consultare i warning di Paesi non comunitari?", "answer": "Proprio in questa ottica è sempre bene consultare la seguente pagina del sito dello IOSCO: [https://www.iosco.org/investor_protection/?subsection=investor_alerts_portal](https://www.iosco.org/investor_protection/?subsection=investor_alerts_portal) dove vengono riportati anche i warning di Paesi non comunitari.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1723", "question": "Quale sito europeo fornisce sezioni dedicate alla protezione degli investitori?", "answer": "E' bene, inoltre, consultare anche il sito dell'Esma (Autorità europea degli strumenti finanziari e dei mercati) la quale ha pubblicato varie sezioni del proprio sito per mettere gli investitori in guardia su alcuni pericoli legati agli investimenti on line o a particolari strumenti finanziari come forex e cfd.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1724", "question": "Quali sono i link del sito ESMA utili per gli investitori?", "answer": "[https://www.esma.europa.eu/investor-corner/check-if-firm-regulated](https://www.esma.europa.eu/investor-corner/check-if-firm-regulated) - [https://www.esma.europa.eu/investor-corner/file-complaint](https://www.esma.europa.eu/investor-corner/file-complaint) - [https://www.esma.europa.eu/investor-corner/frauds-and-scams](https://www.esma.europa.eu/investor-corner/frauds-and-scams) - [https://www.esma.europa.eu/investor-corner/warning-and-publications-investors](https://www.esma.europa.eu/investor-corner/warning-and-publications-investors)", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/link-utili"}},
{"id": "chunk_1725", "question": "Cosa rende più pericolose le truffe finanziarie?", "answer": "Le truffe finanziarie diventano ancora più pericolose se vengono poste in essere da soggetti non autorizzati.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1726", "question": "Chi può prestare servizi di investimento?", "answer": "La prestazione di servizi d'investimento, in considerazione della delicatezza dell'attività, è una attività riservata ad operatori autorizzati i quali devono essere costantemente vigilati ed iscritti in appositi albi pubblici, previa verifica dei necessari requisiti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1727", "question": "Chi deve autorizzare l'offerta di prodotti finanziari?", "answer": "Anche l'offerta di prodotti finanziari (azioni, obbligazioni, quote di fondi, ecc.) deve essere preventivamente autorizzata.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1728", "question": "Cosa comporta operare senza le prescritte autorizzazioni?", "answer": "Già solo operare senza le prescritte autorizzazioni è contrario alla legge, a prescindere che si pongano o meno in essere truffe.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1729", "question": "Qual è l'esempio usato per spiegare l'operare senza autorizzazioni?", "answer": "E' un po' come il guidare senza patente: si è sanzionati anche se in concreto non si commettono specifiche infrazioni alla guida.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1730", "question": "Perché chi offre prodotti finanziari deve avere requisiti specifici?", "answer": "Come chi vuole guidare deve prima dimostrare di esserne in grado, allo stesso modo chi presta o offre prodotti finanziari deve avere i requisiti e le caratteristiche per farlo in modo corretto.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1731", "question": "Quali possono essere le conseguenze negative dell'operare senza autorizzazione?", "answer": "Le conseguenze negative possono essere assai gravi: si può provocare un incidente o si possono \"bruciare\" i risparmi di una vita.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1732", "question": "Quante tipologie di abusivismo finanziario prevede l'ordinamento italiano?", "answer": "Il nostro ordinamento prevede tre tipologie di abusivismo finanziario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1733", "question": "Cos'è l'abusiva prestazione di servizi e attività di investimento?", "answer": "È lo svolgimento di attività riservate (es. collocamento di strumenti finanziari, gestione di portafogli, negoziazione di strumenti finanziari o valute, consulenza per investimenti ecc.) in assenza delle autorizzazione rilasciate dalle Autorità competenti.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1734", "question": "Cos'è lo svolgimento abusivo dell'attività di promotore finanziario?", "answer": "È l'esercizio professionale, da parte di una persona non iscritta all'Albo dei promotori finanziari, dell'offerta fuori sede (ad esempio a casa dei clienti) come agente, dipendente o mandatario di un intermediario.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1735", "question": "Cos'è l'offerta abusiva di prodotti finanziari e attività pubblicitaria?", "answer": "Si ha quando viene posta in essere o pubblicizzata un'offerta di prodotti finanziari (es. azioni, obbligazioni, contratti derivati, fondi comuni d'investimento, polizze assicurative a carattere finanziario, ecc.) senza la pubblicazione e il deposito presso la Consob o altra Autorità di un prospetto informativo, laddove la legge lo preveda.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1736", "question": "Quanto sono frequenti i casi di abusivismo finanziario?", "answer": "Questi casi di abusivismo, nella realtà di tutti i giorni, sono più frequenti di quello che possa sembrare.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1737", "question": "Perché gli abusivismi finanziari sono diventati più frequenti?", "answer": "Ciò è anche dovuto alla recente larghissima diffusione di internet che - comportando il moltiplicarsi delle possibilità di contatto e, quindi, anche di pubblicizzare, proporre e concludere investimenti (attraverso siti web o e-mail) - ha mutato l'abitudine degli investitori.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1738", "question": "Come si sono evolute le abitudini degli investitori con internet?", "answer": "Oggi, con sempre più frequenza, si concludono operazioni su strumenti finanziari via internet ma, purtroppo, tra di esse si possono nascondere attività illecite.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}},
{"id": "chunk_1739", "question": "Quale percentuale dei casi di abusivismo riguarda attività sul web?", "answer": "I due terzi delle ipotesi di abusivismo sottoposte all'attenzione della Consob riguardano attività poste in essere tramite il web.", "metadata": {"source_title": "CONSOB", "source_url": "https://www.consob.it/web/investor-education/gli-abusivismi-finanziari"}}
];

export default KNOWLEDGE_BASE;
